'use strict';

/* =====================================================================
   Formatting helpers
   ===================================================================== */

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'];

const omrNumber = new Intl.NumberFormat('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
const countNumber = new Intl.NumberFormat('en-US');

// Money arrives from the API as DECIMAL strings ("1234.500"); only format here.
function formatOmr(value) {
  return `OMR ${omrNumber.format(Number(value) || 0)}`;
}
function formatAmount(value) {
  return omrNumber.format(Number(value) || 0);
}
function formatCount(value) {
  return countNumber.format(Number(value) || 0);
}
function formatDate(date) {
  return date.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}
function formatTime(date) {
  return date.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false });
}

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}
const byId = id => document.getElementById(id);

/* =====================================================================
   Data source
   Replace the body of fetchDashboard() with
     (await apiRequest(`api/dashboard.php?month=${month}&year=${year}&chartMonth=...`)).data
   once the backend exists. The shape below is the API contract.
   ===================================================================== */

// The figures come from the company's own records (api/dashboard.php); zeros if they could not be loaded.
// range: the cards' From – To (the header's dates); without it the cards count the month.
async function fetchDashboard({ year, month }, range = null) {
  const weeks = Math.ceil(new Date(year, month, 0).getDate() / 7);
  const lastMonth = shiftMonth(today.getFullYear(), today.getMonth() + 1, -1);
  try {
    const dates = range ? `&from=${range.from}&to=${range.to}` : '';
    const data = await apiRequest(`api/dashboard.php?year=${year}&month=${month}${dates}`);
    // A manager's figures have no profit & loss or activities (the admins'): empty ones keep the page drawing.
    data.profitLoss ??= { overall: { margin: '0.0' }, lastMonth: { margin: '0.0' } };
    data.activities ??= [];
    data.activityTotal ??= 0;
    data.profitLoss.lastMonth = { ...lastMonth, ...data.profitLoss.lastMonth };
    return data;
  } catch (error) {
    console.warn('Dashboard figures not loaded:', error);
  }
  return {
    kpis: { totalSales: '0.000', totalPurchase: '0.000', pendingPurchase: '0.000', totalItems: 0, totalEmployees: 0, creditors: 0, debtors: 0 },
    profitLoss: { lastMonth: { ...lastMonth, margin: '0.0' }, overall: { margin: '0.0' } },
    chart: { sales: '0.000', purchase: '0.000',
      weeks: Array.from({ length: weeks }, (_, i) => ({ label: `W${i + 1}`, sales: '0.000', purchase: '0.000' })) },
    returns: { purchaseReturn: '0.000', salesReturn: '0.000', rmaCount: 0, topReason: '', topReasonCount: 0 },
    quotations: { total: 0, totalValue: '0.000', pending: 0, approved: 0, rejected: 0 },
    activities: [],
  };
}

/* =====================================================================
   State
   ===================================================================== */

const today = new Date();
// The cards show the current month; only the Monthly Purchase & Sales chart follows the month buttons.
const currentPeriod = { year: today.getFullYear(), month: today.getMonth() + 1 };
const state = {
  chartYear: currentPeriod.year,
  chartMonth: currentPeriod.month,         // 1..12
  data: null,
};
const ACTIVITY_PAGE_SIZE = 5;                 // the dashboard shows the latest 5; View All shows the rest

/* =====================================================================
   Header: the cards' dates (From – To)
   The button shows the dates the cards count (Total Purchase, Purchase & Sales Return); it opens From / To, with
   This Month, Last Month and This Year. It starts on this month, the 1st to its last day (1st – 30th).
   Keys: Enter in From → To, Enter in To applies; Esc closes. The Monthly chart keeps its own month buttons.
   ===================================================================== */

const ymd = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
const monthRange = (year, month) => ({ from: ymd(new Date(year, month - 1, 1)), to: ymd(new Date(year, month, 0)) });
const DASH_PRESETS = {
  month: () => monthRange(today.getFullYear(), today.getMonth() + 1),
  last: () => monthRange(today.getMonth() === 0 ? today.getFullYear() - 1 : today.getFullYear(), today.getMonth() === 0 ? 12 : today.getMonth()),
  year: () => ({ from: `${today.getFullYear()}-01-01`, to: `${today.getFullYear()}-12-31` }),
};
state.range = DASH_PRESETS.month();

function renderRange() {
  const fmt = day => { const [y, m, d] = day.split('-').map(Number); return new Date(y, m - 1, d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }); };
  byId('dashboard-range-text').textContent = `${fmt(state.range.from)} — ${fmt(state.range.to)}`;
}

function syncRangePresets() {
  const from = byId('dash-from').value;
  const to = byId('dash-to').value;
  for (const button of document.querySelectorAll('[data-dash-preset]')) {
    const range = DASH_PRESETS[button.dataset.dashPreset]();
    button.setAttribute('aria-pressed', String(range.from === from && range.to === to));
  }
}

function openRangePop() {
  byId('dash-from').value = state.range.from;
  byId('dash-to').value = state.range.to;
  byId('dash-range-error').hidden = true;
  syncRangePresets();
  byId('dash-range-pop').hidden = false;
  byId('dashboard-range-btn').setAttribute('aria-expanded', 'true');
  byId('dash-from').focus();
}

function closeRangePop(refocus = true) {
  if (byId('dash-range-pop').hidden) return;
  byId('dash-range-pop').hidden = true;
  byId('dashboard-range-btn').setAttribute('aria-expanded', 'false');
  if (refocus) byId('dashboard-range-btn').focus();
}

function applyRange() {
  const from = byId('dash-from').value;
  const to = byId('dash-to').value;
  if (!from || !to || to < from) {
    const error = byId('dash-range-error');
    error.textContent = !from || !to ? 'Enter both dates as DD/MM/YYYY.' : 'To must be on or after From.';
    error.hidden = false;
    (!from ? byId('dash-from') : byId('dash-to')).focus();
    return;
  }
  state.range = { from, to };
  renderRange();
  closeRangePop();
  loadDashboard();
}

function initDashRange() {
  renderRange();
  const pop = byId('dash-range-pop');
  byId('dashboard-range-btn').addEventListener('click', () => { if (pop.hidden) openRangePop(); else closeRangePop(); });
  pop.addEventListener('click', event => {
    const preset = event.target.closest('[data-dash-preset]');
    if (preset) {
      const range = DASH_PRESETS[preset.dataset.dashPreset]();
      byId('dash-from').value = range.from;
      byId('dash-to').value = range.to;
      byId('dash-range-error').hidden = true;
      syncRangePresets();
      return;
    }
    const action = event.target.closest('[data-dash-range]')?.dataset.dashRange;
    if (action === 'apply') applyRange();
    else if (action === 'cancel') closeRangePop();
  });
  // From: a whole date puts the same date in To when To is empty or before it (as the Filter popups).
  byId('dash-from').addEventListener('input', event => {
    const from = event.target.value;
    const to = byId('dash-to');
    if (from && (!to.value || to.value < from)) to.value = from;
    syncRangePresets();
  });
  byId('dash-to').addEventListener('input', syncRangePresets);
  pop.addEventListener('keydown', event => {
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); closeRangePop(); return; }
    if (event.key !== 'Enter' || event.ctrlKey || event.altKey || event.shiftKey) return;
    if (event.target === byId('dash-from')) { event.preventDefault(); event.stopPropagation(); byId('dash-to').focus(); }
    else if (event.target === byId('dash-to')) { event.preventDefault(); event.stopPropagation(); applyRange(); }
  });
  // A click outside closes it (without changing the dates).
  document.addEventListener('mousedown', event => {
    if (!pop.hidden && !event.target.closest('.dash-range')) closeRangePop(false);
  });
}

/* =====================================================================
   KPI tiles
   ===================================================================== */

// Grouped by module, each in its module colour: sales blue, purchase green, masters amber, employees violet.
const KPI_ICONS = {
  sales: '<path d="M3 17l6-6 4 4 8-8"></path><path d="M14 7h7v7"></path>',
  purchase: '<circle cx="9" cy="20" r="1.5"></circle><circle cx="18" cy="20" r="1.5"></circle><path d="M2 3h3l2.7 12.4a2 2 0 0 0 2 1.6h8.6a2 2 0 0 0 2-1.6L22 7H6"></path>',
  pending: '<circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 2"></path>',
  items: '<path d="M21 8 12 3 3 8v8l9 5 9-5z"></path><path d="m3 8 9 5 9-5M12 13v8"></path>',
  creditors: '<path d="M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2"></path><path d="M15 18H9"></path><path d="M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.62l-3.48-4.35A1 1 0 0 0 17.52 8H14"></path><circle cx="17" cy="18" r="2"></circle><circle cx="7" cy="18" r="2"></circle>',
  debtors: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"></path>',
  employees: '<circle cx="12" cy="8" r="4"></circle><path d="M4 21a8 8 0 0 1 16 0"></path>',
};
// Each tile opens the page behind its number (route).
const KPI_TILES = [
  { key: 'totalSales', label: 'Total Sales', money: true, tone: 'sales', icon: 'sales', route: 'entry/sales-entry' },
  { key: 'totalPurchase', label: 'Total Purchase', money: true, tone: 'purchase', icon: 'purchase', route: 'entry/purchase-entry' },
  { key: 'pendingPurchase', label: 'Pending Purchase', money: true, tone: 'purchase', icon: 'pending', route: 'purchase-book/purchase-order' },
  { key: 'totalItems', label: 'Total Items', money: false, tone: 'masters', icon: 'items', route: 'masters/item' },
  { key: 'creditors', label: 'Creditors', money: false, tone: 'masters', icon: 'creditors', admin: true, route: 'masters/supplier' },
  { key: 'debtors', label: 'Debtors', money: false, tone: 'masters', icon: 'debtors', admin: true, route: 'masters/customer' },
  { key: 'totalEmployees', label: 'Total Employees', money: false, tone: 'employee', icon: 'employees', admin: true, route: 'employee/employee' },
];

function renderKpis(kpis) {
  const grid = byId('dashboard-kpis');
  // A manager's dashboard has the first four tiles; creditors, debtors and employees are the admins'.
  grid.replaceChildren(...KPI_TILES.filter(tile => userAccess.admin || !tile.admin).map(tile => {
    // A link to the tile's page; a plain card when this user may not open that page.
    const link = tile.route && routeAllowed(tile.route);
    const card = el(link ? 'a' : 'div', `metric-card kpi-card tone-${tile.tone}`);
    if (link) { card.href = `#/${tile.route}`; card.classList.add('is-link'); }
    const head = el('div', 'card-head');
    const icon = el('div', 'card-icon');
    icon.setAttribute('aria-hidden', 'true');
    icon.innerHTML = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${KPI_ICONS[tile.icon]}</svg>`;
    head.append(el('span', 'card-label', tile.label), icon);
    card.append(head, el('div', 'kpi-value', tile.money ? formatOmr(kpis[tile.key]) : formatCount(kpis[tile.key])));
    return card;
  }));
}

/* =====================================================================
   Profit & Loss
   ===================================================================== */

// A negative margin is a loss: label it "Loss", show the size without the sign, colour it red.
function renderMargin(prefix, labelId, valueId, margin) {
  const value = Number(margin) || 0;
  const isLoss = value < 0;
  byId(labelId).textContent = `${prefix} · ${isLoss ? 'Loss' : 'Profit'}`;
  const node = byId(valueId);
  node.textContent = `${Math.abs(value).toFixed(1)}%`;
  node.classList.toggle('is-profit', value > 0);
  node.classList.toggle('is-loss', isLoss);
}

function renderProfitLoss(pl) {
  const { year, month } = pl.lastMonth;
  const monthName = `${MONTH_NAMES[month - 1].slice(0, 3)} ${year}`;
  renderMargin(`Last month (${monthName})`, 'pl-month-label', 'pl-month-value', pl.lastMonth.margin);
  renderMargin('Total overall', 'pl-overall-label', 'pl-overall-value', pl.overall.margin);
}

/* =====================================================================
   Monthly Purchase & Sales chart
   ===================================================================== */

function shiftMonth(year, month, delta) {
  const d = new Date(year, month - 1 + delta, 1);
  return { year: d.getFullYear(), month: d.getMonth() + 1 };
}

function renderChartMonths() {
  const group = byId('chart-months');
  const hadFocus = group.contains(document.activeElement);
  group.replaceChildren(...[-2, -1, 0, 1].map(delta => {
    const { year, month } = shiftMonth(state.chartYear, state.chartMonth, delta);
    const short = MONTH_NAMES[month - 1].slice(0, 3);
    const active = delta === 0;
    const btn = el('button', 'segmented-btn', active ? `${short} ${year}` : short);
    btn.type = 'button';
    btn.setAttribute('aria-pressed', String(active));
    btn.setAttribute('aria-label', `${MONTH_NAMES[month - 1]} ${year}`);
    if (!active) {
      btn.addEventListener('click', () => {
        state.chartYear = year;
        state.chartMonth = month;
        loadChart();
      });
    }
    return btn;
  }));
  if (hadFocus) refocusWithin(group, '[aria-pressed="true"]');
}

function renderChart(chart) {
  byId('chart-sales-total').textContent = formatOmr(chart.sales);
  byId('chart-purchase-total').textContent = formatOmr(chart.purchase);
  byId('chart-legend-sales').textContent = `Sales (${formatOmr(chart.sales)})`;
  byId('chart-legend-purchase').textContent = `Purchase (${formatOmr(chart.purchase)})`;

  const max = Math.max(0, ...chart.weeks.flatMap(w => [Number(w.sales) || 0, Number(w.purchase) || 0]));
  const barHeight = value => {
    const n = Number(value) || 0;
    return max > 0 ? Math.max(4, Math.round((n / max) * 80)) : 4;
  };

  byId('chart-bars').replaceChildren(...chart.weeks.map(week => {
    const col = el('div', 'chart-week');
    const bars = el('div', 'chart-week-bars');
    const purchase = el('div', 'chart-bar chart-bar-purchase');
    const sales = el('div', 'chart-bar chart-bar-sales');
    purchase.title = `Purchase: ${formatOmr(week.purchase)}`;
    sales.title = `Sales: ${formatOmr(week.sales)}`;
    // CSSOM writes are allowed under the strict CSP; style="" attributes are not.
    purchase.style.height = `${barHeight(week.purchase)}px`;
    sales.style.height = `${barHeight(week.sales)}px`;
    bars.append(purchase, sales);
    const values = el('span', 'chart-week-values');
    values.title = `Sales ${formatOmr(week.sales)} / Purchase ${formatOmr(week.purchase)}`;
    values.append(
      el('span', 'chart-week-value-sales', formatAmount(week.sales)),
      el('span', 'chart-week-value-purchase', formatAmount(week.purchase)),
    );
    col.append(
      values,
      bars,
      el('span', 'chart-week-label', week.label),
    );
    return col;
  }));
}

/* =====================================================================
   Returns
   ===================================================================== */

function renderReturns(r) {
  byId('returns-purchase').textContent = formatOmr(r.purchaseReturn);
  byId('returns-sales').textContent = formatOmr(r.salesReturn);
  // Return Root Causes: the month's returns (sales and purchase) and their commonest reason's share of them.
  const count = Number(r.rmaCount) || 0;
  const top = Number(r.topReasonCount) || 0;
  byId('returns-rma-count').textContent = `${formatCount(count)} return${count === 1 ? '' : 's'}`;
  byId('returns-bar').style.width = `${count > 0 ? Math.min(100, top / count * 100) : 0}%`;
  byId('returns-note').textContent = count === 0 ? 'No returns recorded for this period'
    : r.topReason ? `Top cause: ${r.topReason} (${formatCount(top)} of ${formatCount(count)})` : 'No return reasons given';
}

/* =====================================================================
   Quotations
   ===================================================================== */

/* =====================================================================
   Insights (a manager's dashboard): Top Selling Items, Top Customers, Top Suppliers
   ===================================================================== */

function renderInsights(insights) {
  const section = byId('dash-insights');
  section.hidden = !insights;
  if (!insights) return;
  const ranking = (listId, noteId, rows, nouns) => {
    const top = Math.max(0, ...rows.map(row => Number(row.value) || 0));
    byId(noteId).textContent = 'This month';
    byId(listId).replaceChildren(...(rows.length ? rows.map(row => {
      const li = el('li', 'dash-rank-row');
      const head = el('div', 'dash-rank-head');
      head.append(el('span', 'dash-rank-name', row.name), el('span', 'dash-rank-value', formatOmr(row.value)));
      const bar = el('div', 'progress');
      const fill = el('div', 'progress-fill');
      fill.style.width = `${top > 0 ? Math.max(4, (Number(row.value) || 0) / top * 100) : 0}%`;
      bar.append(fill);
      const orders = `${formatCount(row.count)} ${row.count === 1 ? nouns[0] : nouns[1]}`;
      li.append(head, bar, el('span', 'dash-rank-sub', row.qty != null ? `${row.qty} ${row.unit || ''} · ${orders}`.replace(/\s+·/, ' ·') : orders));
      return li;
    }) : [el('li', 'dash-empty', `No ${nouns[2] || nouns[1]} this month.`)]));
  };
  ranking('dash-items', 'dash-items-note', insights.items || [], ['sales order', 'sales orders', 'items sold']);
  ranking('dash-customers', 'dash-customers-note', insights.customers || [], ['sales order', 'sales orders']);
  ranking('dash-suppliers', 'dash-suppliers-note', insights.suppliers || [], ['purchase order', 'purchase orders']);
}

function renderQuotations(q) {
  const total = Number(q.total) || 0;
  const rate = total > 0 ? ((Number(q.approved) || 0) / total) * 100 : 0;
  byId('quotes-total').textContent = formatCount(total);
  byId('quotes-value').textContent = formatOmr(q.totalValue);
  byId('quotes-pending').textContent = formatCount(q.pending);
  byId('quotes-approved').textContent = formatCount(q.approved);
  byId('quotes-rejected').textContent = formatCount(q.rejected);
  byId('quotes-rate').textContent = `${rate.toFixed(1)}%`;
  byId('quotes-rate-bar').style.width = `${Math.min(100, rate)}%`;
}

/* =====================================================================
   Audit trail
   ===================================================================== */

// Module pills use the dashboard's module colours: sales blue, purchase green, masters amber, employees violet.
const MODULE_TONE_RULES = [[/sales|quotation|trade/i, 'blue'], [/purchase|grn/i, 'green'], [/master|supplier|customer|item|party/i, 'amber'], [/employee|staff|hr/i, 'violet']];
const moduleToneOf = name => MODULE_TONE_RULES.find(([re]) => re.test(String(name ?? '')))?.[1];
const STATUS_TONES = { Completed: 'green', Updated: 'blue' };

function avatarClass(name) {
  let hash = 0;
  for (const ch of name) hash = (hash * 31 + ch.charCodeAt(0)) >>> 0;
  return `avatar avatar-${hash % 5}`;
}

function activityRow(a) {
  const at = new Date(a.at);
  const tr = document.createElement('tr');

  const when = el('td', 'col-edge nowrap');
  when.append(el('span', 'audit-date', formatDate(at)), el('span', 'audit-time', formatTime(at)));

  const who = el('td', 'nowrap');
  const userWrap = el('div', 'audit-user');
  const nameWrap = el('div');
  nameWrap.append(el('span', 'audit-user-name', a.user), el('span', 'audit-user-role', a.role));
  userWrap.append(el('div', avatarClass(a.user), a.user.charAt(0).toUpperCase()), nameWrap);
  who.append(userWrap);

  const what = el('td');
  const detail = el('span', 'audit-detail', `${a.detail} `);
  detail.append(el('span', 'audit-ref', a.ref));
  what.append(el('span', 'audit-activity', a.title), detail);

  const mod = el('td', 'nowrap');
  const moduleTone = moduleToneOf(a.module);
  mod.append(el('span', moduleTone ? `pill pill-${moduleTone}` : 'pill', a.module));

  const status = el('td', 'col-edge col-right nowrap');
  const statusTone = STATUS_TONES[a.status];
  const statusText = a.status === 'Completed' ? `✓ ${a.status}` : a.status;
  status.append(el('span', `pill pill-mono${statusTone ? ` pill-${statusTone}` : ''}`, statusText));

  tr.append(when, who, what, mod, status);
  return tr;
}

function pagerButton(label, onClick, { disabled = false, current = false, pressed = null } = {}) {
  const btn = el('button', 'pager-btn', label);
  btn.type = 'button';
  btn.disabled = disabled;
  if (current) btn.setAttribute('aria-current', 'page');
  if (pressed !== null) btn.setAttribute('aria-pressed', String(pressed));
  if (!disabled && !current) btn.addEventListener('click', onClick);
  return btn;
}

// The dashboard: the latest 5 activities only; View All opens the Audit Trail page with every one.
function renderActivities(rows, total = rows.length) {
  const visible = rows.slice(0, ACTIVITY_PAGE_SIZE);
  byId('audit-table-body').replaceChildren(...visible.map(activityRow));
  byId('audit-table-empty').hidden = visible.length > 0;
  const count = byId('audit-table-count');
  if (visible.length === 0) count.textContent = 'No recent activities';
  else count.replaceChildren('Latest ', el('strong', '', String(visible.length)), ' of ', el('strong', '', formatCount(Math.max(total, visible.length))), ' activities');
  byId('audit-view-all').hidden = visible.length === 0;
}

/* ---------- Audit Trail page (#/audit) ----------
   Every recorded activity, newest first: AUDIT_PAGE_SIZE a page with Previous / Next / page numbers.
   From / To narrow it to the activities on those days (either may be left blank); Today, Last 7 Days and This Month
   fill both. Keys: ← / → (or PageUp / PageDown) the previous / next page, Esc back. */
/* ---------- From / To date ranges: To can never be before From ----------
   Every From / To pair (To's id → From's id). The To field's calendar starts at From (min). A date field still takes
   a typed or arrow-stepped date below its min, so a whole To date before From is put back to From at once. While
   the year is still being typed (below 1000) the events are held back instead, and leaving To fixes it. A From
   moved past To on leaving it takes To with it. A fix on leaving is sent on as input + change, so every filter's
   own handlers update. */
const DATE_RANGE_PAIRS = {
  'dash-to': 'dash-from', 'audit-to': 'audit-from', 'stkr-ledger-to': 'stkr-ledger-from', 'master-filter-to': 'master-filter-from',
  'rrf-d2': 'rrf-d1', 'erf-d2': 'erf-d1', 'pbf-to': 'pbf-from',
};
const DATE_RANGE_FROM = Object.fromEntries(Object.entries(DATE_RANGE_PAIRS).map(([to, from]) => [from, to]));
const dateRangeTo = node => node instanceof HTMLInputElement && DATE_RANGE_PAIRS[node.id] ? node : null;
const dateRangeFrom = node => node instanceof HTMLInputElement && DATE_RANGE_FROM[node.id] ? node : null;
const dateRangeBackwards = to => { const from = byId(DATE_RANGE_PAIRS[to.id]).value; return Boolean(from && to.value && to.value < from); };
function setDateRangeValue(input, value) {
  input.value = value;
  input.dispatchEvent(new Event('input', { bubbles: true }));
  input.dispatchEvent(new Event('change', { bubbles: true }));
}
for (const type of ['input', 'change']) {
  document.addEventListener(type, event => {
    const to = dateRangeTo(event.target);
    if (to && dateRangeBackwards(to)) {
      if (Number(to.value.slice(0, 4)) >= 1000) to.value = byId(DATE_RANGE_PAIRS[to.id]).value;   // back to From
      else event.stopImmediatePropagation();                     // year still being typed: fixed on leaving
    }
    const from = dateRangeFrom(event.target);
    if (from) byId(DATE_RANGE_FROM[from.id]).min = from.value;
  }, true);
}
document.addEventListener('focusin', event => {
  const to = dateRangeTo(event.target);
  if (to) to.min = byId(DATE_RANGE_PAIRS[to.id]).value;
});
document.addEventListener('focusout', event => {
  const to = dateRangeTo(event.target);
  if (to && dateRangeBackwards(to)) setDateRangeValue(to, byId(DATE_RANGE_PAIRS[to.id]).value);
  const from = dateRangeFrom(event.target);
  const pairTo = from && byId(DATE_RANGE_FROM[from.id]);
  if (pairTo && dateRangeBackwards(pairTo)) setDateRangeValue(pairTo, from.value);
});

const AUDIT_PAGE_SIZE = 15;
const audit = { rows: [], page: 1, all: false, loaded: false, seq: 0 };
// A date as the date inputs hold it (YYYY-MM-DD), in local time.
const auditDay = date => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
// The activities between From and To (both days included).
function auditShownRows() {
  const from = byId('audit-from').value;
  const to = byId('audit-to').value;
  if (!from && !to) return audit.rows;
  return audit.rows.filter(a => {
    const day = auditDay(new Date(a.at));
    return (!from || day >= from) && (!to || day <= to);
  });
}
// The quick ranges as [from, to]: Today, the last 7 days (today included), this month so far.
function auditRanges() {
  const today = new Date();
  const back = days => auditDay(new Date(today.getFullYear(), today.getMonth(), today.getDate() - days));
  return { today: [back(0), back(0)], week: [back(6), back(0)],
    month: [auditDay(new Date(today.getFullYear(), today.getMonth(), 1)), back(0)], clear: ['', ''] };
}
function setAuditRange(range) {
  const [from, to] = auditRanges()[range];
  byId('audit-from').value = from;
  byId('audit-to').value = to;
  audit.page = 1;
  renderAuditPage();
}
// The quick range buttons show which one From / To match; Clear shows while a date is set.
function syncAuditRange() {
  const from = byId('audit-from').value;
  const to = byId('audit-to').value;
  const ranges = auditRanges();
  for (const button of document.querySelectorAll('[data-audit-range]:not([data-audit-range="clear"])')) {
    const [f, t] = ranges[button.dataset.auditRange];
    button.setAttribute('aria-pressed', String(from === f && to === t));
  }
  byId('audit-clear').hidden = !from && !to;
}

async function loadAuditPage() {
  const seq = ++audit.seq;
  try {
    const { activities } = await apiRequest('api/dashboard.php?audit=1');
    if (seq !== audit.seq) return;
    audit.rows = activities || [];
  } catch (error) {
    if (seq !== audit.seq) return;
    audit.rows = [];
    showToast('The audit trail could not be loaded', error.message, true);
  }
  audit.loaded = true;
  renderAuditPage();
}

// Page numbers around the current one, with the first and last always shown: 1 … 4 5 6 … 12.
function auditPageNumbers(pages, current) {
  const shown = new Set([1, pages, current - 1, current, current + 1].filter(n => n >= 1 && n <= pages));
  return [...shown].sort((a, b) => a - b);
}

function renderAuditPage() {
  syncAuditRange();
  const rows = auditShownRows();
  const filtered = rows.length !== audit.rows.length;
  const pages = Math.max(1, Math.ceil(rows.length / AUDIT_PAGE_SIZE));
  audit.page = Math.min(Math.max(1, audit.page), pages);
  const start = audit.all ? 0 : (audit.page - 1) * AUDIT_PAGE_SIZE;
  const visible = audit.all ? rows : rows.slice(start, start + AUDIT_PAGE_SIZE);
  byId('audit-page-body').replaceChildren(...visible.map(activityRow));
  byId('audit-page-empty').hidden = rows.length > 0 || !audit.loaded;
  byId('audit-page-empty').textContent = audit.rows.length ? 'No activity in this date range.' : 'No activity recorded yet.';
  const count = byId('audit-page-count');
  if (!audit.loaded) count.textContent = 'Loading…';
  else if (rows.length === 0) count.textContent = filtered ? 'No activities in this date range' : 'No recent activities';
  else count.replaceChildren('Showing ', el('strong', '', `${start + 1}–${start + visible.length}`), ' of ', el('strong', '', formatCount(rows.length)), ' activities');

  const nav = byId('audit-page-pager');
  const hadFocus = nav.contains(document.activeElement);
  const focusedLabel = hadFocus ? document.activeElement.textContent : '';
  const go = page => () => { audit.all = false; audit.page = page; renderAuditPage(); };
  const p = audit.page;
  const buttons = [pagerButton('Previous', go(p - 1), { disabled: audit.all || p <= 1 })];
  let last = 0;
  for (const n of auditPageNumbers(pages, p)) {
    if (n - last > 1) buttons.push(el('span', 'pager-gap', '…'));
    buttons.push(pagerButton(String(n), go(n), { current: !audit.all && n === p }));
    last = n;
  }
  buttons.push(pagerButton('Next', go(p + 1), { disabled: audit.all || p >= pages }));
  nav.replaceChildren(...buttons);
  if (hadFocus) {
    const same = [...nav.querySelectorAll('button:not([disabled])')].find(btn => btn.textContent === focusedLabel);
    (same || nav.querySelector('[aria-current="page"], [aria-pressed="true"]') || byId('audit-page-back')).focus();
  }
}

// #/audit: a page of its own (opened from the dashboard's View All); it loads afresh on every visit.
function initAuditPage() {
  FORM_PAGES.audit = {
    page: 'audit',
    reset: () => {
      Object.assign(audit, { page: 1, all: false, rows: [], loaded: false });
      byId('audit-from').value = '';
      byId('audit-to').value = '';
      renderAuditPage();
      loadAuditPage();
    },
    firstField: () => byId('audit-page-back'),
  };
  FORM_KEY_HANDLERS.audit = handleAuditPageKeys;
  byId('audit-page-back').addEventListener('click', () => { location.hash = '#/home'; });
  for (const id of ['audit-from', 'audit-to']) byId(id).addEventListener('change', () => { audit.page = 1; renderAuditPage(); });
  byId('audit-page').querySelector('.audit-filter').addEventListener('click', event => {
    const button = event.target.closest('[data-audit-range]');
    if (button) setAuditRange(button.dataset.auditRange);
  });
}

function handleAuditPageKeys(event) {
  if (event.ctrlKey || event.altKey || event.metaKey) return false;
  // The date fields keep their arrows: ↑/↓ step the day, month or year, ←/→ move between them. Enter goes
  // From → To → Today; Tab / Shift+Tab leave as anywhere else.
  if (event.target.matches?.('input[type="date"]') && event.key !== 'Escape') {
    if (event.key.startsWith('Arrow') && !event.shiftKey) return true;
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      if (event.target.id === 'audit-from') byId('audit-to').focus();
      else document.querySelector('[data-audit-range="today"]').focus();
      return true;
    }
    return false;
  }
  const pages = Math.max(1, Math.ceil(auditShownRows().length / AUDIT_PAGE_SIZE));
  const step = { ArrowLeft: -1, PageUp: -1, ArrowRight: 1, PageDown: 1 }[event.key];
  if (event.key === 'Escape') {
    event.preventDefault();
    if (!event.repeat) location.hash = '#/home';
    return true;
  }
  if (step && !audit.all) {
    event.preventDefault();
    const page = Math.min(pages, Math.max(1, audit.page + step));
    if (page !== audit.page) { audit.page = page; renderAuditPage(); }
    return true;
  }
  return false;
}

/* =====================================================================
   Keyboard navigation
   Tab / Shift+Tab cycle through the page's controls and wrap at either
   end, so focus never leaves for the browser toolbar. Arrow keys move
   focus to the nearest control in that direction. Only interactive
   controls take part: headings and plain text are never focus stops.
   ===================================================================== */

const FOCUSABLE_SELECTOR = [
  'a[href]', 'button:not([disabled])', 'select:not([disabled])',
  'input:not([disabled]):not([type="hidden"])', 'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

// While a modal dialog is open, navigation is confined to it.
function navigationRoot() {
  return document.querySelector('dialog[open]') || document;
}

function focusableControls() {
  return [...navigationRoot().querySelectorAll(FOCUSABLE_SELECTOR)].filter(node =>
    !/^H[1-6]$/.test(node.tagName)
    && node.tabIndex >= 0                 // tabindex="-1" opts out, e.g. the read-only code fields
    && !node.closest('[hidden], [inert]')
    && node.getClientRects().length > 0);
}

function isTextEntry(node) {
  if (node.isContentEditable || node.tagName === 'TEXTAREA') return true;
  return node.tagName === 'INPUT' && !['button', 'checkbox', 'radio', 'submit', 'reset'].includes(node.type);
}

function moveFocusByTab(backwards) {
  const controls = focusableControls();
  if (controls.length === 0) return;
  const index = controls.indexOf(document.activeElement);
  let next;
  if (index === -1) next = backwards ? controls.length - 1 : 0;
  else next = (index + (backwards ? -1 : 1) + controls.length) % controls.length;
  controls[next].focus();
}

// True when ←/→ should leave this field rather than move its caret: the caret is at
// that end, or the whole text is selected (how a field looks on arriving by keyboard).
function caretAtEdge(field, key) {
  const { selectionStart: start, selectionEnd: end, value } = field;
  if (start == null) return true;         // no caret to move
  if (start === 0 && end === value.length) return true;
  if (start !== end) return false;
  return key === 'ArrowLeft' ? start === 0 : end === value.length;
}

// Typed text that matches a suggestion may have the browser's list open, and ↑/↓ pick from it.
function mayHaveOpenSuggestions(input) {
  if (!input.list) return false;
  const typed = input.value.trim().toLowerCase();
  const options = [...input.list.options].map(option => option.value.toLowerCase());
  return typed !== '' && !options.includes(typed) && options.some(option => option.includes(typed));
}

// Should this arrow key leave the text field it was pressed in?
function arrowLeavesField(event) {
  const field = event.target;
  const key = event.key;
  if (isLookupField(field)) return true;   // picked values only: no caret to move
  if (field.isContentEditable) return false;   // the PO remarks editor: arrows move its caret; Tab leaves
  if (key === 'ArrowLeft' || key === 'ArrowRight') return caretAtEdge(field, key);
  if (field.tagName === 'TEXTAREA') {
    // Only the browser knows the wrapped lines: if ↑/↓ did not move the caret, it was on the last line that way.
    const caret = field.selectionStart;
    setTimeout(() => {
      if (document.activeElement === field && field.selectionStart === caret && field.selectionEnd === caret) moveFocusByArrow(key);
    }, 0);
    return false;
  }
  return !mayHaveOpenSuggestions(field);
}

// Arrival by arrow: single-line text is selected, so typing replaces it and the next arrow moves on.
function focusByArrow(node) {
  if (node.tagName === 'TEXTAREA') node.focus(); else focusField(node);
}

// Gap from rect a to rect b along the arrow direction, or null if b is not in that direction.
function directionalGap(a, b, key) {
  const ax = (a.left + a.right) / 2, ay = (a.top + a.bottom) / 2;
  const bx = (b.left + b.right) / 2, by = (b.top + b.bottom) / 2;
  switch (key) {
    case 'ArrowRight': return bx > ax + 1 && b.right > a.right ? Math.max(0, b.left - a.right) : null;
    case 'ArrowLeft':  return bx < ax - 1 && b.left < a.left ? Math.max(0, a.left - b.right) : null;
    case 'ArrowDown':  return by > ay + 1 && b.bottom > a.bottom ? Math.max(0, b.top - a.bottom) : null;
    case 'ArrowUp':    return by < ay - 1 && b.top < a.top ? Math.max(0, a.top - b.bottom) : null;
    default: return null;
  }
}

// Distance across the arrow direction; 0 when the two boxes share a row (or column).
function crossGap(a, b, key) {
  const horizontal = key === 'ArrowLeft' || key === 'ArrowRight';
  const [aStart, aEnd, bStart, bEnd] = horizontal
    ? [a.top, a.bottom, b.top, b.bottom]
    : [a.left, a.right, b.left, b.right];
  return Math.max(0, bStart - aEnd, aStart - bEnd);
}

const ROW_TOLERANCE = 24;   // px: controls this close vertically count as one row

// Left/Right: nearest control on the same row; at a row's end, continue in reading order.
// Up/Down: nearest row above/below, then the control closest horizontally; stop at the edge.
function moveFocusByArrow(key) {
  const controls = focusableControls();
  if (controls.length === 0) return;
  const current = document.activeElement;
  if (!controls.includes(current)) { controls[0].focus(); return; }

  const from = current.getBoundingClientRect();
  const candidates = controls
    .filter(node => node !== current)
    .map(node => {
      const rect = node.getBoundingClientRect();
      return { node, rect, gap: directionalGap(from, rect, key) };
    })
    .filter(c => c.gap !== null);

  if (key === 'ArrowLeft' || key === 'ArrowRight') {
    const sameRow = candidates.filter(c => crossGap(from, c.rect, key) === 0);
    if (sameRow.length) {
      sameRow.sort((a, b) => a.gap - b.gap);
      focusByArrow(sameRow[0].node);
    } else {
      moveFocusByTab(key === 'ArrowLeft');
    }
    return;
  }

  if (candidates.length === 0) return;  // top or bottom edge: stay put
  const nearestRow = Math.min(...candidates.map(c => c.gap));
  const centerX = r => (r.left + r.right) / 2;
  const row = candidates.filter(c => c.gap <= nearestRow + ROW_TOLERANCE);
  row.sort((a, b) => Math.abs(centerX(a.rect) - centerX(from)) - Math.abs(centerX(b.rect) - centerX(from)));
  focusByArrow(row[0].node);
}

// Pull keyboard focus from the browser toolbar into the page on load, so the
// first Tab lands on the first control. #app has tabindex="-1": it can hold
// focus but is never a Tab or arrow stop itself.
function focusPageAnchor() {
  const app = byId('app');
  if (app.contains(document.activeElement) && document.activeElement !== app) return;
  window.focus();
  app.focus({ preventScroll: true });
}

// Shortcuts belong to this page only: they act while this tab has keyboard focus,
// and every key the page uses has its browser action cancelled (preventDefault).
// They use Ctrl, never Cmd, so macOS keeps its own Cmd shortcuts (Cmd+M, Cmd+Q …).
// Browsers keep a few keys for themselves (Ctrl+T, Ctrl+N, Ctrl+W, Ctrl+Tab), so
// the page never uses those.
function initKeyboardNavigation() {
  keepFullScreenOnEscape();
  focusPageAnchor();
  window.addEventListener('pageshow', focusPageAnchor);   // back/forward cache restores
  // Coming back to the window with nothing focused: give the keyboard to the page again.
  window.addEventListener('focus', () => {
    if (document.activeElement === document.body || !document.activeElement) focusPageAnchor();
  });

  const handleWindowKeys = event => {
    if (event.defaultPrevented || event.isComposing) return;   // IME composition: not a shortcut
    // The GRN Stock Transfer popup: Shift+X adds a row even while a stock point list is open (it closes first).
    if (byId('grn-transfer')?.open && event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === 'x') {
      closeSelectMenu();
      grnTransferKeys?.(event);
      event.stopPropagation();
      return;
    }
    // A dropdown list opened with Enter (openSelectMenu) takes every key while it is open.
    if (handleSelectMenuKeys(event)) {
      event.stopPropagation();
      return;
    }
    // Party › Under: ↓ opens its list (Creditors / Debtors) instead of moving to the next field.
    if (event.target.id === 'party-under' && event.key === 'ArrowDown' && !event.ctrlKey && !event.altKey && !event.metaKey && !event.shiftKey) {
      event.preventDefault();
      openSelectMenu(event.target);
      event.stopPropagation();
      return;
    }
    // An open styled dropdown (.fp-select-list) keeps focus on its options and handles its own keys.
    // After Enter picks an option of a dropdown that Enter opened (data-enter-opens), move on like a lookup pick.
    const openSelect = event.target.closest?.('select');
    if (openSelect && isOpenSelect(openSelect)) {
      if (event.key === 'Enter' && openSelect.dataset.enterOpens !== undefined && openSelect.closest('form')) {
        setTimeout(() => { if (!isOpenSelect(openSelect)) focusNextField(openSelect); }, 0);
      }
      return;
    }

    // The document preview page: B goes back, P / Ctrl+P prints; Esc closes it like any popup.
    if (byId('pb-preview').open) {
      handlePreviewKeys(event);
      event.stopPropagation();
      return;
    }
    // The company logo popup: its buttons, Tab and Esc work as usual, no page shortcuts.
    if (byId('company-icon').open) {
      event.stopPropagation();
      return;
    }
    // An open "Select …" popup takes every key; a lookup field's own keys come before the page's.
    if (byId('lookup').open) {
      handleLookupDialogKeys(event);
      event.stopPropagation();
      return;
    }
    if (byId('item-desc').open) {
      handleItemDescKeys(event);
      event.stopPropagation();
      return;
    }
    // The GRN Stock Transfer popup: its own keys (Shift+X, Enter, arrows); Tab and Esc work as usual.
    if (byId('grn-transfer')?.open) {
      grnTransferKeys?.(event);
      event.stopPropagation();
      return;
    }
    if (handleSuggestKeys(event) || handleLookupFieldKeys(event)) {
      event.stopPropagation();
      return;
    }

    if (byId('quick-item').open && handleQuickItemKeys(event)) {
      event.stopPropagation();
      return;
    }
    if (byId('quick-supplier').open && handleQuickSupplierKeys(event)) {
      event.stopPropagation();
      return;
    }
    if (byId('quick-contact').open && handleQuickContactKeys(event)) {
      event.stopPropagation();
      return;
    }

    // The open form's own keys (Esc, Shift+Enter, Enter …) come first, unless the menu is over it.
    const pageKeys = FORM_KEY_HANDLERS[currentPage];
    if (pageKeys && !byId('quick-menu').open && pageKeys(event)) {
      event.stopPropagation();
      return;
    }

    // Ctrl+D, dashboard letters M/P/T/E/R/S, and Esc / letter keys inside the quick menu.
    if (handleQuickMenuKeys(event)) {
      event.stopPropagation();
      return;
    }

    if (event.altKey || event.ctrlKey || event.metaKey) return;

    if (event.key === 'Tab') {
      event.preventDefault();
      moveFocusByTab(event.shiftKey);
      return;
    }

    if (event.shiftKey || !event.key.startsWith('Arrow')) {
      // Enter opens a focused dropdown (Space and Alt+Down already do natively).
      if (event.key === 'Enter' && !event.shiftKey && event.target.tagName === 'SELECT') {
        event.preventDefault();
        if (!event.repeat) openSelectMenu(event.target);
      }
      return;
    }
    if (event.target.closest('.fp-row') && (['INPUT', 'SELECT'].includes(event.target.tagName) || isRowActionButton(event.target))) return;  // handleTableArrows
    if (isTextEntry(event.target) && !arrowLeavesField(event)) return;  // the arrow moves the caret instead
    event.preventDefault();                 // also stops a closed <select> changing value
    moveFocusByArrow(event.key);
  };
  window.addEventListener('keydown', event => {
    handleWindowKeys(event);
    if (event.cancelBubble) finishEscape(event);   // stopped here: it never reaches the window's bubbling listener
  }, true);
}

// Shift+Enter saves the open form, from any field. Ctrl+S no longer saves; isBrowserSaveKey() lets the
// pages swallow it, so the browser's "Save page as" dialog does not open instead.
const isSaveKey = event => event.key === 'Enter' && event.shiftKey && !event.ctrlKey && !event.altKey && !event.metaKey;
const isBrowserSaveKey = event => (event.ctrlKey || event.metaKey) && !event.altKey && event.key.toLowerCase() === 's';

// ':open' (an open dropdown list) is recent: where the browser does not know it, matches() throws.
function isOpenSelect(select) {
  try { return select.matches(':open'); } catch { return false; }
}

// Name fields (input[data-upper]) hold capitals whatever the Caps Lock state; the caret stays where it was.
// Runs in the capture phase, before the forms record the edit for undo.
function initUppercaseFields() {
  document.addEventListener('input', event => {
    const field = event.target;
    if (!(field instanceof HTMLInputElement) || field.dataset.upper === undefined) return;
    const upper = field.value.toUpperCase();
    if (upper === field.value) return;
    const { selectionStart, selectionEnd } = field;
    field.value = upper;
    field.setSelectionRange(selectionStart, selectionEnd);
  }, true);
}

// Characters a field does not take are dropped as they are typed or pasted (the caret stays where it was):
//   inputmode="numeric"  digits (Decimal Allowed, Credit Days, Total Items, Capacity)
//   inputmode="decimal"  digits and one decimal point (amounts, rates, stock, discount, conversion factor)
//   inputmode="tel"      digits, spaces, + - ( ) (phone numbers)
//   data-letters         letters of any language, spaces and . ' - (person names, designations, cities)
// Record names and codes are not filtered: they hold digits and symbols ("BALL VALVE 1/2\" SS316").
const INPUT_FILTERS = {
  numeric: /[0-9]/,
  decimal: /[0-9.]/,
  tel: /[0-9+\-\s()]/,
  letters: /[\p{L}\p{M}\s.'-]/u,
};
function initInputFilters() {
  document.addEventListener('input', event => {
    const field = event.target;
    if (!(field instanceof HTMLInputElement) || field.type !== 'text' || isDateField(field)) return;
    const kind = field.dataset.letters !== undefined ? 'letters' : field.inputMode;
    const allowed = INPUT_FILTERS[kind];
    if (!allowed) return;
    const caret = field.selectionStart ?? field.value.length;
    let kept = '', removedBeforeCaret = 0, seenDot = false;
    [...field.value].forEach((char, index) => {
      let ok = allowed.test(char);
      if (ok && kind === 'decimal' && char === '.') { ok = !seenDot; seenDot = true; }   // one decimal point
      if (ok) kept += char;
      else if (index < caret) removedBeforeCaret += char.length;
    });
    if (kept === field.value) return;
    field.value = kept;
    field.setSelectionRange(caret - removedBeforeCaret, caret - removedBeforeCaret);
  }, true);
}

/* Esc never takes the browser out of full screen. Firefox-based browsers leave full screen on any Esc the page
   does not claim (preventDefault), and a popup closed by the browser's own Esc handling never claims it. So
   every Esc is claimed (finishEscape), after the page's own handlers: last on the way back up (window,
   bubbling), or straight after the page's key handler when that stopped the key there. A popup that nothing
   closed yet gets the browser's usual "cancel" (its own cancel handler still decides what closing means).
   The popups open when the key went down are noted first, so one Esc never closes two popups. */
let escapeOpenAtStart = [];
function keepFullScreenOnEscape() {
  window.addEventListener('keydown', event => {
    if (event.key === 'Escape') escapeOpenAtStart = [...document.querySelectorAll('dialog[open]')];
  }, true);
  window.addEventListener('keydown', finishEscape);
}
function finishEscape(event) {
  if (event.key !== 'Escape' || event.isComposing || escapeOpenAtStart === null) return;
  const before = escapeOpenAtStart;
  escapeOpenAtStart = null;                       // once per key press
  const handled = event.defaultPrevented;
  event.preventDefault();
  if (handled) return;
  const open = [...document.querySelectorAll('dialog[open]')];
  if (!open.length || open.length !== before.length || open.some((dialog, i) => dialog !== before[i])) return;
  const top = open.find(dialog => dialog.contains(document.activeElement)) || open[open.length - 1];
  if (top.dispatchEvent(new Event('cancel', { cancelable: true }))) top.close();
}

// On the form pages a field that takes focus scrolls into view with room below it for its dropdown
// (scroll-margin in the CSS), so the next field is never hidden under the bottom of the screen.
function initFocusScrolling() {
  document.addEventListener('focusin', event => {
    const field = event.target;
    if (!(field instanceof Element) || !field.matches('input, select, textarea') || !field.closest('.form-page')) return;
    field.scrollIntoView({ block: 'nearest' });
  });
}

// Re-rendering replaces buttons; keep focus on the equivalent control.
function refocusWithin(container, selector) {
  const target = container.querySelector(selector);
  if (target) target.focus();
}

/* =====================================================================
   Quick menu (Ctrl+D) and its sub-menus
   One <dialog>: the main view plus one view per card (and nested views
   such as Masters › Create). ↑/↓ move through the view's entries and Quit
   (wrapping), Home/End jump to the first/last, → or Enter opens the focused
   entry's sub-menu, ← steps back one level (to the entry it came from).
   Esc steps back too; from the main menu it closes the menu.
   The bold letter on each entry is its shortcut. On the dashboard, a
   main-menu letter alone (M P T E R S L) opens that sub-menu.
   Inside an open view, the plain letter or Alt + letter picks the entry.
   ===================================================================== */

let quickMenuReturnFocus = null;
let quickMenuView = 'main';
let quickMenuAltArmed = false;            // Alt is down and no other key has been pressed with it
// Either Alt key: on Linux and most non-US layouts the right one reports itself as AltGraph.
const isAltKey = key => key === 'Alt' || key === 'AltGraph';

function quickMenuViewEl(view) {
  return byId('quick-menu').querySelector(`.qm-view[data-view="${view}"]`);
}

function showQuickMenuView(view, focusSelector) {
  const menu = byId('quick-menu');
  quickMenuView = view;
  menu.dataset.view = view;               // lets CSS size the panel per view
  for (const section of menu.querySelectorAll('.qm-view')) section.hidden = section.dataset.view !== view;
  const current = quickMenuViewEl(view);
  menu.setAttribute('aria-labelledby', current.querySelector('.qm-title').id);
  current.querySelector('.qm-list').scrollTop = 0;
  if (!menu.open) return;
  const target = (focusSelector && current.querySelector(focusSelector)) || current.querySelector('.qm-list .qm-item');
  if (target) target.focus();
}

function openQuickMenu(view = 'main', focusSelector) {
  const menu = byId('quick-menu');
  if (!menu.open) {
    quickMenuReturnFocus = document.activeElement;
    document.documentElement.classList.add('has-modal');
    menu.showModal();
  }
  // Every view opens on its top entry (Create in sub-menus), unless told otherwise.
  showQuickMenuView(view, focusSelector);
}

function closeQuickMenu() {
  const menu = byId('quick-menu');
  if (menu.open) menu.close();            // 'close' handler restores focus
}

// One level up: a view's data-parent (e.g. Create Masters → Masters), else the main menu.
function quickMenuBack() {
  if (quickMenuView === 'main') { closeQuickMenu(); return; }
  const from = quickMenuView;
  const parent = quickMenuViewEl(from).dataset.parent || 'main';
  showQuickMenuView(parent, `[data-qm-open="${from}"]`);   // land on the entry we came from
}

// Shortcuts that work on the page (Ctrl+D, dashboard letters) or only
// while the menu is open (Esc, letters, Alt + letter). Returns true when handled.
function handleQuickMenuKeys(event) {
  const menu = byId('quick-menu');
  const plainCtrl = event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey;
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  if (!isAltKey(key)) quickMenuAltArmed = false;   // Alt + another key is a different shortcut

  if (plainCtrl && key === 'd') {          // replaces the browser's "bookmark page"
    event.preventDefault();
    if (event.repeat) return true;         // held down: act once, swallow the repeats
    if (menu.open) closeQuickMenu(); else openQuickMenu('main');
    return true;
  }
  // On the dashboard, a main-menu letter on its own (M P T E R S L) opens that sub-menu.
  // Not while typing in a field, and not on form pages, where letters are text.
  const noModifiers = !event.ctrlKey && !event.metaKey && !event.altKey && !event.shiftKey;
  const opener = !menu.open && currentPage === 'dashboard' && noModifiers && key.length === 1
    && !isTextEntry(event.target)
    && quickMenuViewEl('main').querySelector(`[data-qm-open][data-key="${CSS.escape(key)}"]`);
  if (opener) {
    event.preventDefault();
    if (!event.repeat) openQuickMenu(opener.dataset.qmOpen);
    return true;
  }
  // Alt on its own (pressed and released) opens this sub-menu's Create; see handleQuickMenuAltUp.
  // Checked before the Ctrl test: on Windows the right Alt (AltGr) arrives with ctrlKey set.
  if (menu.open && isAltKey(key) && !event.shiftKey && quickMenuViewEl(quickMenuView).querySelector('[aria-keyshortcuts="Alt"]')) {
    event.preventDefault();
    if (!event.repeat) quickMenuAltArmed = true;
    return true;
  }
  if (!menu.open || event.ctrlKey || event.metaKey) return false;
  if (key === 'Escape' && !event.altKey && quickMenuView !== 'main') {
    event.preventDefault();                // stop the dialog closing; step back instead
    if (!event.repeat) quickMenuBack();    // holding Esc must not run through every level
    return true;
  }
  if (!event.altKey && !event.shiftKey && QUICK_MENU_NAV_KEYS.includes(key)) return handleQuickMenuArrows(event, key);
  // A plain letter, or Alt + letter ("Create (Alt)"), picks the entry with that bold letter.
  // Alt uses the physical key, since Option+letter on a Mac types a symbol.
  const letter = event.altKey
    ? (/^Key[A-Z]$/.test(event.code) ? event.code.slice(3).toLowerCase() : '')
    : (key.length === 1 ? key : '');
  if (letter && !event.shiftKey) {
    const item = quickMenuViewEl(quickMenuView).querySelector(`[data-key="${CSS.escape(letter)}"]`);
    if (item) {
      event.preventDefault();
      item.focus();
      item.click();
      return true;
    }
  }
  return false;
}

const QUICK_MENU_NAV_KEYS = ['ArrowDown', 'ArrowUp', 'ArrowLeft', 'ArrowRight', 'Home', 'End'];

// Arrow keys in the open menu. They stay on the view's entries (never the Back / Close buttons in its
// header, which Tab still reaches). Every arrow is handled here, so the page's own arrow navigation
// never takes over inside the menu.
function handleQuickMenuArrows(event, key) {
  event.preventDefault();
  const view = quickMenuViewEl(quickMenuView);
  const entries = [...view.querySelectorAll('.qm-list .qm-item, .qm-quit')].filter(node => node.getClientRects().length > 0);
  if (entries.length === 0) return true;
  const index = entries.indexOf(document.activeElement);
  if (key === 'ArrowRight') {               // open the focused entry's sub-menu (links open with Enter)
    const opener = index === -1 ? null : entries[index].closest('[data-qm-open]');
    if (opener && !event.repeat) opener.click();
    return true;
  }
  if (key === 'ArrowLeft') {
    if (quickMenuView !== 'main' && !event.repeat) quickMenuBack();
    return true;
  }
  const last = entries.length - 1;
  const next = {
    ArrowDown: index === -1 ? 0 : (index + 1) % entries.length,
    ArrowUp: index === -1 ? last : (index - 1 + entries.length) % entries.length,
    Home: 0,
    End: last,
  }[key];
  entries[next].focus();
  entries[next].scrollIntoView({ block: 'nearest' });
  return true;
}

// Fires on Alt release, so Alt + letter (the "Create (Alt)" entries) still works.
// preventDefault stops Firefox showing its menu bar.
function handleQuickMenuAltUp(event) {
  if (!isAltKey(event.key) || !quickMenuAltArmed) return;
  quickMenuAltArmed = false;
  event.preventDefault();
  const create = byId('quick-menu').open && quickMenuViewEl(quickMenuView).querySelector('[aria-keyshortcuts="Alt"]');
  if (create) create.click();
}

function initQuickMenu() {
  const menu = byId('quick-menu');
  window.addEventListener('keyup', handleQuickMenuAltUp, true);
  window.addEventListener('blur', () => { quickMenuAltArmed = false; });
  menu.addEventListener('close', () => {
    // Chromium can deliver 'close' (after Esc) late; if a shortcut has already
    // reopened the menu, this event is stale and must not reset it.
    if (menu.open) return;
    document.documentElement.classList.remove('has-modal');
    showQuickMenuView('main');             // next Ctrl+D starts on the main menu
    // 'close' can arrive after an entry has opened a page and focused its first field: keep that focus.
    const active = document.activeElement;
    const pageTookFocus = active && active !== document.body && active !== byId('app') && !menu.contains(active);
    if (!pageTookFocus) {
      const target = quickMenuReturnFocus && document.contains(quickMenuReturnFocus) ? quickMenuReturnFocus : byId('app');
      target.focus({ preventScroll: true });
    }
    quickMenuReturnFocus = null;
  });

  menu.addEventListener('click', event => {
    // A click on the backdrop lands on the <dialog> itself, outside its box.
    if (event.target === menu) {
      const r = menu.getBoundingClientRect();
      const inside = event.clientX >= r.left && event.clientX <= r.right && event.clientY >= r.top && event.clientY <= r.bottom;
      if (!inside) closeQuickMenu();
      return;
    }
    const action = event.target.closest('[data-qm]')?.dataset.qm;
    if (action === 'close') { closeQuickMenu(); return; }
    if (action === 'back') { quickMenuBack(); return; }

    const opener = event.target.closest('[data-qm-open]');
    if (opener) { showQuickMenuView(opener.dataset.qmOpen); return; }

    // Module screens don't exist yet; the hash records where the user is heading.
    if (event.target.closest('a.qm-item')) {
      pageOriginView = quickMenuView;      // Esc on the page comes back to this view
      closeQuickMenu();
    }
  });
}

/* =====================================================================
   Toast (shared by every screen)
   ===================================================================== */

let toastTimer = 0;
function showToast(title, message, isError = false) {
  const toast = byId('toast');
  byId('toast-title').textContent = title;
  byId('toast-message').textContent = message;
  byId('toast-icon').textContent = isError ? '!' : '✓';
  toast.classList.toggle('is-error', isError);
  toast.classList.add('is-visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2600);
}

/* =====================================================================
   Shared by form pages
   ===================================================================== */

function clearFieldError(node) {
  node.classList.remove('is-invalid');
  node.removeAttribute('aria-invalid');
  node.removeAttribute('title');
}

function clearFormErrors(form) {
  for (const node of form.querySelectorAll('.is-invalid')) clearFieldError(node);
}

// Marks every failed field, then focuses and announces the first. errors: [{ node, message }]
function showFormErrors(errors, reveal) {
  for (const { node, message } of errors) {
    node.classList.add('is-invalid');
    node.setAttribute('aria-invalid', 'true');
    node.title = message;
  }
  reveal?.(errors[0].node);                // the field may be on another tab
  errors[0].node.focus();
  showToast('Check the highlighted fields', errors[0].message, true);
}

// Fields Enter walks through, in page order, ending on the Save button.
function formEnterOrder(form, saveButton) {
  const fields = [...form.querySelectorAll('input:not([readonly]):not([disabled]):not([type="file"]), select:not([disabled]), textarea, [contenteditable="true"]')]
    .filter(node => node.dataset.enterSkip === undefined)
    .filter(node => !(node.dataset.enterSkipFilled !== undefined && lookupIdInput(node)?.value))   // e.g. a name the picked code filled
    .filter(node => node.getClientRects().length > 0 && !node.closest('[inert]'))   // e.g. the party form before Under is chosen
    .filter(node => !childLookupIsEmpty(node));
  return [...fields, saveButton];
}

// A child lookup (Subcategory under Category, Rack / Bin under Stock Point) has nothing to pick while its
// parent is empty, or when the parent's choice has no child rows (known once that list has loaded):
// Enter passes it by. Tab, arrows and clicks still reach it.
function childLookupIsEmpty(node) {
  const parent = isLookupField(node) ? lookupParentField(node) : null;
  if (!parent) return false;
  const parentId = lookupIdInput(parent)?.value;
  if (!parentId) return true;
  const rows = lookupCache[node.dataset.lookup];
  const key = LOOKUPS[node.dataset.lookup].parentKey;
  return Array.isArray(rows) && !rows.some(row => String(row[key]) === parentId);
}

// The stop after node in an Enter order. A field Enter skips (data-enter-skip) is not in the order
// itself, so from there Enter goes to the first stop after it on the page.
function fieldAfter(order, node) {
  const index = order.indexOf(node);
  if (index !== -1) return order[index + 1];
  return order.find(other => other && node.compareDocumentPosition(other) & Node.DOCUMENT_POSITION_FOLLOWING);
}

// Today as a date input holds it (YYYY-MM-DD), in local time.
function todayInputValue() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}

/* ---------- Date fields ----------
   Every <input type="date"> becomes a typed DD/MM/YYYY field: the browsers' own date boxes move between
   day, month and year differently (Safari hardly at all). Digits fill the day, then the month, then the
   year, and the slashes appear by themselves: 13052026 → 13/05/2026. A first digit that cannot start a
   two-digit day (4–9) or month (2–9) moves on at once (5 → 05/), and / . - or a space ends a part early
   (1/ → 01/). On leaving the field a missing year becomes this year and a two-digit year 20xx.
   The field's .value stays YYYY-MM-DD ('' until it is a real date), so the forms read, set, compare and
   save dates exactly as before. The calendar button, Alt+↓ or F4 opens the browser's date picker. */

const NATIVE_VALUE = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value');
const isDateField = node => node?.dataset?.date !== undefined;
const typedDate = input => NATIVE_VALUE.get.call(input);

// "2026-05-13" → "13/05/2026" ('' for anything else).
function isoToDisplay(iso) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso ?? ''));
  return match ? `${match[3]}/${match[2]}/${match[1]}` : '';
}
// "13/05/2026" → "2026-05-13"; '' while it is not a real date (31/02/2026, a year still being typed …).
function displayToIso(text) {
  const match = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(text ?? '').trim());
  if (!match) return '';
  const [day, month, year] = [Number(match[1]), Number(match[2]), Number(match[3])];
  const date = new Date(year, month - 1, day);
  date.setFullYear(year);                    // years below 100 are not 19xx
  if (year < 1000 || date.getMonth() !== month - 1 || date.getDate() !== day) return '';
  return `${match[3]}-${match[2]}-${match[1]}`;
}

// Typed text → "DD/MM/YYYY" so far, with the slash after each finished part.
function formatTypedDate(text) {
  const parts = [''];                        // day, month, year
  for (const char of text) {
    const index = parts.length - 1;
    if (/\d/.test(char)) {
      if (index === 2) { if (parts[2].length < 4) parts[2] += char; continue; }
      parts[index] += char;
      const single = parts[index].length === 1 && Number(char) > (index === 0 ? 3 : 1);   // 4–9 / 2–9: one digit only
      if (single) parts[index] = `0${char}`;
      if (parts[index].length === 2) parts.push('');
    } else if (/[/.\-\s]/.test(char) && index < 2 && parts[index].length === 1) {
      parts[index] = `0${parts[index]}`;    // "1/" → "01/"
      parts.push('');
    }                                        // anything else, or a separator after a finished part, is dropped
  }
  return parts.join('/');
}

// Leaving the field: pad the day and month, and supply the year (this year, or 20 + two digits).
function completeTypedDate(text) {
  const [day = '', month = '', year = ''] = text.split('/');
  if (!day || !month) return text;
  const fullYear = !year ? String(new Date().getFullYear()) : year.length === 2 ? `20${year}` : year;
  const pad = part => (/^[1-9]$/.test(part) ? `0${part}` : part);   // a lone 0 stays: the date check flags it
  return `${pad(day)}/${pad(month)}/${fullYear}`;
}

function enhanceDateField(input) {
  if (isDateField(input)) return;
  const stored = typedDate(input);
  input.type = 'text';
  input.dataset.date = '';
  input.dataset.check ??= 'date';
  input.inputMode = 'numeric';
  input.autocomplete = 'off';
  input.spellcheck = false;
  input.maxLength = 10;
  if (!input.placeholder) input.placeholder = 'DD/MM/YYYY';
  // .value is YYYY-MM-DD both ways; anything else written to it is shown as it is.
  Object.defineProperty(input, 'value', {
    configurable: true,
    get() { return displayToIso(typedDate(this)); },
    set(value) {
      const text = String(value ?? '');
      NATIVE_VALUE.set.call(this, /^\d{4}-\d{2}-\d{2}$/.test(text) ? isoToDisplay(text) : text);
    },
  });
  input.value = stored;

  const wrap = el('span', 'fp-date');
  input.before(wrap);
  const button = el('button', 'fp-date-btn');
  button.type = 'button';
  button.tabIndex = -1;
  button.title = 'Open the calendar (Alt+↓ or F4)';
  button.setAttribute('aria-label', 'Open the calendar');
  button.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="18" rx="2"></rect><path d="M16 2v4M8 2v4M3 10h18"></path></svg>';
  // The browser's picker, opened by the button: an invisible date input under the field.
  const picker = el('input', 'fp-date-picker');
  picker.type = 'date';
  picker.tabIndex = -1;
  picker.dataset.datePicker = '';
  picker.dataset.enterSkip = '';
  picker.setAttribute('aria-hidden', 'true');
  wrap.append(input, button, picker);

  const openPicker = () => {
    picker.value = input.value;
    try { picker.showPicker(); } catch { /* no picker in this browser: typing still works */ }
  };
  const takePick = event => {
    event.stopPropagation();                 // the form records the date field's change, not the picker's
    if (!picker.value || picker.value === input.value) return;
    input.value = picker.value;
    input.focus();
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  };
  picker.addEventListener('input', takePick);
  picker.addEventListener('change', takePick);
  button.addEventListener('mousedown', event => event.preventDefault());   // keep focus in the field
  button.addEventListener('click', openPicker);
  input.addEventListener('keydown', event => {
    if (event.key === 'F4' || (event.altKey && event.key === 'ArrowDown')) {
      event.preventDefault();
      event.stopPropagation();
      openPicker();
    }
  });
}

function initDateFields() {
  // Typing: reformat to DD/MM/YYYY and keep the caret after the same digit.
  document.addEventListener('input', event => {
    const input = event.target;
    if (!isDateField(input) || !event.inputType) return;            // our own events carry no inputType
    const text = typedDate(input);
    const caret = input.selectionStart ?? text.length;
    const digitsBefore = text.slice(0, caret).replace(/\D/g, '').length;
    let formatted = formatTypedDate(text);
    if (event.inputType.startsWith('delete')) formatted = formatted.replace(/\/$/, '');   // let Backspace remove a slash
    if (formatted === text) return;
    NATIVE_VALUE.set.call(input, formatted);
    let position = 0;
    for (let seen = 0; position < formatted.length && seen < digitsBefore; position += 1) if (/\d/.test(formatted[position])) seen += 1;
    if (formatted[position] === '/' && !event.inputType.startsWith('delete')) position += 1;
    input.setSelectionRange(position, position);
  }, true);
  // Leaving: finish the date before the field checks look at it (they listen later, without capture).
  document.addEventListener('focusout', event => {
    const input = event.target;
    if (!isDateField(input)) return;
    const text = typedDate(input);
    const complete = completeTypedDate(text);
    if (complete === text) return;
    NATIVE_VALUE.set.call(input, complete);
    input.dispatchEvent(new Event('input', { bubbles: true }));
  }, true);
  // form.reset() puts the raw default back: show it as a date again.
  document.addEventListener('reset', event => {
    setTimeout(() => { for (const input of event.target.querySelectorAll('[data-date]')) input.value = typedDate(input); }, 0);
  }, true);

  const selector = 'input[type="date"]:not([data-date-picker])';
  for (const input of document.querySelectorAll(selector)) enhanceDateField(input);
  // Rows added from templates (expiry dates, order dates).
  new MutationObserver(records => {
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (!(node instanceof Element)) continue;
        if (node.matches(selector)) enhanceDateField(node);
        for (const input of node.querySelectorAll(selector)) enhanceDateField(input);
      }
    }
  }).observe(document.body, { childList: true, subtree: true });
}

// A table cell counts as filled once it holds something other than its starting value.
const isCellFilled = cell => cell.value.trim() !== '' && cell.value !== cell.defaultValue;

function focusField(node) {
  node.focus();
  if (node.select) node.select();
}

// Moving on with Enter (or a pick / Esc in a popup): every dropdown opens straight away — a lookup field
// its "Select …" popup, a <select> its list, a type-to-search field (Unit …) all its rows, and a field with
// suggestions shows them. Tab, arrows and other focus moves only focus the field.
function enterField(node) {
  focusField(node);
  if (isLookupField(node)) openLookup(node, { byKeyboard: true });
  else if (node instanceof HTMLSelectElement) { if (hasDropdownChoices(node)) openSelectMenu(node); }
  else if (isSuggestField(node) && node.dataset.suggestTyped === undefined) openSuggest(node, { browse: true });   // data-suggest-typed: only once typing
  else if (node instanceof HTMLInputElement && node.list) showDropdown(node);
}

// Dropdowns on the forms: a <select>, or an input with a suggestion list (Inventory Status). Enter on one that
// has choices opens it (a <select> opens the select menu below; picking with Enter moves on). data-picker-open marks
// a dropdown that has been opened, until focus leaves it. A dropdown with nothing to choose just moves on.
function hasDropdownChoices(field) {
  if (field instanceof HTMLSelectElement) return [...field.options].some(option => option.value !== '' && !option.disabled);
  return field instanceof HTMLInputElement && Boolean(field.list?.options.length);
}
function showDropdown(field) {
  if (field instanceof HTMLSelectElement) return openSelectMenu(field);
  try { field.showPicker(); } catch { return false; }   // not supported: Space / Alt+↓ still open it
  field.dataset.pickerOpen = '';
  return true;
}
// Called on Enter: true when it opened the dropdown (the caller stays on the field).
function openDropdownOnEnter(field) {
  if (field instanceof HTMLSelectElement) return hasDropdownChoices(field) && openSelectMenu(field);
  if (field.dataset.pickerOpen !== undefined || !hasDropdownChoices(field)) return false;
  return showDropdown(field);
}
document.addEventListener('focusout', event => { if (event.target instanceof HTMLElement) delete event.target.dataset.pickerOpen; });

/* ---------- Select menu: the list a <select> opens on Enter ----------
   The browser's own picker cannot be opened from a key in every browser (Safari has no
   select.showPicker()), so Enter opens this list under the field instead. Focus stays on the
   <select>: ↑/↓, PgUp/PgDn, Home/End move the highlight, typing jumps to a matching option,
   Enter (or Space) picks it, Esc or Tab closes the list. Picking with Enter inside a form moves on
   to the next field, like a lookup pick. The mouse still opens the browser's own picker. */
const selectMenu = { select: null, node: null, options: [], active: -1, typed: '', typedAt: 0 };

function openSelectMenu(select) {
  closeSelectMenu();
  const options = [...select.options].filter(option => !option.hidden && !option.disabled);
  if (options.length === 0) return false;
  const node = document.createElement('ul');
  node.className = 'fp-suggest fp-select-menu';
  node.id = 'select-menu';
  node.setAttribute('role', 'listbox');
  node.replaceChildren(...options.map((option, index) => {
    const item = el('li', 'fp-suggest-item', option.textContent.trim() || option.value);
    item.id = `select-menu-option-${index}`;
    item.dataset.index = String(index);
    item.setAttribute('role', 'option');
    return item;
  }));
  // Keep focus on the select: mousedown would move it to the list.
  node.addEventListener('mousedown', event => {
    event.preventDefault();
    const item = event.target.closest('[data-index]');
    if (item) pickSelectMenu(Number(item.dataset.index), { advance: false });
  });
  (select.closest('dialog[open]') || document.body).append(node);
  Object.assign(selectMenu, { select, node, options, active: Math.max(0, options.indexOf(select.selectedOptions[0])), typed: '' });
  placeSelectMenu();
  select.setAttribute('aria-expanded', 'true');
  select.setAttribute('aria-controls', node.id);
  syncSelectMenuActive();
  return true;
}

function closeSelectMenu() {
  const { select, node } = selectMenu;
  if (!node) return;
  node.remove();
  select.removeAttribute('aria-expanded');
  select.removeAttribute('aria-controls');
  select.removeAttribute('aria-activedescendant');
  Object.assign(selectMenu, { select: null, node: null, options: [], active: -1 });
}

// Under the field (position: fixed, so table and card edges do not clip it), or above it when the window has no room below.
function placeSelectMenu() {
  const { select, node } = selectMenu;
  const box = select.getBoundingClientRect();
  const width = Math.max(box.width, 160);
  Object.assign(node.style, { position: 'fixed', zIndex: '1000', right: 'auto', width: 'auto', minWidth: `${width}px`, maxWidth: `${Math.max(width, 360)}px` });
  node.style.left = `${Math.max(8, Math.min(box.left, window.innerWidth - node.offsetWidth - 8))}px`;
  const below = window.innerHeight - box.bottom - 8;
  const height = Math.min(node.scrollHeight, 240);
  if (below >= height || below >= box.top) { node.style.top = `${box.bottom + 4}px`; node.style.bottom = 'auto'; }
  else { node.style.top = 'auto'; node.style.bottom = `${window.innerHeight - box.top + 4}px`; }
}

function syncSelectMenuActive() {
  const { select, node, active } = selectMenu;
  for (const item of node.children) {
    const on = Number(item.dataset.index) === active;
    item.classList.toggle('is-active', on);
    item.setAttribute('aria-selected', String(on));
    if (on) { select.setAttribute('aria-activedescendant', item.id); item.scrollIntoView({ block: 'nearest' }); }
  }
}

// Sets the select as a user's pick would (input + change, so the form records it for undo).
function pickSelectMenu(index, { advance }) {
  const { select, options } = selectMenu;
  const option = options[index];
  closeSelectMenu();
  if (!option) return;
  if (select.value !== option.value) {
    select.value = option.value;
    select.dispatchEvent(new Event('input', { bubbles: true }));
    select.dispatchEvent(new Event('change', { bubbles: true }));
  }
  // A change handler may already have moved focus (Party › Under goes straight to Name). Outside a form (the GRN
  // Stock Transfer popup) the popup moves on itself, on 'menu-advance'.
  if (advance && document.activeElement === select) {
    if (select.closest('form')) focusNextField(select);
    else select.dispatchEvent(new CustomEvent('menu-advance', { bubbles: true }));
  }
}

// Every key while the list is open. Returns true when handled.
function handleSelectMenuKeys(event) {
  const { select, options } = selectMenu;
  if (!select) return false;
  if (event.target !== select || !select.isConnected) { closeSelectMenu(); return false; }
  const { key } = event;
  if (event.ctrlKey || event.metaKey || event.altKey) {
    if (event.altKey && key === 'ArrowUp') { event.preventDefault(); closeSelectMenu(); return true; }
    closeSelectMenu();
    return false;
  }
  if (key === 'Shift') return true;
  const step = { ArrowDown: 1, ArrowUp: -1, PageDown: 8, PageUp: -8 }[key];
  const listKey = step || key === 'Escape' || key === 'Home' || key === 'End'
    || ((key === 'Enter' || key === ' ') && !event.shiftKey) || (key.length === 1 && key !== ' ');
  // Anything else (Tab, ←/→, Shift+Enter to save …) closes the list and does its usual job.
  if (!listKey) { closeSelectMenu(); return false; }
  event.preventDefault();
  if (key === 'Escape') { closeSelectMenu(); return true; }
  if (key === 'Enter' || key === ' ') {
    if (!event.repeat) pickSelectMenu(selectMenu.active, { advance: key === 'Enter' });
    return true;
  }
  const last = options.length - 1;
  if (step) selectMenu.active = Math.max(0, Math.min(last, selectMenu.active + step));
  else if (key === 'Home') selectMenu.active = 0;
  else if (key === 'End') selectMenu.active = last;
  else if (key.length === 1) {
    // Type to jump: letters typed quickly build a prefix; one letter again cycles through its options.
    const now = Date.now();
    selectMenu.typed = now - selectMenu.typedAt < 700 ? selectMenu.typed + key.toLowerCase() : key.toLowerCase();
    selectMenu.typedAt = now;
    const text = option => option.textContent.trim().toLowerCase();
    const cycling = [...selectMenu.typed].every(char => char === selectMenu.typed[0]);
    const prefix = cycling ? selectMenu.typed[0] : selectMenu.typed;
    const order = options.map((_, i) => (selectMenu.active + (cycling ? 1 : 0) + i) % options.length);
    const match = order.find(i => text(options[i]).startsWith(prefix));
    if (match !== undefined) selectMenu.active = match;
  }
  syncSelectMenuActive();
  return true;
}

document.addEventListener('focusout', event => { if (event.target === selectMenu.select) closeSelectMenu(); });
document.addEventListener('mousedown', event => { if (selectMenu.node && !selectMenu.node.contains(event.target)) closeSelectMenu(); }, true);
window.addEventListener('resize', closeSelectMenu);
window.addEventListener('hashchange', closeSelectMenu);
document.addEventListener('scroll', event => { if (selectMenu.node && !selectMenu.node.contains(event.target)) closeSelectMenu(); }, true);


/* =====================================================================
   API client  (backend/public/api/*.php, behind Caddy on the same origin)
   Success: { data }. Errors: { error, fields? } with 4xx/5xx. Writes send
   the session's CSRF token (from api/session.php) in X-CSRF-Token.
   ===================================================================== */

class ApiError extends Error {
  constructor(message, status = 0, fields = {}) {
    super(message);
    this.status = status;
    this.fields = fields;
  }
}

let csrfToken = null;
// login.html; once signed in, the dashboard opens on its home page.
function goToSignIn() {
  location.replace('login.html');      // signing in again opens the dashboard's home page
}
// Before anything loads: the signed-in user, or off to the sign-in page (null).
// The signed-in user's name (an employee's login: the employee's name): the Created By / Requested By of the documents
// made here: a new PR's Requested By, and the Salesman / Created By field of the PO, Quotation, Delivery Note, Purchase
// Return and Purchase Replacement, and a new supplier's / customer's Account Head. Those fields are read-only; an
// edit keeps the saved name. (form.reset() puts a
// field's default back, so the default is set.)
let signedInName = '';
function useSignedInName(user) {
  signedInName = String(user.fullName || user.username || '').trim();
  if (!signedInName) return;
  for (const id of ['po-salesman', 'qt-salesman', 'dn-salesman', 'prt-created-by', 'prp-created-by', 'party-sup-head', 'party-cus-head']) {
    const field = byId(id);
    if (!field) continue;
    const name = field.dataset.upper !== undefined ? signedInName.toUpperCase() : signedInName;
    if (field.value === field.defaultValue) field.value = name;
    field.defaultValue = name;
  }
  byId('pr-requested-by').defaultValue = signedInName;
  byId('pr-requested-by').value = signedInName;
}

async function checkSignedIn() {
  try {
    const session = await apiRequest('api/session.php');
    csrfToken = session.csrfToken;
    if (session.user) { pageCompany = session.user.company?.code ?? null; setUserAccess(session.user); return session.user; }
  } catch { /* server down: the sign-in page says so */ }
  goToSignIn();
  return null;
}
/* ---------- Company icon (header, #company-avatar) ----------
   A round icon with the company's first letter; the popup (#company-icon) uploads a logo (api/company-icon.php)
   that then takes the letter's place. Removing the logo brings the letter back. */
let companyIcon = null;   // { name, size, version } when a logo is uploaded
const companyLetter = () => (byId('app').querySelector('.brand-name').textContent.match(/[A-Za-z0-9]/)?.[0] || 'G').toUpperCase();

function renderCompanyIcon() {
  for (const box of [byId('company-avatar'), byId('company-icon-preview')]) {
    const letter = Object.assign(document.createElement('span'), { className: 'company-avatar-letter', textContent: companyLetter() });
    box.classList.toggle('has-logo', !!companyIcon);
    if (!companyIcon) { box.replaceChildren(letter); continue; }
    const img = new Image();
    img.alt = '';
    img.addEventListener('error', () => { box.replaceChildren(letter); box.classList.remove('has-logo'); });
    img.src = `api/company-icon.php?file=1&v=${companyIcon.version}`;
    box.replaceChildren(img);
  }
  byId('company-avatar').setAttribute('aria-label', companyIcon ? 'Company logo: change or remove it' : 'Company logo: upload one');
  byId('company-icon-name').textContent = companyIcon ? 'Logo uploaded' : 'No logo yet: the first letter is shown';
  byId('company-icon-upload').textContent = companyIcon ? 'Change logo' : 'Upload logo';
  byId('company-icon-remove').hidden = !companyIcon;
}

/* The logo with its plain background made transparent, as a PNG, so only the logo shows on the page.
   The background is the colour all four corners share; every pixel near that colour (inside letters too) becomes
   see-through, and the logo's soft edges fade into it instead of keeping a grey fringe. A logo whose corners
   differ (a photo, a full-bleed design) or are already transparent is sent as it is. Large logos are scaled down
   (they show at most 88 px tall), which also keeps the PNG well under the 2 MB limit. */
const LOGO_MAX_HEIGHT = 320;
const LOGO_MAX_WIDTH = 1280;
async function logoWithoutBackground(file) {
  let bitmap;
  try { bitmap = await createImageBitmap(file); } catch { return file; }
  const scale = Math.min(1, LOGO_MAX_HEIGHT / bitmap.height, LOGO_MAX_WIDTH / bitmap.width);
  const width = Math.max(1, Math.round(bitmap.width * scale));
  const height = Math.max(1, Math.round(bitmap.height * scale));
  const canvas = Object.assign(document.createElement('canvas'), { width, height });
  const context = canvas.getContext('2d', { willReadFrequently: true });
  context.drawImage(bitmap, 0, 0, width, height);
  bitmap.close?.();
  const pixels = context.getImageData(0, 0, width, height);
  const data = pixels.data;
  const at = (x, y) => (y * width + x) * 4;
  const corners = [at(0, 0), at(width - 1, 0), at(0, height - 1), at(width - 1, height - 1)];
  if (corners.some(i => data[i + 3] < 250)) return file;                       // already transparent
  const distance = (i, rgb) => Math.max(Math.abs(data[i] - rgb[0]), Math.abs(data[i + 1] - rgb[1]), Math.abs(data[i + 2] - rgb[2]));
  const background = [0, 1, 2].map(c => Math.round(corners.reduce((sum, i) => sum + data[i + c], 0) / 4));
  if (corners.some(i => distance(i, background) > 12)) return file;            // no single plain background
  const CLEAR = 14;     // this close to the background: fully see-through
  const SOLID = 70;     // this far: fully the logo; in between, the logo's anti-aliased edge
  for (let i = 0; i < data.length; i += 4) {
    const d = distance(i, background);
    if (d >= SOLID) continue;
    const alpha = d <= CLEAR ? 0 : (d - CLEAR) / (SOLID - CLEAR);
    if (alpha === 0) { data[i + 3] = 0; continue; }
    for (let c = 0; c < 3; c++) {                 // the edge colour without the background mixed into it
      data[i + c] = Math.max(0, Math.min(255, Math.round((data[i + c] - background[c] * (1 - alpha)) / alpha)));
    }
    data[i + 3] = Math.round(alpha * data[i + 3]);
  }
  context.putImageData(pixels, 0, 0);
  const png = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
  return png || file;
}

async function loadCompanyIcon() {
  try {
    const icon = await apiRequest('api/company-icon.php');
    companyIcon = icon ? { ...icon, version: Date.now() } : null;
  } catch { companyIcon = null; }
  renderCompanyIcon();
}

function initCompanyIcon() {
  const dialog = byId('company-icon');
  const picker = byId('company-icon-file');
  const error = message => { byId('company-icon-error').textContent = message || ''; byId('company-icon-error').hidden = !message; };
  const busy = on => { for (const button of dialog.querySelectorAll('[data-ci="upload"], [data-ci="remove"]')) button.disabled = on; };
  byId('company-avatar').addEventListener('click', () => {
    error('');
    renderCompanyIcon();
    dialog.showModal();
    byId('company-icon-upload').focus();
  });
  dialog.addEventListener('click', async event => {
    if (event.target === dialog) { dialog.close(); return; }      // a click on the backdrop
    const action = event.target.closest('[data-ci]')?.dataset.ci;
    if (action === 'close') dialog.close();
    if (action === 'upload') picker.click();
    if (action === 'remove') {
      error('');
      busy(true);
      try {
        await apiRequest('api/company-icon.php', { method: 'DELETE' });
        companyIcon = null;
        renderCompanyIcon();
        showToast('Logo removed', 'The company icon shows the first letter again.');
        byId('company-icon-upload').focus();
      } catch (problem) { error(problem.message); }
      busy(false);
    }
  });
  picker.addEventListener('change', async () => {
    const file = picker.files[0];
    picker.value = '';
    if (!file) return;
    error('');
    if (!['image/png', 'image/jpeg'].includes(file.type)) { error('The logo must be a PNG or JPG image.'); return; }
    if (file.size > 2 * 1024 * 1024) { error('The logo image must be at most 2 MB.'); return; }
    busy(true);
    try {
      const image = await logoWithoutBackground(file);
      const body = new FormData();
      body.append('icon', image, image === file ? file.name : 'icon.png');
      const icon = await apiRequest('api/company-icon.php', { method: 'POST', body });
      companyIcon = { ...icon, version: Date.now() };
      renderCompanyIcon();
      showToast('Logo saved', 'The company icon now shows your logo.');
    } catch (problem) { error(problem.message); }
    busy(false);
  });
}

async function signOut() {
  try { await apiRequest('api/login.php', { method: 'DELETE' }); } catch { /* signed out anyway below */ }
  location.replace('login.html');
}
async function loadCsrfToken() {
  csrfToken = (await apiRequest('api/session.php')).csrfToken;
  return csrfToken;
}

// options: { method, json (body to send as JSON), body (e.g. FormData) }. Resolves to the response's data.
// The company this page was opened for (set by checkSignedIn). Every request names it, so the server never
// answers with another company's records after a sign-in to that company in another tab.
let pageCompany = null;

async function apiRequest(url, { method = 'GET', json, body } = {}, retried = false) {
  const headers = { Accept: 'application/json' };
  if (pageCompany) headers['X-Company'] = pageCompany;
  if (json !== undefined) {
    headers['Content-Type'] = 'application/json';
    body = JSON.stringify(json);
  }
  if (method !== 'GET') headers['X-CSRF-Token'] = csrfToken ?? await loadCsrfToken();
  let response;
  try {
    response = await fetch(url, { method, headers, body, credentials: 'same-origin' });
  } catch {
    throw new ApiError('The server could not be reached. Check that the backend is running.');
  }
  let result = null;
  try { result = await response.json(); } catch { /* not JSON: handled below */ }
  const ownChange = response.headers.get('X-Data-Version');
  if (ownChange && typeof noteOwnChange === 'function') noteOwnChange(ownChange);   // sync.js
  // An expired session has a new token: fetch it and try once more.
  if (response.status === 403 && method !== 'GET' && !retried) {
    await loadCsrfToken();
    return apiRequest(url, { method, json, body: json === undefined ? body : undefined }, true);
  }
  // Signed out meanwhile (another tab, or the session ended): back to the sign-in page.
  if (response.status === 401) goToSignIn();
  // Signed in to another company in another tab: show that company here too, never its records under this name.
  if (response.status === 412 && pageCompany) location.reload();
  if (!response.ok || !result || !('data' in result)) {
    throw new ApiError(result?.error || `The server answered ${response.status}. Check that the backend is running.`, response.status, result?.fields || {});
  }
  // A saved (or deleted) document that moves stock: the item popups read the stock on hand afresh next time.
  if (method !== 'GET' && STOCK_MOVING_API.test(url)) forgetLookups('item', 'itemcode');
  return result.data;
}
const STOCK_MOVING_API = /api\/(grns|purchase-entries|delivery-notes|tax-invoices|stock-transfers|stock-adjustments|stock-reservations|sales-replacements|purchase-replacements|damage-restock)\.php/;

/* =====================================================================
   Lookup popups ("Select UOM", "Select Warehouse" …), one per foreign key
   in the data model (database model/Growth-Engine-Masters-HD.png):
     items.uom_id → uoms, items.category_id → categories,
     items.sub_category_id → sub_categories, items.brand_id → brands,
     items.warehouse_id → warehouses (stock points), items.rack_id → rack_bins,
     item_brands / item_brand_suppliers → brands, suppliers,
     uoms.conversion_base_id → uoms, supplier_brands → brands,
     and the country pickers on the supplier, customer and warehouse forms.

   A lookup field is <input data-lookup="KIND"> inside .fp-lookup-wrap; the
   chosen record's id goes into the hidden input beside it. The field
   cannot be typed into: a letter, Space, F4, Alt+↓, a click, or Enter while
   it is empty opens the popup (the letter starts the search). Backspace or
   Delete clears it. In the popup, type to search, ↑/↓ move, Enter picks,
   Esc closes. A field with data-lookup-parent (sub-category, rack) lists
   only the rows under the parent's choice.
   ===================================================================== */

// Countries are a fixed list, not a table; the record keeps the name (customers.country).
// Each carries its currency and calling code, which the forms fill in when the country is picked.
const COUNTRIES = [
// The last two numbers are the fewest and most digits a phone number has after the calling code
// (PHONE_DIGITS in backend/src/master_validation.php is the same list).
// Oman, the UAE and India come first (the usual ones); the rest follow.
  ['OM', 'Oman', 'OMR', '+968', 8, 8], ['AE', 'United Arab Emirates', 'AED', '+971', 8, 9], ['IN', 'India', 'INR', '+91', 10, 10],
  ['SA', 'Saudi Arabia', 'SAR', '+966', 8, 9], ['QA', 'Qatar', 'QAR', '+974', 8, 8], ['KW', 'Kuwait', 'KWD', '+965', 8, 8], ['BH', 'Bahrain', 'BHD', '+973', 8, 8],
  ['PK', 'Pakistan', 'PKR', '+92', 9, 10], ['EG', 'Egypt', 'EGP', '+20', 8, 10], ['JO', 'Jordan', 'JOD', '+962', 8, 9], ['TR', 'Türkiye', 'TRY', '+90', 10, 10],
  ['CN', 'China', 'CNY', '+86', 10, 11], ['JP', 'Japan', 'JPY', '+81', 9, 10], ['KR', 'South Korea', 'KRW', '+82', 8, 10], ['DE', 'Germany', 'EUR', '+49', 6, 11],
  ['IT', 'Italy', 'EUR', '+39', 6, 11], ['GB', 'United Kingdom', 'GBP', '+44', 9, 10], ['US', 'United States', 'USD', '+1', 10, 10],
].map(([code, name, currency, dial, min, max]) => ({ id: name, code, name, currency, dial, min, max }));
const countryNamed = name => COUNTRIES.find(country => country.name === name);

/* Phone fields: a calling-code dropdown (select[data-phone-code]) in front of the number. The code
   follows the country, Enter passes it by (data-enter-skip); ←, Tab or a click reach it to change it. */
function fillPhoneCodes(select) {
  select.replaceChildren(...COUNTRIES.map(country => {
    const option = el('option', '', country.dial);
    option.value = country.dial;
    option.dataset.country = country.name;           // shown beside the code in the open list
    return option;
  }));
}
// One stored value: "+968 9123 4455". A number typed with its own + code is kept as typed.
const joinPhone = (code, number) => {
  const digits = String(number ?? '').trim();
  if (!digits) return '';
  return digits.startsWith('+') ? digits : `${code} ${digits}`;
};
// "+91 94470 12345" → ['+91', '94470 12345']; a number without a known code keeps the fallback code.
function splitPhone(value, fallback) {
  const text = String(value ?? '').trim();
  const dial = [...COUNTRIES].sort((a, b) => b.dial.length - a.dial.length).find(country => text.startsWith(`${country.dial} `) || text === country.dial)?.dial;
  return dial ? [dial, text.slice(dial.length).trim()] : [fallback, text];
}
// A phone input's own calling-code dropdown (the select in the same .fp-phone).
const phoneCodeOf = input => input.closest('.fp-phone').querySelector('select[data-phone-code]');
// Shows a stored number in a phone input and its dropdown; a number without a known code takes fallbackDial.
function setPhoneField(input, value, fallbackDial) {
  const [code, number] = splitPhone(value, fallbackDial);
  phoneCodeOf(input).value = code;
  input.value = number;
}
// Forms' phone fields: phoneOf(input) is "+968 9123 4567" (code + number), putPhone(input, value) shows a stored
// number in the field and its code dropdown ('' clears the number and keeps the code).
const phoneOf = input => (input.closest('.fp-phone') ? readPhoneField(input) : input.value.trim());
function putPhone(input, value, fallbackDial = '+968') {
  if (!input.closest('.fp-phone')) { input.value = value || ''; return; }
  if (!String(value ?? '').trim()) { input.value = ''; return; }
  setPhoneField(input, value, phoneCodeOf(input).value || fallbackDial);
}
// The value to store: code + number. A short extension (data-allow-extension, e.g. 204) is kept without a code.
function readPhoneField(input) {
  const number = input.value.trim();
  if (input.dataset.allowExtension !== undefined && /^\d{1,5}$/.test(number)) return number;
  return joinPhone(phoneCodeOf(input).value, number);
}

/* ---------- Email and phone checks ----------
   Fields with data-check="email" or data-check="phone" are checked when the user leaves them (marked red,
   with a message) and again on Save; the server repeats the same checks.
   A phone number must have the digits its country uses after the calling code (COUNTRIES min / max).
   The code comes from the field's calling-code dropdown, a "+code" typed in the number itself, or the
   country field named by data-country-field. data-allow-extension also takes a short extension (204). */

// Why a phone number is not valid for its country ('' when it is). Spaces, dashes, dots and brackets are fine;
// one leading 0 (a trunk prefix: "+971 050 …") is ignored.
function phoneProblem(value, dial, { allowExtension = false } = {}) {
  let text = String(value ?? '').trim();
  if (!text) return '';
  let country = COUNTRIES.find(entry => entry.dial === dial) || null;
  if (text.startsWith('+')) {
    country = [...COUNTRIES].sort((a, b) => b.dial.length - a.dial.length).find(entry => text.startsWith(entry.dial)) || null;
    text = country ? text.slice(country.dial.length) : text.slice(1);
  }
  const digits = text.replace(/[\s\-().]/g, '');
  if (!/^\d+$/.test(digits)) return 'Use digits only (spaces and dashes are fine).';
  if (allowExtension && digits.length <= 5) return '';                 // an extension such as 204
  if (!country) return digits.length >= 6 && digits.length <= 15 ? '' : 'Enter 6 to 15 digits, or start with a country code such as +968.';
  const national = digits.length > country.max && digits.startsWith('0') ? digits.slice(1) : digits;
  if (national.length >= country.min && national.length <= country.max) return '';
  const range = country.min === country.max ? `${country.min} digits` : `${country.min} to ${country.max} digits`;
  return `Numbers in ${country.name} have ${range} after ${country.dial}.`;
}

const emailProblem = value => (!value.trim() || EMAIL.test(value.trim()) ? '' : 'Enter a valid email address, like name@company.com.');

// The calling code a phone field's number belongs to.
function phoneDialFor(field) {
  const code = field.closest('.fp-phone')?.querySelector('select[data-phone-code]');
  if (code) return code.value;
  const countryField = field.dataset.countryField && byId(field.dataset.countryField);
  return countryNamed(countryField?.value)?.dial || '';
}

// The message for a data-check field ('' when its value is fine or empty).
function fieldCheckProblem(field) {
  if (field.dataset.check === 'email') return emailProblem(field.value);
  if (field.dataset.check === 'date') return typedDate(field).trim() && !field.value ? 'Enter a real date as DD/MM/YYYY, e.g. 13/05/2026.' : '';
  if (field.dataset.check === 'phone') return phoneProblem(field.value, phoneDialFor(field), { allowExtension: field.dataset.allowExtension !== undefined });
  return '';
}

// Every failing data-check field of a form, for Save. Fields on the other side of the party form are skipped.
function fieldCheckErrors(form) {
  return [...form.querySelectorAll('[data-check]')]
    .filter(field => !field.disabled && !field.closest('[data-under][hidden]'))
    .map(field => ({ node: field, message: fieldCheckProblem(field) }))
    .filter(entry => entry.message);
}

function initFieldChecks() {
  document.addEventListener('focusout', event => {
    const field = event.target;
    if (!(field instanceof HTMLInputElement) || field.dataset.check === undefined) return;
    // Moving between a number and its own calling code is not leaving the field.
    if (event.relatedTarget && field.closest('.fp-phone')?.contains(event.relatedTarget)) return;
    const message = fieldCheckProblem(field);
    if (message) {
      field.classList.add('is-invalid');
      field.setAttribute('aria-invalid', 'true');
      field.title = message;
      const titles = { email: 'Check the email address', date: 'Check the date', phone: 'Check the phone number' };
      showToast(titles[field.dataset.check], message, true);
    } else if (field.classList.contains('is-invalid')) {
      clearFieldError(field);
    }
  });
}

/* A card for the popups without one of their own (Supplier, Currency): the name over "code • country", a tick circle. */
function plainLookupCard(config, row) {
  const cell = el('td', 'lk-card-cell');
  cell.colSpan = config.columns.length;
  const text = el('div', 'lk-card-text');
  const name = config.cardName ? config.cardName(row) : config.display(row);
  text.append(el('div', 'lk-card-name', name));
  // Under the name: the card's own line, else the popup's other columns (code, category, date …) joined with •.
  const meta = config.cardMeta ? config.cardMeta(row)
    : config.columns.map(([key, heading]) => {
      const value = row[key];
      if (value === undefined || value === null || String(value).trim() === '' || String(value) === String(name)) return '';
      // A bare count says what it counts: "2 Items", "1 Item".
      if (/^\d+$/.test(String(value).trim())) return `${value} ${Number(value) === 1 ? heading.replace(/s$/, '') : heading}`;
      return String(value);
    }).filter(Boolean).join(' • ');
  if (meta) text.append(el('div', 'lk-card-meta', meta));
  const tick = el('span', 'lk-card-tick');
  tick.setAttribute('aria-hidden', 'true');
  tick.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9.5"></circle><path d="m8 12.2 2.7 2.7L16 9.6"></path></svg>';
  cell.append(text, tick);
  return cell;
}

/* The item popups list each item as a card: the code, the name, the category; on the right the
   price and "Available Stock: 12 PIECES" (amber at none, green with stock). */
// A line of a document to a customer (Quotation, Sales Order, Delivery Note): its prices are selling prices.
const SALES_ROW_KINDS = ['qt', 'so', 'dn', 'ti', 'se', 'sr', 'rp', 'sales'];
const isSalesLine = node => SALES_ROW_KINDS.includes(node?.closest?.('[data-pb-row]')?.dataset.pbRow);
// The price an item is offered at on this line: the selling price to a customer, else the buying rate.
const itemLinePrice = (item, node) => (isSalesLine(node) ? item.sellingPrice : item.buyingRate);

function itemLookupCard(row) {
  // The stock on hand (GRNs, transfers, sales … counted: api/items.php stockOnHand), not the Item page's opening stock.
  const stock = pbNum(row.stockOnHand ?? row.availableStock);
  const td = el('td', 'lk-item');
  const main = el('div', 'lk-item-main');
  const top = el('div', 'lk-item-top');
  top.append(el('span', 'lk-item-code', row.code));
  main.append(top, el('div', 'lk-item-name', row.name));
  if (row.category) main.append(el('span', 'lk-item-cat', row.category));
  const side = el('div', 'lk-item-side');
  side.append(el('div', 'lk-item-price', pbMoney(pbNum(itemLinePrice(row, lookup.field)))),
    el('span', `lk-stock lk-stock-wide${stock > 0 ? ' has-stock' : ''}`, `Available Stock: ${pbQty(stock)}${row.unit ? ` ${row.unit.toUpperCase()}` : ''}`));
  td.append(main, side);
  return td;
}

