const MASTER_FORMS = [uomForm, brandForm, categoryForm, warehouseForm, partyForm];

/* =====================================================================
   Hash router: #/home (dashboard), the form pages in FORM_PAGES and the
   edit pages (#/masters/<list>/edit/<id>: the creation form in edit mode,
   see masterEditPage). Routes for screens not built yet fall back to the dashboard.
   ===================================================================== */

FORM_PAGES[ITEM_ROUTE] = { page: 'item', reset: resetItemForm, firstField: () => itemEl('name'), isEditing: () => itemEditing !== null };

let currentPage = 'dashboard';
let pageOriginView = null;                // quick-menu view the open page was launched from
let pendingMenuReturn = null;             // { view, focusSelector } to open once the dashboard is back
const routeTrail = [];                    // routes visited before the current one, oldest first
let currentRoute = null;
let routeGoingBack = false;               // the next route change is goBack(): do not add to the trail

// Esc (and the list pages' Back button): back to the page before this one, e.g. New Supplier → Supplier Master,
// Edit Item → Item Master. When the page before was the dashboard (or there is none, after a reload),
// back to the dashboard with the popup that opened the page.
function goBack() {
  while (routeTrail.length) {
    const previous = routeTrail.pop();
    if (previous === currentRoute) continue;
    if (previous === '' || previous === 'home') break;
    routeGoingBack = true;
    location.hash = `#/${previous}`;
    return;
  }
  leavePageToMenu();
}

// After a save, back to the master's list page with focus on the saved record's row, when the form was
// opened from that list (New … on the list page) or is an edit. A form opened from Masters › Create stays
// open for the next record instead: returns false and the caller resets the form.
function showSavedInList(route, code, { edited = false } = {}) {
  const fromList = routeTrail.at(-1) === route;
  if (!fromList && !edited) return false;
  const list = allLists().find(entry => entry.config.route === route);
  if (list) list.returnTo = code;
  if (fromList) {
    goBack();
  } else {                                 // an edit opened by a link: open its list in the form's place
    routeGoingBack = true;
    location.hash = `#/${route}`;
  }
  return true;
}

// Every list page: the masters and the Purchase Book documents.
const allLists = () => [...MASTER_LISTS, ...PURCHASE_LISTS];

// An edit route opens the list's creation form with the record (see the lists' edit()).
function masterEditPage(route) {
  const match = /^((?:masters|purchase-book|trade|entry|returns|supply)\/[a-z-]+)\/edit\/(\d+)$/.exec(route);
  const list = match && allLists().find(entry => entry.config.route === match[1]);
  if (!list) return null;
  const id = Number(match[2]);
  return {
    page: list.config.formPage,
    alwaysReset: true,                     // another record may be opened while this page is showing
    reset: () => list.config.edit(id),
    firstField: () => [...byId(`${list.config.formPage}-form`).querySelectorAll('input:not([readonly]):not([type="hidden"]):not([disabled]), select:not([disabled])')]
      .find(node => node.getClientRects().length > 0) || byId('app'),
  };
}

// Back to the dashboard with the popup that opened the page.
// After a reload or a pasted link there is no origin, so use the first view linking to this page.
function leavePageToMenu() {
  const href = `#/${location.hash.replace(/^#\/?/, '').replace(/\/+$/, '')}`;
  const selector = `a.qm-item[href="${CSS.escape(href)}"]`;
  const view = pageOriginView || byId('quick-menu').querySelector(selector)?.closest('.qm-view').dataset.view || 'main';
  // Staff: back to the cards of the page's module (no dashboard, no menu popup).
  if (isModuleLanding()) {
    const module = view.replace(/-create$/, '');
    location.hash = module && module !== 'main' ? `#/modules/${module}` : '#/home';
    return;
  }
  pendingMenuReturn = { view, focusSelector: selector };
  location.hash = '#/home';
}

function showPage(page) {
  currentPage = page;
  document.body.dataset.page = page;
  byId('dashboard-view').hidden = page !== 'dashboard';
  for (const section of document.querySelectorAll('.form-page')) section.hidden = section.id !== `${page}-page`;
}

function renderRoute() {
  const route = location.hash.replace(/^#\/?/, '').replace(/\/+$/, '');
  const cameFrom = currentRoute;
  if (routeGoingBack) routeGoingBack = false;
  else if (currentRoute !== null && currentRoute !== route) {
    routeTrail.push(currentRoute);
    if (routeTrail.length > 50) routeTrail.shift();
  }
  currentRoute = route;
  closeSuggest();
  if (!routeAllowed(route)) { showNoAccess(route); return; }   // User Setting: not allowed for this user
  const formPage = FORM_PAGES[route] || masterEditPage(route) || employeeEditPage(route) || userEditPage(route);
  if (formPage) {
    // A form left open in edit mode starts over as a new record.
    if (currentPage !== formPage.page || formPage.alwaysReset || formPage.isEditing?.()) {
      showPage(formPage.page);
      formPage.reset();
      formPage.firstField().focus();
      formPage.onShow?.();                 // e.g. the quotation opens its Buyer popup straight away
      formPage.opened?.();
      return;
    }
    formPage.firstField().focus();
    formPage.opened?.();
    return;
  }
  const wasElsewhere = currentPage !== 'dashboard';
  showPage('dashboard');
  // The module cards: staff's home page, and #/modules/<module> (a module's pages) for anyone.
  const moduleRoute = /^modules\/([a-z-]+)$/.exec(route);
  const cards = isModuleLanding() || Boolean(moduleRoute);
  byId('module-home').hidden = !cards;
  byId('dashboard-view').classList.toggle('mh-on', cards);
  byId('dashboard-view').classList.toggle('mh-sub', Boolean(moduleRoute));   // a module's pages: no header
  if (cards) {
    renderModuleHome(moduleRoute?.[1] || null);
    focusModuleHome(cameFrom);
    pageOriginView = null;
    pendingMenuReturn = null;
    return;
  }
  if (wasElsewhere && state.data) loadDashboard();      // back from a form or list: the figures may have changed
  if (route !== '' && route !== 'home') {
    history.replaceState(null, '', '#/home');
    currentRoute = 'home';
    showToast('Not built yet', `The screen for “${route}” is coming soon.`);
  }
  if (wasElsewhere) focusPageAnchor();    // first, so closing the popup returns focus here
  pageOriginView = null;
  if (pendingMenuReturn) {
    const { view, focusSelector } = pendingMenuReturn;
    pendingMenuReturn = null;
    openQuickMenu(view, focusSelector);
  }
}

/* =====================================================================
   Purchase Book  (Quick Menu › Purchase Book): Purchase Request, Quotation Request (RFQ),
   Purchase Order and Goods Receipt Note (GRN). Each is a createFormPage() form with item lines.

   A line's Item Code and Item Name are "Select Item" popups over the Item master; picking either fills the
   other, the item's brand and its unit. The popup's Create New Item (Alt+N) saves a new item and picks it.
   Selects with data-bind (row) or data-bind-id (header) show a hidden input that holds the value,
   so undo restores them even when their options load later (a row's brands, a supplier's contacts).
   Purchase orders and GRNs total their lines as the server does (backend/src/purchase_book.php):
   the Discount Amount is shared across the lines by value before tax; VAT is each line's VAT % on
   what is left, included in the prices or added on top (Include / Exclude VAT); Shipping is added last.
   Keys: Enter next field, Ctrl+S or Shift+Enter save, Alt+A add an item row, Alt+I create an item, Esc back.
   ===================================================================== */

const pbData = { items: new Map(), suppliers: new Map(), customers: new Map(), racks: [] };
const pbNum = value => {
  const number = parseFloat(String(value ?? '').replace(/,/g, ''));
  return Number.isFinite(number) ? number : 0;
};
const pbMoney = number => (Number.isFinite(number) ? number : 0).toFixed(3);
// Amounts as shown (not typed into a field): thousands separated, "1061720.000" → "1,061,720.000" (big INR / AED
// figures stay readable). groupDigits does it to every amount (digits with decimals) in a text; pbNum reads them back.
const groupDigits = text => String(text ?? '').replace(/(^|[^\w.,])(-?)(\d{4,})(\.\d+)(?![\w.])/g,
  (match, before, sign, whole, decimals) => `${before}${sign}${whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}${decimals}`);
const pbShow = number => groupDigits(pbMoney(number));
const pbQty = number => String(Math.round(number * 1000) / 1000);
const pbCell = (row, field) => row.querySelector(`[data-field="${field}"]`);

// The row templates share their item, unit and action cells (index.html keeps them once): every line's Action
// column has the Purchase Order's buttons, move up, move down and remove.
function composePurchaseTemplates() {
  const cells = id => [...byId(id).content.cloneNode(true).children];
  for (const id of ['pb-line-simple', 'pb-line-po', 'pb-line-grn', 'pb-line-sales', 'pb-line-so', 'pb-line-qt', 'pb-line-dn', 'pb-line-ti', 'pb-line-pe', 'pb-line-se', 'pb-line-sr', 'pb-line-rp', 'pb-line-prt', 'pb-line-prp',
    'pb-line-sa', 'pb-line-st', 'pb-line-rsv']) {
    const row = byId(id).content.firstElementChild;
    row.prepend(...cells('pb-cell-item'));
    const hidden = () => Object.assign(document.createElement('input'), { type: 'hidden' });
    const nameCell = row.querySelector('[data-field="itemName"]').closest('td');
    const nameHtml = hidden(); nameHtml.dataset.field = 'itemNameHtml';     // the Full Item Description's formatting (every line)
    nameCell.append(nameHtml);
    if (id === 'pb-line-grn') {
      const reason = Object.assign(document.createElement('input'), {
        type: 'text', className: 'fp-cell pb-reject-reason', maxLength: 300, autocomplete: 'off', hidden: true,
        placeholder: 'Rejection reason...', title: 'Why the rejected quantity was rejected, e.g. damaged goods, wrong grade, missing parts',
      });
      reason.dataset.field = 'rejectReason';
      reason.setAttribute('aria-label', 'Rejection reason');
      nameCell.append(reason);
    }
    if (['pb-line-po', 'pb-line-sales', 'pb-line-dn', 'pb-line-ti', 'pb-line-pe', 'pb-line-se', 'pb-line-sr', 'pb-line-rp', 'pb-line-prt', 'pb-line-prp', 'pb-line-st'].includes(id)) {          // priced lines keep the brand in the item name cell
      const brandCell = row.querySelector('[data-brand-cell]');
      const brandId = hidden(); brandId.dataset.field = 'brandId';
      const brandName = hidden(); brandName.dataset.field = 'brandName';
      nameCell.append(brandId, brandName);
      brandCell.remove();
    }
    const unitSlot = row.querySelector('[data-unit-cell]');
    if (row.hasAttribute('data-no-unit')) {          // the Stock Adjustment: no Unit column (the item's unit is kept)
      const unit = hidden(); unit.dataset.field = 'unit';
      const uomId = hidden(); uomId.dataset.field = 'uomId';
      nameCell.append(unit, uomId);
    } else if (unitSlot) unitSlot.replaceWith(...cells('pb-cell-unit'));
    else row.append(...cells('pb-cell-unit'));
    row.append(...cells('pb-cell-remove'));
    if (id === 'pb-line-po' || id === 'pb-line-pe' || id === 'pb-line-se') {
      // Purchase Order Unit: type to search, not a dropdown. The list shows only once a letter is typed ("k" → KG,
      // "p" → PCS, PACKET, PAIRS); no arrow; arriving selects the unit, so typing replaces it.
      const unit = row.querySelector('[data-field="unit"]');
      unit.dataset.suggestTyped = '';
      unit.dataset.selectOnFocus = '';
      unit.placeholder = 'Unit';
      row.querySelector('.pb-unit-chevron')?.remove();
    }
    // Purchase Book lines (PR, RFQ, PO, GRN): Enter passes the Unit by; it is picked by hand (the arrow keys or a click reach it).
    if (['pb-line-simple', 'pb-line-po', 'pb-line-grn'].includes(id)) {
      const unit = row.querySelector('[data-field="unit"]');
      if (unit) unit.dataset.enterSkip = '';
    }
  }
}


function fillSelect(select, options, placeholder) {
  const keep = select.value;
  select.replaceChildren(...(placeholder === undefined ? [] : [new Option(placeholder, '')]),
    ...options.map(option => new Option(option.label, String(option.value))));
  select.value = keep;
  if (select.value !== keep) select.value = '';
}

const boundHidden = select => (select.dataset.bindId
  ? byId(select.dataset.bindId)
  : select.closest('td').querySelector(`input[type="hidden"][data-field="${select.dataset.bind}"]`));

function syncBoundSelects(root) {
  for (const select of root.querySelectorAll('select[data-bind], select[data-bind-id]')) {
    const value = boundHidden(select).value;
    select.value = value;
    if (select.value !== value) select.value = '';
  }
}

// Cached master records the rows need: an item's brands, a supplier's contacts and currency.
function pbItem(id) {
  if (!pbData.items.has(id)) {
    pbData.items.set(id, apiRequest(`api/items.php?id=${id}`).catch(error => { pbData.items.delete(id); throw error; }));
  }
  return pbData.items.get(id);
}
function pbSupplier(id) {
  if (!pbData.suppliers.has(id)) {
    pbData.suppliers.set(id, apiRequest(`api/suppliers.php?id=${id}`).catch(error => { pbData.suppliers.delete(id); throw error; }));
  }
  return pbData.suppliers.get(id);
}

const itemBrands = item => {
  const seen = new Map();
  for (const source of item.sourcing || []) if (source.brandId && !seen.has(source.brandId)) seen.set(source.brandId, source.brandName);
  if (item.brandId && !seen.has(item.brandId)) seen.set(item.brandId, item.brandName);
  return [...seen].map(([value, label]) => ({ value, label }));
};

// The Brand lookup (PR / RFQ / GRN): locked, "Select an item first", until the row has an item.
function lockRowBrand(row, locked = !pbCell(row, 'itemId').value) {
  const brandInput = pbCell(row, 'brandName');
  if (!brandInput?.matches('.fp-lookup')) return;
  brandInput.disabled = locked;
  brandInput.placeholder = locked ? 'Select an item first' : 'Select brand...';
  brandInput.closest('.fp-input-wrap')?.classList.toggle('is-locked', locked);
}

function setRowBrands(row, item) {
  lockRowBrand(row);
  const select = row.querySelector('select[data-bind="brandId"]');
  if (!select) return;                   // the purchase order has no Brand column
  if (!item) {
    fillSelect(select, [], 'Select item first');
    select.disabled = true;
    return;
  }
  const brands = itemBrands(item);
  fillSelect(select, brands, brands.length ? 'Select brand' : 'No brand');
  select.disabled = brands.length === 0;
  select.value = pbCell(row, 'brandId').value;
  if (select.value !== pbCell(row, 'brandId').value) select.value = '';
}

function setRowRacks(row, warehouseId) {
  const select = row.querySelector('select[data-bind="rackId"]');
  if (!select) return;
  const racks = pbData.racks.filter(rack => String(rack.warehouseId) === String(warehouseId));
  fillSelect(select, racks.map(rack => ({ value: rack.id, label: rack.code })), '—');
  const hidden = pbCell(row, 'rackId');
  select.value = hidden.value;
  if (select.value !== hidden.value) { select.value = ''; hidden.value = ''; }
}

// Shows a row's selects from its hidden values (after undo, a fetched document, or a new row).
async function syncPurchaseRow(row, warehouseId) {
  syncBoundSelects(row);
  const itemId = pbCell(row, 'itemId').value;
  row.querySelector('[data-code-id]').value = itemId;
  row.dataset.itemApplied = itemId;
  setRowRacks(row, warehouseId);
  if (!itemId) { setRowBrands(row, null); return; }
  try {
    const item = await pbItem(itemId);
    if (pbCell(row, 'itemId').value !== itemId) return;
    setRowBrands(row, item);
    if (row.dataset.pbRow === 'dn') dnAutoStockPoint(row, item, false);   // lines copied in on Auto: the stock point with the most
  } catch { setRowBrands(row, null); }
}

// A Purchase Order line's buying price from the Item master: the sourcing line of the order's supplier (and the line's
// brand when one is picked), else the item's buying rate. With it, the brand that supplier's line names.
function poItemSource(item, row) {
  const supplierId = byId('po-supplier-id')?.value || '';
  const brandId = pbCell(row, 'brandId')?.value || '';
  const lines = (item.sourcing || []).filter(line => pbNum(line.cost) > 0);
  const ofSupplier = supplierId ? lines.filter(line => String(line.supplierId ?? '') === supplierId) : [];
  const line = (brandId && ofSupplier.find(entry => String(entry.brandId ?? '') === brandId)) || ofSupplier[0]
    || (brandId && lines.find(entry => String(entry.brandId ?? '') === brandId)) || null;
  return { cost: pbNum(line ? line.cost : item.buyingRate), brandId: line?.brandId ? String(line.brandId) : '', brandName: line?.brandName || '' };
}

// Fills a row from a picked item: code, name, brand list (one brand is picked for you, except where Brand is a
// popup), unit and cost.
async function applyPurchaseItem(form, row, itemId) {
  row.dataset.itemApplied = itemId;
  let item;
  try {
    item = await pbItem(itemId);
  } catch (error) {
    showToast('The item could not be loaded', error.message, true);
    return;
  }
  if (row.dataset.itemApplied !== itemId || !row.isConnected) return;
  pbCell(row, 'itemCode').value = item.code;
  row.querySelector('[data-code-id]').value = String(item.id);
  pbCell(row, 'itemName').value = item.name;
  pbCell(row, 'itemId').value = String(item.id);
  const brands = itemBrands(item);
  // The Brand popup (PR, RFQ, GRN) is the user's choice: nothing is picked for them, so Esc leaves it empty.
  // (Cleared when the item is picked, before this loads, so a brand picked meanwhile stays.)
  if (!pbCell(row, 'brandName')?.matches('.fp-lookup')) {
    pbCell(row, 'brandId').value = brands.length === 1 ? String(brands[0].value) : '';
    pbCell(row, 'brandName').value = brands.length === 1 ? brands[0].label : '';
  }
  const poSource = row.dataset.pbRow === 'po' ? poItemSource(item, row) : null;   // a purchase order line: its supplier's brand
  if (poSource?.brandId && !pbCell(row, 'brandId').value) {
    pbCell(row, 'brandId').value = poSource.brandId;
    pbCell(row, 'brandName').value = poSource.brandName;
  }
  setRowBrands(row, item);
  pbCell(row, 'uomId').value = item.uomId ? String(item.uomId) : '';
  pbCell(row, 'unit').value = item.unit || '';
  syncBoundSelects(row);
  // A quotation / sales order / delivery note line: the selling price; a purchase order line: its supplier's buying price.
  const offered = poSource ? poSource.cost : pbNum(itemLinePrice(item, row));
  const sales = isSalesLine(row) || !!poSource || ['prt', 'prp'].includes(row.dataset.pbRow);   // a new pick replaces the old item's price
  // A sales / purchase replacement line: the returned item's price is the Old Price, and the New Price too while the
  // same item goes back (a replacement item picked keeps its own price).
  const priceFields = !['rp', 'prp'].includes(row.dataset.pbRow) ? ['price', 'unitCost']
    : pbCell(row, 'replacementItemId').value ? ['oldPrice'] : ['oldPrice', 'price'];
  for (const field of priceFields) {
    const cell = pbCell(row, field);
    // A sales line always takes the picked item's selling price (never a price left from the item it had before).
    if (cell && offered > 0 && (sales || pbNum(cell.value) === 0)) cell.value = pbMoney(offered);
  }
  // The sales order's Buying Cost: what the item was last bought for (soBuyingPrice), the item's buying rate when it
  // was never bought.
  if (pbCell(row, 'buyingCost')) await soFillBuyingCost(row, item);
  if (form.spec.onItem) await form.spec.onItem(form, row, item);
  if (row.dataset.itemApplied !== itemId || !row.isConnected) return;
  if (row.dataset.pbRow === 'dn') dnAutoStockPoint(row, item, true);   // the delivery note line: where the most is in stock
  form.page.absorb();
  form.refresh();
}

/* An item's stock at each stock point (id → quantity): the opening stock of its sourcing lines there, added up. An
   item saved before stock was kept per line holds its total at its first line's stock point (else its own), as
   warehouse_stock() on the server counts it. */
function itemStockByPoint(item) {
  const stock = new Map();
  // The stock on hand at each stock point, from the documents (api/items.php stockByPoint).
  if (item.stockByPoint) {
    for (const [id, quantity] of Object.entries(item.stockByPoint)) stock.set(String(id), pbNum(quantity));
    return stock;
  }
  const lines = item.sourcing || [];
  const kept = lines.filter(line => line.openingStock !== null && line.openingStock !== undefined && line.openingStock !== '');
  if (kept.length) {
    for (const line of kept) {
      if (line.warehouseId) stock.set(String(line.warehouseId), (stock.get(String(line.warehouseId)) || 0) + pbNum(line.openingStock));
    }
  } else {
    const point = lines[0]?.warehouseId ?? item.warehouseId;
    if (point) stock.set(String(point), pbNum(item.availableStock));
  }
  return stock;
}

// A delivery note line's Stock Point: the one holding the most of its item (Auto when none has any). `replace` false
// leaves a stock point already chosen on the line as it is.
function dnAutoStockPoint(row, item, replace) {
  const select = pbCell(row, 'warehouseId');
  if (!select || (!replace && select.value)) return;
  let best = '';
  let most = 0;
  for (const [id, quantity] of itemStockByPoint(item)) {
    if (quantity > most && [...select.options].some(option => option.value === id)) { best = id; most = quantity; }
  }
  select.value = best;
}

/* The Sales Order line's Buying Cost when an item is picked: the price it was last bought for from a supplier
   (api/item-purchase-price.php: the newest Purchase Entry bill, else GRN unit cost, else purchase order price), from
   the order's supplier (one supplier) or the line's supplier (multi supplier) first, any supplier's otherwise. A
   multi-supplier line with no supplier yet takes the supplier it was bought from. The price is in OMR, as every
   purchase price; an item never bought keeps the Item master's buying rate. */
async function soFillBuyingCost(row, item) {
  const multi = typeof soIsMulti === 'function' && soIsMulti();
  const supplierId = multi ? pbCell(row, 'supplierId')?.value : byId('so-supplier-id')?.value;
  const itemId = String(item.id);
  let bought = null;
  try {
    bought = await apiRequest(`api/item-purchase-price.php?itemId=${encodeURIComponent(itemId)}${supplierId ? `&supplierId=${encodeURIComponent(supplierId)}` : ''}`);
  } catch { /* the Item master's rate below */ }
  if (pbCell(row, 'itemId').value !== itemId || !row.isConnected) return;
  const buying = pbCell(row, 'buyingCost');
  if (!bought) {
    if (pbNum(item.buyingRate) > 0) buying.value = pbMoney(pbNum(item.buyingRate));
    return;
  }
  if (multi && !pbCell(row, 'supplierId').value) {
    fillLookup(pbCell(row, 'supplierName'), { id: bought.supplierId, name: bought.supplierName });
    pbCell(row, 'supplierCurrency').value = bought.currency;
  }
  buying.value = pbMoney(pbNum(bought.rate));                 // purchase prices are in OMR (PRICES_IN_OMR), as the buying cost
}

// Lines copied into the sales order (from a quotation, or another document opened as a sales order) come without a
// buying cost: each line with an item and none yet gets the one picking the item would give.
async function soFillCopiedBuyingCosts(form) {
  const rows = form.page.rowsOf('items').filter(row => pbCell(row, 'itemId')?.value && !pbNum(pbCell(row, 'buyingCost')?.value));
  if (!rows.length) return;
  await Promise.all(rows.map(async row => {
    const item = await pbItem(pbCell(row, 'itemId').value).catch(() => null);
    if (item) await soFillBuyingCost(row, item);
  }));
  form.refresh();
  form.page.absorb();
}

/* ---------- Full Item Description popup (#item-desc; design/masters/item_description.png) ----------
   Every Purchase Book line (Purchase Request, Quotation Request, Purchase Order, GRN): a click, Enter, Space, F4,
   Alt+↓ or typing on an Item Name that holds an item opens this popup, never Select Item (the Item Code changes the
   item; an empty Item Name still opens Select Item). It has two pages of one fixed size:
   - View: the name with its formatting, Unit and Unit Price; Copy Name, Edit Name, Close (Enter).
   - Editing mode (Edit / Edit Name): Bold, Bold All, Red, Blue, Black and Plain over the name, and the line's Unit
     editable. Save & Apply (Ctrl+Enter, or Enter) renames the item in the Item master when the text changed, keeps
     the formatting on this document's line (printed on its PDF) and sets the line's unit. Cancel (Esc) leaves all as it was.

   Keys (itemDescMove): ←/→ along a row of buttons, ↑/↓ between the rows (close ✕ · Edit · name · Unit · buttons);
   in the name or Unit box ←/→ move the caret, and ↑/↓ leave it at its start / end. Enter presses the focused
   button, else Close / Save; Esc cancels editing, then closes; Ctrl+C copies the name; Ctrl+B bolds. */
const itemDesc = { field: null, row: null, form: null, itemId: '', item: null, editing: false, saving: false, range: null };
const idpEl = suffix => byId(`item-desc-${suffix}`);
const idpText = text => String(text ?? '').replace(/\s+/g, ' ').trim().toUpperCase();

// A Purchase Book line's Item Name cell with an Item master item in it.
const isItemDescField = field => field.dataset.field === 'itemName' && field.dataset.lookup === 'item'
  && Boolean(lookupCreateForm(field)) && Boolean(lookupIdInput(field)?.value);

// The line's formatted name, only while its text is still the item's name.
function itemDescHtml(row, name) {
  const html = pbCell(row, 'itemNameHtml')?.value || '';
  if (!html) return '';
  const box = document.createElement('div');
  box.append(remarksFragment(html));
  return idpText(box.textContent) === idpText(name) ? html : '';
}

const itemDescName = () => itemDesc.item?.name ?? itemDesc.field.value;

// The name in the view, with the line's formatting (the hidden plain box keeps the text for Copy's fallback).
function showItemDescName() {
  const name = itemDescName();
  idpEl('name').value = name;
  const html = itemDescHtml(itemDesc.row, name);
  idpEl('view').replaceChildren(html ? remarksFragment(html) : document.createTextNode(name));
}

function openItemDescription(field) {
  const dialog = byId('item-desc');
  if (dialog.open) return;
  const row = field.closest('.fp-row');
  const itemId = lookupIdInput(field).value;
  const form = lookupCreateForm(field);
  const lineNo = [...row.parentElement.rows].filter(other => other.matches('.fp-row')).indexOf(row) + 1;
  Object.assign(itemDesc, { field, row, form, itemId, item: null, editing: false, saving: false, range: null });
  idpEl('sub').textContent = `Line Item #${lineNo}`;
  showItemDescCode(pbCell(row, 'itemCode').value || '—');
  idpEl('unit').textContent = pbCell(row, 'unit')?.value || '—';
  showItemDescPrice(null);
  setItemDescEditing(false);
  showItemDescName();
  document.documentElement.classList.add('has-modal');
  dialog.showModal();
  idpEl('primary').focus();
  pbItem(itemId).then(item => {
    if (!dialog.open || itemDesc.itemId !== itemId) return;
    itemDesc.item = item;
    if (!itemDesc.editing) showItemDescName();
    showItemDescCode(item.code);
    if (!pbCell(row, 'unit')?.value) idpEl('unit').textContent = item.unit || '—';
    showItemDescPrice(item);
  }).catch(() => {});
}

// The item code, at the right of the Complete Item Name row (the card's head is hidden).
function showItemDescCode(code) {
  idpEl('code').textContent = `Code: ${code}`;
  idpEl('code-inline').textContent = `Code: ${code}`;
}

// Unit Price: the line's price (PO) or unit cost (GRN); lines without a price show the item's buying rate.
function showItemDescPrice(item) {
  const cell = pbCell(itemDesc.row, 'price') || pbCell(itemDesc.row, 'unitCost');
  idpEl('price-label').textContent = cell ? 'Unit Price' : 'Buying Rate';
  if (cell) idpEl('price').textContent = pbShow(pbNum(cell.value));
  else idpEl('price').textContent = item ? pbMoney(pbNum(item.buyingRate)) : '…';
}

// View ↔ editing mode: the toolbar, the editor, the tip and the Unit box show; Copy / Edit Name give way to Cancel.
function setItemDescEditing(editing) {
  itemDesc.editing = editing;
  idpEl('primary-label').textContent = itemDesc.saving ? 'Saving…' : editing ? 'Save & Apply' : 'Close';
  idpEl('primary-key').textContent = editing ? 'Ctrl+Enter' : 'Enter';
  idpEl('primary').disabled = itemDesc.saving;
  idpEl('error').hidden = true;
  for (const button of byId('item-desc').querySelectorAll('[data-idp="edit-name"]')) button.setAttribute('aria-pressed', String(editing));
  byId('item-desc').classList.toggle('is-editing', editing);
  const show = (suffix, on) => { idpEl(suffix).hidden = !on; };
  for (const suffix of ['mode', 'editor', 'tip', 'unit-hint', 'unit-input', 'cancel']) show(suffix, editing);
  for (const suffix of ['view', 'unit', 'edit', 'copy', 'edit-name']) show(suffix, !editing);
  idpEl('unit-label').textContent = editing ? 'Unit (editable)' : 'Unit';
}

// Edit / Edit Name: the editor starts with the line's name and formatting, the Unit box with its unit.
function startItemDescEdit() {
  const name = itemDescName();
  const html = itemDescHtml(itemDesc.row, name);
  const editor = idpEl('rich');
  editor.replaceChildren(html ? remarksFragment(html) : document.createTextNode(name));
  idpEl('unit-input').value = pbCell(itemDesc.row, 'unit')?.value || '';
  itemDesc.range = null;
  setItemDescEditing(true);
  updateItemDescCount();
  editor.focus();
  placeCaret(editor, false);
}

// The caret at the start (atStart) or the end of a box.
function placeCaret(box, atStart) {
  const range = document.createRange();
  range.selectNodeContents(box);
  range.collapse(atStart);
  const selection = getSelection();
  selection.removeAllRanges();
  selection.addRange(range);
}

function updateItemDescCount() {
  const count = idpText(idpEl('rich').textContent).length;
  idpEl('count').textContent = `${count} char${count === 1 ? '' : 's'}`;
}

function cancelItemDescEdit() {
  setItemDescEditing(false);
  showItemDescName();
  idpEl('primary').focus();
}

function closeItemDescription() {
  const dialog = byId('item-desc');
  if (!dialog.open) return;
  dialog.close();
  if (!byId('quick-menu').open && !byId('lookup').open) document.documentElement.classList.remove('has-modal');
  if (itemDesc.field && document.contains(itemDesc.field)) focusField(itemDesc.field);
}

async function copyItemDescName() {
  const name = itemDescName();
  try {
    await navigator.clipboard.writeText(name);
  } catch {
    const input = idpEl('name');
    input.hidden = false;
    input.select();
    const copied = document.execCommand('copy');
    input.hidden = true;
    if (!copied) { showToast('Could not copy', 'Select the name and copy it yourself.', true); return; }
  }
  showToast('Item name copied', name);
}

// Renames the item in the Item master, then shows the new name on every line holding it. Returns the saved item.
async function renameItemInMaster(itemId, name) {
  const saved = await apiRequest(`api/items.php?id=${itemId}`, { method: 'PUT', json: { itemName: name } });
  pbData.items.set(itemId, Promise.resolve(saved));
  forgetLookups('item', 'itemcode');
  for (const form of PURCHASE_FORMS) {
    if (!form.page) continue;
    let changed = false;
    for (const line of form.page.rowsOf('items')) {
      if (pbCell(line, 'itemId').value !== itemId) continue;
      pbCell(line, 'itemName').value = saved.name;
      pbCell(line, 'itemCode').value = saved.code;
      changed = true;
    }
    if (changed) form.page.absorb();      // the master changed, not the document: nothing to undo
  }
  return saved;
}

// The editor's name, cleaned as the remarks and kept on one line: { text, html } (html '' without formatting).
function itemDescEdited() {
  const box = document.createElement('div');
  box.append(remarksFragment(idpEl('rich').innerHTML));
  for (const br of box.querySelectorAll('br')) br.replaceWith(' ');
  for (const node of [...box.querySelectorAll('div, p, ul, ol, li, i, em, u')].reverse()) node.replaceWith(...node.childNodes, ' ');
  const walker = document.createTreeWalker(box, NodeFilter.SHOW_TEXT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) node.nodeValue = node.nodeValue.replace(/\s+/g, ' ').toUpperCase();
  const text = idpText(box.textContent);
  const formatted = Boolean(box.querySelector('b, strong, span[style]'));
  return { text, html: formatted ? box.innerHTML.trim() : '' };
}

// The Unit box's text as a Unit of Measure row: undefined (unchanged), null (cleared) or the row; false when unknown.
async function itemDescUnit() {
  const text = idpEl('unit-input').value.trim();
  const cell = pbCell(itemDesc.row, 'unit');
  if (!cell || sameText(text, cell.value)) return undefined;
  if (!text) return null;
  const units = await loadLookup('uom');
  const exact = units.find(unit => sameText(unit.name, text) || sameText(String(unit.code ?? ''), text));
  if (exact) return exact;
  const close = suggestMatches(LOOKUPS.uom, units, text.toLowerCase());
  return close.length === 1 ? close[0] : false;
}

// Save & Apply: the formatting (and unit) on this document's line; a changed text renames the item in the Item master.
async function saveItemDescRich() {
  if (!itemDesc.editing || itemDesc.saving) return;
  const { row, form, itemId } = itemDesc;
  const { text, html } = itemDescEdited();
  if (!text) { showItemDescError('Enter the item name.'); idpEl('rich').focus(); return; }
  if (text.length > 200) { showItemDescError('The item name can have at most 200 characters.'); idpEl('rich').focus(); return; }
  const unit = await itemDescUnit();
  if (unit === false) {
    showItemDescError(`"${idpEl('unit-input').value.trim()}" is not in the Unit of Measure list. Type a unit such as PCS or KG.`);
    idpEl('unit-input').focus();
    return;
  }
  const renamed = idpText(text) !== idpText(itemDescName());
  if (renamed) {
    itemDesc.saving = true;
    setItemDescEditing(true);
    try {
      itemDesc.item = await renameItemInMaster(itemId, text);
    } catch (error) {
      itemDesc.saving = false;
      setItemDescEditing(true);
      showItemDescError(Object.values(error.fields || {})[0] || error.message);
      return;
    }
    itemDesc.saving = false;
  }
  if (!byId('item-desc').open || itemDesc.itemId !== itemId || !document.contains(row)) return;
  pbCell(row, 'itemNameHtml').value = html;
  if (unit !== undefined) {
    fillLookup(pbCell(row, 'unit'), unit);
    idpEl('unit').textContent = unit ? LOOKUPS.uom.display(unit) : '—';
  }
  form.page.record();
  setItemDescEditing(false);
  showItemDescName();
  idpEl('primary').focus();
  const changes = [renamed && 'renamed in the Item master', html ? 'formatting kept on this line' : '', unit !== undefined && 'unit changed'].filter(Boolean);
  showToast('Line item updated', `${itemDescName()}${changes.length ? ` · ${changes.join(', ')}` : ''}`);
}

// A line's item name for the View popup: bold, with the line's formatting when it has some.
function lineItemNameCell(line) {
  const name = el('strong', '', line.itemNameHtml ? '' : line.itemName || '—');
  if (line.itemNameHtml) name.append(remarksFragment(line.itemNameHtml));
  return name;
}

function showItemDescError(message) {
  idpEl('error').textContent = message;
  idpEl('error').hidden = false;
}

// The toolbar: Bold and the colours work on the highlighted text (with nothing highlighted, on the whole name);
// Bold All bolds the whole name; Plain removes all formatting.
function itemDescTool(tool, colour) {
  const editor = idpEl('rich');
  const selection = getSelection();
  // The highlighted text: the live selection in the editor (a click), else the one kept when a tool took the focus (keys).
  const live = selection.rangeCount && editor.contains(selection.anchorNode) ? selection.getRangeAt(0).cloneRange() : null;
  const kept = live || (itemDesc.range && editor.contains(itemDesc.range.commonAncestorContainer) ? itemDesc.range : null);
  editor.focus();
  if (kept) {
    selection.removeAllRanges();
    selection.addRange(kept);
  }
  const whole = tool === 'bold-all' || tool === 'plain' || selection.isCollapsed || !editor.contains(selection.anchorNode);
  if (whole) {
    const range = document.createRange();
    range.selectNodeContents(editor);
    selection.removeAllRanges();
    selection.addRange(range);
  }
  if (tool === 'plain') {
    editor.textContent = editor.textContent;
    placeCaret(editor, false);
  } else {
    document.execCommand('styleWithCSS', false, tool === 'colour');   // bold as <b>, colours as <span style="color">
    if (tool === 'colour') document.execCommand('foreColor', false, colour);
    else if (tool === 'bold-all') { if (!document.queryCommandState('bold')) document.execCommand('bold'); }
    else document.execCommand('bold');
  }
  itemDesc.range = selection.rangeCount ? selection.getRangeAt(0).cloneRange() : null;
  updateItemDescCount();
}

function itemDescAction(action, button) {
  if (itemDesc.saving) return;
  if (action === 'close') closeItemDescription();
  else if (action === 'copy') copyItemDescName();
  else if (action === 'primary') { if (!itemDesc.editing) closeItemDescription(); else saveItemDescRich(); }
  else if (action === 'cancel-edit') cancelItemDescEdit();
  else if (action === 'edit-name') { if (itemDesc.editing) cancelItemDescEdit(); else startItemDescEdit(); }
  else if (action === 'tool') itemDescTool(button.dataset.idpTool, button.dataset.colour);
}

// The popup's places for the arrow keys, as rows top to bottom (only the ones showing).
function itemDescRows() {
  const dialog = byId('item-desc');
  const shown = node => node && !node.hidden && node.getClientRects().length > 0;
  const rows = [
    [dialog.querySelector('.lk-close')],
    [idpEl('edit')],
    [...dialog.querySelectorAll('.idp-tools .idp-tool')],
    [idpEl('rich')],
    [idpEl('unit-input')],
    [...dialog.querySelectorAll('.idp-foot button')],
  ];
  return rows.map(row => row.filter(shown)).filter(row => row.length);
}

// Whether the caret in a text box / the editor is at its start or end (so ↑ / ↓ may leave it).
function caretAtEdge(box, end) {
  if (box instanceof HTMLInputElement) {
    const at = end ? box.value.length : 0;
    return box.selectionStart === at && box.selectionEnd === at;
  }
  const selection = getSelection();
  if (!selection.rangeCount || !selection.isCollapsed) return false;
  const range = selection.getRangeAt(0);
  const probe = document.createRange();
  probe.selectNodeContents(box);
  if (end) probe.setStart(range.endContainer, range.endOffset); else probe.setEnd(range.startContainer, range.startOffset);
  return probe.toString().trim() === '';
}

// Arrow keys between the popup's buttons and boxes. Returns true when the key moved the focus.
function itemDescMove(event) {
  const { key, target } = event;
  const rows = itemDescRows();
  const r = rows.findIndex(row => row.includes(target));
  if (r === -1) {                                   // nothing of ours focused: start on the main button
    if (!key.startsWith('Arrow')) return false;
    idpEl('primary').focus();
    return true;
  }
  const row = rows[r];
  const c = row.indexOf(target);
  const isBox = target === idpEl('rich') || target instanceof HTMLInputElement;
  if (key === 'ArrowLeft' || key === 'ArrowRight') {
    if (isBox) return false;                        // the caret moves
    const next = row[c + (key === 'ArrowRight' ? 1 : -1)];
    if (next) next.focus();
    return true;
  }
  if (key !== 'ArrowUp' && key !== 'ArrowDown') return false;
  const down = key === 'ArrowDown';
  if (isBox && !caretAtEdge(target, down)) return false;   // still inside the text: the caret moves
  const to = rows[r + (down ? 1 : -1)];
  if (!to) return true;
  // The nearest place on the next row: the main button going down to the buttons, else the same column.
  const pick = down && to.includes(idpEl('primary')) ? idpEl('primary') : to[Math.min(c, to.length - 1)];
  pick.focus();
  if (pick === idpEl('rich')) placeCaret(pick, down);
  else if (pick instanceof HTMLInputElement) pick.setSelectionRange(down ? 0 : pick.value.length, down ? 0 : pick.value.length);
  return true;
}

// Keys while the popup is open; it takes every key, so nothing reaches the form behind it.
function handleItemDescKeys(event) {
  const { key, target } = event;
  const ctrl = event.ctrlKey || event.metaKey;
  const typing = itemDesc.editing && (target === idpEl('rich') || target === idpEl('unit-input'));
  if (key === 'Escape') {
    event.preventDefault();
    if (event.repeat) return;
    if (itemDesc.editing) cancelItemDescEdit(); else closeItemDescription();
    return;
  }
  // Ctrl+Enter saves while editing (Enter too, but on a button Enter presses that button).
  if (key === 'Enter' && ctrl && itemDesc.editing) {
    event.preventDefault();
    if (!event.repeat) itemDescAction('primary');
    return;
  }
  if (key === 'Enter' && !event.altKey && !event.shiftKey && !ctrl) {
    if (target.tagName === 'BUTTON' && target !== idpEl('primary')) return;   // the focused button presses itself
    event.preventDefault();
    if (!event.repeat) itemDescAction('primary');
    return;
  }
  if (key === 'Enter') { event.preventDefault(); return; }   // no new lines in the name
  if (ctrl && key.toLowerCase() === 'b' && itemDesc.editing) {
    event.preventDefault();
    if (!event.repeat) itemDescTool('bold');
    return;
  }
  if (ctrl && ['i', 'u'].includes(key.toLowerCase()) && target === idpEl('rich')) { event.preventDefault(); return; }   // bold and colours only
  if (ctrl && key.toLowerCase() === 'c' && !typing) {
    event.preventDefault();
    if (!event.repeat) copyItemDescName();
    return;
  }
  if (ctrl && ['s', 'd', 'z'].includes(key.toLowerCase()) && !typing) { event.preventDefault(); return; }   // the form's shortcuts wait
  if (key.startsWith('Arrow') && !ctrl && !event.altKey && !event.shiftKey && itemDescMove(event)) event.preventDefault();
}

function initItemDescription() {
  const dialog = byId('item-desc');
  dialog.addEventListener('cancel', event => { event.preventDefault(); if (itemDesc.editing) cancelItemDescEdit(); else closeItemDescription(); });
  dialog.addEventListener('click', event => {
    if (event.target === dialog) { closeItemDescription(); return; }   // backdrop
    const tool = event.target.closest('[data-idp-tool]');
    if (tool) { itemDescAction('tool', tool); return; }
    const action = event.target.closest('[data-idp]')?.dataset.idp;
    if (action) itemDescAction(action);
  });
  // The toolbar keeps the highlighted text: a click on a tool does not take the focus from the editor.
  dialog.querySelector('.idp-tools').addEventListener('mousedown', event => { if (event.target.closest('[data-idp-tool]')) event.preventDefault(); });
  const editor = idpEl('rich');
  document.addEventListener('selectionchange', () => {
    const selection = getSelection();
    if (selection.rangeCount && editor.contains(selection.anchorNode)) itemDesc.range = selection.getRangeAt(0).cloneRange();
  });
  editor.addEventListener('input', () => { idpEl('error').hidden = true; updateItemDescCount(); });
  // Pasted text comes in plain and on one line.
  editor.addEventListener('paste', event => {
    event.preventDefault();
    const text = (event.clipboardData?.getData('text/plain') || '').replace(/\s+/g, ' ');
    document.execCommand('insertText', false, text);
  });
  idpEl('unit-input').addEventListener('input', () => { idpEl('error').hidden = true; });
}

// A document's lines (from a purchase request, quotation request or purchase order) into the item table. The
// item name's bold / colour (Full Item Description) belongs to the document it was made on: copied lines show the plain name.
async function loadPurchaseLines(form, lines, toRow) {
  form.page.setRows('items', lines.map(line => ({ ...toRow(line), itemNameHtml: '' })));
  const rows = form.page.rowsOf('items');
  await Promise.all(rows.map(row => syncPurchaseRow(row, form.warehouseId?.())));
  form.page.record();
}

const PB_VAT_RATE = 5;                              // the VAT % a line gets when VAT is enabled
// The documents whose line prices and totals are always in OMR; the Currency field is the party's (supplier's or
// customer's) currency, and the summary (and the PDF) also gives the Grand Total in it at the fixed SO_RATES_TO_OMR.
const PRICES_IN_OMR = ['po', 'pe', 'se', 'qt', 'so', 'dn', 'ti', 'sr', 'prt', 'rp', 'prp'];

/* Line maths, the same as pb_totals() on the server. */
function purchaseTotals(rows, kind, vatMode, discount, shipping) {
  const nets = rows.map(row => {
    const value = field => pbNum(pbCell(row, field)?.value);
    if (kind === 'grn') {
      const gross = value('acceptedQty') * value('unitCost');
      return gross - gross * value('discountPct') / 100;
    }
    const gross = pbCell(row, 'foc').value === 'Yes' ? 0 : value('quantity') * value('price');
    return Math.max(0, gross - value('discountAmount'));
  });
  const subtotal = nets.reduce((sum, net) => sum + net, 0);
  const shared = Math.min(discount, subtotal);
  let vat = 0;
  const lineTotals = rows.map((row, i) => {
    const rate = pbNum(pbCell(row, 'vatRate').value);
    const taxable = nets[i] - (subtotal > 0 ? shared * nets[i] / subtotal : 0);
    vat += vatMode === 'include' ? taxable * rate / (100 + rate) : taxable * rate / 100;
    return vatMode === 'include' ? nets[i] : nets[i] * (1 + rate / 100);
  });
  return { lineTotals, subtotal, vat, discount: shared, grand: subtotal - shared + (vatMode === 'exclude' ? vat : 0) + shipping };
}

/*
 * One Purchase Book form. spec: key, route, noun, api, firstField, kind ('simple' | 'po' | 'grn'),
 * header() → payload keys, check(check, errors) adds header errors, fieldNodes, onReset(), init(form),
 * extra (chips), lookups (dropped after a save).
 */
/* Grand Total (OMR): under the Financial Summary's Grand Total while the document is in another currency, converted at
   the fixed rates of SO_RATES_TO_OMR (the server's SB_RATES_TO_OMR). Not shown in OMR, nor for a currency without a rate.
   The documents in PRICES_IN_OMR the other way round: their prices and Grand Total are in OMR, and the row under it is
   that Grand Total in the party's currency. */
function showGrandInOmr(el, pricesInOmr = false) {
  const grand = el('grand');
  const currency = el('currency-id')?.value || 'OMR';
  if (!grand) return;
  if (pricesInOmr) { showGrandInSupplierCurrency(grand, currency); return; }
  const grandRow = grand.closest('div');
  let row = grandRow.parentElement.querySelector('.pb-sum-omr');
  if (!row) {
    row = document.createElement('div');
    row.className = 'pb-sum-omr';
    const label = document.createElement('dt');
    label.textContent = 'Grand Total (OMR)';
    row.append(label, document.createElement('dd'));
    grandRow.after(row);
  }
  const rate = SO_RATES_TO_OMR[currency];
  row.hidden = currency === 'OMR' || !rate;
  row.querySelector('dd').textContent = pbShow(pbNum(grand.textContent) * (rate || 0));
  row.title = rate ? `1 ${currency} = ${rate} OMR` : '';
}

function showGrandInSupplierCurrency(grand, currency) {
  const grandRow = grand.closest('div');
  let row = grandRow.parentElement.querySelector('.pb-sum-omr');
  if (!row) {
    row = document.createElement('div');
    row.className = 'pb-sum-omr';
    row.append(document.createElement('dt'), document.createElement('dd'));
    grandRow.after(row);
  }
  const rate = SO_RATES_TO_OMR[currency];
  row.hidden = currency === 'OMR' || !rate;
  const label = (grandRow.querySelector('.rp-grand-label') || grandRow.querySelector('dt')).textContent.replace(/\s*\([A-Z]{3}\)\s*$/, '');
  row.querySelector('dt').textContent = `${label} (${currency})`;
  row.querySelector('dd').textContent = pbShow(rate ? pbNum(grand.textContent) / rate : 0);
  row.title = rate ? `1 ${currency} = ${rate} OMR` : '';
}

function createPurchaseForm(spec) {
  const el = suffix => byId(`${spec.key}-${suffix}`);
  const form = { el, spec };
  const priced = spec.kind !== 'simple';
  const printBox = () => byId(`${spec.key}-form`).querySelector('.pb-print');
  const flags = () => ({
    includeSignatory: printBox().querySelector('[data-print-field="includeSignatory"]').checked,
    signatories: readSignatories(printBox()),
    attachSeal: printBox().querySelector('[data-print-field="attachSeal"]').checked,
  });
  const rows = () => form.page.rowsOf('items');
  const isBlankRow = row => !pbCell(row, 'itemName').value.trim() && !pbCell(row, 'itemId').value && !pbCell(row, 'itemCode').value.trim();
  const vatMode = () => el('vat-mode')?.value || 'include';

  // VAT Enabled / Disabled (the switch on the PO and GRN): on while any line has a VAT %.
  const vatRateText = rate => (spec.kind === 'po' ? rate.toFixed(2) : pbQty(rate));
  const vatOn = () => rows().some(row => pbNum(pbCell(row, 'vatRate')?.value) > 0);
  // Every line to 5% (on) or 0% (off); VAT is added on top of the line values.
  form.setVat = on => {
    el('vat-mode').value = 'exclude';
    for (const row of rows()) pbCell(row, 'vatRate').value = vatRateText(on ? PB_VAT_RATE : 0);
    form.refresh();
  };
  form.toggleVat = () => {
    form.setVat(!vatOn());
    form.page.record();
  };

  form.refresh = function refresh() {
    syncVatToggle();
    if (spec.kind === 'grn') rows().forEach(syncGrnRow);
    if (!priced) { spec.afterRefresh?.(); return; }
    const totals = purchaseTotals(rows(), spec.kind, vatMode(), pbNum(el('discount').value), pbNum(el('shipping').value));
    rows().forEach((row, i) => {
      const filled = !isBlankRow(row) || totals.lineTotals[i] > 0;
      row.querySelector('[data-total]').textContent = spec.kind === 'po' && !filled ? '—' : pbMoney(totals.lineTotals[i]);
    });
    el('subtotal').textContent = pbShow(totals.subtotal);
    el('vat').textContent = pbShow(totals.vat);
    el('grand').textContent = pbShow(totals.grand);
    if (el('grand-currency')) el('grand-currency').textContent = PRICES_IN_OMR.includes(spec.key) ? 'OMR' : el('currency-id')?.value || 'OMR';
    // The summary says what the VAT switch is set to: "VAT (5%)", "VAT (Disabled)", or the rates when lines differ.
    const filled = rows().filter(row => !isBlankRow(row));
    const rates = [...new Set((filled.length ? filled : rows()).map(row => pbNum(pbCell(row, 'vatRate').value)))];
    const vatNote = !vatOn() ? 'Disabled'
      : rates.length === 1 ? `${pbQty(rates[0])}%` : `${rates.filter(rate => rate > 0).map(rate => `${pbQty(rate)}%`).join(' / ')}`;
    const vatName = spec.kind === 'po' ? 'VAT' : 'Total VAT Amount';
    el('vat-label').textContent = `${vatName} (${vatNote}${vatMode() === 'include' && vatOn() ? ', included' : ''})`;
    spec.afterRefresh?.(totals);                      // the sales order's buying cost and profit
    showGrandInOmr(el, PRICES_IN_OMR.includes(spec.key));
  };

  function syncVatToggle() {
    const vatSwitch = byId(`${spec.key}-form`).querySelector('[data-vat-switch]');
    if (vatSwitch) {
      const on = vatOn();
      vatSwitch.setAttribute('aria-pressed', String(on));
      vatSwitch.querySelector('[data-vat-label]').textContent = on ? 'VAT Enabled' : 'VAT Disabled';
      vatSwitch.title = on ? `VAT Enabled: ${PB_VAT_RATE}% VAT on the line items. Click to set every line's VAT % to 0.`
        : `VAT Disabled: no VAT on the line items. Click to set every line's VAT % to ${PB_VAT_RATE}.`;
    }
    const toggle = byId(`${spec.key}-form`).querySelector('[data-vat-toggle]');
    if (!toggle) return;
    for (const button of toggle.querySelectorAll('[data-vat]')) button.setAttribute('aria-pressed', String(button.dataset.vat === vatMode()));
  }

  function readLines(errors) {
    const lines = [];
    rows().forEach((row, index) => {
      if (isBlankRow(row)) return;
      const value = field => pbCell(row, field)?.value.trim() ?? '';
      const line = {
        itemId: value('itemId') || null, itemCode: value('itemCode'), itemName: value('itemName'),
        brandId: value('brandId') || null, brandName: value('brandName'), uomId: value('uomId') || null, unit: value('unit'),
        itemNameHtml: value('itemNameHtml'),
      };
      const fail = (field, message) => errors.push({ node: pbCell(row, field), message: `Row ${index + 1}: ${message}` });
      if (spec.itemsFromMaster && !line.itemId) fail('itemName', 'pick an item from the Item master, or create one (Alt+N in the popup).');
      else if (!line.itemName) fail('itemName', 'enter the item name or pick an item.');
      if (spec.kind === 'grn') {
        Object.assign(line, {
          receivedQty: value('receivedQty'), acceptedQty: value('acceptedQty'), rejectedQty: value('rejectedQty'),
          rejectReason: pbNum(value('rejectedQty')) > 0 ? value('rejectReason') : '',
          expiryDate: value('expiryDate'), unitCost: value('unitCost'),
          vatRate: value('vatRate'), discountPct: value('discountPct'), transfers: grnTransfers(row),
        });
        const sent = line.transfers.reduce((sum, t) => sum + pbNum(t.quantity), 0);
        if (sent > pbNum(line.acceptedQty) + 0.0005) {
          fail('acceptedQty', `the stock transferred (${pbQty(sent)}) is more than the accepted quantity; open Transfer to change it.`);
        }
        if (!(pbNum(line.receivedQty) > 0)) fail('receivedQty', 'enter the received quantity.');
        else if (pbNum(line.acceptedQty) + pbNum(line.rejectedQty) > pbNum(line.receivedQty) + 0.0005) {
          fail('acceptedQty', 'accepted and rejected together cannot be more than received.');
        }
      } else {
        line.quantity = value('quantity');
        if (spec.zeroQty ? line.quantity === '' : !(pbNum(line.quantity) > 0)) {
          fail('quantity', spec.zeroQty ? 'enter the counted quantity (0 when none).' : 'the quantity must be more than 0.');
        }
      }
      if (spec.kind === 'po') {
        Object.assign(line, {
          price: value('price'), vatRate: value('vatRate'), discountPct: value('discountPct'),
          discountAmount: value('discountAmount'), foc: value('foc') === 'Yes',
        });
      }
      for (const extra of spec.lineExtras || []) line[extra] = value(extra);   // the sales lines' Delivery Term
      for (const [field, ok] of Object.entries(line)) {
        if (['quantity', 'receivedQty', 'acceptedQty', 'rejectedQty', 'price', 'unitCost', 'discountAmount'].includes(field)
          && ok !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(ok)) fail(field, 'enter a number with up to 3 decimals.');
        if (['vatRate', 'discountPct'].includes(field) && ok !== '' && (!/^\d{1,3}(\.\d{1,2})?$/.test(ok) || pbNum(ok) > 100)) {
          fail(field, 'enter a percentage from 0 to 100.');
        }
      }
      lines.push(line);
    });
    if (!lines.length && !errors.length) {
      errors.push({ node: pbCell(rows()[0], 'itemName'), message: 'Add at least one item.' });
    }
    return lines;
  }

  const extra = {
    read: () => ({ flags: flags(), chips: spec.chips ? spec.chips.get() : null }),
    write(state) {
      printBox().querySelector('[data-print-field="includeSignatory"]').checked = state.flags.includeSignatory;
      writeSignatories(printBox(), state.flags.signatories);
      printBox().querySelector('[data-print-field="attachSeal"]').checked = state.flags.attachSeal;
      if (spec.chips) { spec.chips.set(state.chips); spec.onChips?.(); }
    },
    reset() { writeSignatories(printBox(), PB_DEFAULT_SIGNATORIES); if (spec.chips) { spec.chips.set([]); spec.onChips?.(); } },
  };

  // Edit mode (#/purchase-book/<list>/edit/<id>): the saved document back in the form, once the
  // dropdowns it needs (suppliers, requests …) have loaded.
  async function fillDocument(record) {
    showRecordCode(el('code'), record.code);
    await form.ready;
    const formNode = byId(`${spec.key}-form`);
    spec.fill(form, record);
    el('remarks').value = record.remarks || '';
    formNode.querySelector('[data-print-field="includeSignatory"]').checked = Boolean(record.includeSignatory);
    writeSignatories(formNode.querySelector('.pb-print'), record.signatories || []);
    formNode.querySelector('[data-print-field="attachSeal"]').checked = Boolean(record.attachSeal);
    remarksEditor(form)?.show();
    if (priced) {
      el('vat-mode').value = record.vatMode || 'include';
      el('discount').value = pbMoney(pbNum(record.discountAmount));
      el('shipping').value = pbMoney(pbNum(record.shipping));
      syncVatToggle();
    }
    form.page.setRows('items', record.items.map(line => purchaseLineValues(spec.kind, line)));
    await Promise.all(rows().map(row => syncPurchaseRow(row, form.warehouseId?.())));
    await spec.afterFill?.(form, record);
    form.page.absorb();                       // the filled document is where undo stops
    form.refresh();
  }

  form.vatMode = vatMode;
  form.syncVatToggle = syncVatToggle;

  form.page = createFormPage({
    key: spec.key, route: spec.route, noun: spec.noun, api: spec.api, ctrlSave: true, lookups: spec.lookups, listRoute: spec.listRoute,
    afterCreate: record => printPurchaseDocument(spec, record.id),   // every new purchase document opens on its PDF preview
    firstField: () => spec.firstField(),
    opened: () => spec.opened?.(form),
    onShow: spec.onShow,
    setCode: () => showNextCode(el('code'), spec.api),
    lists: { items: { body: `${spec.key}-items`, template: spec.template, initial: 1, label: i => String(i + 1),
      // A row added while VAT is disabled starts at 0% (the first row of a new document keeps the template's 5%).
      defaults: () => (priced && rows().length > 0 && !vatOn() ? { vatRate: vatRateText(0) } : {}) } },
    addRowList: () => 'items',
    // Shift+X (or Alt+A): the new line's Select Item popup opens at once.
    afterRowShortcut(row) {
      const name = pbCell(row, 'itemName');
      if (!name?.matches('.fp-lookup')) return;
      name.focus();
      openLookup(name, { byKeyboard: true });
    },
    extra,
    extraFocus: () => spec.chips?.input,
    fieldNodes: {
      items: () => pbCell(rows()[0], 'itemName'),
      remarks: () => el('remarks'),
      signatories: () => printBox().querySelector('[data-signatories] input') || printBox().querySelector('[data-signatory="add"]'),
      ...Object.fromEntries(Object.entries(spec.fieldNodes || {}).map(([key, id]) => [key, () => byId(id)])),
    },
    refresh: () => form.refresh(),
    afterRestore() {
      syncBoundSelects(byId(`${spec.key}-form`));
      syncVatToggle();
      remarksEditor(form)?.show();
      for (const row of rows()) syncPurchaseRow(row, form.warehouseId?.());
      spec.afterRestore?.(form);
    },
    onReset() {
      for (const input of byId(`${spec.key}-form`).querySelectorAll('input[type="hidden"][id]')) input.value = '';
      if (el('vat-mode')) el('vat-mode').value = spec.vatDefault || 'include';
      syncVatToggle();
      remarksEditor(form)?.show();
      for (const row of rows()) syncPurchaseRow(row, form.warehouseId?.());
      form.ready = Promise.resolve(spec.onReset?.(form)).catch(() => {});
    },
    read() {
      const errors = [];
      const header = spec.header(form);
      spec.check?.(form, errors);
      const lines = readLines(errors);
      const payload = { ...header, ...flags(), remarks: el('remarks').value.trim(), items: lines };
      if (priced) Object.assign(payload, { vatMode: vatMode(), discountAmount: el('discount').value.trim() || '0', shipping: el('shipping').value.trim() || '0' });
      for (const id of ['discount', 'shipping']) {
        if (priced && el(id).value.trim() !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(el(id).value.trim())) {
          errors.push({ node: el(id), message: 'Enter an amount with up to 3 decimals.' });
        }
      }
      return { payload, errors };
    },
    fill: fillDocument,
    // Alt+I: Create Item (saved to the Item master and filled into the line).
    onKey(event) {
      if (!(event.altKey && !event.ctrlKey && !event.metaKey && event.code === 'KeyI')) return false;
      event.preventDefault();
      if (!event.repeat) openQuickItem(form);
      return true;
    },
    init() { initPurchaseForm(form); spec.init?.(form); },
  });
  return form;
}

function initPurchaseForm(form) {
  const { spec, el } = form;
  const formNode = el('form');
  const body = el('items');

  // The PDF print box: Include Signatory Slots, Attach Seal with Replace / Remove.
  const box = formNode.querySelector('.pb-print');
  box.append(byId('pb-print-box').content.cloneNode(true));
  box.querySelector('[data-print-field="includeSignatory"]').id = `${spec.key}-signatory`;
  box.querySelector('[data-print-field="attachSeal"]').id = `${spec.key}-seal`;
  // Add Signatory: one more named slot (its name field takes focus), and Include Signatory Slots is ticked.
  box.addEventListener('click', event => {
    if (event.target.closest('[data-signatory="add"]')) {
      const list = box.querySelector('[data-signatories]');
      if (list.children.length >= PB_MAX_SIGNATORIES) { showToast('Signatories', `At most ${PB_MAX_SIGNATORIES} signatories.`, true); return; }
      list.append(signatoryRow(null));
      box.querySelector('[data-print-field="includeSignatory"]').checked = true;
      list.lastElementChild.querySelector('input').focus();
      formNode.dispatchEvent(new Event('input', { bubbles: true }));     // recorded like any other change
      return;
    }
    const remove = event.target.closest('[data-signatory="remove"]');
    if (remove) {
      const row = remove.closest('li');
      const next = row.nextElementSibling || row.previousElementSibling;
      row.remove();
      (next?.querySelector('input') || box.querySelector('[data-signatory="add"]')).focus();
      formNode.dispatchEvent(new Event('input', { bubbles: true }));
    }
  });
  initRemarksEditor(form);

  // Before the form's own input handler records the change: keep hidden values and linked cells in step.
  formNode.addEventListener('input', event => {
    const target = event.target;
    if (target.matches('select[data-bind], select[data-bind-id]')) {
      boundHidden(target).value = target.value;
      if (target.dataset.bind === 'brandId') pbCell(target.closest('tr'), 'brandName').value = target.value ? target.selectedOptions[0].text : '';
      if (target.dataset.bind === 'uomId') pbCell(target.closest('tr'), 'unit').value = target.value ? target.selectedOptions[0].text : '';
    }
    const row = target.closest('.fp-row');
    if (!row) return;
    const field = target.dataset.field;
    // Item popups: a pick fills the whole row; clearing either cell (Backspace) clears the item.
    if (isLookupField(target) && (field === 'itemName' || field === 'itemCode')) {
      const id = lookupIdInput(target).value;
      if (pbCell(row, 'itemNameHtml') && id !== pbCell(row, 'itemId').value) pbCell(row, 'itemNameHtml').value = '';
      if (id) {
        // Fill the other cell at once from the popup's list (the full item loads after), so Enter can pass it by.
        const other = field === 'itemName' ? pbCell(row, 'itemCode') : pbCell(row, 'itemName');
        const picked = lookupCache[other.dataset.lookup]?.find(entry => String(entry.id) === id)
          || lookupCache[target.dataset.lookup]?.find(entry => String(entry.id) === id);
        if (picked) fillLookup(other, picked);
        // Another item: its Brand starts empty (PR, RFQ, GRN pick it in the popup; Esc leaves it empty).
        const brandCell = pbCell(row, 'brandName');
        if (brandCell?.matches('.fp-lookup') && id !== row.dataset.itemApplied) {
          brandCell.value = '';
          pbCell(row, 'brandId').value = '';
        }
        lockRowBrand(row, false);        // at once: Enter moves on from the item to Brand (and opens it), not past it
        applyPurchaseItem(form, row, id);
        // A pick by mouse leaves the cursor on the item: on to Brand and its popup, as Enter does (PR, RFQ, GRN).
        const brand = pbCell(row, 'brandName');
        if (['pr', 'rfq', 'grn'].includes(spec.key) && brand?.matches('.fp-lookup')) {
          setTimeout(() => {
            if (byId('lookup').open || !row.isConnected || brand.disabled) return;   // Enter already opened it
            if (document.activeElement !== target && document.activeElement !== document.body) return;
            focusField(brand);
            openLookup(brand, { byKeyboard: true });
          }, 0);
        }
      } else {
        for (const cell of [pbCell(row, 'itemCode'), pbCell(row, 'itemName')]) fillLookup(cell, null);
        for (const name of ['brandId', 'brandName', 'uomId', 'unit']) if (pbCell(row, name)) pbCell(row, name).value = '';
        row.dataset.itemApplied = '';
        setRowBrands(row, null);
        syncBoundSelects(row);
      }
    }
    linkRowNumbers(row, field);
  }, true);

  body.addEventListener('focusin', event => { form.lastRow = event.target.closest('.fp-row'); });

  // Numbers read as money / percentages once a cell is left.
  formNode.addEventListener('change', event => {
    const target = event.target;
    const field = target.dataset.field;
    if (target.value.trim() === '' || !/^[\d.,]+$/.test(target.value.trim())) return;
    const value = pbNum(target.value);
    if (['price', 'unitCost', 'discountAmount', 'buyingCost'].includes(field) || target.classList.contains('pb-sum-input')) target.value = pbMoney(value);
    else if (spec.kind === 'po' && ['vatRate', 'discountPct'].includes(field)) target.value = value.toFixed(2);
    else if (['quantity', 'receivedQty', 'acceptedQty', 'rejectedQty', 'vatRate', 'discountPct'].includes(field)) target.value = pbQty(value);
    else return;
    form.page.absorb();
    form.refresh();
  });

  formNode.addEventListener('click', event => {
    const vat = event.target.closest('[data-vat]');
    const vatSwitch = event.target.closest('[data-vat-switch]');
    if (vatSwitch) {
      form.toggleVat();
      return;
    }
    if (vat) {
      el('vat-mode').value = vat.dataset.vat;
      for (const button of vat.parentElement.querySelectorAll('[data-vat]')) button.setAttribute('aria-pressed', String(button === vat));
      form.page.record();
      return;
    }
    if (event.target.closest('[data-create-item]')) {
      openQuickItem(form);
      return;
    }
    const move = event.target.closest('[data-action="move-up"], [data-action="move-down"]');
    if (move) {
      const row = move.closest('tr');
      const up = move.dataset.action === 'move-up';
      const sibling = up ? row.previousElementSibling : row.nextElementSibling;
      if (!sibling) return;
      if (up) sibling.before(row); else sibling.after(row);
      form.page.record();
      move.focus();
    }
  });

  function linkRowNumbers(row, field) {
    const cell = name => pbCell(row, name);
    if (spec.kind === 'grn' && (field === 'receivedQty' || field === 'acceptedQty')) {
      // Rejected = Received - Accepted as either is typed. Accepted keeps its own value when Received changes (it is
      // not cut while Received is still being typed: "12" passes through "1"); Save refuses Accepted above Received.
      const received = pbNum(cell('receivedQty').value);
      if (field === 'acceptedQty' && pbNum(cell('acceptedQty').value) > received) cell('acceptedQty').value = pbQty(received);
      cell('rejectedQty').value = pbQty(Math.max(0, received - pbNum(cell('acceptedQty').value)));
      syncGrnRow(row);
    }
    if (spec.kind === 'po') {
      const gross = cell('foc').value === 'Yes' ? 0 : pbNum(cell('quantity').value) * pbNum(cell('price').value);
      if (['quantity', 'price', 'discountPct', 'foc'].includes(field)) cell('discountAmount').value = pbMoney(gross * pbNum(cell('discountPct').value) / 100);
      if (field === 'discountAmount') cell('discountPct').value = gross > 0 ? (pbNum(cell('discountAmount').value) / gross * 100).toFixed(2) : '0.00';
    }
  }
}

/* ---------- Formatted remarks (Purchase Order) ----------
   A contenteditable box with Bold / Italic / Underline, six colours plus a custom one, a bulleted list and Clear.
   Its HTML is kept in the hidden #<key>-remarks input, so undo, save and edit treat it like any other field.
   The server cleans it (pb_clean_html); the page cleans it again before showing it (cleanRemarksHtml). */
const REMARK_TAGS = new Set(['B', 'STRONG', 'I', 'EM', 'U', 'SPAN', 'FONT', 'BR', 'DIV', 'P', 'UL', 'OL', 'LI']);
const REMARK_DROP = new Set(['SCRIPT', 'STYLE', 'IFRAME', 'OBJECT', 'EMBED', 'TEMPLATE', 'SVG', 'MATH', 'HEAD', 'TITLE', 'META', 'LINK', 'FORM', 'INPUT', 'BUTTON', 'TEXTAREA', 'SELECT', 'IMG']);
const isRemarksHtml = text => /<\/?(b|strong|i|em|u|span|font|br|div|p|ul|ol|li)\b/i.test(String(text ?? ''));

function remarkColour(value) {
  const colour = String(value || '').trim().toLowerCase();
  if (/^#([0-9a-f]{3}|[0-9a-f]{6})$/.test(colour)) return colour;
  const rgb = /^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*[\d.]+\s*)?\)$/.exec(colour);
  return rgb ? `#${rgb.slice(1, 4).map(n => Math.min(255, Number(n)).toString(16).padStart(2, '0')).join('')}` : '';
}

// Remarks as safe nodes: formatted remarks keep only the tags above and a text colour; plain text keeps its line breaks.
function remarksFragment(text) {
  const fragment = document.createDocumentFragment();
  const value = String(text ?? '');
  if (!isRemarksHtml(value)) {
    value.split('\n').forEach((line, i) => { if (i) fragment.append(document.createElement('br')); fragment.append(document.createTextNode(line)); });
    return fragment;
  }
  const parsed = new DOMParser().parseFromString(`<body>${value}</body>`, 'text/html').body;
  const copy = (from, into) => {
    for (const node of from.childNodes) {
      if (node.nodeType === Node.TEXT_NODE) { into.append(document.createTextNode(node.nodeValue)); continue; }
      if (node.nodeType !== Node.ELEMENT_NODE || REMARK_DROP.has(node.tagName)) continue;
      if (!REMARK_TAGS.has(node.tagName)) { copy(node, into); continue; }
      const clean = document.createElement(node.tagName === 'FONT' ? 'span' : node.tagName.toLowerCase());
      const colour = remarkColour(node.style?.color || node.getAttribute('color'));
      if (colour) clean.style.color = colour;
      copy(node, clean);
      into.append(clean);
    }
  };
  copy(parsed, fragment);
  return fragment;
}
const cleanRemarksHtml = text => { const box = document.createElement('div'); box.append(remarksFragment(text)); return box.innerHTML; };

// The form's editor, or null for forms with a plain Remarks box.
function remarksEditor(form) {
  const area = byId(`${form.spec.key}-remarks-editor`);
  if (!area) return null;
  return {
    area,
    // Hidden value → editor (after reset, fill and undo).
    show() { area.replaceChildren(remarksFragment(form.el('remarks').value)); },
    // Editor → hidden value. Text without tags is wrapped, so it is never read back as plain text.
    store() {
      const empty = !area.textContent.trim() && !area.querySelector('li');
      const html = empty ? '' : area.innerHTML;
      form.el('remarks').value = !html || isRemarksHtml(html) ? html : `<div>${html}</div>`;
    },
  };
}

function initRemarksEditor(form) {
  const editor = remarksEditor(form);
  if (!editor) return;
  const { area } = editor;
  const bar = area.parentElement.querySelector('.pb-editor-bar');
  let saved = null;                                   // the selection, kept while the colour picker is open
  document.addEventListener('selectionchange', () => {
    const selection = document.getSelection();
    if (selection.rangeCount && area.contains(selection.anchorNode)) saved = selection.getRangeAt(0).cloneRange();
  });
  const run = (command, value) => {
    area.focus();
    if (saved) { const selection = document.getSelection(); selection.removeAllRanges(); selection.addRange(saved); }
    document.execCommand('styleWithCSS', false, false);   // <b>, <i>, <u>, <font color>: the tags the cleaners keep
    document.execCommand(command, false, value);   // fires the editor's input event: stored and recorded there
  };
  area.addEventListener('input', () => editor.store());            // before the form records the change
  area.addEventListener('paste', event => {                          // pasted text arrives plain
    event.preventDefault();
    document.execCommand('insertText', false, event.clipboardData.getData('text/plain'));
  });
  bar.addEventListener('mousedown', event => {                      // keep the text selection when a tool is clicked
    if (event.target.closest('button')) event.preventDefault();
  });
  bar.addEventListener('click', event => {
    const tool = event.target.closest('[data-cmd], [data-colour]');
    if (!tool) return;
    if (tool.dataset.cmd) run(tool.dataset.cmd); else run('foreColor', tool.dataset.colour);
  });
  bar.querySelector('[data-custom-colour]').addEventListener('input', event => run('foreColor', event.target.value));
}

/* The signatory slots in a form's PDF print box: a name and a position / title each, with a remove button.
   A new document starts with one: Prepared By (Procurement Officer); Add Signatory adds more. */
const PB_DEFAULT_SIGNATORIES = [{ name: 'Prepared By', title: 'Procurement Officer' }];
const PB_MAX_SIGNATORIES = 6;
function signatoryRow(slot) {
  const { name = '', title = '' } = typeof slot === 'string' ? { name: slot } : (slot || {});
  const li = el('li', 'pb-signatory');
  const field = (label, key, value, placeholder) => {
    const wrap = el('label', 'pb-signatory-field');
    const input = el('input', 'fp-input pb-signatory-input');
    Object.assign(input, { type: 'text', value, maxLength: 60, placeholder, autocomplete: 'off' });
    input.dataset.signatoryPart = key;
    wrap.append(el('span', 'pb-signatory-label', label), input);
    return wrap;
  };
  const remove = el('button', 'pb-icon-btn pb-icon-danger');
  Object.assign(remove, { type: 'button', title: 'Remove this signatory' });
  remove.dataset.signatory = 'remove';
  remove.setAttribute('aria-label', 'Remove this signatory');
  remove.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6M10 11v6M14 11v6"></path></svg>';
  li.append(field('Signatory Name', 'name', name, 'e.g. Prepared By'), field('Position / Title', 'title', title, 'e.g. Procurement Officer'), remove);
  return li;
}
const readSignatories = box => [...box.querySelectorAll('[data-signatories] li')]
  .map(li => ({ name: li.querySelector('[data-signatory-part="name"]').value.trim(), title: li.querySelector('[data-signatory-part="title"]').value.trim() }))
  .filter(slot => slot.name || slot.title);
function writeSignatories(box, slots) {
  box.querySelector('[data-signatories]').replaceChildren(...(slots || []).map(signatoryRow));
}

// Units for the Unit cells, racks for the GRN; whether a seal is on file (Attach Seal warns without one).
async function loadPurchaseMasters() {
  loadLookup('uom').catch(() => {});              // ready before the first Unit cell is typed in
  try { pbData.racks = await apiRequest('api/rack-bins.php'); } catch { pbData.racks = []; }
  showSealName();
}

let sealOnFile = false;
// The seal image, downloaded once per page load and kept in memory (the PDF preview shows it without a wait).
let sealImagePromise = null;
function companySealImage() {
  sealImagePromise ||= fetch('api/company-seal.php?file=1', { credentials: 'same-origin' })
    .then(response => (response.ok ? response.blob() : null))
    .then(blob => (blob ? URL.createObjectURL(blob) : null))
    .catch(() => { sealImagePromise = null; return null; });
  return sealImagePromise;
}

async function showSealName() {
  let seal = null;
  try { seal = await apiRequest('api/company-seal.php'); } catch { /* shown as no seal */ }
  sealOnFile = Boolean(seal);
  // Attach Seal shows nothing on the form: the seal prints on the PDF only. Its image is fetched now, so the PDF
  // preview shows it without a wait.
  if (seal) companySealImage();
}

/* Attach Seal is a checkbox only: the seal itself is added on Create a Company. Ticked without a seal on file,
   it says so (the PDF prints without one). */
function initSealButtons() {
  document.addEventListener('change', event => {
    if (event.target.matches?.('[data-print-field="attachSeal"]') && event.target.checked && !sealOnFile) {
      showToast('No company seal on file', 'The seal is added on Create a Company; this PDF will print without one.', true);
    }
  });
}

const purchaseLineRow = line => ({
  itemId: line.itemId ?? '', itemCode: line.itemCode, itemName: line.itemName, brandId: line.brandId ?? '', brandName: line.brandName,
  uomId: line.uomId ?? '', unit: line.unit, itemNameHtml: line.itemNameHtml || '',
  deliveryTerm: line.deliveryTerm ?? '',          // sales lines (a quotation's lines copied into a sales order …)
  // A sales order line's buying side (left as it is on lines that have none).
  ...(line.buyingCost !== undefined ? { buyingCost: pbMoney(pbNum(line.buyingCost)) } : {}),
  ...(line.warehouseId !== undefined ? { warehouseId: line.warehouseId ?? '' } : {}),     // a delivery note line's Branch
  ...(line.supplierId !== undefined ? { supplierId: line.supplierId ?? '', supplierName: line.supplierName || '', supplierCurrency: line.supplierCurrency || '' } : {}),
});

// A saved line as a row's cell values (edit mode), formatted as the form shows them.
function purchaseLineValues(kind, line) {
  const values = purchaseLineRow(line);
  if (kind === 'grn') {
    return { ...values, receivedQty: pbQty(pbNum(line.receivedQty)), acceptedQty: pbQty(pbNum(line.acceptedQty)), rejectedQty: pbQty(pbNum(line.rejectedQty)),
      rejectReason: line.rejectReason || '', expiryDate: line.expiryDate || '', unitCost: pbMoney(pbNum(line.unitCost)),
      vatRate: pbQty(pbNum(line.vatRate)), discountPct: pbQty(pbNum(line.discountPct)),
      transfers: line.transfers?.length ? JSON.stringify(line.transfers.map(t => ({ warehouseId: t.warehouseId, quantity: pbQty(pbNum(t.quantity)) }))) : '' };
  }
  values.quantity = pbQty(pbNum(line.quantity));
  if (kind === 'po') {
    Object.assign(values, { price: pbMoney(pbNum(line.price)), vatRate: pbNum(line.vatRate).toFixed(2), discountPct: pbNum(line.discountPct).toFixed(2),
      discountAmount: pbMoney(pbNum(line.discountAmount)), foc: line.foc ? 'Yes' : 'No' });
  }
  if (line.soldQty !== undefined) values.soldQty = pbQty(pbNum(line.soldQty));       // a sales return line
  if (line.receivedQty !== undefined) values.receivedQty = pbQty(pbNum(line.receivedQty));   // a purchase return line
  if (line.condition !== undefined) values.condition = line.condition;
  if (line.oldPrice !== undefined) {                                                     // a sales replacement line
    Object.assign(values, { oldPrice: pbMoney(pbNum(line.oldPrice)), replacementItemId: line.replacementItemId ? String(line.replacementItemId) : '',
      replacementItemName: line.replacementItemName || '' });
  }
  return values;
}

// Sets a select, adding the option first when the list does not have it (an inactive supplier on an old document).
function setSelectValue(select, value, label) {
  const text = String(value ?? '');
  if (text && ![...select.options].some(option => option.value === text)) select.append(new Option(label || text, text));
  select.value = text;
}

async function purchaseOptions(select, api, label) {
  try {
    const rows = await apiRequest(api);
    fillSelect(select, rows.map(row => ({ value: row.id, label: label(row) })), select.options[0]?.text ?? '');
  } catch (error) {
    showToast('A list could not be loaded', error.message, true);
  }
}

/* ---------- Purchase Request ---------- */
const prForm = createPurchaseForm({
  key: 'pr', route: 'purchase-book/purchase-request/new', noun: 'Purchase Request', api: 'api/purchase-requests.php',
  kind: 'simple', template: 'pb-line-simple', lookups: ['purchaserequest'], itemsFromMaster: true,   // every line is an Item master item
  firstField: () => byId('pr-reference'),
  fieldNodes: { referenceNo: 'pr-reference', purchaseType: 'pr-type', requestedDate: 'pr-date', requiredDate: 'pr-required',
    remarks: 'pr-remarks-editor' },
  header: () => ({
    referenceNo: byId('pr-reference').value.trim(), purchaseType: byId('pr-type').value, requestedDate: byId('pr-date').value,
    requiredDate: byId('pr-required').value, requestedBy: byId('pr-requested-by').value,
  }),
  check(form, errors) {
    if (!byId('pr-date').value) errors.push({ node: byId('pr-date'), message: 'Enter the requested date.' });
    if (byId('pr-required').value && byId('pr-required').value < byId('pr-date').value) {
      errors.push({ node: byId('pr-required'), message: 'The required delivery date cannot be before the requested date.' });
    }
  },
  onReset() { byId('pr-date').value = todayInputValue(); byId('pr-requested-by').value = signedInName || 'admin'; },
  listRoute: 'purchase-book/purchase-request',
  fill(form, pr) {
    byId('pr-reference').value = pr.referenceNo;
    setSelectValue(byId('pr-type'), pr.purchaseType);
    byId('pr-date').value = pr.requestedDate;
    byId('pr-required').value = pr.requiredDate || '';
    byId('pr-requested-by').value = pr.requestedBy || signedInName || 'admin';
  },
});

/* ---------- Quotation Request (RFQ) ---------- */
const rfqSuppliers = createLookupChips({ container: 'rfq-suppliers', entry: 'rfq-supplier-entry', onChange: () => { rfqNote(); rfqForm.page.record(); } });
function rfqNote() {
  const count = rfqSuppliers.get().length;
  byId('rfq-supplier-note').lastElementChild.textContent = count ? `${count} supplier${count === 1 ? '' : 's'} selected.` : 'No suppliers selected.';
}
let rfqPrLoaded = '';                     // the purchase request whose items the lines hold
const rfqForm = createPurchaseForm({
  key: 'rfq', route: 'purchase-book/quotation-request/new', noun: 'Quotation Request', api: 'api/quotation-requests.php',
  kind: 'simple', template: 'pb-line-simple', lookups: [], chips: rfqSuppliers, onChips: rfqNote,
  firstField: () => byId('rfq-pr'),
  onShow: () => openLookup(byId('rfq-pr')),             // a new request starts by picking the purchase request
  fieldNodes: { purchaseRequestId: 'rfq-pr', requestDate: 'rfq-date', submissionDeadline: 'rfq-deadline', supplierIds: 'rfq-supplier-entry' },
  header: () => ({
    purchaseRequestId: byId('rfq-pr-id').value || null, requestDate: byId('rfq-date').value,
    submissionDeadline: byId('rfq-deadline').value, supplierIds: rfqSuppliers.ids(),
  }),
  check(form, errors) {
    if (!rfqSuppliers.get().length) errors.push({ node: rfqSuppliers.input, message: 'Select at least one supplier.' });
    if (byId('rfq-deadline').value && byId('rfq-deadline').value < byId('rfq-date').value) {
      errors.push({ node: byId('rfq-deadline'), message: 'The submission deadline cannot be before the request date.' });
    }
  },
  onReset() {
    byId('rfq-date').value = todayInputValue();
    byId('rfq-pr').value = '';
    byId('rfq-pr-id').value = '';
    rfqPrLoaded = '';
  },
  listRoute: 'purchase-book/quotation-request',
  fill(form, rfq) {
    byId('rfq-pr').value = rfq.purchaseRequestCode || '';
    byId('rfq-pr-id').value = rfq.purchaseRequestId ?? '';
    rfqPrLoaded = String(rfq.purchaseRequestId ?? '');
    byId('rfq-date').value = rfq.requestDate;
    byId('rfq-deadline').value = rfq.submissionDeadline || '';
    rfqSuppliers.set(rfq.suppliers);
    rfqNote();
  },
  init(form) {
    // A purchase request picked in the PR ID popup: its items become the lines (once per pick).
    byId('rfq-pr').addEventListener('input', async () => {
      const id = byId('rfq-pr-id').value;
      if (!id || id === rfqPrLoaded) { rfqPrLoaded = id; return; }
      rfqPrLoaded = id;
      try {
        const pr = await apiRequest(`api/purchase-requests.php?id=${id}`);
        await loadPurchaseLines(form, pr.items, line => ({ ...purchaseLineRow(line), quantity: pbQty(pbNum(line.quantity)) }));
        showToast('Items fetched', `${pr.items.length} item${pr.items.length === 1 ? '' : 's'} from ${pr.code}.`);
      } catch (error) { showToast('The purchase request could not be loaded', error.message, true); }
    });
  },
});

/* ---------- Purchase Order ---------- */
// Certification Required: the ticks are kept in #po-certifications ("N/A" or "A, B"); N/A clears the others and back.
const poCertBoxes = () => [...byId('po-form').querySelectorAll('[data-cert]')];
function poShowCertifications() {
  const picked = byId('po-certifications').value.split(',').map(value => value.trim()).filter(Boolean);
  for (const box of poCertBoxes()) box.checked = picked.includes(box.dataset.cert);
}

// The supplier's contacts as suggestions for Contact Person Name; its currency becomes the order's.
async function poShowSupplier({ fresh = false } = {}) {
  const id = byId('po-supplier-id').value;
  if (!id) return null;
  let supplier;
  try { supplier = await pbSupplier(id); } catch (error) { showToast('The supplier could not be loaded', error.message, true); return null; }
  if (byId('po-supplier-id').value !== id) return null;
  const contacts = (supplier.contacts || []).filter(contact => contact.name);
  if (fresh) {
    if (supplier.currency) poSetCurrency(supplier.currency);
    // The supplier's first contact person and number (the others are in the Select Contact Person popup); with none, its own phone.
    if (contacts.length) {
      fillLookup(byId('po-contact'), { id: contacts[0].name, name: contacts[0].name });
      putPhone(byId('po-contact-number'), contacts[0].number ? poSupplierPhone(contacts[0].number, supplier) : '');   // its own number only
    } else if (supplier.phone || supplier.telephone) {
      putPhone(byId('po-contact-number'), poSupplierPhone(supplier.phone || supplier.telephone, supplier));
    }
  }
  return supplier;
}

// A supplier contact's number as one text ("+968 9123 4567"): a number without a + code takes the supplier's country code.
function poSupplierPhone(number, supplier) {
  const text = String(number ?? '').trim();
  if (!text || text.startsWith('+')) return text;
  return `${countryNamed(supplier?.country)?.dial || '+968'} ${text}`;
}

// Credit Period: shown (and required) only while Payment Mode is Credit, in the place after Payment Mode.
const poIsCredit = () => byId('po-payment').value === 'Credit';
async function poShowCredit({ fill = false } = {}) {
  byId('po-credit-field').hidden = !poIsCredit();
  if (!fill || !poIsCredit() || byId('po-credit-period').value.trim()) return;
  // Just switched to Credit: the supplier's credit days, else 30 Days.
  const supplierId = byId('po-supplier-id').value;
  const supplier = supplierId ? await pbSupplier(supplierId).catch(() => null) : null;
  const days = Number(supplier?.debitDays) || 30;
  byId('po-credit-period').value = `${days} Days`;
}

// VAT follows the currency: VAT Enabled (5%) on an order in OMR (Omani Rial, Oman), none in any other currency.
// The VAT button can still change it for one order.
function poVatFromCurrency(form) {
  form.setVat(poCurrency() === 'OMR');
}

// The order's currency code, and setting it (a code not in the list is shown as it is).
const poCurrency = () => byId('po-currency-id').value || 'OMR';
function poSetCurrency(code) {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId('po-currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}

// The PR / RFQ Number's picked document ("pr:5" / "rfq:3"), and the one whose items are already the lines.
const poRef = () => { const [kind, id] = byId('po-ref-id').value.split(':'); return { kind, id: id || '' }; };
let poRefLoaded = '';

const poForm = createPurchaseForm({
  key: 'po', route: 'purchase-book/purchase-order/new', noun: 'Purchase Order', api: 'api/purchase-orders.php',
  kind: 'po', template: 'pb-line-po', lookups: ['purchaseorder'], vatDefault: 'exclude',
  previewOnCreate: true,           // a new order opens on its preview page (Print / Export PDF), as a new Purchase Request
  firstField: () => byId('po-date'),
  onShow: () => openLookup(byId('po-ref')),             // a new order starts by picking the PR / RFQ
  fieldNodes: { poDate: 'po-date', purchaseRequestId: 'po-ref', quotationRequestId: 'po-ref', quotationNumber: 'po-quotation-no',
    deliveryDate: 'po-delivery-date', deliveryLocation: 'po-location', deliveryTerms: 'po-terms', paymentMode: 'po-payment',
    creditPeriod: 'po-credit-period', salesman: 'po-salesman', salesmanContact: 'po-salesman-contact', certifications: 'po-cert-label', remarks: 'po-remarks-editor',
    supplierId: 'po-supplier', contactName: 'po-contact', contactNumber: 'po-contact-number', currency: 'po-currency',
    discountAmount: 'po-discount', shipping: 'po-shipping' },
  header() {
    return {
      poDate: byId('po-date').value, quotationNumber: byId('po-quotation-no').value.trim(),
      purchaseRequestId: poRef().kind === 'pr' ? poRef().id : null, quotationRequestId: poRef().kind === 'rfq' ? poRef().id : null,
      deliveryDate: byId('po-delivery-date').value,
      deliveryLocation: byId('po-location').value.trim(), deliveryTerms: byId('po-terms').value.trim(), paymentMode: byId('po-payment').value,
      creditPeriod: poIsCredit() ? byId('po-credit-period').value.trim() : '',
      salesman: byId('po-salesman').value.trim(), salesmanContact: phoneOf(byId('po-salesman-contact')),
      certifications: byId('po-certifications').value.split(',').map(value => value.trim()).filter(Boolean),
      supplierId: byId('po-supplier-id').value || null, contactName: byId('po-contact').value.trim(),
      contactNumber: phoneOf(byId('po-contact-number')), currency: poCurrency(),
    };
  },
  check(form, errors) {
    if (poIsCredit() && !byId('po-credit-period').value.trim()) errors.push({ node: byId('po-credit-period'), message: 'Enter the credit period (e.g. 30 Days).' });
    if (!byId('po-salesman').value.trim()) errors.push({ node: byId('po-salesman'), message: 'Enter the salesman name.' });
    if (!byId('po-supplier-id').value) errors.push({ node: byId('po-supplier'), message: 'Select the supplier.' });
    if (byId('po-delivery-date').value && byId('po-delivery-date').value < byId('po-date').value) {
      errors.push({ node: byId('po-delivery-date'), message: 'The delivery date cannot be before the PO date.' });
    }
  },
  afterRestore() { poShowCertifications(); poShowSupplier(); poShowCredit(); },
  listRoute: 'purchase-book/purchase-order',
  fill(form, po) {
    byId('po-date').value = po.poDate;
    // The picked request (PR / RFQ Number) and the supplier's own Quotation Number.
    const ref = po.quotationRequestId ? `rfq:${po.quotationRequestId}` : po.purchaseRequestId ? `pr:${po.purchaseRequestId}` : '';
    byId('po-ref').value = po.quotationRequestCode || po.purchaseRequestCode || '';
    byId('po-ref-id').value = ref;
    byId('po-quotation-no').value = po.quotationNumber;
    poRefLoaded = ref;
    byId('po-delivery-date').value = po.deliveryDate || '';
    byId('po-location').value = po.deliveryLocation;
    byId('po-terms').value = po.deliveryTerms;
    setSelectValue(byId('po-payment'), po.paymentMode || 'As usual');
    byId('po-credit-period').value = po.creditPeriod || '';
    poShowCredit();
    byId('po-salesman').value = po.salesman || signedInName.toUpperCase();   // read-only: kept as saved
    putPhone(byId('po-salesman-contact'), po.salesmanContact);
    byId('po-certifications').value = (po.certifications || []).join(', ');
    poShowCertifications();
    fillLookup(byId('po-supplier'), po.supplierId ? { id: po.supplierId, name: po.supplierName } : null);   // the Select Supplier popup field
    fillLookup(byId('po-contact'), po.contactName ? { id: po.contactName, name: po.contactName } : null);
    putPhone(byId('po-contact-number'), po.contactNumber);
    poSetCurrency(po.currency);
  },
  afterFill: () => poShowSupplier(),
  async onReset(form) {
    byId('po-date').value = todayInputValue();
    fillLookup(byId('po-ref'), null);
    poRefLoaded = '';
    poSetCurrency('OMR');                        // hidden ids were cleared by the reset
    poVatFromCurrency(form);                     // a new order is in OMR: VAT Enabled
    byId('po-certifications').value = 'N/A';
    poShowCertifications();
    poShowCredit();
    poShowSupplier();
  },
  init(form) {
    // A pick in the PR / RFQ Number popup: its items become the lines (once per pick), VAT as the order's currency.
    byId('po-ref').addEventListener('input', async () => {
      const key = byId('po-ref-id').value;
      if (!key || key === poRefLoaded) { poRefLoaded = key; return; }
      poRefLoaded = key;
      const { kind, id } = poRef();
      try {
        const doc = await apiRequest(`api/${kind === 'rfq' ? 'quotation-requests' : 'purchase-requests'}.php?id=${id}`);
        if (byId('po-ref-id').value !== key) return;          // another pick came in meanwhile
        await loadPurchaseLines(form, doc.items, line => ({ ...purchaseLineRow(line), quantity: pbQty(pbNum(line.quantity)) }));
        // Each line's buying price (and the supplier's brand) from the Item master, as when the item is picked by hand.
        await Promise.all(form.page.rowsOf('items').map(async row => {
          const itemId = pbCell(row, 'itemId').value;
          const item = itemId ? await pbItem(itemId).catch(() => null) : null;
          if (!item) return;
          const source = poItemSource(item, row);
          if (source.brandId && !pbCell(row, 'brandId').value) {
            pbCell(row, 'brandId').value = source.brandId;
            pbCell(row, 'brandName').value = source.brandName;
          }
          if (source.cost > 0 && pbNum(pbCell(row, 'price').value) === 0) pbCell(row, 'price').value = pbMoney(source.cost);
        }));
        poVatFromCurrency(form);
        form.page.absorb();
        showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
      } catch (error) { showToast(`The ${kind === 'rfq' ? 'quotation' : 'purchase'} request could not be loaded`, error.message, true); }
    });
    byId('po-supplier').addEventListener('input', async () => {      // a pick in the Select Supplier popup
      fillLookup(byId('po-contact'), null);
      byId('po-contact-number').value = '';
      const supplier = await poShowSupplier({ fresh: true });   // the order takes the supplier's currency
      if (supplier) poVatFromCurrency(form);
      form.page.absorb();
      form.refresh();
    });
    // A contact picked in the Select Contact Person popup (or just created) brings its number; a contact
    // without a number (or no contact) leaves Contact Person Number empty, never the previous contact's.
    byId('po-contact').addEventListener('input', async () => {
      const name = byId('po-contact').value;
      const supplierId = byId('po-supplier-id').value;
      const supplier = supplierId ? await pbSupplier(supplierId).catch(() => null) : null;
      if (byId('po-contact').value !== name) return;            // another pick came in meanwhile
      const contact = name ? supplier?.contacts?.find(entry => sameText(entry.name, name)) : null;
      putPhone(byId('po-contact-number'), contact?.number ? poSupplierPhone(contact.number, supplier) : '');
      form.page.absorb();
    });
    // A pick in the Select Currency popup: the form records it first (its listener is older), then VAT follows in the same step.
    byId('po-form').addEventListener('input', event => {
      if (event.target.id !== 'po-currency') return;
      poVatFromCurrency(form);
      form.page.absorb();
    });
    // Payment Mode: Credit shows Credit Period (filled with the supplier's days); any other mode hides it.
    byId('po-payment').addEventListener('change', async () => {
      await poShowCredit({ fill: true });
      form.page.absorb();
    });
    byId('po-form').addEventListener('change', event => {
      const box = event.target.closest('[data-cert]');
      if (!box) return;
      const boxes = poCertBoxes();
      if (box.checked && box.dataset.cert === 'N/A') boxes.forEach(other => { if (other !== box) other.checked = false; });
      else if (box.checked) boxes.find(other => other.dataset.cert === 'N/A').checked = false;
      byId('po-certifications').value = boxes.filter(other => other.checked).map(other => other.dataset.cert).join(', ');
      form.page.record();
    });
  },
});

/* ---------- Goods Receipt Note ---------- */
const grnForm = createPurchaseForm({
  key: 'grn', route: 'purchase-book/grn/new', noun: 'GRN', api: 'api/grns.php',
  kind: 'grn', template: 'pb-line-grn', lookups: [], vatDefault: 'exclude',
  firstField: () => byId('grn-supplier'),
  // A new GRN starts on the Select Supplier popup.
  opened(form) {
    setTimeout(() => {
      if (currentRoute !== 'purchase-book/grn/new' || form.page.isEditing() || byId('grn-supplier-id').value || byId('lookup').open) return;
      if (document.activeElement === byId('grn-supplier')) openLookup(byId('grn-supplier'), { byKeyboard: true });
    }, 150);
  },
  fieldNodes: { grnDate: 'grn-date', supplierId: 'grn-supplier', warehouseId: 'grn-warehouse', poNumber: 'grn-po', purchaseOrderId: 'grn-po',
    discountAmount: 'grn-discount', shipping: 'grn-shipping', remarks: 'grn-remarks-editor' },
  header: () => ({
    grnDate: byId('grn-date').value, supplierId: byId('grn-supplier-id').value || null, warehouseId: byId('grn-warehouse-id').value || null,
    purchaseOrderId: byId('grn-po-id').value || null, poNumber: byId('grn-po').value.trim(),
  }),
  check(form, errors) {
    if (!byId('grn-supplier-id').value) errors.push({ node: byId('grn-supplier'), message: 'Select the supplier.' });
    if (!byId('grn-warehouse-id').value) errors.push({ node: byId('grn-warehouse'), message: 'Select the stock point the goods are received into.' });
  },
  onReset() {
    byId('grn-date').value = todayInputValue();
    forgetLookups('purchaseorder');
  },
  listRoute: 'purchase-book/grn',
  fill(form, grn) {
    byId('grn-date').value = grn.grnDate;
    // Supplier and Stock Point are "Select …" popups: show the saved record and keep its id.
    fillLookup(byId('grn-supplier'), grn.supplierId ? { id: grn.supplierId, name: grn.supplierName } : null);
    fillLookup(byId('grn-warehouse'), grn.warehouseId ? { id: grn.warehouseId, code: grn.warehouseCode, name: grn.warehouseName } : null);
    byId('grn-po').value = grn.poNumber;
    byId('grn-po-id').value = grn.purchaseOrderId ?? '';
  },
  init(form) {
    form.warehouseId = () => byId('grn-warehouse-id').value;
    initGrnTransfer(form);
    // Picking a purchase order in the Select Purchase Order popup fills the supplier and its lines
    // (received = ordered, all accepted).
    byId('grn-form').addEventListener('input', async event => {
      if (event.target.id !== 'grn-po') return;
      const id = byId('grn-po-id').value;
      if (!id) return;
      try {
        const po = await apiRequest(`api/purchase-orders.php?id=${id}`);
        if (po.supplierId) fillLookup(byId('grn-supplier'), { id: po.supplierId, name: po.supplierName });
        byId('grn-vat-mode').value = po.vatMode;
        await loadPurchaseLines(form, po.items, line => ({
          ...purchaseLineRow(line), receivedQty: pbQty(pbNum(line.quantity)), acceptedQty: pbQty(pbNum(line.quantity)), rejectedQty: '0',
          unitCost: pbMoney(pbNum(line.price)), vatRate: pbQty(pbNum(line.vatRate)), discountPct: pbQty(pbNum(line.discountPct)),
        }));
        form.syncVatToggle();
        showToast('Items fetched', `${po.items.length} item${po.items.length === 1 ? '' : 's'} from ${po.code}.`);
        // On to the first line: its Brand popup opens (the PO's brand already there: straight to Rec. Qty).
        const first = form.page.rowsOf('items')[0];
        if (first) {
          const brand = pbCell(first, 'brandName');
          if (brand?.matches('.fp-lookup') && pbCell(first, 'itemId').value && !pbCell(first, 'brandId').value) {
            lockRowBrand(first, false);
            brand.focus();
            openLookup(brand, { byKeyboard: true });
          } else {
            focusField(pbCell(first, 'receivedQty'));
          }
        }
      } catch (error) { showToast('The purchase order could not be loaded', error.message, true); }
    });
  },
});

/* ---------- Trade Management: Quotation, Sales Order, Delivery Note ----------
   The Purchase Order's form to a customer: Customer (the Select Customer popup) with a contact and currency, priced
   lines with a Delivery Term each (printed under the item as "DELIVERY: …"), VAT, Special Discount and a delivery
   charge, remarks, signatory slots and the seal. A sales order can be filled from a quotation, a delivery note from
   a sales order (Quotation Ref / Sales Order Ref: the customer, terms and lines are copied). */
function pbCustomer(id) {
  if (!pbData.customers.has(id)) {
    pbData.customers.set(id, apiRequest(`api/customers.php?id=${id}`).catch(error => { pbData.customers.delete(id); throw error; }));
  }
  return pbData.customers.get(id);
}

// A customer contact's number as one text: a number without a + code takes the customer's country code.
function salesCustomerPhone(number, customer) {
  const text = String(number ?? '').trim();
  if (!text || text.startsWith('+')) return text;
  return `${countryNamed(customer?.country)?.dial || '+968'} ${text}`;
}

/*
 * One Trade Management form. cfg: key ('qt' | 'so' | 'dn'), route (the list's), noun, api, dateKey (the payload's date),
 * lookups, fieldNodes / header() / fill(doc) / check(errors) / onReset() / init(form, sales) for the kind's own fields.
 */
const SALES_HELPERS = {};                          // each sales form's copyFrom … (the Sales Order's Document Title opens the others)
function createSalesForm(cfg) {
  const k = cfg.key;
  const $ = suffix => byId(`${k}-${suffix}`);
  const currency = () => $('currency-id').value || 'OMR';
  const setCurrency = code => {
    const text = String(code || 'OMR').toUpperCase();
    fillLookup($('currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
  };
  // The sales order has free-text Payment Terms and no Credit Period / Salesman fields.
  const isCredit = () => Boolean($('credit-field')) && $('payment')?.value === 'Credit';
  const vatWanted = () => (cfg.vatWanted ? cfg.vatWanted() : currency() === 'OMR');
  async function showCredit({ fill = false } = {}) {
    if (!$('credit-field')) return;
    $('credit-field').hidden = !isCredit();
    if (!fill || !isCredit() || $('credit-period').value.trim()) return;
    const customerId = $('customer-id').value;       // just switched to Credit: the customer's credit days, else 30 Days
    const customer = customerId ? await pbCustomer(customerId).catch(() => null) : null;
    const days = Number(customer?.creditDays) || 30;
    $('credit-period').value = cfg.creditDaysOnly ? String(days) : `${days} Days`;   // the quotation asks Credit Days (a number)
  }
  // The customer's contacts as suggestions for Contact Person Name; a fresh pick brings its currency and only contact.
  async function showCustomer({ fresh = false } = {}) {
    const id = $('customer-id').value;
    const list = $('contact-list');
    if (!id) { list.replaceChildren(); return null; }
    let customer;
    try { customer = await pbCustomer(id); } catch (error) { showToast('The customer could not be loaded', error.message, true); return null; }
    if ($('customer-id').value !== id) return null;
    const contacts = (customer.contacts || []).filter(contact => contact.name);
    list.replaceChildren(...contacts.map(contact => {
      const option = new Option(contact.name);
      if (contact.designation) option.label = contact.designation;
      return option;
    }));
    if (fresh) {
      const code = String(customer.currency || '').toUpperCase();
      if (PO_CURRENCIES.some(row => row.code === code)) setCurrency(code);
      if (contacts.length === 1) {
        $('contact').value = contacts[0].name;
        if ($('contact').dataset.lookup) lookupIdInput($('contact')).value = contacts[0].name;
        putPhone($('contact-number'), salesCustomerPhone(contacts[0].number, customer));
      } else if (!contacts.length && customer.phone) {
        putPhone($('contact-number'), salesCustomerPhone(customer.phone, customer));
      }
    }
    return customer;
  }
  // Certification Required (the quotation): the ticks are kept in #qt-certifications; N/A clears the others and back.
  const certBoxes = () => [...$('form').querySelectorAll('[data-cert]')];
  const setPayment = value => {
    if (!$('payment')) return;                       // the delivery note has no payment terms
    // A select (quotation, delivery note) takes only its own modes: a sales order's free-text terms ("30 Days Net") become As usual.
    // The tax invoice's (data-payment-keep) also keeps terms not in its list ("45 Days Net"), added as an option.
    if ($('payment').dataset.paymentKeep !== undefined) setSelectValue($('payment'), value || 'As usual');
    else if ($('payment').tagName === 'SELECT') {
      $('payment').value = [...$('payment').options].some(option => option.value === value) ? value : 'As usual';
    }
    else $('payment').value = value || '';
  };
  const showCerts = () => {
    if (!$('certifications')) return;
    const picked = $('certifications').value.split(',').map(value => value.trim()).filter(Boolean);
    for (const box of certBoxes()) box.checked = picked.includes(box.dataset.cert);
  };

  // Copies a quotation / sales order into this form: the customer and its terms, then the lines.
  async function copyFrom(doc, form) {
    if (doc.customerId) fillLookup($('customer'), { id: doc.customerId, name: doc.customerName });
    $('contact').value = doc.contactName || '';
    putPhone($('contact-number'), doc.contactNumber);
    setCurrency(doc.currency);
    if (doc.deliveryLocation) $('location').value = doc.deliveryLocation;
    setPayment(doc.paymentMode);
    if ($('credit-period')) $('credit-period').value = cfg.creditDaysOnly ? String(doc.creditPeriod || '').replace(/\D/g, '') : doc.creditPeriod || '';
    showCredit();
    $('vat-mode').value = doc.vatMode || 'exclude';
    $('discount').value = pbMoney(pbNum(doc.discountAmount));
    $('shipping').value = pbMoney(pbNum(doc.shipping));
    if (doc.items.length) await loadPurchaseLines(form, doc.items, line => (cfg.copyLine || (values => values))(purchaseLineValues('po', line)));
    if (k === 'so') await soFillCopiedBuyingCosts(form);   // the sales order's buying cost for each copied line
    form.syncVatToggle();
    form.refresh();
    showCustomer();
    form.page.absorb();
    if (doc.items.length) showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
  }
  const sales = { $, copyFrom, currency, showCustomer };
  SALES_HELPERS[k] = sales;

  const form = createPurchaseForm({
    key: k, route: `${cfg.route}/new`, noun: cfg.noun, api: cfg.api, listRoute: cfg.route,
    kind: 'po', template: cfg.template || 'pb-line-sales', lineExtras: cfg.lineExtras || ['deliveryTerm'], lookups: cfg.lookups, vatDefault: 'exclude',
    // The Grand Total in the customer's currency is the generic row under Grand Total (showGrandInOmr).
    afterRefresh: totals => cfg.afterRefresh?.(totals),
    onShow: cfg.onShow,
    firstField: () => $('date'),
    fieldNodes: {
      [cfg.dateKey]: `${k}-date`, customerId: `${k}-customer`, contactName: `${k}-contact`, contactNumber: `${k}-contact-number`,
      currency: `${k}-currency`, deliveryLocation: `${k}-location`, paymentMode: `${k}-payment`, creditPeriod: `${k}-credit-period`,
      salesman: `${k}-salesman`, salesmanContact: `${k}-salesman-contact`, remarks: `${k}-remarks-editor`,
      discountAmount: `${k}-discount`, shipping: `${k}-shipping`, ...cfg.fieldNodes,
    },
    header: () => ({
      [cfg.dateKey]: $('date').value, customerId: $('customer-id').value || null, contactName: $('contact').value.trim(),
      contactNumber: phoneOf($('contact-number')), currency: currency(), deliveryLocation: $('location').value.trim(),
      paymentMode: $('payment')?.value.trim() ?? '', creditPeriod: isCredit() ? $('credit-period').value.trim() : '',
      ...($('salesman') ? { salesman: $('salesman').value.trim(), salesmanContact: phoneOf($('salesman-contact')) } : {}),
      ...cfg.header(),
    }),
    check(form, errors) {
      if (!$('customer-id').value) errors.push({ node: $('customer'), message: 'Select the customer.' });
      if ($('salesman') && !$('salesman').value.trim()) errors.push({ node: $('salesman'), message: 'Enter the salesman name.' });
      if (isCredit() && !$('credit-period').value.trim()) errors.push({ node: $('credit-period'), message: 'Enter the credit period (e.g. 30 Days).' });
      cfg.check?.(errors);
    },
    afterRestore() { showCerts(); showCustomer(); showCredit(); },
    fill(form, doc) {
      $('date').value = doc[cfg.dateKey];
      fillLookup($('customer'), doc.customerId ? { id: doc.customerId, name: doc.customerName } : null);
      $('contact').value = doc.contactName || '';
      putPhone($('contact-number'), doc.contactNumber);
      setCurrency(doc.currency);
      $('location').value = doc.deliveryLocation || '';
      setPayment(doc.paymentMode);
      if ($('credit-period')) $('credit-period').value = doc.creditPeriod || '';
      showCredit();
      if ($('salesman')) {
        $('salesman').value = doc.salesman || signedInName.toUpperCase();   // read-only: kept as saved
        putPhone($('salesman-contact'), doc.salesmanContact);
      }
      cfg.fill(doc);
      showCerts();
    },
    afterFill: () => showCustomer(),
    async onReset(form) {
      $('date').value = todayInputValue();
      setCurrency('OMR');                            // hidden ids were cleared by the reset
      form.setVat(vatWanted());                      // a new document is in OMR: VAT Enabled (a sales order: none)
      if (cfg.defaultLocation !== false && !$('location').value.trim()) $('location').value = 'DDP Muscat Limit';
      if ($('certifications')) $('certifications').value = 'N/A';
      showCerts();
      showCredit();
      showCustomer();
      cfg.onReset?.();
    },
    init(form) {
      $('customer').addEventListener('input', async () => {         // a pick in the Select Customer popup
        $('contact').value = '';
        if ($('contact').dataset.lookup) lookupIdInput($('contact')).value = '';
        $('contact-number').value = '';
        const customer = await showCustomer({ fresh: true });
        if (customer) form.setVat(vatWanted());
        form.page.absorb();
        form.refresh();
      });
      // A contact picked from the suggestions brings its number.
      $('contact').addEventListener($('contact').dataset.lookup ? 'input' : 'change', async () => {
        const customerId = $('customer-id').value;
        const customer = customerId ? await pbCustomer(customerId).catch(() => null) : null;
        const contact = customer?.contacts?.find(entry => sameText(entry.name, $('contact').value));
        if (contact?.number) { putPhone($('contact-number'), salesCustomerPhone(contact.number, customer)); form.page.absorb(); }
      });
      // VAT follows the currency: VAT Enabled (5%) in OMR, none in any other currency (the VAT button can still change it).
      $('form').addEventListener('input', event => {
        if (event.target.id !== `${k}-currency`) return;
        form.setVat(vatWanted());
        form.page.absorb();
      });
      if ($('credit-field')) {
        $('payment').addEventListener('change', async () => {
          await showCredit({ fill: true });
          form.page.absorb();
        });
      }
      $('form').addEventListener('change', event => {
        const box = event.target.closest('[data-cert]');
        if (!box) return;
        const boxes = certBoxes();
        if (box.checked && box.dataset.cert === 'N/A') boxes.forEach(other => { if (other !== box) other.checked = false; });
        else if (box.checked) boxes.find(other => other.dataset.cert === 'N/A').checked = false;
        $('certifications').value = boxes.filter(other => other.checked).map(other => other.dataset.cert).join(', ');
        form.page.record();
      });
      cfg.init?.(form, sales);
    },
  });
  return form;
}

/* Quotation: the quotation screen's fields. Offer Validity is a list with Custom… (a typed validity), Accepted Terms
   of Payment As usual / Cash / Credit (Credit asks Credit Days), the line shows its Brand, and the summary reads
   Items Total Amount (before line discounts), Total VAT, Line Discounts Total, Delivery Charge, Special Discount,
   Round Off and Grand Total (Round Off added). */
const QT_VALIDITY = ['15 Days', '30 Days', '45 Days', '60 Days', '90 Days', '120 Days'];
function qtShowValidity({ focus = false } = {}) {
  const custom = byId('qt-validity-pick').value === 'CUSTOM';
  byId('qt-validity').hidden = !custom;
  if (custom && focus) byId('qt-validity').focus();
}
const qtOfferValidity = () => (byId('qt-validity-pick').value === 'CUSTOM' ? byId('qt-validity').value.trim() : byId('qt-validity-pick').value);
const qtRoundOff = () => {
  const text = byId('qt-round').value.trim();
  return /^-?\d+(\.\d+)?$/.test(text) ? Number(text) : 0;
};

const qtForm = createSalesForm({
  key: 'qt', route: 'trade/quotation', noun: 'Quotation', api: 'api/quotations.php', dateKey: 'quotationDate', lookups: ['quotation'],
  template: 'pb-line-qt', creditDaysOnly: true,
  onShow: () => openLookup(byId('qt-customer')),          // a new quotation starts by picking the Buyer
  fieldNodes: { referenceNo: 'qt-reference', loyaltyMemberId: 'qt-loyalty', offerValidity: 'qt-validity-pick', certifications: 'qt-cert-label', roundOff: 'qt-round' },
  header: () => {
    const days = byId('qt-credit-period').value.replace(/\D/g, '');
    return {
      referenceNo: byId('qt-reference').value.trim(), loyaltyMemberId: byId('qt-loyalty').value.trim(), offerValidity: qtOfferValidity(),
      certifications: byId('qt-certifications').value.split(',').map(value => value.trim()).filter(Boolean),
      creditPeriod: byId('qt-payment').value === 'Credit' && days ? `${days} Days` : '',
      roundOff: byId('qt-round').value.trim() || '0',
    };
  },
  check(errors) {
    if (byId('qt-validity-pick').value === 'CUSTOM' && !byId('qt-validity').value.trim()) errors.push({ node: byId('qt-validity'), message: 'Enter the offer validity (e.g. 10 Days).' });
    if (!/^-?\d{1,11}(\.\d{1,3})?$/.test(byId('qt-round').value.trim() || '0')) errors.push({ node: byId('qt-round'), message: 'Enter an amount with up to 3 decimals (may be negative).' });
  },
  afterRefresh(totals) {
    const lineDiscounts = [...byId('qt-items').rows].reduce((sum, row) => sum + pbNum(pbCell(row, 'discountAmount')?.value), 0);
    byId('qt-items-total').textContent = pbShow(totals.subtotal + lineDiscounts);
    byId('qt-line-discounts').textContent = pbShow(lineDiscounts);
    byId('qt-vat-label').textContent = 'Total VAT Amount';               // the quotation screen's wording
    byId('qt-grand').textContent = pbShow(totals.grand + qtRoundOff());
  },
  fill(doc) {
    byId('qt-reference').value = doc.referenceNo || '';
    byId('qt-loyalty').value = doc.loyaltyMemberId || '';
    const validity = doc.offerValidity || '';
    byId('qt-validity-pick').value = !validity || QT_VALIDITY.includes(validity) ? (validity || '30 Days') : 'CUSTOM';
    byId('qt-validity').value = QT_VALIDITY.includes(validity) ? '' : validity;
    qtShowValidity();
    byId('qt-credit-period').value = String(doc.creditPeriod || '').replace(/\D/g, '');
    byId('qt-round').value = pbMoney(pbNum(doc.roundOff));
    byId('qt-certifications').value = (doc.certifications || []).join(', ');
  },
  onReset() {
    byId('qt-validity-pick').value = '30 Days';
    byId('qt-validity').value = '';
    qtShowValidity();
  },
  init(form) {
    byId('qt-validity-pick').addEventListener('change', () => { qtShowValidity({ focus: true }); form.page.absorb(); });
    byId('qt-round').addEventListener('input', () => form.refresh());
    byId('qt-round').addEventListener('change', () => {           // a negative amount is not reformatted by the summary's own handler
      const value = byId('qt-round').value.trim();
      if (/^-\d+(\.\d+)?$/.test(value)) byId('qt-round').value = pbMoney(Number(value));
      form.refresh();
    });
  },
});

/* Sales Order: the fields of the sales order screen. Document Title (Sales Order, or Proforma Invoice: VAT, no
   supplier or buying side), Supplier Mode (one Supplier Name and Supplier Currency for the order, or a Supplier per
   line), a buying cost per line with the line's Total Buying and Profit %, and the Financial Summary: landing cost,
   custom duty (when a supplier currency is not the base currency), transportation, business promotion, total buying
   cost (and in AED), total profit. The same sums as sb_order_costs() on the server, with the same fixed rates. */
const SO_RATES_TO_OMR = { OMR: 1, AED: 0.1055, USD: 0.385, SAR: 0.1026, INR: 1 / 241.3, EUR: 0.42, GBP: 0.49, QAR: 0.1057, KWD: 1.25, BHD: 1.02 };
const soRate = (from, to) => (from === to || !SO_RATES_TO_OMR[from] || !SO_RATES_TO_OMR[to] ? 1 : SO_RATES_TO_OMR[from] / SO_RATES_TO_OMR[to]);
const soIsInvoice = () => byId('so-doc-title').value === 'Proforma Invoice';
const soIsMulti = () => byId('so-mode').value === 'multi';
const soBase = () => 'OMR';                          // prices, costs and profit are in OMR (PRICES_IN_OMR)
const soCurrency = () => byId('so-currency-id').value || 'OMR';   // the customer's currency
let soSales = null;                                    // createSalesForm's helpers for the sales order

// Shows what the title and the mode allow (the CSS hides the rest) and the currency labels.
function soShowMode() {
  const formNode = byId('so-form');
  formNode.dataset.doc = soIsInvoice() ? 'invoice' : 'order';
  formNode.dataset.mode = soIsMulti() ? 'multi' : 'single';
  for (const label of formNode.querySelectorAll('[data-so-base]')) label.textContent = soBase();
  for (const label of formNode.querySelectorAll('[data-so-sup-label]')) label.textContent = ' (OMR)';   // buying costs are in OMR too
  // An opened Sales Order is updated (as the other forms' Update … Record).
  byId('so-save-label').textContent = FORM_PAGES['trade/sales-order/new']?.isEditing?.() ? 'Update Sales Order Record' : 'Save Sales Order';
}

// Each line's buying side and the summary (after the form's own totals).
function soRefreshCosts(totals) {
  const base = soBase();
  const rows = soForm.page.rowsOf('items');
  const value = (row, field) => pbNum(pbCell(row, field)?.value);
  let items = 0;
  let foreign = false;
  // The currencies the suppliers are paid in other than OMR: the order's own (single supplier), or each line's
  // supplier's (multi supplier). The summary shows the Total Buying Cost in each of them.
  const supplierCurrencies = new Set(soIsMulti() ? [] : [byId('so-supplier-currency').value]);
  for (const row of rows) {
    const supplierCurrency = soIsMulti() ? (pbCell(row, 'supplierCurrency').value || base) : byId('so-supplier-currency').value;
    if (soIsMulti() && pbCell(row, 'supplierId').value) supplierCurrencies.add(supplierCurrency);
    const landing = supplierCurrency === 'AED' ? 1.1 : 1;
    const qty = value(row, 'quantity');
    const price = value(row, 'price');
    const buying = value(row, 'buyingCost');
    const lineBuying = qty * buying * landing;                 // in OMR, as the buying cost (the supplier's currency only sets the landing)
    const buyingBase = buying * landing;
    items += lineBuying;
    if (supplierCurrency !== base && buying > 0) foreign = true;
    row.querySelector('[data-buying-total]').textContent = pbShow(lineBuying);
    const profit = price > 0 ? (price - buyingBase) / price * 100 : 0;
    const cell = row.querySelector('[data-profit]');
    cell.textContent = `${profit.toFixed(2)}%`;
    cell.classList.toggle('is-loss', profit < 0);
  }
  const duty = pbNum(byId('so-duty').value);
  const shipping = pbNum(byId('so-shipping').value);
  const promotion = pbNum(byId('so-promotion').value);
  const totalBuying = items + duty + shipping + promotion;
  const profit = totals.subtotal - items - duty - shipping - promotion - totals.discount;
  byId('so-landing').textContent = pbShow(items);
  byId('so-total-buying').textContent = pbShow(totalBuying);
  // Total Buying Cost (AED), (USD) …: one row per foreign supplier currency, after the base currency's row (which
  // already shows it in the order's own currency). None for OMR, nor for a currency without a rate in SO_RATES_TO_OMR.
  for (const old of byId('so-form').querySelectorAll('.so-foreign-row')) old.remove();
  let after = byId('so-total-buying').parentElement;
  for (const code of [...supplierCurrencies].filter(code => code && code !== 'OMR' && code !== base && SO_RATES_TO_OMR[code]).sort()) {
    const row = el('div', 'so-buy-row so-foreign-row');
    row.append(el('dt', '', `Total Buying Cost (${code})`), el('dd', '', pbMoney(totalBuying * soRate(base, code))));
    after.after(row);
    after = row;
  }
  byId('so-profit').textContent = pbShow(profit);
  byId('so-profit-pct').textContent = `${(totals.subtotal > 0 ? profit / totals.subtotal * 100 : 0).toFixed(2)}%`;
  for (const id of ['so-profit', 'so-profit-pct']) byId(id).classList.toggle('is-loss', profit < 0);
  // Custom Duty: only when a supplier is paid in another currency than the base (or a duty is already entered).
  byId('so-duty-row').hidden = !foreign && !soIsMulti() && byId('so-supplier-currency').value === base && !duty;
}

// What is entered on the sales order, as a saved document's shape (for copyFrom into a quotation or delivery note).
function soAsDocument() {
  const value = id => byId(id).value.trim();
  // A sales order's lines have no VAT; in the quotation / delivery note they take VAT as usual (5% in OMR).
  const vat = soIsInvoice() ? null : (value('so-currency-id') || 'OMR') === 'OMR' ? '5.00' : '0.00';
  const items = soForm.page.rowsOf('items').map(row => {
    const cell = field => pbCell(row, field)?.value.trim() ?? '';
    return {
      itemId: cell('itemId') || null, itemCode: cell('itemCode'), itemName: cell('itemName'), itemNameHtml: cell('itemNameHtml'),
      brandId: cell('brandId') || null, brandName: cell('brandName'), uomId: cell('uomId') || null, unit: cell('unit'),
      deliveryTerm: cell('deliveryTerm'), quantity: cell('quantity'), price: cell('price'), vatRate: vat ?? cell('vatRate'),
      discountPct: '0', discountAmount: '0', foc: false,
    };
  }).filter(line => line.itemName || line.itemId);
  return {
    code: 'the Sales Order', customerId: value('so-customer-id') || null, customerName: value('so-customer'),
    contactName: value('so-contact'), contactNumber: phoneOf(byId('so-contact-number')), currency: value('so-currency-id') || 'OMR',
    deliveryLocation: value('so-location'), paymentMode: value('so-payment'), creditPeriod: '',
    vatMode: 'exclude', discountAmount: value('so-discount'), shipping: value('so-shipping'), items,
  };
}

/* Auto-Select Best Supplier (Multi Supplier): for each line, the supplier whose newest known price for the item
   (supplier quotations, purchase orders, earlier sales orders; api/supplier-rates.php) costs least in the base
   currency (AED landing 1.10 included). The line takes that supplier and its price as the buying cost. */
async function soAutoSelectSuppliers(form) {
  const button = byId('so-auto-supplier');
  button.disabled = true;
  try {
    const rates = await apiRequest('api/supplier-rates.php');
    const base = soBase();
    let picked = 0;
    for (const row of form.page.rowsOf('items')) {
      const itemId = pbCell(row, 'itemId').value;
      const name = pbCell(row, 'itemName').value.trim();
      if (!itemId && !name) continue;
      const latest = new Map();                               // the newest price of each supplier (rows come newest first)
      for (const offer of rates) {
        const same = (itemId && offer.itemId && String(offer.itemId) === itemId) || sameText(offer.itemName, name);
        if (same && !latest.has(offer.supplierId)) latest.set(offer.supplierId, offer);
      }
      let best = null;
      let bestCost = Infinity;
      for (const offer of latest.values()) {
        const currency = offer.currency || base;
        const cost = pbNum(offer.rate) * (currency === 'AED' ? 1.1 : 1);   // the prices are in OMR
        if (cost < bestCost) { bestCost = cost; best = offer; }
      }
      if (!best) continue;
      fillLookup(pbCell(row, 'supplierName'), { id: best.supplierId, name: best.supplierName });
      pbCell(row, 'supplierCurrency').value = best.currency;
      pbCell(row, 'buyingCost').value = pbMoney(pbNum(best.rate));
      picked++;
    }
    form.refresh();
    form.page.record();
    if (picked) showToast('Best suppliers selected', `${picked} line${picked === 1 ? ' now uses' : 's now use'} the lowest known supplier price.`);
    else showToast('No supplier prices found', 'None of these items has a price from a supplier quotation, purchase order or earlier sales order.', true);
  } catch (error) {
    showToast('Supplier prices could not be loaded', error.message, true);
  } finally {
    button.disabled = false;
  }
}

const soForm = createSalesForm({
  key: 'so', route: 'trade/sales-order', noun: 'Sales Order', api: 'api/sales-orders.php', dateKey: 'orderDate', lookups: ['salesorder'],
  template: 'pb-line-so', lineExtras: ['deliveryTerm', 'buyingCost', 'supplierId'], defaultLocation: false,
  // A Sales Order has no VAT; a Proforma Invoice has VAT Enabled in OMR.
  vatWanted: () => soIsInvoice() && soCurrency() === 'OMR',
  copyLine: values => ({ ...values, discountPct: '0.00', discountAmount: '0.000', vatRate: soIsInvoice() ? values.vatRate : '0.00' }),
  afterRefresh: totals => soRefreshCosts(totals),
  fieldNodes: { documentTitle: 'so-doc-title', supplierMode: 'so-mode', supplierId: 'so-supplier', supplierCurrency: 'so-supplier-currency',
    quotationId: 'so-quotation', customerPo: 'so-customer-po', purchaseCategory: 'so-category', customDuty: 'so-duty',
    businessPromotion: 'so-promotion', advancePayment: 'so-advance', paymentMode: 'so-payment' },
  header: () => ({
    documentTitle: byId('so-doc-title').value, supplierMode: byId('so-mode').value,
    supplierId: !soIsInvoice() && !soIsMulti() ? byId('so-supplier-id').value || null : null,
    supplierCurrency: byId('so-supplier-currency').value, quotationId: byId('so-quotation-id').value || null,
    customerPo: byId('so-customer-po').value.trim(), purchaseCategory: byId('so-category').value.trim(),
    customDuty: byId('so-duty').value.trim() || '0', businessPromotion: byId('so-promotion').value.trim() || '0',
    advancePayment: byId('so-advance').value.trim() || '0',   // no Send For Approval on this screen: an edit keeps the saved status
    // Multi Supplier: no order-level Payment Terms or Delivery Location (each line's supplier has its own terms).
    ...(soIsMulti() && !soIsInvoice() ? { paymentMode: '', deliveryLocation: '' } : {}),
  }),
  check(errors) {
    for (const id of ['so-duty', 'so-promotion', 'so-advance']) {
      const amount = byId(id).value.trim();
      if (amount !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(amount)) errors.push({ node: byId(id), message: 'Enter an amount with up to 3 decimals.' });
    }
    if (!soIsInvoice() && soIsMulti()) {
      soForm.page.rowsOf('items').forEach((row, index) => {
        const filled = pbCell(row, 'itemName').value.trim() || pbCell(row, 'itemId').value;
        if (filled && !pbCell(row, 'supplierId').value) errors.push({ node: pbCell(row, 'supplierName'), message: `Row ${index + 1}: select the supplier (Multi Supplier).` });
      });
    }
  },
  fill(doc) {
    setSelectValue(byId('so-doc-title'), doc.documentTitle || 'Sales Order');
    setSelectValue(byId('so-mode'), doc.supplierMode || 'single');
    fillLookup(byId('so-supplier'), doc.supplierId ? { id: doc.supplierId, name: doc.supplierName } : null);
    setSelectValue(byId('so-supplier-currency'), doc.supplierCurrency || 'OMR');
    fillLookup(byId('so-quotation'), doc.quotationId ? { id: doc.quotationId, code: doc.quotationCode } : null);
    byId('so-customer-po').value = doc.customerPo || '';
    byId('so-category').value = doc.purchaseCategory || '';
    byId('so-duty').value = pbMoney(pbNum(doc.customDuty));
    byId('so-promotion').value = pbMoney(pbNum(doc.businessPromotion));
    byId('so-advance').value = pbMoney(pbNum(doc.advancePayment));
    soShowMode();
  },
  onReset() {
    forgetLookups('quotation');
    byId('so-doc-title').value = 'Sales Order';
    byId('so-mode').value = 'single';
    byId('so-supplier-currency').value = 'OMR';
    soShowMode();
  },
  init(form, sales) {
    soSales = sales;
    // A quotation picked in Ref ID: its customer, terms and lines become the order's, each line with the buying cost
    // an item picked on the line gets (soFillBuyingCost).
    // Another buyer: a quotation picked for the one before is cleared (it is not this buyer's).
    byId('so-customer').addEventListener('input', () => {
      const quotationId = byId('so-quotation-id').value;
      const customerId = byId('so-customer-id').value;
      const quotation = (lookupCache.quotation || []).find(row => String(row.id) === quotationId);
      if (quotation && customerId && String(quotation.customerId) !== customerId) fillLookup(byId('so-quotation'), null);
    });
    byId('so-quotation').addEventListener('input', async () => {
      const id = byId('so-quotation-id').value;
      if (!id) return;
      try {
        const quotation = await apiRequest(`api/quotations.php?id=${id}`);
        await sales.copyFrom(quotation, form);
        if (quotation.referenceNo && !byId('so-customer-po').value.trim()) byId('so-customer-po').value = quotation.referenceNo;
        form.page.absorb();
      } catch (error) { showToast('The quotation could not be loaded', error.message, true); }
    });
    // Document Title: a Sales Order carries no VAT; a Proforma Invoice has VAT (5% in OMR) and no buying side.
    // Quotation or Delivery Note opens that document's form with what is entered here (customer, terms, lines).
    byId('so-doc-title').addEventListener('change', async () => {
      const target = { Quotation: ['qt', qtForm, 'trade/quotation/new'], 'Delivery Note': ['dn', dnForm, 'trade/delivery-note/new'] }[byId('so-doc-title').value];
      if (target) {
        const doc = soAsDocument();
        byId('so-doc-title').value = 'Sales Order';
        location.hash = `#/${target[2]}`;
        await new Promise(resolve => setTimeout(resolve, 150));          // the route opens the new, empty form
        if (doc.customerId || doc.items.length) await SALES_HELPERS[target[0]].copyFrom(doc, target[1]);
        return;
      }
      soShowMode();
      form.setVat(soIsInvoice() && soCurrency() === 'OMR');
      form.page.absorb();
    });
    byId('so-mode').addEventListener('change', () => { soShowMode(); form.refresh(); form.page.absorb(); });
    byId('so-auto-supplier').addEventListener('click', () => soAutoSelectSuppliers(form));
    // Supplier Name (single mode): its currency becomes the Supplier Currency.
    byId('so-supplier').addEventListener('input', async () => {
      const id = byId('so-supplier-id').value;
      const supplier = id ? await pbSupplier(id).catch(() => null) : null;
      const code = String(supplier?.currency || '').toUpperCase();
      if (SO_RATES_TO_OMR[code]) byId('so-supplier-currency').value = code;
      soShowMode();
      form.refresh();
      form.page.absorb();
    });
    byId('so-supplier-currency').addEventListener('change', () => { soShowMode(); form.refresh(); form.page.absorb(); });
    // A line's supplier (multi mode) brings its currency.
    byId('so-items').addEventListener('input', async event => {
      if (event.target.dataset.field !== 'supplierName') return;
      const row = event.target.closest('tr');
      const id = pbCell(row, 'supplierId').value;
      const supplier = id ? await pbSupplier(id).catch(() => null) : null;
      pbCell(row, 'supplierCurrency').value = String(supplier?.currency || '').toUpperCase();
      form.refresh();
      form.page.absorb();
    });
    // The costs in the summary are worked into the profit as they are typed.
    for (const id of ['so-duty', 'so-promotion', 'so-advance']) byId(id).addEventListener('input', () => form.refresh());
    byId('so-form').addEventListener('input', event => {
      if (event.target.id === 'so-currency') soShowMode();
      if (event.target.dataset.field === 'buyingCost') form.refresh();
    });
  },
});

/* Delivery Note: the delivery note screen's fields. Ref Num (SO / Quote) is typed, or picked from the sales orders
   and quotations (the suggestions); a pick copies that document's customer and lines. Each line has a Branch
   (a stock point; Auto = the one with the most stock). No payment terms, delivery charge or discount; the summary
   reads Items Total Amount, Total Quantity, Total VAT, Line Discounts Total and Grand Total. */
async function dnFillBranches() {
  let rows = [];
  try { rows = await loadLookup('warehouse'); } catch { rows = []; }
  const options = () => [new Option('Auto (Highest Stock)', ''), ...rows.map(row => new Option(row.name, String(row.id)))];
  byId('pb-line-dn').content.querySelector('[data-field="warehouseId"]').replaceChildren(...options());
  for (const select of byId('dn-items').querySelectorAll('[data-field="warehouseId"]')) {
    const keep = select.dataset.value ?? select.value;
    select.replaceChildren(...options());
    select.value = keep;
  }
}

const dnForm = createSalesForm({
  key: 'dn', route: 'trade/delivery-note', noun: 'Delivery Note', api: 'api/delivery-notes.php', dateKey: 'deliveryNoteDate', lookups: ['dnref'],
  template: 'pb-line-dn', lineExtras: ['deliveryTerm', 'warehouseId'],
  onShow: () => openLookup(byId('dn-customer')),          // a new delivery note starts by picking the Buyer
  // A sales order's lines carry no VAT: on the delivery note they take VAT as usual (5% in OMR).
  copyLine: values => ({ ...values, vatRate: pbNum(values.vatRate) === 0 && (byId('dn-currency-id').value || 'OMR') === 'OMR' ? '5.00' : values.vatRate }),
  fieldNodes: { referenceNo: 'dn-reference', customerPo: 'dn-customer-po', carrier: 'dn-carrier', vehicleNo: 'dn-vehicle' },
  header: () => {
    const [kind, id] = byId('dn-reference-id').value.split(':');
    return {
      referenceNo: byId('dn-reference').value.trim(), salesOrderId: kind === 'so' ? id : null, quotationId: kind === 'qt' ? id : null,
      customerPo: byId('dn-customer-po').value.trim(), carrier: byId('dn-carrier').value.trim(), vehicleNo: byId('dn-vehicle').value.trim(),
    };
  },
  afterRefresh() {
    const rows = [...byId('dn-items').rows];
    const lineDiscounts = rows.reduce((sum, row) => sum + pbNum(pbCell(row, 'discountAmount')?.value), 0);
    const subtotal = pbNum(byId('dn-subtotal').textContent);
    byId('dn-items-total').textContent = pbShow(subtotal + lineDiscounts);
    byId('dn-line-discounts').textContent = pbShow(lineDiscounts);
    byId('dn-vat-label').textContent = 'Total VAT Amount';
  },
  fill(doc) {
    const refId = doc.salesOrderId ? `so:${doc.salesOrderId}` : doc.quotationId ? `qt:${doc.quotationId}` : '';
    fillLookup(byId('dn-reference'), refId ? { id: refId, code: doc.referenceNo } : null);
    if (!refId) byId('dn-reference').value = doc.referenceNo || '';     // an older note's typed reference
    byId('dn-customer-po').value = doc.customerPo || '';
    byId('dn-carrier').value = doc.carrier || '';
    byId('dn-vehicle').value = doc.vehicleNo || '';
  },
  onReset() { forgetLookups('dnref'); dnFillBranches(); },   // the stock points as they are now
  init(form, sales) {
    dnFillBranches();
    // A quotation or sales order picked in the Ref Num popup: its customer, terms and lines become the note's.
    byId('dn-reference').addEventListener('input', async () => {
      const [kind, id] = byId('dn-reference-id').value.split(':');
      if (!id) return;
      try {
        const doc = await apiRequest(`api/${kind === 'so' ? 'sales-orders' : 'quotations'}.php?id=${id}`);
        if (doc.customerPo) byId('dn-customer-po').value = doc.customerPo;
        await sales.copyFrom(doc, form);
      } catch (error) { showToast('The document could not be loaded', error.message, true); }
    });
  },
});

/* Tax Invoice (Transaction Entry): a VAT invoice to a customer, in the Transaction Entry teal. Document Title
   (Invoice; Quotation / Sales Order / Delivery Note open that form with what is entered here), Ref ID (a quotation,
   sales order or delivery note picked in its popup: its buyer, terms and lines are copied in), Customer PO Number,
   Purchase Category, Delivery Location, Payment Terms (a list) and, for Credit, Credit Period; lines with Delivery Term, Qty, Unit, Unit Price,
   VAT % and Total Price (VAT Enabled in OMR); the summary: Total Selling Price, Transportation Charge, VAT / Tax
   Total, Discount, Advance Payment, Grand Total. Send For Approval saves it approved. */
const tiBase = () => byId('ti-currency-id').value || 'OMR';

// What is entered on the invoice, as a saved document's shape (for copyFrom into the form its Document Title opens).
function tiAsDocument() {
  const value = id => byId(id).value.trim();
  const items = tiForm.page.rowsOf('items').map(row => {
    const cell = field => pbCell(row, field)?.value.trim() ?? '';
    return {
      itemId: cell('itemId') || null, itemCode: cell('itemCode'), itemName: cell('itemName'), itemNameHtml: cell('itemNameHtml'),
      brandId: cell('brandId') || null, brandName: cell('brandName'), uomId: cell('uomId') || null, unit: cell('unit'),
      deliveryTerm: cell('deliveryTerm'), quantity: cell('quantity'), price: cell('price'), vatRate: cell('vatRate'),
      discountPct: '0', discountAmount: '0', foc: false,
    };
  }).filter(line => line.itemId || line.itemName);
  return {
    code: value('ti-code') || 'this invoice', customerId: value('ti-customer-id') || null, customerName: value('ti-customer'),
    contactName: value('ti-contact'), contactNumber: value('ti-contact-number'), currency: tiBase(), deliveryLocation: value('ti-location'),
    paymentMode: value('ti-payment'), creditPeriod: value('ti-payment') === 'Credit' ? value('ti-credit-period') : '', vatMode: 'exclude', discountAmount: value('ti-discount'), shipping: value('ti-shipping'),
    customerPo: value('ti-customer-po'), purchaseCategory: value('ti-category'), items,
  };
}

const tiForm = createSalesForm({
  key: 'ti', route: 'entry/tax-invoice', noun: 'Tax Invoice', api: 'api/tax-invoices.php', dateKey: 'invoiceDate', lookups: [],
  template: 'pb-line-ti', defaultLocation: false,
  onShow: () => openLookup(byId('ti-customer')),          // a new invoice starts by picking the Buyer
  // A sales order's lines carry no VAT: on the invoice they take VAT as usual (5% in OMR). A line's discount is kept
  // (in the line's hidden cells), so the invoice totals what the document it came from does.
  copyLine: values => ({ ...values, vatRate: pbNum(values.vatRate) === 0 && tiBase() === 'OMR' ? '5.00' : values.vatRate }),
  fieldNodes: { documentTitle: 'ti-doc-title', referenceNo: 'ti-reference', quotationId: 'ti-reference', salesOrderId: 'ti-reference',
    deliveryNoteId: 'ti-reference', customerPo: 'ti-customer-po', purchaseCategory: 'ti-category', advancePayment: 'ti-advance' },
  header: () => {
    const [kind, id] = byId('ti-reference-id').value.split(':');
    return {
      documentTitle: 'Invoice', referenceNo: byId('ti-reference').value.trim(),
      quotationId: kind === 'qt' ? id : null, salesOrderId: kind === 'so' ? id : null, deliveryNoteId: kind === 'dn' ? id : null,
      customerPo: byId('ti-customer-po').value.trim(), purchaseCategory: byId('ti-category').value.trim(),
      advancePayment: byId('ti-advance').value.trim() || '0', sendForApproval: byId('ti-approval').checked,
    };
  },
  check(errors) {
    const amount = byId('ti-advance').value.trim();
    if (amount !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(amount)) errors.push({ node: byId('ti-advance'), message: 'Enter an amount with up to 3 decimals.' });
  },
  afterRefresh() {
    for (const label of byId('ti-form').querySelectorAll('[data-ti-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
    byId('ti-vat-label').textContent = 'VAT / Tax Total (OMR)';
    byId('ti-save-label').textContent = FORM_PAGES['entry/tax-invoice/new']?.isEditing?.() ? 'Update Invoice' : 'Save Invoice';
  },
  fill(doc) {
    const kind = doc.deliveryNoteId ? 'dn' : doc.salesOrderId ? 'so' : doc.quotationId ? 'qt' : '';
    const id = { dn: doc.deliveryNoteId, so: doc.salesOrderId, qt: doc.quotationId }[kind];
    byId('ti-reference').value = doc.referenceNo || '';
    byId('ti-reference-id').value = kind ? `${kind}:${id}` : '';
    byId('ti-customer-po').value = doc.customerPo || '';
    byId('ti-category').value = doc.purchaseCategory || '';
    byId('ti-advance').value = pbMoney(pbNum(doc.advancePayment));
    byId('ti-approval').checked = Boolean(doc.sendForApproval);
  },
  onReset() {
    byId('ti-doc-title').value = 'Invoice';
    byId('ti-approval').checked = false;
  },
  init(form, sales) {
    // A document picked in Ref ID: its buyer, terms and lines become the invoice's.
    byId('ti-reference').addEventListener('input', async () => {
      const [kind, id] = byId('ti-reference-id').value.split(':');
      if (!id) return;
      const api = { qt: 'quotations', so: 'sales-orders', dn: 'delivery-notes' }[kind];
      try {
        const doc = await apiRequest(`api/${api}.php?id=${id}`);
        if (doc.customerPo && !byId('ti-customer-po').value.trim()) byId('ti-customer-po').value = doc.customerPo;
        if (doc.purchaseCategory && !byId('ti-category').value.trim()) byId('ti-category').value = doc.purchaseCategory;
        if (pbNum(doc.advancePayment) && !pbNum(byId('ti-advance').value)) byId('ti-advance').value = pbMoney(pbNum(doc.advancePayment));
        await sales.copyFrom(doc, form);
      } catch (error) { showToast('The document could not be loaded', error.message, true); }
    });
    // Document Title: Quotation, Sales Order or Delivery Note opens that form with what is entered here.
    byId('ti-doc-title').addEventListener('change', async () => {
      const target = { Quotation: ['qt', qtForm, 'trade/quotation/new'], 'Sales Order': ['so', soForm, 'trade/sales-order/new'],
        'Delivery Note': ['dn', dnForm, 'trade/delivery-note/new'] }[byId('ti-doc-title').value];
      if (!target) return;
      const doc = tiAsDocument();
      byId('ti-doc-title').value = 'Invoice';
      location.hash = `#/${target[2]}`;
      await new Promise(resolve => setTimeout(resolve, 150));          // the route opens the new, empty form
      if (doc.customerId || doc.items.length) await SALES_HELPERS[target[0]].copyFrom(doc, target[1]);
    });
    byId('ti-advance').addEventListener('input', () => form.refresh());
    byId('ti-approval').addEventListener('change', () => form.page.record());
  },
});

/* ---------- Supply Management: Stock Adjustment, Stock Transfer, Stock Reservation ----------
   Item lines from the Item master (Create Item adds one), Remarks, signatory slots and the seal, as the Purchase Book.
   Stock figures come from api/stock-levels.php (src/supply.php): on hand at a stock point (opening stock, GRNs,
   delivery notes, transfers, adjustments) and what running reservations hold. Shift+X adds a line. */
const smLevels = { sa: null, st: null, rsv: null };          // the stock figures each page shows: { key, onHand, reserved }
const smEditing = { sa: null, st: null, rsv: null };         // the id of the document open for editing
const smSigned = value => (value > 0.0005 ? `+${pbQty(value)}` : pbQty(value));
const smUser = () => byId('header-user')?.textContent.trim() || '';
const smFilled = row => Boolean(pbCell(row, 'itemId').value || pbCell(row, 'itemName').value.trim());

async function smLoadLevels(key, warehouseId, except) {
  const query = new URLSearchParams();
  if (warehouseId) query.set('warehouseId', warehouseId);
  if (smEditing[key]) query.set(except, smEditing[key]);
  const wanted = query.toString();
  if (smLevels[key]?.key === wanted) return smLevels[key];
  try {
    const levels = await apiRequest(`api/stock-levels.php?${wanted}`);
    smLevels[key] = { key: wanted, onHand: levels.onHand || {}, reserved: levels.reserved || {} };
  } catch (error) {
    showToast('Stock levels could not be loaded', error.message, true);
    smLevels[key] = { key: wanted, onHand: {}, reserved: {} };
  }
  return smLevels[key];
}
const smOnHand = (levels, itemId) => pbNum(levels?.onHand?.[itemId]);
// An item's buying cost (Item master) for the line's Unit Cost when it has none.
function smUnitCost(row, item) {
  const cell = pbCell(row, 'unitCost');
  if (cell && pbNum(cell.value) === 0 && pbNum(item.buyingRate) > 0) cell.value = pbMoney(pbNum(item.buyingRate));
}

/* Stock Adjustment (ADJ000001): a stock point's counted quantities. System Qty is the stock there now (kept on the
   line when saved); Physical Qty what was counted (starts at the system quantity); Difference = Physical − System;
   Adj. Qty its size; Adj. Value = Difference × Unit Cost. A saved adjustment moves the stock. */
async function saSetSystem(form, rows) {
  const levels = await smLoadLevels('sa', byId('sa-warehouse-id').value, 'adjustment');
  for (const row of rows) {
    const itemId = pbCell(row, 'itemId').value;
    if (!itemId) continue;
    const before = pbCell(row, 'systemQty').value;
    const system = byId('sa-warehouse-id').value ? pbQty(smOnHand(levels, itemId)) : '';
    pbCell(row, 'systemQty').value = system;
    // A new count starts at the system quantity (only the differences are typed).
    if (row.dataset.counted !== '1' && (pbCell(row, 'quantity').value === '0' || pbCell(row, 'quantity').value === before)) {
      pbCell(row, 'quantity').value = system || '0';
    }
  }
  form.refresh();
}

const saForm = createPurchaseForm({
  key: 'sa', route: 'supply/stock-adjustment/new', noun: 'Stock Adjustment', api: 'api/stock-adjustments.php',
  kind: 'simple', template: 'pb-line-sa', itemsFromMaster: true, zeroQty: true, shiftXAddsRow: true,
  lineExtras: ['systemQty', 'unitCost', 'lineReason'],
  firstField: () => byId('sa-warehouse'),
  // A new adjustment starts on Stock Point with its popup open (no items are fetched: they are added by hand).
  opened(form) {
    setTimeout(() => {
      if (currentRoute !== 'supply/stock-adjustment/new' || form.page.isEditing() || byId('sa-warehouse-id').value || byId('lookup').open) return;
      if (document.activeElement === byId('sa-warehouse')) openLookup(byId('sa-warehouse'), { byKeyboard: true });
    }, 150);
  },
  fieldNodes: { adjustmentDate: 'sa-date', warehouseId: 'sa-warehouse', reason: 'sa-reason',
    requestedBy: 'sa-requested', approvedBy: 'sa-approved', remarks: 'sa-remarks-editor' },
  header: () => ({
    adjustmentDate: byId('sa-date').value, warehouseId: byId('sa-warehouse-id').value || null,
    reason: byId('sa-reason').value.trim(), requestedBy: byId('sa-requested').value.trim(), approvedBy: byId('sa-approved').value.trim(),
  }),
  check(form, errors) {
    if (!byId('sa-warehouse-id').value) errors.push({ node: byId('sa-warehouse'), message: 'Select the stock point.' });
    saForm.page.rowsOf('items').forEach((row, i) => {
      const cost = pbCell(row, 'unitCost').value.trim();
      if (smFilled(row) && cost !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(cost)) errors.push({ node: pbCell(row, 'unitCost'), message: `Row ${i + 1}: enter the unit cost with up to 3 decimals.` });
    });
  },
  afterRefresh() {
    const rows = saForm.page.rowsOf('items');
    let net = 0;
    let value = 0;
    for (const row of rows) {
      const filled = smFilled(row);
      const systemText = pbCell(row, 'systemQty').value;
      const diff = pbNum(pbCell(row, 'quantity').value) - pbNum(systemText);
      const amount = diff * pbNum(pbCell(row, 'unitCost').value);
      row.querySelector('[data-system]').textContent = filled && systemText !== '' ? systemText : '—';
      const diffCell = row.querySelector('[data-diff]');
      // ↑ 2 (counted more, green) or ↓ 2 (counted less, red); 0 when they match.
      diffCell.textContent = !filled ? '—' : diff > 0.0005 ? `↑ ${pbQty(diff)}` : diff < -0.0005 ? `↓ ${pbQty(-diff)}` : '0';
      diffCell.classList.toggle('is-up', filled && diff > 0.0005);
      diffCell.classList.toggle('is-down', filled && diff < -0.0005);
      row.querySelector('[data-adj]').textContent = filled ? pbQty(Math.abs(diff)) : '—';
      // Under Adj. Qty: Stock In (counted more) or Stock Out (counted less); nothing when they match.
      const dir = row.querySelector('[data-dir]');
      dir.textContent = !filled ? '' : diff > 0.0005 ? 'Stock In' : diff < -0.0005 ? 'Stock Out' : '';
      dir.className = `sm-dir${diff > 0.0005 ? ' is-in' : diff < -0.0005 ? ' is-out' : ''}`;
      row.querySelector('[data-total]').textContent = pbShow(filled ? amount : 0);
      if (!filled) continue;
      net += diff;
      value += amount;
    }
    byId('sa-item-count').textContent = String(rows.filter(smFilled).length || rows.length);
    byId('sa-net').textContent = smSigned(net);
    byId('sa-subtotal').textContent = pbShow(value);
    byId('sa-grand').textContent = pbShow(value);
    byId('sa-save-label').textContent = FORM_PAGES['supply/stock-adjustment/new']?.isEditing?.() ? 'Update Adjustment' : 'Save Adjustment';
  },
  listRoute: 'supply/stock-adjustment',
  async onItem(form, row, item) {
    smUnitCost(row, item);
    delete row.dataset.counted;
    pbCell(row, 'quantity').value = '0';
    await saSetSystem(form, [row]);
  },
  fill(form, doc) {
    smEditing.sa = doc.id;
    smLevels.sa = null;
    byId('sa-date').value = doc.adjustmentDate;
    fillLookup(byId('sa-warehouse'), doc.warehouseId ? { id: doc.warehouseId, code: doc.warehouseCode, name: doc.warehouseName } : null);
    byId('sa-reason').value = doc.reason || '';
    byId('sa-requested').value = doc.requestedBy || '';
    byId('sa-approved').value = doc.approvedBy || '';
  },
  afterFill(form, doc) {
    form.page.rowsOf('items').forEach((row, i) => {
      const line = doc.items[i] || {};
      row.dataset.counted = '1';
      pbCell(row, 'systemQty').value = pbQty(pbNum(line.systemQty));
      pbCell(row, 'unitCost').value = pbMoney(pbNum(line.unitCost));
      pbCell(row, 'lineReason').value = line.lineReason || '';
    });
  },
  onReset() {
    smEditing.sa = null;
    smLevels.sa = null;
    byId('sa-date').value = todayInputValue();
    byId('sa-reason').value = 'Physical Count Difference';
    byId('sa-requested').value = smUser();
  },
  init(form) {
    byId('sa-warehouse').addEventListener('input', () => saSetSystem(form, form.page.rowsOf('items')));
    byId('sa-form').addEventListener('input', event => {
      if (event.target.dataset.field === 'quantity') event.target.closest('tr').dataset.counted = '1';
      if (['quantity', 'unitCost'].includes(event.target.dataset.field)) form.refresh();
    });
  },
});

/* Stock Transfer (ST-0001): stock sent From one stock point To another; Total = Quantity × Unit Cost. A quantity
   more than the source holds is marked (the transfer still saves). */
async function stMarkStock(rows) {
  const from = byId('st-from-id').value;
  const levels = from ? await smLoadLevels('st', from, 'transfer') : null;
  for (const row of rows) {
    const itemId = pbCell(row, 'itemId').value;
    const cell = pbCell(row, 'quantity');
    const over = Boolean(levels && itemId && pbNum(cell.value) > smOnHand(levels, itemId) + 0.0005);
    cell.classList.toggle('sm-over', over);
    cell.title = levels && itemId ? `${pbQty(smOnHand(levels, itemId))} in stock at ${byId('st-from').value}` : '';
  }
}

const stForm = createPurchaseForm({
  key: 'st', route: 'supply/stock-transfer/new', noun: 'Stock Transfer', api: 'api/stock-transfers.php',
  kind: 'simple', template: 'pb-line-st', itemsFromMaster: true, shiftXAddsRow: true, lineExtras: ['unitCost'],
  firstField: () => byId('st-date'),
  fieldNodes: { transferDate: 'st-date', expectedDate: 'st-expected', fromWarehouseId: 'st-from', toWarehouseId: 'st-to',
    transferReason: 'st-reason', remarks: 'st-remarks-editor' },
  header: () => ({
    transferDate: byId('st-date').value, expectedDate: byId('st-expected').value || null,
    fromWarehouseId: byId('st-from-id').value || null, toWarehouseId: byId('st-to-id').value || null, transferReason: byId('st-reason').value.trim(),
  }),
  check(form, errors) {
    if (!byId('st-date').value) errors.push({ node: byId('st-date'), message: 'Enter the transfer date.' });
    if (!byId('st-from-id').value) errors.push({ node: byId('st-from'), message: 'Select the stock point the stock leaves.' });
    if (!byId('st-to-id').value) errors.push({ node: byId('st-to'), message: 'Select the stock point the stock goes to.' });
    else if (byId('st-to-id').value === byId('st-from-id').value) errors.push({ node: byId('st-to'), message: 'The destination must be a different stock point from the source.' });
    if (byId('st-expected').value && byId('st-date').value && byId('st-expected').value < byId('st-date').value) {
      errors.push({ node: byId('st-expected'), message: 'The expected date cannot be before the transfer date.' });
    }
    stForm.page.rowsOf('items').forEach((row, i) => {
      const cost = pbCell(row, 'unitCost').value.trim();
      if (smFilled(row) && cost !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(cost)) errors.push({ node: pbCell(row, 'unitCost'), message: `Row ${i + 1}: enter the unit cost with up to 3 decimals.` });
    });
  },
  afterRefresh() {
    const rows = stForm.page.rowsOf('items');
    let total = 0;
    for (const row of rows) {
      const amount = smFilled(row) ? pbNum(pbCell(row, 'quantity').value) * pbNum(pbCell(row, 'unitCost').value) : 0;
      row.querySelector('[data-total]').textContent = pbShow(amount);
      total += amount;
    }
    byId('st-subtotal').textContent = pbShow(total);
    byId('st-grand').textContent = pbShow(total);
    byId('st-item-count').textContent = String(rows.filter(smFilled).length || rows.length);
    byId('st-save-label').textContent = FORM_PAGES['supply/stock-transfer/new']?.isEditing?.() ? 'Update Stock Transfer' : 'Save Stock Transfer';
    stMarkStock(rows);
  },
  listRoute: 'supply/stock-transfer',
  onItem(form, row, item) { smUnitCost(row, item); },
  fill(form, doc) {
    smEditing.st = doc.id;
    smLevels.st = null;
    byId('st-date').value = doc.transferDate;
    byId('st-expected').value = doc.expectedDate || '';
    fillLookup(byId('st-from'), doc.fromWarehouseId ? { id: doc.fromWarehouseId, code: doc.fromWarehouseCode, name: doc.fromWarehouseName } : null);
    fillLookup(byId('st-to'), doc.toWarehouseId ? { id: doc.toWarehouseId, code: doc.toWarehouseCode, name: doc.toWarehouseName } : null);
    byId('st-reason').value = doc.transferReason || '';
  },
  afterFill(form, doc) {
    form.page.rowsOf('items').forEach((row, i) => { pbCell(row, 'unitCost').value = pbMoney(pbNum(doc.items[i]?.unitCost)); });
  },
  onReset() {
    smEditing.st = null;
    smLevels.st = null;
    byId('st-date').value = todayInputValue();
  },
  init(form) {
    // From lists every stock point; picking the one already in To clears To (To never offers From's stock point).
    byId('st-from').addEventListener('input', () => {
      if (byId('st-from-id').value && byId('st-from-id').value === byId('st-to-id').value) fillLookup(byId('st-to'), null);
      form.refresh();
    });
    byId('st-form').addEventListener('input', event => {
      if (['quantity', 'unitCost'].includes(event.target.dataset.field)) form.refresh();
    });
  },
});

/* Stock Reservation (SR000001): stock held for a customer until the Required Date. Available Qty = on hand at the
   stock point (every stock point when none is chosen) less what other running reservations hold; a reserved
   quantity more than that is marked. */
// Where an item's stock is (api/stock-levels.php?itemId=), kept for the page: shown under Available Qty when the
// chosen stock point has none of it, e.g. "1200 at WH-2026-0003".
const rsvStockPoints = new Map();
function rsvItemPoints(itemId) {
  if (!rsvStockPoints.has(itemId)) {
    rsvStockPoints.set(itemId, apiRequest(`api/stock-levels.php?itemId=${encodeURIComponent(itemId)}`)
      .then(result => result.points || []).catch(() => { rsvStockPoints.delete(itemId); return []; }));
  }
  return rsvStockPoints.get(itemId);
}

async function rsvShowAvailable(rows) {
  const warehouseId = byId('rsv-warehouse-id').value;
  const levels = await smLoadLevels('rsv', warehouseId, 'reservation');
  for (const row of rows) {
    const itemId = pbCell(row, 'itemId').value;
    const available = itemId ? smOnHand(levels, itemId) - pbNum(levels.reserved?.[itemId]) : null;
    row.querySelector('[data-available]').textContent = available === null ? '—' : pbQty(available);
    pbCell(row, 'quantity').classList.toggle('sm-over', available !== null && pbNum(pbCell(row, 'quantity').value) > available + 0.0005);
    const note = row.querySelector('[data-elsewhere]');
    note.textContent = '';
    note.title = '';
    if (!itemId || !warehouseId || available > 0.0005) continue;
    // None at this stock point: say where the item's stock is (or that there is none anywhere).
    rsvItemPoints(itemId).then(points => {
      if (pbCell(row, 'itemId').value !== itemId || byId('rsv-warehouse-id').value !== warehouseId) return;
      const others = points.filter(point => String(point.warehouseId) !== String(warehouseId) && pbNum(point.qty) > 0);
      note.textContent = others.length ? `${pbQty(pbNum(others[0].qty))} at ${others[0].code}${others.length > 1 ? ` +${others.length - 1}` : ''}` : 'No stock';
      note.title = others.length ? others.map(point => `${pbQty(pbNum(point.qty))} at ${point.code} · ${point.name}`).join(', ') : 'This item has no stock at any stock point.';
    });
  }
}

const rsvForm = createPurchaseForm({
  key: 'rsv', route: 'supply/stock-reservation/new', noun: 'Stock Reservation', api: 'api/stock-reservations.php',
  kind: 'simple', template: 'pb-line-rsv', itemsFromMaster: true, shiftXAddsRow: true,
  firstField: () => byId('rsv-date'),
  fieldNodes: { reservationDate: 'rsv-date', reservationType: 'rsv-type', referenceNo: 'rsv-reference', customerId: 'rsv-customer',
    warehouseId: 'rsv-warehouse', requiredDate: 'rsv-required', remarks: 'rsv-remarks-editor' },
  header: () => ({
    reservationDate: byId('rsv-date').value, reservationType: byId('rsv-type').value, referenceNo: byId('rsv-reference').value.trim(),
    customerId: byId('rsv-customer-id').value || null, warehouseId: byId('rsv-warehouse-id').value || null,
    requiredDate: byId('rsv-required').value,
  }),
  check(form, errors) {
    if (!byId('rsv-date').value) errors.push({ node: byId('rsv-date'), message: 'Enter the reservation date.' });
    if (!byId('rsv-required').value) errors.push({ node: byId('rsv-required'), message: 'Enter the date the stock is required.' });
    else if (byId('rsv-date').value && byId('rsv-required').value < byId('rsv-date').value) {
      errors.push({ node: byId('rsv-required'), message: 'The required date cannot be before the reservation date.' });
    }
  },
  afterRefresh() {
    const rows = rsvForm.page.rowsOf('items');
    byId('rsv-item-count').textContent = String(rows.filter(smFilled).length || rows.length);
    byId('rsv-sum-point').textContent = byId('rsv-warehouse').value.trim() || 'All stock points';
    byId('rsv-sum-required').textContent = poSlashDate(byId('rsv-required').value) || '—';
    byId('rsv-total').textContent = pbQty(rows.filter(smFilled).reduce((sum, row) => sum + pbNum(pbCell(row, 'quantity').value), 0));
    byId('rsv-save-label').textContent = FORM_PAGES['supply/stock-reservation/new']?.isEditing?.() ? 'Update Stock Reservation' : 'Save Stock Reservation';
    rsvShowAvailable(rows);
  },
  listRoute: 'supply/stock-reservation',
  fill(form, doc) {
    smEditing.rsv = doc.id;
    smLevels.rsv = null;
    byId('rsv-date').value = doc.reservationDate;
    byId('rsv-type').value = doc.reservationType || 'Sales Order';
    byId('rsv-reference').value = doc.referenceNo || '';
    fillLookup(byId('rsv-customer'), doc.customerId ? { id: doc.customerId, name: doc.customerName } : null);
    fillLookup(byId('rsv-warehouse'), doc.warehouseId ? { id: doc.warehouseId, code: doc.warehouseCode, name: doc.warehouseName } : null);
    byId('rsv-required').value = doc.requiredDate || '';
    byId('rsv-created-by').value = doc.createdBy || '';
    byId('rsv-created-date').value = poSlashDate(doc.createdAt);
  },
  onReset() {
    smEditing.rsv = null;
    smLevels.rsv = null;
    const today = todayInputValue();
    byId('rsv-date').value = today;
    const required = new Date(`${today}T00:00:00`);
    required.setDate(required.getDate() + 7);            // a week to collect, by default
    byId('rsv-required').value = `${required.getFullYear()}-${String(required.getMonth() + 1).padStart(2, '0')}-${String(required.getDate()).padStart(2, '0')}`;
    byId('rsv-type').value = 'Sales Order';
    byId('rsv-created-by').value = smUser();
    byId('rsv-created-date').value = poSlashDate(today);
  },
  init(form) {
    byId('rsv-form').addEventListener('input', event => {
      if (['rsv-warehouse', 'rsv-required', 'rsv-date'].includes(event.target.id) || event.target.dataset.field === 'quantity') form.refresh();
    });
  },
});

/* ---------- Stock Ledger (Supply Management › Stock Ledger, #/supply/stock-report) ----------
   api/stock-report.php sends every stock movement worked out from the documents (src/stock_report.php) and the
   damaged stock; this page sums them per item and stock point.
   - Stock Levels & Valuation: one row per item at a stock point. Purchased = GRN / purchase / replacement received,
     Sold = invoice / delivery note / replacement given, Stock Available = everything in less everything out (as at
     the end of the Period), Avg Buying Cost = the purchases' weighted rate (else the Item master's buying rate),
     Selling Price = the sales' weighted rate (else the Item master's), Stock Value = Available × Avg Buying Cost.
     Low Stock: at or under the item's minimum stock level (none set: a tenth of what was purchased).
   - Stock Movement Ledger: every movement, newest first.
   - Damaged Stock: every sales return and purchase return line (returns never change the stock on hand), with a
     replacement's returned goods; Damaged Entries, Items, Quantity and Value. On this tab the bar shows Filter
     (All / Sales Return / Purchase Return) in place of Stock Point, and the tab has its own stock point list.
   - Stock Point (in the bar on the Movement Ledger, in the Stock Levels row; one choice) and Period are for the cards
     and both tabs: that stock point (All Stock Points: every one) and that month (All Months: everything). Stock
     Levels has Filter (All / All Sales / All Purchases) in the bar. History: one item's movements with the
     balance. */
const STK_PAGE_SIZE = 8;
const STK_PURCHASE_IN = ['Stock In (GRN)', 'Stock In (Purchase)', 'Stock In (Replacement)'];
const STK_SALES_OUT = ['Stock Out (Delivery Note)', 'Stock Out (Invoice)', 'Stock Out (Replacement)'];
const STK_TYPE_TONE = {
  'Opening Stock': 'grey', 'Stock In (GRN)': 'green', 'Stock In (Purchase)': 'green', 'Stock In (Replacement)': 'green', 'Stock In (Replacement Return)': 'green',
  'Stock Out (Delivery Note)': 'red', 'Stock Out (Invoice)': 'red', 'Stock Out (Replacement)': 'red', 'Stock Out (Replacement Return)': 'red',
  'Transfer In': 'blue', 'Transfer Out': 'blue', 'Adjustment (+)': 'grey', 'Adjustment (−)': 'grey', 'Damage Restock': 'green',
};
const stk = { data: null, tab: 'levels', page: { levels: 1, ledger: 1, damaged: 1 }, loading: null, historyItem: null };
const STK_RETURN_TONE = { 'Sales Return': 'blue', 'Sales Replacement': 'blue', 'Purchase Return': 'amber', 'Purchase Replacement': 'amber' };
const stkEl = suffix => byId(`stkr-${suffix}`);
const stkQty = value => pbQty(pbNum(value));
const stkMoney = value => pbNum(value).toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
const stkSigned = value => (value > 0.0005 ? `+${stkQty(value).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}` : value < -0.0005 ? `−${stkQty(-value).replace(/\B(?=(\d{3})+(?!\d))/g, ',')}` : '0');
const stkItem = id => stk.data?.items?.[id] || { code: '', name: `Item #${id}`, brand: '', unit: '' };
const stkPoint = id => (id ? stk.data?.stockPoints?.[id] : null) || { code: '', name: id ? `Stock point #${id}` : 'No stock point' };
const stkMonthEnd = period => { const [y, m] = period.split('-').map(Number); return `${period}-${String(new Date(y, m, 0).getDate()).padStart(2, '0')}`; };
const stkInPeriod = date => !stkEl('period').value || String(date).startsWith(stkEl('period').value);
const stkUpTo = date => !stkEl('period').value || String(date) <= stkMonthEnd(stkEl('period').value);
const stkAtPoint = warehouseId => !stkEl('point').value || String(warehouseId) === stkEl('point').value;
const stkText = (...values) => values.join(' ').toLowerCase();
// Goods moved back from Damaged Stock show on Stock Levels & Valuation (and the item's History), not in the
// Stock Movement Ledger.
const stkInLedger = m => m.type !== 'Damage Restock';

async function stkLoad({ sync = false } = {}) {
  if (stk.loading) return stk.loading;
  stkEl('synced').textContent = sync ? 'Syncing stocks…' : 'Loading…';
  stk.loading = (async () => {
    try {
      if (sync) forgetLookups('item', 'warehouse');       // new items and stock points show too
      stk.data = await apiRequest('api/stock-report.php');
      const at = new Date(stk.data.generatedAt);
      stkEl('synced').textContent = `Last synced: ${at.toLocaleDateString('en-GB')} ${at.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })}`;
      stkFillFilters();
      stkRender();
      if (sync) showToast('Stocks synced', `${stk.data.movements.length} stock movement${stk.data.movements.length === 1 ? '' : 's'} worked out from the documents.`);
    } catch (error) {
      stkEl('synced').textContent = 'Could not load';
      showToast('The stock ledger could not be loaded', error.message, true);
    } finally {
      stk.loading = null;
    }
  })();
  return stk.loading;
}

// The Period, Stock Point and Movement Type lists from the data (a choice already made is kept).
function stkFillFilters() {
  const keep = select => select.value;
  // Every month of every year from the first stock document to this year, grouped by year (the newest year first),
  // each year's months in calendar order January → December — not only the months that have movements (a month
  // without any shows its empty figures).
  const now = new Date();
  const years = [...stk.data.movements, ...stk.data.damaged].map(m => Number(String(m.date).slice(0, 4))).filter(y => y > 1900 && y < 3000);
  const firstYear = Math.min(now.getFullYear(), ...years);
  const lastYear = Math.max(now.getFullYear(), ...years);
  const months = [];
  const period = stkEl('period'); const p = keep(period);
  const groups = [];
  for (let y = lastYear; y >= firstYear; y--) {
    const group = document.createElement('optgroup');
    group.label = String(y);
    for (let m = 1; m <= 12; m++) {
      const value = `${y}-${String(m).padStart(2, '0')}`;
      months.push(value);
      group.append(new Option(new Date(y, m - 1, 1).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' }), value));
    }
    groups.push(group);
  }
  period.replaceChildren(new Option('All Months', ''), ...groups);
  period.value = months.includes(p) ? p : '';
  const points = Object.entries(stk.data.stockPoints).map(([id, w]) => new Option(`${w.code} · ${w.name}`, id));
  for (const id of ['point', 'levels-point', 'damaged-point']) {
    const select = stkEl(id); const v = keep(select);
    select.replaceChildren(new Option('All Stock Points', ''), ...points.map(option => option.cloneNode(true)));
    select.value = v;
  }
}

// The Movement Type list (fixed): every movement, all in, all out, GRN, purchase entry, delivery note, invoice,
// stock transfers (in and out: GRN line transfers and Stock Transfers).
const STK_MOVE_FILTER = {
  in: m => m.dir === 'in', out: m => m.dir === 'out',
  grn: m => m.type === 'Stock In (GRN)', pe: m => m.type === 'Stock In (Purchase)',
  dn: m => m.type === 'Stock Out (Delivery Note)', ti: m => m.type === 'Stock Out (Invoice)',
  transfer: m => m.type === 'Transfer In' || m.type === 'Transfer Out',
};

// Per item: the weighted purchase and sales rates (all stock points, all dates).
function stkRates() {
  const acc = {};
  for (const m of stk.data.movements) {
    const a = acc[m.itemId] ||= { buyQty: 0, buyValue: 0, sellQty: 0, sellValue: 0 };
    if ((STK_PURCHASE_IN.includes(m.type) || m.type === 'Opening Stock') && m.rate > 0) { a.buyQty += m.qty; a.buyValue += m.qty * m.rate; }
    if (STK_SALES_OUT.includes(m.type) && m.rate > 0) { a.sellQty += m.qty; a.sellValue += m.qty * m.rate; }
  }
  const out = {};
  for (const id of Object.keys(stk.data.items)) {
    const a = acc[id] || {}; const item = stkItem(id);
    out[id] = { cost: a.buyQty ? a.buyValue / a.buyQty : pbNum(item.buyingRate), price: a.sellQty ? a.sellValue / a.sellQty : pbNum(item.sellingPrice) };
  }
  return out;
}

// One row per item and stock point, as at the end of the Period.
function stkLevelRows() {
  const rates = stkRates();
  const rows = new Map();
  for (const m of stk.data.movements) {
    if (!stkUpTo(m.date)) continue;
    const key = `${m.itemId}|${m.warehouseId ?? 0}`;
    const row = rows.get(key) || { itemId: m.itemId, warehouseId: m.warehouseId, inQty: 0, outQty: 0, purchased: 0, sold: 0, restocked: 0,
      restockedSales: 0, restockedPurchase: 0 };
    if (m.dir === 'in') row.inQty += m.qty; else row.outQty += m.qty;
    if (stkInPeriod(m.date)) {
      if (STK_PURCHASE_IN.includes(m.type)) row.purchased += m.qty;
      if (STK_SALES_OUT.includes(m.type)) row.sold += m.qty;
      if (m.type === 'Damage Restock') {                            // moved back from Damaged Stock
        row.restocked += m.qty;
        if (m.side === 'sales') row.restockedSales += m.qty; else row.restockedPurchase += m.qty;
      }
    }
    rows.set(key, row);
  }
  return [...rows.values()].map(row => {
    const item = stkItem(row.itemId);
    const available = row.inQty - row.outQty;
    const min = item.minStock == null ? null : pbNum(item.minStock);
    const status = available <= 0.0005 ? 'out'
      : (min && min > 0 ? available <= min : row.purchased > 0 && available <= row.purchased * 0.1) ? 'low' : 'in';
    const cost = rates[row.itemId]?.cost || 0;
    return { ...row, item, point: stkPoint(row.warehouseId), available, status, cost, price: rates[row.itemId]?.price || 0,
      value: Math.max(available, 0) * cost };
  }).sort((a, b) => a.item.name.localeCompare(b.item.name) || a.point.code.localeCompare(b.point.code));
}

function stkFilteredLevels() {
  const q = stkEl('levels-search').value.trim().toLowerCase();
  const status = stkEl('levels-status').value;
  const scope = stkEl('levels-scope').value;                // All / All Sales (items sold) / All Purchases (items purchased)
  return stkLevelRows().filter(row => (!q || stkText(row.item.name, row.item.code, row.item.brand, row.point.name, row.point.code).includes(q))
    && stkAtPoint(row.warehouseId) && (!status || row.status === status)
    && (!scope || (scope === 'sales' ? row.sold > 0 || row.restockedSales > 0 : row.purchased > 0 || row.restockedPurchase > 0)));
}

function stkFilteredLedger() {
  const q = stkEl('ledger-search').value.trim().toLowerCase();
  const type = stkEl('ledger-type').value;
  const from = stkEl('ledger-from').value; const to = stkEl('ledger-to').value;
  return stk.data.movements.filter(m => stkInLedger(m) && stkInPeriod(m.date) && (!type || STK_MOVE_FILTER[type](m)) && stkAtPoint(m.warehouseId) && (!from || m.date >= from) && (!to || m.date <= to)
    && (!q || stkText(m.ref, m.type, m.party, m.remarks, m.by, stkItem(m.itemId).name, stkItem(m.itemId).code, stkPoint(m.warehouseId).name).includes(q)))
    .slice().reverse();
}

// Damaged stock within the Period at the tab's stock point.
function stkDamagedInScope() {
  const point = stkEl('damaged-point').value;
  return stk.data.damaged.filter(d => stkInPeriod(d.date) && (!point || String(d.warehouseId) === point));
}

function stkFilteredDamaged() {
  const q = stkEl('damaged-search').value.trim().toLowerCase();
  const side = stkEl('dmg-filter').value;
  return stkDamagedInScope().filter(d => (!side || d.side === side)
    && (!q || stkText(d.ref, d.source, d.party, d.condition, d.remarks, stkItem(d.itemId).name, stkItem(d.itemId).code).includes(q)))
    .slice().sort((a, b) => String(b.date).localeCompare(String(a.date)));
}

// Small cell builders.
function stkItemCell(itemId) {
  const td = el('td', 'stk-item'); const item = stkItem(itemId);
  td.append(el('div', 'stk-item-name', item.name), el('div', 'stk-sku', `SKU: ${item.code}`));
  return td;
}
function stkPointCell(warehouseId) {
  const td = el('td', 'stk-point'); const point = stkPoint(warehouseId);
  td.append(el('div', '', point.name), ...(point.code ? [el('div', 'stk-sku', point.code)] : []));
  return td;
}
function stkUnitQty(value, unit, tone) {
  const span = el('span', `stk-q${tone ? ` is-${tone}` : ''}`, value);
  if (unit) span.append(el('small', '', ` ${String(unit).toUpperCase()}`));
  return span;
}
const stkDate = value => poSlashDate(value);
function stkPager(id, total, page, onPage) {
  const pages = Math.max(1, Math.ceil(total / STK_PAGE_SIZE));
  const pager = stkEl(id);
  const button = (label, target, disabled, current) => {
    const b = el('button', `ml-page${current ? ' ml-page-current' : ''}`, label);
    b.type = 'button'; b.disabled = disabled;
    if (current) b.setAttribute('aria-current', 'page');
    b.addEventListener('click', () => onPage(target));
    return b;
  };
  const numbers = auditPageNumbers(pages, page);
  pager.replaceChildren(button('‹ Previous', page - 1, page <= 1),
    ...numbers.flatMap((n, i) => [...(i && n - numbers[i - 1] > 1 ? [el('span', 'stk-gap', '…')] : []), button(String(n), n, false, n === page)]),
    button('Next ›', page + 1, page >= pages));
}
function stkShowing(id, total, page) {
  const start = total ? (page - 1) * STK_PAGE_SIZE + 1 : 0;
  stkEl(id).textContent = `Showing ${start} to ${Math.min(total, page * STK_PAGE_SIZE)} of ${total}`;
}
const stkPageOf = (rows, key) => {
  const pages = Math.max(1, Math.ceil(rows.length / STK_PAGE_SIZE));
  stk.page[key] = Math.min(Math.max(1, stk.page[key]), pages);
  return rows.slice((stk.page[key] - 1) * STK_PAGE_SIZE, stk.page[key] * STK_PAGE_SIZE);
};

function stkRender() {
  if (!stk.data) return;
  const period = stkEl('period');
  const label = period.value ? period.selectedOptions[0].text : 'all months';
  // The cards: on hand and value as at the end of the Period (and the chosen stock point); in / out within it
  // (transfers between stock points are neither).
  const levels = stkLevelRows().filter(row => stkAtPoint(row.warehouseId));
  let inQty = 0; let outQty = 0;
  for (const m of stk.data.movements) {
    if (!stkInPeriod(m.date) || !stkAtPoint(m.warehouseId) || m.type.startsWith('Transfer')) continue;
    if (m.dir === 'in') inQty += m.qty; else outQty += m.qty;
  }
  stkEl('kpi-hand').textContent = stkQty(levels.reduce((sum, row) => sum + Math.max(row.available, 0), 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  stkEl('kpi-in').textContent = stkSigned(inQty);
  stkEl('kpi-out').textContent = outQty ? stkSigned(-outQty) : '0';
  stkEl('kpi-value').replaceChildren(document.createTextNode(stkMoney(levels.reduce((sum, row) => sum + row.value, 0))), el('small', '', ' OMR'));
  stkEl('kpi-in-note').textContent = `From GRN, purchases & returns · ${label}`;
  stkEl('kpi-out-note').textContent = `From invoices, delivery notes & returns · ${label}`;
  stkEl('levels-sub').textContent = `Stock on hand from purchase inward and invoice / delivery note outward – ${label}.`;

  // Stock Levels & Valuation.
  const levelRows = stkFilteredLevels();
  stkEl('levels-body').replaceChildren(...stkPageOf(levelRows, 'levels').map(row => {
    const tr = el('tr');
    if (stk.flash && stk.flash === `${row.itemId}|${row.warehouseId ?? 0}`) tr.classList.add('stk-flash');
    const unit = row.item.unit;
    const statusText = `${stkQty(row.available)} ${String(unit || '').toUpperCase()}${row.status === 'low' ? ' (Low)' : row.status === 'out' ? ' (Out)' : ''}`.replace(/\s+/g, ' ');
    const actions = el('td', 'center');
    const act = (label, cls, handler) => { const b = el('button', `stk-act ${cls}`, label); b.type = 'button'; b.addEventListener('click', handler); return b; };
    actions.append(el('div', 'stk-acts'));
    actions.firstChild.append(act('History', 'is-history', () => stkOpenHistory(row.itemId)),
      act('Edit', 'is-edit', () => stkOpenItemEdit(row.itemId, row.warehouseId)),
      act('Delete', 'is-delete', () => stkDeleteItem(row.itemId)));
    tr.append(stkItemCell(row.itemId), el('td', 'stk-brand', row.item.brand || '—'), stkPointCell(row.warehouseId),
      el('td', 'num'), el('td', 'num'), el('td', 'center'), el('td', 'num stk-money'), el('td', 'num stk-money'), el('td', 'num stk-money stk-strong'), actions);
    tr.children[3].append(row.purchased ? stkUnitQty(stkSigned(row.purchased), unit, 'in') : el('span', 'stk-dash', '–'));
    tr.children[4].append(row.sold ? stkUnitQty(stkSigned(-row.sold), unit, 'out') : el('span', 'stk-dash', '–'));
    tr.children[5].append(el('span', `stk-pill is-${row.status}`, statusText));
    // Moved back from Damaged Stock: one line for sales returns, one for purchase returns.
    for (const [qty, from] of [[row.restockedSales, 'Sales Return'], [row.restockedPurchase, 'Purchase Return']]) {
      if (qty) tr.children[5].append(el('div', 'stk-restocked', `${stkSigned(qty)} ${String(unit || '').toUpperCase()} from ${from} (Damaged)`.replace(/\s+/g, ' ')));
    }
    tr.children[6].append(stkMoney(row.cost), el('small', '', ' OMR'));
    tr.children[7].append(stkMoney(row.price), el('small', '', ' OMR'));
    tr.children[8].append(stkMoney(row.value), el('small', '', ' OMR'));
    return tr;
  }));
  stkEl('levels-empty').hidden = levelRows.length > 0;
  stkShowing('levels-count', levelRows.length, stk.page.levels);
  stkPager('levels-pager', levelRows.length, stk.page.levels, page => { stk.page.levels = page; stkRender(); });

  // Stock Movement Ledger.
  const moves = stkFilteredLedger();
  stkEl('count-ledger').textContent = String(stk.data.movements.filter(m => stkInLedger(m) && stkInPeriod(m.date) && stkAtPoint(m.warehouseId)).length);
  stkEl('ledger-total').textContent = String(moves.length);
  stkEl('ledger-body').replaceChildren(...stkPageOf(moves, 'ledger').map(m => {
    const tr = el('tr'); const unit = stkItem(m.itemId).unit;
    const remarks = el('td', 'stk-remarks'); remarks.append(el('div', '', m.remarks || '—'));
    if (m.by) remarks.append(el('div', 'stk-by', `By: ${m.by}`));
    tr.append(el('td', 'stk-mono', stkDate(m.date)), el('td', 'stk-mono stk-strong', m.ref), el('td'), stkItemCell(m.itemId), el('td', 'stk-party', m.party || '—'),
      stkPointCell(m.warehouseId), el('td', 'num'), el('td', 'num'), el('td', 'num stk-money', stkMoney(m.rate)), el('td', 'num stk-money stk-strong', stkMoney(m.qty * m.rate)), remarks);
    tr.children[2].append(el('span', `stk-type is-${STK_TYPE_TONE[m.type] || 'grey'}`, m.type));
    tr.children[6].append(m.dir === 'in' ? stkUnitQty(stkSigned(m.qty), unit, 'in') : el('span', 'stk-dash', '–'));
    tr.children[7].append(m.dir === 'out' ? stkUnitQty(stkSigned(-m.qty), unit, 'out') : el('span', 'stk-dash', '–'));
    return tr;
  }));
  stkEl('ledger-empty').hidden = moves.length > 0;
  stkShowing('ledger-count', moves.length, stk.page.ledger);
  stkPager('ledger-pager', moves.length, stk.page.ledger, page => { stk.page.ledger = page; stkRender(); });

  // Damaged Stock.
  const damaged = stkFilteredDamaged();
  const inScope = stkDamagedInScope();
  stkEl('count-damaged').textContent = String(inScope.length);
  const side = stkEl('dmg-filter').value;
  stkEl('damaged-title').textContent = side ? `Damaged Stock – ${side === 'sales' ? 'Sales Return' : 'Purchase Return'}` : 'Damaged Stock';
  stkEl('damaged-sub').textContent = `Damaged goods from sales returns and purchase returns – ${label}.`;
  stkEl('dmg-entries').textContent = String(damaged.length);
  stkEl('dmg-items').textContent = String(new Set(damaged.map(d => String(d.itemId))).size);
  stkEl('dmg-qty').textContent = stkQty(damaged.reduce((sum, d) => sum + pbNum(d.qty), 0));
  stkEl('dmg-value').replaceChildren(document.createTextNode(stkMoney(damaged.reduce((sum, d) => sum + pbNum(d.qty) * pbNum(d.rate), 0))), el('small', '', ' OMR'));
  stkEl('damaged-body').replaceChildren(...stkPageOf(damaged, 'damaged').map(d => {
    const tr = el('tr'); const unit = stkItem(d.itemId).unit;
    const reason = el('td', 'stk-remarks'); reason.append(el('div', '', d.remarks || d.condition || '—'));
    if (d.by) reason.append(el('div', 'stk-by', `By: ${d.by}`));
    // Move to Stock: the sales side only (goods a customer sent back: Sales Return, Sales Replacement). Purchase
    // returns and replacements go back to the supplier, so they are not put back into stock here.
    const action = el('td', 'stk-act-col');
    if (stkCanRestock(d)) {
      const move = el('button', 'stk-move-btn', 'Move to Stock');
      move.type = 'button'; move.dataset.stkMove = d.key;
      move.prepend(stkMoveIcon());
      action.append(move);
    } else {
      action.append(el('span', 'stk-dash', '–'));
    }
    tr.append(el('td', 'stk-mono', stkDate(d.date)), el('td', 'stk-mono stk-strong', d.ref), el('td'), stkItemCell(d.itemId), el('td', 'stk-party', d.party || '—'),
      stkPointCell(d.warehouseId), el('td', 'num'), el('td', 'num stk-money', stkMoney(d.rate)), el('td', 'num stk-money stk-strong', stkMoney(pbNum(d.qty) * pbNum(d.rate))), reason, action);
    tr.children[2].append(el('span', `stk-type is-${STK_RETURN_TONE[d.source] || 'grey'}`, d.source));
    tr.children[6].append(stkUnitQty(stkQty(d.qty), unit, 'out'));
    // Part of the line already moved to stock: "1 METER / of 4".
    if (pbNum(d.origQty) > pbNum(d.qty)) tr.children[6].append(el('div', 'stk-of', `of ${stkQty(d.origQty)}`));
    return tr;
  }));
  stkEl('damaged-empty').hidden = damaged.length > 0;
  stkShowing('damaged-count', damaged.length, stk.page.damaged);
  stkPager('damaged-pager', damaged.length, stk.page.damaged, page => { stk.page.damaged = page; stkRender(); });
  if (byId('stkr-history').open) stkRenderHistory();
}

function stkShowTab(tab) {
  stk.tab = tab;
  for (const button of document.querySelectorAll('[data-stk-tab]')) button.setAttribute('aria-selected', String(button.dataset.stkTab === tab));
  for (const panel of document.querySelectorAll('[data-stk-panel]')) panel.hidden = panel.dataset.stkPanel !== tab;
  // "Export" on the button (the tab's tools stay on one line with the tabs); what it exports in its tooltip.
  const exportName = { levels: 'Export Valuation', ledger: 'Export Movements', damaged: 'Export Damaged Stock' }[tab];
  stkEl('export-label').textContent = 'Export';
  const exportButton = document.querySelector('#stkr-page [data-stk="export"]');
  exportButton.title = exportName;
  exportButton.setAttribute('aria-label', exportName);
  // Damaged Stock: Filter (All / Sales Return / Purchase Return) in the bar instead of Stock Point, and no Print PDF.
  stkEl('dmg-filter-wrap').hidden = tab !== 'damaged';
  // Stock Levels: Filter (All / All Sales / All Purchases) in the bar, Stock Point in the tab's own row.
  stkEl('levels-scope-wrap').hidden = tab !== 'levels';
  stkEl('point-wrap').hidden = tab !== 'ledger';
  stkEl('print').hidden = tab === 'damaged';
}

// History: one item's movements at every stock point, oldest first for the balance, shown newest first.
function stkOpenHistory(itemId) {
  stk.historyItem = itemId;
  stkEl('hist-search').value = '';
  stkEl('hist-dir').value = '';
  stkRenderHistory();
  const dialog = byId('stkr-history');
  if (!dialog.open) dialog.showModal();
  stkEl('hist-search').focus();
}
function stkRenderHistory() {
  const itemId = stk.historyItem;
  const item = stkItem(itemId); const unit = String(item.unit || '').toUpperCase();
  const all = stk.data.movements.filter(m => String(m.itemId) === String(itemId));
  let balance = 0;
  const withBalance = all.map(m => { balance += m.dir === 'in' ? m.qty : -m.qty; return { ...m, balance }; });
  const inQty = all.filter(m => m.dir === 'in').reduce((s, m) => s + m.qty, 0);
  const outQty = all.filter(m => m.dir === 'out').reduce((s, m) => s + m.qty, 0);
  const cost = stkRates()[itemId]?.cost || 0;
  stkEl('hist-title').textContent = item.name;
  stkEl('hist-meta').replaceChildren(el('span', '', 'SKU: '), el('b', 'stk-mono', item.code), el('span', '', `  ·  Brand: ${item.brand || '—'}  ·  Unit: ${unit || '—'}`));
  const withUnit = (node, value) => { node.replaceChildren(document.createTextNode(value), el('small', '', ` ${unit}`)); };
  withUnit(stkEl('hist-in'), stkSigned(inQty));
  withUnit(stkEl('hist-out'), outQty ? stkSigned(-outQty) : '0');
  withUnit(stkEl('hist-avail'), stkQty(inQty - outQty));
  stkEl('hist-value').replaceChildren(document.createTextNode(stkMoney(Math.max(inQty - outQty, 0) * cost)), el('small', '', ' OMR'));
  const q = stkEl('hist-search').value.trim().toLowerCase(); const dir = stkEl('hist-dir').value;
  const shown = withBalance.filter(m => (!dir || m.dir === dir)
    && (!q || stkText(m.type, m.party, m.ref, stkDate(m.date), m.date, m.remarks, stkPoint(m.warehouseId).name).includes(q))).reverse();
  stkEl('hist-body').replaceChildren(...shown.map(m => {
    const tr = el('tr');
    const remarks = el('td', 'stk-remarks'); remarks.append(el('div', '', m.remarks || '—'));
    if (m.by) remarks.append(el('div', 'stk-by', `By: ${m.by}`));
    // Ref No: the document's number (GRN, invoice, delivery note, transfer...); opening stock has none.
    const ref = m.doc === 'opening' ? '—' : (m.ref || '—');
    tr.append(el('td', 'stk-mono', stkDate(m.date)), el('td', 'stk-mono stk-ref', ref), el('td'), stkPointCell(m.warehouseId),
      el('td', 'num'), el('td', 'num'), el('td', 'num'), el('td', 'num stk-money', m.rate ? stkMoney(m.rate) : '–'),
      el('td', 'num stk-money stk-strong', m.rate ? stkMoney(m.qty * m.rate) : '–'), remarks);
    tr.children[2].append(el('span', `stk-type is-${STK_TYPE_TONE[m.type] || 'grey'}`, m.type));
    tr.children[4].append(m.dir === 'in' ? stkUnitQty(stkSigned(m.qty), '', 'in') : el('span', 'stk-dash', '–'));
    tr.children[5].append(m.dir === 'out' ? stkUnitQty(stkSigned(-m.qty), '', 'out') : el('span', 'stk-dash', '–'));
    tr.children[6].append(stkUnitQty(stkQty(m.balance), unit));
    return tr;
  }));
  stkEl('hist-empty').hidden = shown.length > 0;
}

/* ---------- Move to Stock (Damaged Stock) ----------
   A damaged line (or part of it) back into stock at its stock point: api/damage-restock.php takes it off the
   damaged line and the ledger adds a Damage Restock (in). The list holds every damaged line still in Damaged Stock. */
function stkMoveIcon() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  for (const [k, v] of Object.entries({ width: 12, height: 12, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': 2.4, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'aria-hidden': 'true' })) svg.setAttribute(k, v);
  const circle = document.createElementNS(ns, 'circle'); circle.setAttribute('cx', 12); circle.setAttribute('cy', 12); circle.setAttribute('r', 9);
  const path = document.createElementNS(ns, 'path'); path.setAttribute('d', 'M8 12h8M13 8.5 16.5 12 13 15.5');
  svg.append(circle, path);
  return svg;
}
// Damaged lines by key (a return's lines for one item together): { key: { first line, qty still damaged } }.
// Only the sales side's damaged goods can be moved back to stock (see damage_restock_save on the server).
const stkCanRestock = d => d.side === 'sales';
// Damaged lines that can be moved to stock, by key (a return's lines for one item together).
function stkDamagedByKey() {
  const byKey = new Map();
  for (const d of stk.data.damaged.filter(stkCanRestock)) {
    const entry = byKey.get(d.key);
    if (entry) entry.qty += pbNum(d.qty);
    else byKey.set(d.key, { line: d, qty: pbNum(d.qty) });
  }
  return byKey;
}
function stkOpenRestock(key) {
  const byKey = stkDamagedByKey();
  if (!byKey.has(key)) return;
  const select = stkEl('restock-key');
  select.replaceChildren(...[...byKey.entries()].map(([k, { line, qty }]) => {
    const item = stkItem(line.itemId);
    return new Option(`${line.ref} · ${mtsWords(item.name)} · ${stkQty(qty)} ${String(item.unit || '').toLowerCase()}`.trim(), k);
  }));
  select.value = key;
  stkFillRestock(true);
  const dialog = byId('stkr-restock');
  if (!dialog.open) dialog.showModal();
  stkEl('restock-qty').focus();
  stkEl('restock-qty').select();
}
// The chosen damaged line's details; fresh: the quantity is set to all of it and the description cleared.
// "HYDRAULIC HOSE 2\"" → "Hydraulic Hose 2\"" (the popup reads quieter in title case); codes stay as they are: a word of
// up to 3 letters and no vowel (MCB, WH, SKF) or with a digit in it (32A, 3-POLE); "NEW" is a word: "New".
const mtsWords = text => String(text || '').split(' ').map(word => ((word.length <= 3 && !/[aeiou]/i.test(word)) || /\d/.test(word)
  ? word.toUpperCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())).join(' ');
function stkFillRestock(fresh) {
  const entry = stkDamagedByKey().get(stkEl('restock-key').value);
  if (!entry) return;
  const { line, qty } = entry; const item = stkItem(line.itemId); const unit = mtsWords(item.unit || '');
  // "Damaged · PRT-0002 · NHNH"
  const from = stkEl('restock-from');
  from.replaceChildren(el('b', '', 'Damaged'), ` · ${line.ref}${line.party ? ` · ${line.party}` : ''}`);
  stkEl('restock-avail').textContent = `${stkQty(qty)} ${unit}`.trim();
  stkEl('restock-to').textContent = mtsWords(stkPoint(line.warehouseId).name);
  stkEl('restock-unit').textContent = `${unit ? `${unit} · ` : ''}max ${stkQty(qty)}`;
  stkEl('restock-qty').max = String(qty);
  if (fresh) { stkEl('restock-qty').value = stkQty(qty); stkEl('restock-desc').value = ''; }
  stkEl('restock-error').hidden = true;
  stkEl('restock-qty').classList.remove('is-invalid');
}
async function stkSaveRestock() {
  const key = stkEl('restock-key').value;
  const entry = stkDamagedByKey().get(key);
  const qty = pbNum(stkEl('restock-qty').value);
  const fail = message => { const box = stkEl('restock-error'); box.textContent = message; box.hidden = false; stkEl('restock-qty').classList.add('is-invalid'); stkEl('restock-qty').focus(); };
  if (!entry) return;
  if (!(qty > 0)) return fail('Enter a quantity more than 0.');
  if (qty > entry.qty + 0.0005) return fail(`Only ${stkQty(entry.qty)} ${String(stkItem(entry.line.itemId).unit || '').toUpperCase()} is in Damaged Stock.`.replace(' .', '.'));
  const button = stkEl('restock-save'); button.disabled = true;
  try {
    await apiRequest('api/damage-restock.php', { method: 'POST', json: { key, qty, description: stkEl('restock-desc').value.trim() } });
    byId('stkr-restock').close();
    const item = stkItem(entry.line.itemId);
    showToast('Moved to stock', `${stkQty(qty)} ${String(item.unit || '').toUpperCase()} ${item.name} from ${entry.line.ref} added to ${stkPoint(entry.line.warehouseId).name}.`);
    forgetLookups('item');
    await stkLoad();
    stkShowRestocked(entry.line.itemId, entry.line.warehouseId);
  } catch (error) {
    fail(error.fields?.qty || error.fields?.key || error.fields?.description || error.message);
  } finally {
    button.disabled = false;
  }
}

// Stock Levels & Valuation with the item's row at that stock point on screen and highlighted for a few seconds
// (filters that would hide it are cleared).
function stkShowRestocked(itemId, warehouseId) {
  const key = `${itemId}|${warehouseId ?? 0}`;
  const find = () => stkFilteredLevels().findIndex(row => `${row.itemId}|${row.warehouseId ?? 0}` === key);
  stkShowTab('levels');
  if (find() < 0) {
    for (const id of ['levels-search', 'levels-status', 'levels-scope', 'period']) stkEl(id).value = '';
    if (stkEl('point').value && stkEl('point').value !== String(warehouseId)) { stkEl('point').value = ''; stkEl('levels-point').value = ''; }
  }
  const index = find();
  stk.page.levels = index < 0 ? 1 : Math.floor(index / STK_PAGE_SIZE) + 1;
  stk.flash = key;
  stkRender();
  stkEl('levels-body').querySelector('.stk-flash')?.scrollIntoView({ block: 'center', behavior: 'smooth' });
  clearTimeout(stk.flashTimer);
  stk.flashTimer = setTimeout(() => { stk.flash = null; stkEl('levels-body').querySelector('.stk-flash')?.classList.remove('stk-flash'); }, 4000);
}

/* ---------- Edit Item (Stock Levels › Edit) ----------
   A popup on the Stock Ledger: the item's name, unit, brand, status, category, selling price, its stock point lines'
   buying cost and opening stock, and comments. Saved with PUT api/items.php (only these keys; the rest of the item
   stays as it is), then the Stock Ledger reloads and the row is highlighted. */
const stkIe = { item: null, itemId: null, warehouseId: null, subs: [] };
function stkIeOptions(select, rows, value, blank = '— None —') {
  select.replaceChildren(new Option(blank, ''), ...rows.map(r => new Option(r.name + (r.code ? ` (${r.code})` : ''), String(r.id))));
  select.value = value == null ? '' : String(value);
  if (value != null && select.value !== String(value)) { select.append(new Option(`#${value}`, String(value))); select.value = String(value); }
}
function stkIeFillSubs(value) {
  const category = stkEl('ie-category').value;
  stkIeOptions(stkEl('ie-subcategory'), stkIe.subs.filter(r => String(r.categoryId) === category), value);
  stkEl('ie-subcategory').disabled = !category;
}
async function stkOpenItemEdit(itemId, warehouseId) {
  Object.assign(stkIe, { item: null, itemId, warehouseId });
  const dialog = byId('stkr-itemedit');
  stkEl('ie-loading').hidden = false; stkEl('ie-loading').textContent = 'Loading item…';
  stkEl('ie-fields').hidden = true; stkEl('ie-save').disabled = true;
  stkEl('ie-meta').textContent = `SKU: ${stkItem(itemId).code}`;
  if (!dialog.open) dialog.showModal();
  try {
    const [item, uoms, brands, categories, subs] = await Promise.all([apiRequest(`api/items.php?id=${itemId}`), apiRequest('api/uoms.php'),
      apiRequest('api/brands.php'), apiRequest('api/categories.php'), apiRequest('api/sub-categories.php')]);
    if (stkIe.itemId !== itemId) return;                     // another item was opened meanwhile
    stkIe.item = item; stkIe.subs = subs;
    stkEl('ie-meta').textContent = `SKU: ${item.code}${item.warehouseName ? `  ·  ${item.warehouseName}` : ''}`;
    stkEl('ie-code').value = item.code;
    stkEl('ie-name').value = item.name || '';
    stkIeOptions(stkEl('ie-uom'), uoms, item.uomId);
    stkIeOptions(stkEl('ie-brand'), brands, item.brandId);
    stkEl('ie-status').value = item.status || 'ACTIVE / RELEASED';
    stkIeOptions(stkEl('ie-category'), categories, item.categoryId);
    stkIeFillSubs(item.subCategoryId);
    stkEl('ie-price').value = item.sellingPrice == null || item.sellingPrice === '' ? '' : pbQty(pbNum(item.sellingPrice));
    stkEl('ie-comments').value = item.description || '';
    stkEl('ie-lines').replaceChildren(...item.sourcing.map((line, index) => {
      const tr = el('tr');
      const point = el('td', 'stk-point'); point.append(el('div', '', line.warehouseName || '—'), ...(line.warehouseCode ? [el('div', 'stk-sku', line.warehouseCode)] : []));
      const input = (key, value) => {
        const td = el('td', 'num'); const box = el('input', 'fp-input stk-ie-num');
        Object.assign(box, { type: 'number', min: '0', step: 'any', inputMode: 'decimal', value: value == null || value === '' ? '' : pbQty(pbNum(value)) });
        box.dataset.line = String(index); box.dataset.key = key; box.setAttribute('aria-label', `${key === 'cost' ? 'Buying cost' : 'Opening stock'}, line ${index + 1}`);
        td.append(box); return td;
      };
      tr.append(point, el('td', '', line.brandName || '—'), el('td', '', line.supplierName || '—'), input('cost', line.cost), input('openingStock', line.openingStock));
      if (String(line.warehouseId ?? '') === String(stkIe.warehouseId ?? '')) tr.classList.add('stk-ie-here');
      return tr;
    }));
    stkEl('ie-nolines').hidden = item.sourcing.length > 0;
    stkIeClearErrors();
    stkEl('ie-loading').hidden = true; stkEl('ie-fields').hidden = false; stkEl('ie-save').disabled = false;
    stkEl('ie-name').focus();
  } catch (error) {
    stkEl('ie-loading').textContent = `The item could not be loaded: ${error.message}`;
  }
}
function stkIeClearErrors() {
  stkEl('ie-error').hidden = true;
  for (const node of byId('stkr-itemedit').querySelectorAll('.is-invalid')) node.classList.remove('is-invalid');
}
function stkIeFail(message, field) {
  const box = stkEl('ie-error'); box.textContent = message; box.hidden = false;
  const target = field ? byId('stkr-itemedit').querySelector(`[data-field="${field}"]`) : null;
  if (target) { target.classList.add('is-invalid'); target.focus(); }
}
async function stkSaveItemEdit() {
  const item = stkIe.item;
  if (!item) return;
  stkIeClearErrors();
  const name = stkEl('ie-name').value.trim();
  if (!name) return stkIeFail('Enter the item name.', 'itemName');
  const num = value => (String(value).trim() === '' ? null : String(value).trim());
  for (const box of byId('stkr-itemedit').querySelectorAll('.stk-ie-num')) {
    if (box.value.trim() !== '' && !(pbNum(box.value) >= 0)) { box.classList.add('is-invalid'); box.focus(); return stkIeFail('Enter a number of 0 or more.'); }
  }
  const lines = item.sourcing.map((line, index) => {
    const get = key => byId('stkr-itemedit').querySelector(`input[data-line="${index}"][data-key="${key}"]`).value;
    return { warehouseId: line.warehouseId, brandId: line.brandId, supplierId: line.supplierId, cost: num(get('cost')), openingStock: num(get('openingStock')) };
  });
  if (lines.length) lines[0].sellingPrice = num(stkEl('ie-price').value);
  const payload = { itemName: name, uomId: stkEl('ie-uom').value ? Number(stkEl('ie-uom').value) : null,
    brandId: stkEl('ie-brand').value ? Number(stkEl('ie-brand').value) : null, status: stkEl('ie-status').value,
    categoryId: stkEl('ie-category').value ? Number(stkEl('ie-category').value) : null,
    subCategoryId: stkEl('ie-subcategory').value ? Number(stkEl('ie-subcategory').value) : null,
    comments: stkEl('ie-comments').value, sourcing: lines };
  const button = stkEl('ie-save'); button.disabled = true;
  try {
    const saved = await apiRequest(`api/items.php?id=${item.id}`, { method: 'PUT', json: payload });
    byId('stkr-itemedit').close();
    showToast('Item updated', `${saved.name || name} (${saved.code || item.code}) saved.`);
    forgetLookups('item');
    await stkLoad();
    stkShowRestocked(item.id, stkIe.warehouseId);           // back on the row, highlighted
  } catch (error) {
    const [field, message] = Object.entries(error.fields || {})[0] || [];
    stkIeFail(message || error.message, field);
  } finally {
    button.disabled = false;
  }
}

// Refresh: the page as when first opened (every filter, search, date and page back to the start, popups closed,
// Stock Levels & Valuation) with the stock worked out again from the documents.
async function stkRefresh() {
  const button = document.querySelector('#stkr-page [data-stk="refresh"]');
  if (button.disabled) return;
  for (const id of ['stkr-history', 'stkr-restock', 'stkr-itemedit']) if (byId(id).open) byId(id).close();
  for (const id of ['levels-search', 'levels-scope', 'levels-point', 'levels-status', 'point', 'period', 'ledger-search', 'ledger-type',
    'ledger-from', 'ledger-to', 'dmg-filter', 'damaged-search', 'damaged-point']) {
    const field = stkEl(id); if (field) field.value = '';
  }
  stk.page = { levels: 1, ledger: 1, damaged: 1 };
  stk.flash = null;
  stkShowTab('levels');
  button.disabled = true; button.classList.add('is-busy');
  try {
    forgetLookups('item', 'warehouse');
    await stkLoad();
    window.scrollTo({ top: 0, behavior: 'smooth' });
    if (stk.data) showToast('Refreshed', 'Stock Ledger reloaded with the latest stock.');
  } finally {
    button.disabled = false; button.classList.remove('is-busy');
  }
}

async function stkDeleteItem(itemId) {
  const item = stkItem(itemId);
  if (!confirm(`Delete ${item.name} (${item.code}) from the Item master?\n\nAn item used on any document cannot be deleted.`)) return;
  try {
    await apiRequest(`api/items.php?id=${itemId}`, { method: 'DELETE' });
    forgetLookups('item');
    showToast('Item deleted', `${item.name} was deleted from the Item master.`);
    await stkLoad();
  } catch (error) {
    showToast('The item could not be deleted', error.message, true);
  }
}

// Export (CSV, the tab's rows with its filters, every page) and Print PDF (the same rows on a printable page).
/* ---------- Excel export (.xlsx), no library (the CSP allows 'self' only) ----------
   downloadXlsx(fileName, sheetName, head, rows): a real workbook that Excel, LibreOffice and Google Sheets open as is —
   columns as wide as their contents, a bold header row frozen at the top with filter arrows, dates (DD/MM/YYYY) as
   dates, numbers as numbers (money with 3 decimals). A CSV cannot hold column widths, so Excel showed ##### and cut
   the text. The file is a zip of XML parts, written uncompressed ("stored"). */
const XLSX_CRC = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1; table[n] = c >>> 0; }
  return bytes => { let c = 0xFFFFFFFF; for (const b of bytes) c = table[(c ^ b) & 0xFF] ^ (c >>> 8); return (c ^ 0xFFFFFFFF) >>> 0; };
})();
function xlsxZip(files) {
  const enc = new TextEncoder();
  const parts = []; const central = []; let offset = 0;
  const u16 = n => [n & 0xFF, (n >>> 8) & 0xFF];
  const u32 = n => [n & 0xFF, (n >>> 8) & 0xFF, (n >>> 16) & 0xFF, (n >>> 24) & 0xFF];
  for (const [name, text] of files) {
    const data = enc.encode(text); const path = enc.encode(name); const crc = XLSX_CRC(data);
    const local = new Uint8Array([0x50, 0x4B, 0x03, 0x04, ...u16(20), ...u16(0x0800), ...u16(0), ...u16(0), ...u16(0x21),
      ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(path.length), ...u16(0)]);
    parts.push(local, path, data);
    central.push(new Uint8Array([0x50, 0x4B, 0x01, 0x02, ...u16(20), ...u16(20), ...u16(0x0800), ...u16(0), ...u16(0), ...u16(0x21),
      ...u32(crc), ...u32(data.length), ...u32(data.length), ...u16(path.length), ...u16(0), ...u16(0), ...u16(0), ...u16(0), ...u32(0), ...u32(offset)]), path);
    offset += local.length + path.length + data.length;
  }
  const size = central.reduce((n, p) => n + p.length, 0);
  const end = new Uint8Array([0x50, 0x4B, 0x05, 0x06, ...u16(0), ...u16(0), ...u16(files.length), ...u16(files.length), ...u32(size), ...u32(offset), ...u16(0)]);
  return new Blob([...parts, ...central, end], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
}
const xlsxEsc = text => String(text ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]))
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
const xlsxCol = i => { let s = ''; for (let n = i + 1; n > 0; n = Math.floor((n - 1) / 26)) s = String.fromCharCode(65 + ((n - 1) % 26)) + s; return s; };
// A cell as Excel should hold it: a DD/MM/YYYY date → a date; "12,200.000" / "−3" → a number; anything else text.
function xlsxValue(value) {
  const text = String(value ?? '').trim();
  const d = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(text) || /^(\d{4})-(\d{2})-(\d{2})$/.exec(text);
  if (d) {
    const [y, m, day] = text.includes('/') ? [d[3], d[2], d[1]] : [d[1], d[2], d[3]];
    const serial = (Date.UTC(+y, +m - 1, +day) - Date.UTC(1899, 11, 30)) / 86400000;
    if (Number.isFinite(serial)) return { kind: 'date', n: serial };
  }
  const plain = text.replace(/,/g, '').replace(/^−/, '-');
  if (/^-?\d+(\.\d+)?$/.test(plain) && !/^0\d/.test(plain.replace(/^-/, ''))) return { kind: 'num', n: Number(plain), decimals: (plain.split('.')[1] || '').length };
  return { kind: 'text', s: text };
}
function downloadXlsx(fileName, sheetName, head, rows, { plain = false } = {}) {
  // Codes, phone numbers, references, IDs stay text (91234567 is a phone number, not 91,234,567).
  const textCol = head.map(h => /code|phone|mobile|contact|tel|fax|zip|postal|\bno\b|no\.|number|\bref\b|reference|\bid\b|vat reg|cr no|account|iban|po\b|sku/i.test(String(h)));
  const values = rows.map(row => row.map((v, c) => (plain || textCol[c] ? { kind: 'text', s: String(v ?? '').trim() } : xlsxValue(v))));
  // A column is money when it holds amounts with 3 decimals (Rate, Value, Cost, Price …), else a plain number.
  const qtyCol = h => /qty|quantity/i.test(h);          // "Total Qty" is a quantity; "Stock Value" is money
  const money = head.map((h, c) => !qtyCol(h) && (/rate|value|cost|price|amount|total|refund|balance|limit/i.test(h)
    || values.some(r => r[c]?.kind === 'num' && r[c].decimals === 3)));
  const width = head.map((h, c) => {
    const longest = Math.max(String(h).length, ...rows.map((r, i) => {
      const v = values[i][c];
      return v?.kind === 'date' ? 10 : v?.kind === 'num' ? (money[c] ? v.n.toFixed(3).length + 3 : String(v.n).length + 2) : String(r[c] ?? '').length;
    }));
    return Math.min(60, Math.max(8, longest + 2));
  });
  const cell = (v, ref) => {
    if (v.kind === 'date') return `<c r="${ref}" s="2"><v>${v.n}</v></c>`;
    if (v.kind === 'num') return `<c r="${ref}" s="${money[xlsxColIndex(ref)] ? 3 : 4}"><v>${v.n}</v></c>`;   // money / number
    return v.s ? `<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${xlsxEsc(v.s)}</t></is></c>` : '';
  };
  const xlsxColIndex = ref => { let n = 0; for (const ch of ref.replace(/\d+/g, '')) n = n * 26 + ch.charCodeAt(0) - 64; return n - 1; };
  const last = `${xlsxCol(head.length - 1)}${rows.length + 1}`;
  const sheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>
<sheetFormatPr defaultRowHeight="18"/>
<cols>${width.map((w, c) => `<col min="${c + 1}" max="${c + 1}" width="${w}" customWidth="1"/>`).join('')}</cols>
<sheetData><row r="1" ht="22" customHeight="1">${head.map((h, c) => `<c r="${xlsxCol(c)}1" t="inlineStr" s="1"><is><t>${xlsxEsc(h)}</t></is></c>`).join('')}</row>
${values.map((row, r) => `<row r="${r + 2}">${row.map((v, c) => cell(v, `${xlsxCol(c)}${r + 2}`)).join('')}</row>`).join('\n')}</sheetData>
<autoFilter ref="A1:${last}"/>
</worksheet>`;
  const styles = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<numFmts count="3"><numFmt numFmtId="164" formatCode="dd/mm/yyyy"/><numFmt numFmtId="165" formatCode="#,##0.000"/><numFmt numFmtId="166" formatCode="#,##0.###"/></numFmts>
<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FF7C2D12"/><name val="Calibri"/></font></fonts>
<fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFFFEDD5"/><bgColor indexed="64"/></patternFill></fill></fills>
<borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left/><right/><top/><bottom style="thin"><color rgb="FFFDBA74"/></bottom><diagonal/></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="5"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"><alignment vertical="center"/></xf>
<xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"><alignment horizontal="left"/></xf>
<xf numFmtId="165" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/>
<xf numFmtId="166" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;
  const name = xlsxEsc(String(sheetName).replace(/[\\/?*[\]:]/g, ' ').slice(0, 31) || 'Sheet1');
  const blob = xlsxZip([
    ['[Content_Types].xml', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>'],
    ['_rels/.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],
    ['xl/workbook.xml', `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="${name}" sheetId="1" r:id="rId1"/></sheets><definedNames><definedName name="_xlnm._FilterDatabase" localSheetId="0" hidden="1">'${name.replace(/'/g, "''")}'!$A$1:$${xlsxCol(head.length - 1)}$${rows.length + 1}</definedName></definedNames></workbook>`],
    ['xl/_rels/workbook.xml.rels', '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>'],
    ['xl/worksheets/sheet1.xml', sheet],
    ['xl/styles.xml', styles],
  ]);
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = fileName;
  document.body.append(link); link.click(); link.remove();
  setTimeout(() => URL.revokeObjectURL(link.href), 1000);
}

function stkTabTable() {
  if (stk.tab === 'levels') {
    return { title: 'Stock Valuation Overview', head: ['Item Code', 'Item Name', 'Brand', 'Stock Point', 'Purchased', 'Sold', 'Stock Available', 'Unit', 'Status', 'Avg Buying Cost', 'Selling Price', 'Stock Value'],
      rows: stkFilteredLevels().map(r => [r.item.code, r.item.name, r.item.brand, [r.point.code, r.point.name].filter(Boolean).join(' · '), stkQty(r.purchased), stkQty(r.sold),
        stkQty(r.available), r.item.unit, { in: 'In Stock', low: 'Low Stock', out: 'Out of Stock' }[r.status], pbMoney(r.cost), pbMoney(r.price), pbMoney(r.value)]) };
  }
  if (stk.tab === 'ledger') {
    return { title: 'Stock Movement Ledger', head: ['Date', 'Reference', 'Movement Type', 'Item Code', 'Item Name', 'Name', 'Stock Point', 'Inward', 'Outward', 'Unit', 'Rate', 'Value', 'Remarks', 'By'],
      rows: stkFilteredLedger().map(m => [stkDate(m.date), m.ref, m.type, stkItem(m.itemId).code, stkItem(m.itemId).name, m.party, stkPoint(m.warehouseId).name,
        m.dir === 'in' ? stkQty(m.qty) : '', m.dir === 'out' ? stkQty(m.qty) : '', stkItem(m.itemId).unit, pbMoney(m.rate), pbMoney(m.qty * m.rate), m.remarks, m.by]) };
  }
  const side = stkEl('dmg-filter').value;
  return { title: side ? `Damaged Stock - ${side === 'sales' ? 'Sales Return' : 'Purchase Return'}` : 'Damaged Stock',
    head: ['Date', 'Return No', 'Return Type', 'Item Code', 'Item Name', 'Name', 'Stock Point', 'Damaged Qty', 'Returned Qty', 'Unit', 'Rate', 'Value', 'Condition', 'Reason', 'By'],
    rows: stkFilteredDamaged().map(d => [stkDate(d.date), d.ref, d.source, stkItem(d.itemId).code, stkItem(d.itemId).name, d.party, stkPoint(d.warehouseId).name,
      stkQty(d.qty), stkQty(d.origQty), stkItem(d.itemId).unit, pbMoney(pbNum(d.rate)), pbMoney(pbNum(d.qty) * pbNum(d.rate)), d.condition, d.remarks, d.by]) };
}
// Export: the tab's rows (its filters, every page) as an Excel workbook (.xlsx): readable columns, dates and numbers.
function stkExport() {
  const { title, head, rows } = stkTabTable();
  downloadXlsx(`${title.replace(/[^A-Za-z]+/g, '-')}-${todayInputValue()}.xlsx`, title, head, rows);
  showToast('Export ready', `${rows.length} row${rows.length === 1 ? '' : 's'} saved as an Excel file.`);
}
function stkPrint() {
  const { title, head, rows } = stkTabTable();
  const period = stkEl('period').value ? stkEl('period').selectedOptions[0].text : 'All months';
  const esc = value => String(value ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
  const company = byId('app')?.querySelector('.brand-name')?.textContent || '';
  const win = window.open('', '_blank');
  if (!win) { showToast('Print blocked', 'Allow pop-ups for this site to print the report.', true); return; }
  win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>
    @page { size: A4 landscape; margin: 12mm; } body { font: 10px/1.4 Arial, sans-serif; color: #0f172a; }
    h1 { margin: 0 0 2px; font-size: 16px; } p { margin: 0 0 10px; color: #475569; }
    table { width: 100%; border-collapse: collapse; } th, td { padding: 4px 6px; border: 1px solid #cbd5e1; text-align: left; vertical-align: top; }
    th { background: #fff7ed; font-size: 9px; text-transform: uppercase; } tr { break-inside: avoid; }</style></head><body>
    <h1>${esc(company)} · Stock Ledger · ${esc(title)}</h1><p>${esc(period)} · ${rows.length} row${rows.length === 1 ? '' : 's'} · printed ${esc(new Date().toLocaleString('en-GB'))}</p>
    <table><thead><tr>${head.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead>
    <tbody>${rows.map(row => `<tr>${row.map(v => `<td>${esc(v)}</td>`).join('')}</tr>`).join('') || `<tr><td colspan="${head.length}">Nothing to show.</td></tr>`}</tbody></table>
    <script>window.onload = () => { window.print(); };<\/script></body></html>`);
  win.document.close();
}

function stkInit() {
  const page = byId('stkr-page');
  if (!page) return;
  FORM_PAGES['supply/stock-report'] = { page: 'stkr', alwaysReset: true, isEditing: () => false,
    reset: () => { stkShowTab(stk.tab); stkLoad(); }, firstField: () => stkEl(`${stk.tab === 'levels' ? 'levels' : stk.tab}-search`) };
  FORM_KEY_HANDLERS.stkr = event => {
    if (event.key === 'Escape') {
      event.preventDefault();
      if (byId('stkr-itemedit').open) byId('stkr-itemedit').close();
      else if (byId('stkr-restock').open) byId('stkr-restock').close();
      else if (byId('stkr-history').open) byId('stkr-history').close();
      else if (!event.repeat) location.hash = '#/home';
      return true;
    }
    if (event.key === '/' && !isTextEntry(event.target)) {
      event.preventDefault();
      stkEl(`${stk.tab}-search`).focus();
      return true;
    }
    return false;
  };
  page.addEventListener('click', event => {
    const action = event.target.closest('[data-stk]')?.dataset.stk;
    if (action === 'refresh') stkRefresh();
    else if (action === 'sync') stkLoad({ sync: true });
    else if (action === 'back') location.hash = '#/home';
    else if (action === 'export') stkExport();
    else if (action === 'print') stkPrint();
    const tab = event.target.closest('[data-stk-tab]')?.dataset.stkTab;
    if (tab) stkShowTab(tab);
    if (event.target.closest('[data-stk-hist="close"]')) byId('stkr-history').close();
    const move = event.target.closest('[data-stk-move]')?.dataset.stkMove;
    if (move) stkOpenRestock(move);
  });
  const itemEdit = byId('stkr-itemedit');
  itemEdit.addEventListener('click', event => {
    if (event.target === itemEdit || event.target.closest('[data-stk-ie="close"]')) itemEdit.close();
  });
  stkEl('ie-category').addEventListener('change', () => stkIeFillSubs(null));
  stkEl('ie-form').addEventListener('input', event => { event.target.classList?.remove('is-invalid'); stkEl('ie-error').hidden = true; });
  stkEl('ie-form').addEventListener('submit', event => { event.preventDefault(); stkSaveItemEdit(); });
  const restock = byId('stkr-restock');
  restock.addEventListener('click', event => {
    if (event.target === restock || event.target.closest('[data-stk-restock="close"]')) restock.close();
  });
  stkEl('restock-key').addEventListener('change', () => { stkFillRestock(true); stkEl('restock-qty').focus(); });
  byId('stkr-restock').addEventListener('click', event => {
    const step = event.target.closest('[data-mts-step]');
    if (!step) return;
    const box = stkEl('restock-qty');
    const max = pbNum(box.max);
    const next = Math.min(max, Math.max(0, Math.round((pbNum(box.value) + Number(step.dataset.mtsStep)) * 1000) / 1000));
    box.value = stkQty(next);
    box.dispatchEvent(new Event('input', { bubbles: true }));
    box.focus();
  });
  stkEl('restock-qty').addEventListener('input', () => { stkEl('restock-error').hidden = true; stkEl('restock-qty').classList.remove('is-invalid'); });
  stkEl('restock-form').addEventListener('submit', event => { event.preventDefault(); stkSaveRestock(); });
  // Any filter: back to page 1 of its tab, and the cards follow the Period and the stock point.
  const again = key => () => { if (key) stk.page[key] = 1; else stk.page = { levels: 1, ledger: 1, damaged: 1 }; stkRender(); };
  stkEl('period').addEventListener('change', again(null));
  // The bar's Stock Point (Movement Ledger) and the Stock Levels one are the same choice.
  for (const [from, to] of [['point', 'levels-point'], ['levels-point', 'point']]) {
    stkEl(from).addEventListener('change', () => { stkEl(to).value = stkEl(from).value; again(null)(); });
  }
  for (const id of ['levels-search', 'levels-scope', 'levels-status']) stkEl(id).addEventListener(id.endsWith('search') ? 'input' : 'change', again('levels'));
  for (const id of ['ledger-search', 'ledger-type', 'ledger-from', 'ledger-to']) stkEl(id).addEventListener(id.endsWith('search') ? 'input' : 'change', again('ledger'));
  stkEl('dmg-filter').addEventListener('change', again('damaged'));
  for (const id of ['damaged-search', 'damaged-point']) stkEl(id).addEventListener(id.endsWith('search') ? 'input' : 'change', again('damaged'));
  stkEl('hist-search').addEventListener('input', stkRenderHistory);
  stkEl('hist-dir').addEventListener('change', stkRenderHistory);
  byId('stkr-history').addEventListener('click', event => { if (event.target === byId('stkr-history')) byId('stkr-history').close(); });
}

/* ---------- Purchase Entry (Transaction Entry, PUR-0001) ----------
   A supplier's bill recorded in the books: Supplier (+ New makes one in the Supplier master), the supplier's own
   invoice number, the purchase order and / or GRN it is for (a pick fills the supplier, currency and lines), the
   currency, lines priced quantity × rate (Total) with Line Total less the line's share of the discount, Remarks,
   signatory slots and the seal. No VAT or shipping (pe_save() keeps them at 0). */
const peCurrency = () => byId('pe-currency-id').value || 'OMR';
function peSetCurrency(code) {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId('pe-currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}

const peForm = createPurchaseForm({
  key: 'pe', route: 'entry/purchase-entry/new', noun: 'Purchase Entry', api: 'api/purchase-entries.php',
  kind: 'po', template: 'pb-line-pe', lookups: ['purchaseorder', 'grn'], vatDefault: 'exclude',
  firstField: () => byId('pe-date'),
  onShow: () => openLookup(byId('pe-supplier')),          // a new purchase entry starts by picking the supplier
  fieldNodes: { purchaseDate: 'pe-date', supplierId: 'pe-supplier', supplierInvoiceNo: 'pe-invoice-no', purchaseOrderId: 'pe-po',
    grnId: 'pe-grn', currency: 'pe-currency', discountAmount: 'pe-discount', remarks: 'pe-remarks-editor' },
  header: () => ({
    purchaseDate: byId('pe-date').value, supplierId: byId('pe-supplier-id').value || null,
    supplierInvoiceNo: byId('pe-invoice-no').value.trim(), purchaseOrderId: byId('pe-po-id').value || null,
    grnId: byId('pe-grn-id').value || null, currency: peCurrency(),
  }),
  check(form, errors) {
    if (!byId('pe-date').value) errors.push({ node: byId('pe-date'), message: 'Enter the purchase date.' });
    if (!byId('pe-supplier-id').value) errors.push({ node: byId('pe-supplier'), message: 'Select the supplier.' });
  },
  // Total = quantity × rate; Line Total = Total less the line's share of the Discount Amount. Total Items counts the filled lines.
  afterRefresh(totals) {
    const rows = peForm.page.rowsOf('items');
    const shared = totals.discount;
    rows.forEach((row, i) => {
      const gross = totals.lineTotals[i];
      row.querySelector('[data-gross]').textContent = pbShow(gross);
      row.querySelector('[data-total]').textContent = pbShow(gross - (totals.subtotal > 0 ? shared * gross / totals.subtotal : 0));
    });
    byId('pe-item-count').textContent = String(rows.filter(row => pbCell(row, 'itemId').value || pbCell(row, 'itemName').value.trim()).length || rows.length);
    for (const label of byId('pe-form').querySelectorAll('[data-pe-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
    byId('pe-save-label').textContent = FORM_PAGES['entry/purchase-entry/new']?.isEditing?.() ? 'Update Purchase' : 'Save Purchase';
  },
  listRoute: 'entry/purchase-entry',
  fill(form, pe) {
    byId('pe-date').value = pe.purchaseDate;
    fillLookup(byId('pe-supplier'), pe.supplierId ? { id: pe.supplierId, name: pe.supplierName } : null);
    byId('pe-invoice-no').value = pe.supplierInvoiceNo || '';
    fillLookup(byId('pe-po'), pe.purchaseOrderId ? { id: pe.purchaseOrderId, code: pe.purchaseOrderCode } : null);
    fillLookup(byId('pe-grn'), pe.grnId ? { id: pe.grnId, code: pe.grnCode } : null);
    peSetCurrency(pe.currency);
  },
  onReset() {
    byId('pe-date').value = todayInputValue();
    peSetCurrency('OMR');                          // hidden ids were cleared by the reset
    forgetLookups('purchaseorder', 'grn');
  },
  init(form) {
    // + New: Quick Add Supplier; the new supplier is filled into Supplier Name.
    byId('pe-supplier-new').addEventListener('click', () => openQuickSupplier(byId('pe-supplier')));
    // A supplier picked: its currency becomes the purchase's.
    byId('pe-supplier').addEventListener('input', async () => {
      const id = byId('pe-supplier-id').value;
      if (!id) return;
      const supplier = await pbSupplier(id).catch(() => null);
      if (supplier?.currency && byId('pe-supplier-id').value === id) peSetCurrency(supplier.currency);
      form.page.absorb();
      form.refresh();
    });
    byId('pe-form').addEventListener('input', event => {
      if (event.target.id === 'pe-currency' || event.target.id === 'pe-discount') form.refresh();
    });
    // As the old Purchase Entry: a purchase order sets the supplier and currency, then takes its latest GRN (the
    // lines from that GRN's accepted quantities); with no GRN yet, the purchase order's own lines. A GRN picked sets
    // its lines, its purchase order when none is picked and the supplier only when none is picked.
    const fetched = (count, from) => showToast('Items fetched', `${count} item${count === 1 ? '' : 's'} from ${from}.`);
    const takeSupplier = async doc => {
      if (!doc.supplierId) return;
      fillLookup(byId('pe-supplier'), { id: doc.supplierId, name: doc.supplierName });
      const code = doc.currency || (await pbSupplier(String(doc.supplierId)).catch(() => null))?.currency;
      if (code) peSetCurrency(code);
    };
    const takeGrn = async id => {
      const grn = await apiRequest(`api/grns.php?id=${id}`);
      fillLookup(byId('pe-grn'), { id: grn.id, code: grn.code });
      if (!byId('pe-supplier-id').value) await takeSupplier(grn);
      if (grn.purchaseOrderId && !byId('pe-po-id').value) {
        const po = (await loadLookup('purchaseorder')).find(row => String(row.id) === String(grn.purchaseOrderId));
        fillLookup(byId('pe-po'), { id: grn.purchaseOrderId, code: po?.code || grn.poNumber });
      }
      // The accepted quantity is what is billed, at the GRN's unit cost.
      const lines = grn.items.filter(line => pbNum(line.acceptedQty) > 0);
      await loadPurchaseLines(form, lines, line => ({
        ...purchaseLineRow(line), quantity: pbQty(pbNum(line.acceptedQty)), price: pbMoney(pbNum(line.unitCost)),
        vatRate: '0.00', discountPct: '0.00', discountAmount: '0.000', foc: 'No',
      }));
      form.refresh();
      fetched(lines.length, grn.code);
    };
    byId('pe-po').addEventListener('input', async () => {
      const id = byId('pe-po-id').value;
      if (!id) return;
      try {
        const po = await apiRequest(`api/purchase-orders.php?id=${id}`);
        await takeSupplier(po);
        forgetLookups('grn');
        const grns = (await loadLookup('grn')).filter(grn => String(grn.purchaseOrderId) === String(po.id));   // newest first
        if (grns.length) {
          await takeGrn(grns[0].id);
          if (grns.length > 1) showToast('GRN selected', `${grns[0].code} is the latest of ${grns.length} GRNs for ${po.code}; pick another in GRN to bill that one.`);
          return;
        }
        fillLookup(byId('pe-grn'), null);
        await loadPurchaseLines(form, po.items, line => ({
          ...purchaseLineRow(line), quantity: pbQty(pbNum(line.quantity)), price: pbMoney(line.foc ? 0 : pbNum(line.price)),
          vatRate: '0.00', discountPct: '0.00', discountAmount: '0.000', foc: 'No',
        }));
        form.refresh();
        fetched(po.items.length, po.code);
      } catch (error) { showToast('The purchase order could not be loaded', error.message, true); }
    });
    byId('pe-grn').addEventListener('input', async () => {
      const id = byId('pe-grn-id').value;
      if (!id) return;
      try { await takeGrn(id); } catch (error) { showToast('The GRN could not be loaded', error.message, true); }
    });
  },
});

/* ---------- Sales Entry (Transaction Entry, SAL-0001) ----------
   The Purchase Entry for a customer: Customer (+ New makes one in the Customer master), the customer's PO / reference
   number, the tax invoice and / or delivery note it is for (a pick fills the customer, currency and lines), the
   currency, lines priced quantity × rate (Total) with Line Total less the line's share of the discount, Remarks,
   signatory slots and the seal. No VAT or shipping (sales_entry_save() keeps them at 0). */
const seCurrency = () => byId('se-currency-id').value || 'OMR';
function seSetCurrency(code) {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId('se-currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}

const seForm = createPurchaseForm({
  key: 'se', route: 'entry/sales-entry/new', noun: 'Sales Entry', api: 'api/sales-entries.php',
  kind: 'po', template: 'pb-line-se', lookups: ['taxinvoice', 'deliverynote'], vatDefault: 'exclude',
  firstField: () => byId('se-date'),
  onShow: () => openLookup(byId('se-customer')),          // a new sales entry starts by picking the customer
  fieldNodes: { salesDate: 'se-date', customerId: 'se-customer', customerRefNo: 'se-ref-no', taxInvoiceId: 'se-ti',
    deliveryNoteId: 'se-dn', currency: 'se-currency', discountAmount: 'se-discount', remarks: 'se-remarks-editor' },
  header: () => ({
    salesDate: byId('se-date').value, customerId: byId('se-customer-id').value || null,
    customerRefNo: byId('se-ref-no').value.trim(), taxInvoiceId: byId('se-ti-id').value || null,
    deliveryNoteId: byId('se-dn-id').value || null, currency: seCurrency(),
  }),
  check(form, errors) {
    if (!byId('se-date').value) errors.push({ node: byId('se-date'), message: 'Enter the sales date.' });
    if (!byId('se-customer-id').value) errors.push({ node: byId('se-customer'), message: 'Select the customer.' });
  },
  // Total = quantity × rate; Line Total = Total less the line's share of the Discount Amount. Total Items counts the filled lines.
  afterRefresh(totals) {
    const rows = seForm.page.rowsOf('items');
    const shared = totals.discount;
    rows.forEach((row, i) => {
      const gross = totals.lineTotals[i];
      row.querySelector('[data-gross]').textContent = pbShow(gross);
      row.querySelector('[data-total]').textContent = pbShow(gross - (totals.subtotal > 0 ? shared * gross / totals.subtotal : 0));
    });
    byId('se-item-count').textContent = String(rows.filter(row => pbCell(row, 'itemId').value || pbCell(row, 'itemName').value.trim()).length || rows.length);
    for (const label of byId('se-form').querySelectorAll('[data-se-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
    byId('se-save-label').textContent = FORM_PAGES['entry/sales-entry/new']?.isEditing?.() ? 'Update Sale' : 'Save Sale';
  },
  listRoute: 'entry/sales-entry',
  fill(form, se) {
    byId('se-date').value = se.salesDate;
    fillLookup(byId('se-customer'), se.customerId ? { id: se.customerId, name: se.customerName } : null);
    byId('se-ref-no').value = se.customerRefNo || '';
    fillLookup(byId('se-ti'), se.taxInvoiceId ? { id: se.taxInvoiceId, code: se.taxInvoiceCode } : null);
    fillLookup(byId('se-dn'), se.deliveryNoteId ? { id: se.deliveryNoteId, code: se.deliveryNoteCode } : null);
    seSetCurrency(se.currency);
  },
  onReset() {
    byId('se-date').value = todayInputValue();
    seSetCurrency('OMR');                          // hidden ids were cleared by the reset
    forgetLookups('taxinvoice', 'deliverynote');
  },
  init(form) {
    // + New: Quick Add Customer; the new customer is filled into Customer Name.
    byId('se-customer-new').addEventListener('click', () => openQuickSupplier(byId('se-customer'), '', 'customer'));
    // A customer picked: its currency becomes the sale's.
    byId('se-customer').addEventListener('input', async () => {
      const id = byId('se-customer-id').value;
      if (!id) return;
      const customer = await pbCustomer(id).catch(() => null);
      if (customer?.currency && byId('se-customer-id').value === id) seSetCurrency(customer.currency);
      form.page.absorb();
      form.refresh();
    });
    byId('se-form').addEventListener('input', event => {
      if (event.target.id === 'se-currency' || event.target.id === 'se-discount') form.refresh();
    });
    // The Purchase Entry's fetching with the tax invoice in place of the purchase order and the delivery note in
    // place of the GRN: a tax invoice sets the customer and currency, its delivery note and its lines (what was
    // billed); a delivery note picked sets its lines, a tax invoice made from it when none is picked and the customer
    // only when none is picked.
    const fetched = (count, from) => showToast('Items fetched', `${count} item${count === 1 ? '' : 's'} from ${from}.`);
    const takeCustomer = async doc => {
      if (!doc.customerId) return;
      fillLookup(byId('se-customer'), { id: doc.customerId, name: doc.customerName });
      const code = doc.currency || (await pbCustomer(String(doc.customerId)).catch(() => null))?.currency;
      if (code) seSetCurrency(code);
    };
    const takeRef = doc => { if (doc.customerPo && !byId('se-ref-no').value.trim()) byId('se-ref-no').value = doc.customerPo; };
    const takeLines = async doc => {
      await loadPurchaseLines(form, doc.items, line => ({
        ...purchaseLineRow(line), quantity: pbQty(pbNum(line.quantity)), price: pbMoney(line.foc ? 0 : pbNum(line.price)),
        vatRate: '0.00', discountPct: '0.00', discountAmount: '0.000', foc: 'No',
      }));
      form.refresh();
      fetched(doc.items.length, doc.code);
    };
    byId('se-ti').addEventListener('input', async () => {
      const id = byId('se-ti-id').value;
      if (!id) return;
      try {
        const ti = await apiRequest(`api/tax-invoices.php?id=${id}`);
        await takeCustomer(ti);
        takeRef(ti);
        fillLookup(byId('se-dn'), ti.deliveryNoteId ? { id: ti.deliveryNoteId, code: ti.deliveryNoteCode } : null);
        await takeLines(ti);
      } catch (error) { showToast('The tax invoice could not be loaded', error.message, true); }
    });
    byId('se-dn').addEventListener('input', async () => {
      const id = byId('se-dn-id').value;
      if (!id) return;
      try {
        const dn = await apiRequest(`api/delivery-notes.php?id=${id}`);
        if (!byId('se-customer-id').value) await takeCustomer(dn);
        takeRef(dn);
        if (!byId('se-ti-id').value) {
          const ti = (await loadLookup('taxinvoice')).find(row => String(row.deliveryNoteId) === String(dn.id));   // newest first
          if (ti) fillLookup(byId('se-ti'), { id: ti.id, code: ti.code });
        }
        await takeLines(dn);
      } catch (error) { showToast('The delivery note could not be loaded', error.message, true); }
    });
  },
});

/* ---------- Sales Return (Return & Replacement) ----------
   Goods a customer sends back. Ref ID picks the delivery note they went out on: its buyer, PO number, contact,
   currency, stock point and lines are copied in, each line's quantity as Sold Qty (Return Qty starts at all of it and
   can be at most that). Unit prices include VAT or have it added (Include / Exclude VAT). Total Refund = the lines' total
   less the Discount and the Restocking Fee, as backend/src/sales_return.php works it out. */
const srCurrency = () => byId('sr-currency-id').value || 'OMR';
function srSetCurrency(code) {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId('sr-currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}
// The buyer's contact persons as suggestions for Buyer Contact Person; a new pick also sets the currency and, when the
// buyer has one contact, fills it in.
async function srShowCustomer({ fresh = false } = {}) {
  const id = byId('sr-customer-id').value;
  const list = byId('sr-contact-list');
  if (!id) { list.replaceChildren(); return; }
  const customer = await pbCustomer(id).catch(() => null);
  if (!customer || byId('sr-customer-id').value !== id) return;
  const contacts = (customer.contacts || []).filter(contact => contact.name);
  list.replaceChildren(...contacts.map(contact => new Option(contact.name)));
  if (!fresh) return;
  const code = String(customer.currency || '').toUpperCase();
  if (PO_CURRENCIES.some(row => row.code === code)) srSetCurrency(code);
  if (contacts.length === 1) {
    byId('sr-contact').value = contacts[0].name;
    putPhone(byId('sr-contact-number'), salesCustomerPhone(contacts[0].number, customer));
  }
}

// The Sales Entry made against the picked delivery note: shown, never picked.
function srSetSalesEntry(entry) {
  byId('sr-se').value = entry ? entry.code : '';
  byId('sr-se-id').value = entry ? String(entry.id) : '';
}

const srForm = createPurchaseForm({
  key: 'sr', route: 'returns/sales-return/new', noun: 'Sales Return', api: 'api/sales-returns.php', listRoute: 'returns/sales-return',
  kind: 'po', template: 'pb-line-sr', lineExtras: ['soldQty', 'condition'], lookups: ['returndn', 'salesentry'], vatDefault: 'exclude',
  firstField: () => byId('sr-date'),
  onShow: () => openLookup(byId('sr-customer')),          // a new return starts by picking the Buyer
  fieldNodes: { returnDate: 'sr-date', deliveryNoteId: 'sr-ref', salesEntryId: 'sr-se', customerId: 'sr-customer',
    customerPo: 'sr-customer-po', currency: 'sr-currency', returnReason: 'sr-reason', warehouseId: 'sr-warehouse', refundMode: 'sr-refund-mode',
    contactName: 'sr-contact', contactNumber: 'sr-contact-number', discountAmount: 'sr-discount', restockingFee: 'sr-restocking',
    remarks: 'sr-remarks-editor' },
  header: () => {
    return {
      returnDate: byId('sr-date').value, deliveryNoteId: byId('sr-ref-id').value || null, salesEntryId: byId('sr-se-id').value || null,
      customerId: byId('sr-customer-id').value || null, customerPo: byId('sr-customer-po').value.trim(), currency: srCurrency(),
      returnReason: byId('sr-reason').value, warehouseId: byId('sr-warehouse-id').value || null, refundMode: byId('sr-refund-mode').value,
      contactName: byId('sr-contact').value.trim(), contactNumber: phoneOf(byId('sr-contact-number')),
      restockingFee: byId('sr-restocking').value.trim() || '0',
    };
  },
  check(form, errors) {
    if (!byId('sr-date').value) errors.push({ node: byId('sr-date'), message: 'Enter the return date.' });
    if (!byId('sr-customer-id').value) errors.push({ node: byId('sr-customer'), message: 'Select the customer.' });
    const fee = byId('sr-restocking').value.trim();
    if (fee !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(fee)) errors.push({ node: byId('sr-restocking'), message: 'Enter an amount with up to 3 decimals.' });
    form.page.rowsOf('items').forEach((row, index) => {
      const sold = pbNum(pbCell(row, 'soldQty').value);
      if (sold > 0 && pbNum(pbCell(row, 'quantity').value) > sold + 0.0005) {
        errors.push({ node: pbCell(row, 'quantity'), message: `Row ${index + 1}: the return quantity cannot be more than the quantity sold (${pbQty(sold)}).` });
      }
    });
  },
  // Every line shows its total (0.000 on a blank one) and its brand; Total Refund less the Restocking Fee.
  afterRefresh(totals) {
    srForm.page.rowsOf('items').forEach((row, i) => {
      row.querySelector('[data-total]').textContent = pbShow(totals.lineTotals[i]);
      row.querySelector('[data-brand-show]').value = pbCell(row, 'brandName').value;
    });
    const fee = Math.min(pbNum(byId('sr-restocking').value), Math.max(0, totals.grand));
    byId('sr-grand').textContent = pbShow(totals.grand - fee);
    for (const label of byId('sr-form').querySelectorAll('[data-sr-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
  },
  fill(form, sr) {
    byId('sr-date').value = sr.returnDate;
    fillLookup(byId('sr-ref'), sr.deliveryNoteId ? { id: sr.deliveryNoteId, code: sr.deliveryNoteCode } : null);
    srSetSalesEntry(sr.salesEntryId ? { id: sr.salesEntryId, code: sr.salesEntryCode } : null);
    fillLookup(byId('sr-customer'), sr.customerId ? { id: sr.customerId, name: sr.customerName } : null);
    byId('sr-customer-po').value = sr.customerPo || '';
    srSetCurrency(sr.currency);
    byId('sr-reason').value = sr.returnReason || '';
    fillLookup(byId('sr-warehouse'), sr.warehouseId ? { id: sr.warehouseId, code: sr.warehouseCode, name: sr.warehouseName } : null);
    byId('sr-refund-mode').value = sr.refundMode || 'Credit Note';
    byId('sr-contact').value = sr.contactName || '';
    putPhone(byId('sr-contact-number'), sr.contactNumber);
    byId('sr-restocking').value = pbMoney(pbNum(sr.restockingFee));
  },
  afterFill: () => srShowCustomer(),
  // Undo / Clear All put the Sales Entry id back; its number is shown again from the cached list.
  async afterRestore() {
    const id = byId('sr-se-id').value;
    if (!id) { byId('sr-se').value = ''; return; }
    const entry = (await loadLookup('salesentry').catch(() => [])).find(row => String(row.id) === id);
    if (byId('sr-se-id').value === id && entry) byId('sr-se').value = entry.code;
  },
  onReset() {
    byId('sr-date').value = todayInputValue();
    srSetCurrency('OMR');                          // hidden ids were cleared by the reset
    byId('sr-restocking').value = '0.000';
    byId('sr-contact-list').replaceChildren();
    forgetLookups('returndn', 'salesentry');
  },
  init(form) {
    // A buyer picked: their contact persons, currency and (when they have one) contact.
    byId('sr-customer').addEventListener('input', async () => {
      if (byId('sr-ref-id').value) { fillLookup(byId('sr-ref'), null); srSetSalesEntry(null); }   // the other buyer's delivery note
      byId('sr-contact').value = '';
      byId('sr-contact-number').value = '';
      await srShowCustomer({ fresh: true });
      form.page.absorb();
      form.refresh();
    });
    byId('sr-form').addEventListener('input', event => {
      if (['sr-currency', 'sr-discount', 'sr-restocking'].includes(event.target.id)) form.refresh();
    });
    // Another item picked on a line: the quantity sold was for the item before, so there is none now.
    byId('sr-items').addEventListener('input', event => {
      if (!['itemName', 'itemCode'].includes(event.target.dataset.field)) return;
      const sold = pbCell(event.target.closest('tr'), 'soldQty');
      if (sold) sold.value = '0';
    });
    // Ref ID (a delivery note) picked: its buyer, PO number, contact, currency, stock point, VAT and lines, and the
    // Sales Entry made against it (only its number: nothing is read from the sales entry). Each line is returned at its
    // net unit price (after its line discount), all of its quantity to begin with.
    const takeDoc = async doc => {
      if (doc.customerId) {
        fillLookup(byId('sr-customer'), { id: doc.customerId, name: doc.customerName });
        await srShowCustomer();
      }
      srSetCurrency(doc.currency);
      byId('sr-customer-po').value = doc.customerPo || byId('sr-customer-po').value;
      if (doc.contactName !== undefined) {
        byId('sr-contact').value = doc.contactName || '';
        putPhone(byId('sr-contact-number'), doc.contactNumber);
      }
      if (doc.warehouseId) fillLookup(byId('sr-warehouse'), { id: doc.warehouseId, code: doc.warehouseCode, name: doc.warehouseName });   // back where they went out from
      byId('sr-vat-mode').value = doc.vatMode === 'exclude' ? 'exclude' : 'include';
      await loadPurchaseLines(form, doc.items, line => {
        const quantity = pbNum(line.quantity);
        const net = line.foc ? 0 : Math.max(0, quantity * pbNum(line.price) - pbNum(line.discountAmount));
        return { ...purchaseLineRow(line), soldQty: pbQty(quantity), quantity: pbQty(quantity), condition: 'Good – Restock',
          price: pbMoney(quantity > 0 ? net / quantity : 0), vatRate: pbNum(line.vatRate).toFixed(2),
          discountPct: '0.00', discountAmount: '0.000', foc: 'No' };
      });
      form.syncVatToggle();
      form.refresh();
      showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
    };
    byId('sr-ref').addEventListener('input', async () => {
      const value = byId('sr-ref-id').value;
      if (!value) return;
      try {
        const doc = await apiRequest(`api/delivery-notes.php?id=${value}`);
        if (byId('sr-ref-id').value !== value) return;          // another delivery note was picked meanwhile
        const entry = (await loadLookup('salesentry').catch(() => [])).find(row => String(row.deliveryNoteId) === String(doc.id));   // newest first
        if (byId('sr-ref-id').value !== value) return;
        srSetSalesEntry(entry ? { id: entry.id, code: entry.code } : null);
        await takeDoc(doc);
      } catch (error) { showToast('The delivery note could not be loaded', error.message, true); }
    });
  },
});

/* ---------- Purchase Return (Return & Replacement) ----------
   Goods sent back to a supplier. Ref ID picks the purchase order or GRN they came in on: its supplier, contact,
   currency, stock point, VAT and lines are copied in, each line's quantity (a GRN's received quantity) as Received Qty
   (Return Qty starts at all of it and can be at most that). VAT Enabled / Disabled (as on the Sales Return) sets
   every line's VAT % to 5 or 0, added on top of the prices. Total Return Amount = the lines' total less the Discount and the Supplier Deduction, as
   backend/src/purchase_return.php works it out. */
// These helpers take the page's key: 'prt' (Purchase Return) or 'prp' (Purchase Replacement).
const prtCurrency = (key = 'prt') => byId(`${key}-currency-id`).value || 'OMR';
function prtSetCurrency(code, key = 'prt') {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId(`${key}-currency`), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}
// The picked Ref ID ("po:5" / "grn:3").
const prtRef = (key = 'prt') => { const [kind, id] = byId(`${key}-ref-id`).value.split(':'); return { kind, id: id || '' }; };
const prtWarehouseLabel = doc => [doc.warehouseCode, doc.warehouseName].filter(Boolean).join(' – ');

// A supplier picked: its currency, and its first contact person and number (its own phone when it has no contact).
async function prtShowSupplier(key = 'prt') {
  const id = byId(`${key}-supplier-id`).value;
  if (!id) return;
  const supplier = await pbSupplier(id).catch(() => null);
  if (!supplier || byId(`${key}-supplier-id`).value !== id) return;
  const code = String(supplier.currency || '').toUpperCase();
  if (PO_CURRENCIES.some(row => row.code === code)) prtSetCurrency(code, key);
  const contact = (supplier.contacts || []).find(entry => entry.name);
  if (contact) {
    fillLookup(byId(`${key}-contact`), { id: contact.name, name: contact.name });
    putPhone(byId(`${key}-contact-number`), contact.number ? poSupplierPhone(contact.number, supplier) : '');
  } else {
    fillLookup(byId(`${key}-contact`), null);
    putPhone(byId(`${key}-contact-number`), poSupplierPhone(supplier.phone || supplier.telephone, supplier));
  }
}

// A contact picked in the Select Contact Person popup brings its number (none: the number is left empty).
async function prtShowContact(form, key = 'prt') {
  const name = byId(`${key}-contact`).value;
  const supplierId = byId(`${key}-supplier-id`).value;
  const supplier = supplierId ? await pbSupplier(supplierId).catch(() => null) : null;
  if (byId(`${key}-contact`).value !== name) return;            // another pick came in meanwhile
  const contact = name ? supplier?.contacts?.find(entry => sameText(entry.name, name)) : null;
  putPhone(byId(`${key}-contact-number`), contact?.number ? poSupplierPhone(contact.number, supplier) : '');
  form.page.absorb();
}

// Ref ID (a PO or GRN) picked: its supplier, contact, currency, stock point and VAT go into the form; resolves to the
// document (null when another one was picked meanwhile). The caller turns its lines into rows.
async function prtLoadRef(key = 'prt') {
  const ref = byId(`${key}-ref-id`).value;
  const { kind, id } = prtRef(key);
  const grn = kind === 'grn';
  const doc = await apiRequest(`api/${grn ? 'grns' : 'purchase-orders'}.php?id=${id}`);
  if (byId(`${key}-ref-id`).value !== ref) return null;
  if (doc.supplierId) {
    fillLookup(byId(`${key}-supplier`), { id: doc.supplierId, name: doc.supplierName });
    if (grn) await prtShowSupplier(key);                     // a GRN has no contact or currency of its own
  }
  if (byId(`${key}-ref-id`).value !== ref) return null;
  if (!grn) {
    prtSetCurrency(doc.currency, key);
    fillLookup(byId(`${key}-contact`), doc.contactName ? { id: doc.contactName, name: doc.contactName } : null);
    putPhone(byId(`${key}-contact-number`), doc.contactNumber);
  }
  if (doc.warehouseId) setSelectValue(byId(`${key}-warehouse`), String(doc.warehouseId), prtWarehouseLabel(doc));
  byId(`${key}-vat-mode`).value = doc.vatMode === 'exclude' ? 'exclude' : 'include';
  return { doc, grn };
}

// A PO / GRN line's received quantity and its net unit price (after its line discount).
function prtRefLine(line, grn) {
  const received = pbNum(grn ? line.receivedQty : line.quantity);
  const net = grn ? pbNum(line.unitCost) * (1 - pbNum(line.discountPct) / 100)
    : line.foc || received <= 0 ? 0 : Math.max(0, received * pbNum(line.price) - pbNum(line.discountAmount)) / received;
  return { received: pbQty(received), unit: pbMoney(net) };
}

// Return Reason "Sales Return": goods a customer returned go back to the supplier. Their lines come from the sales
// return (Sales Return ID, shown beside the reason) instead of a PO / GRN (Ref ID, hidden), and such a return takes
// nothing out of stock: the goods never went back into it.
const PRT_SALES_RETURN = 'Sales Return';
const prtFromSalesReturn = () => byId('prt-reason').value === PRT_SALES_RETURN;

// Shows the Sales Return ID or the Ref ID, as the reason says. Changing over drops the document picked in the other
// one and the lines it brought (returns whether lines were dropped).
function prtShowReason(form) {
  const fromSr = prtFromSalesReturn();
  byId('prt-sr-field').hidden = !fromSr;
  byId('prt-ref-field').hidden = fromSr;
  const other = fromSr ? byId('prt-ref') : byId('prt-sr');
  if (!lookupIdInput(other).value) return false;
  fillLookup(other, null);
  form.page.setRows('items', []);
  form.refresh();
  return true;
}

// A sales return line as a purchase return row: the quantity the customer sent back is received and returned in full,
// at what the item was last bought for (the selected supplier's purchases first, api/item-purchase-price.php), else
// the Item master's buying rate. With no supplier yet, the one the first item was bought from is taken.
async function prtSalesReturnRows(form, doc) {
  const conditions = { 'Good – Restock': 'Good', 'Opened – Inspect': 'Good', 'Damaged – Scrap': 'Damaged', 'Defective – Return to Supplier': 'Defective' };
  const rows = [];
  for (const line of doc.items) {
    let price = 0;
    if (line.itemId) {
      const supplierId = byId('prt-supplier-id').value;
      const bought = await apiRequest(`api/item-purchase-price.php?itemId=${encodeURIComponent(line.itemId)}${supplierId ? `&supplierId=${encodeURIComponent(supplierId)}` : ''}`).catch(() => null);
      if (bought && !supplierId && bought.supplierId) {
        fillLookup(byId('prt-supplier'), { id: bought.supplierId, name: bought.supplierName });
        await prtShowSupplier();
      }
      if (bought) price = pbNum(bought.rate);                 // purchase prices are in OMR (PRICES_IN_OMR)
      else price = pbNum((await pbItem(String(line.itemId)).catch(() => null))?.buyingRate);
    }
    const qty = pbQty(pbNum(line.quantity));
    rows.push({ ...purchaseLineRow(line), receivedQty: qty, quantity: qty, condition: conditions[line.condition] || 'Defective',
      price: pbMoney(price), vatRate: pbNum(line.vatRate).toFixed(2), discountPct: '0.00', discountAmount: '0.000', foc: 'No' });
  }
  return rows;
}

const prtForm = createPurchaseForm({
  key: 'prt', route: 'returns/purchase-return/new', noun: 'Purchase Return', api: 'api/purchase-returns.php', listRoute: 'returns/purchase-return',
  kind: 'po', template: 'pb-line-prt', lineExtras: ['receivedQty', 'condition'], lookups: ['prtref'], vatDefault: 'exclude',
  firstField: () => byId('prt-date'),
  onShow: () => openLookup(byId('prt-ref')),          // a new return starts by picking the PO / GRN
  fieldNodes: { returnDate: 'prt-date', purchaseOrderId: 'prt-ref', grnId: 'prt-ref', createdBy: 'prt-created-by',
    salesReturnId: 'prt-sr', createdByContact: 'prt-created-by-contact', supplierInvoiceNo: 'prt-supplier-invoice', returnReason: 'prt-reason',
    warehouseId: 'prt-warehouse', settlementMode: 'prt-settlement', supplierId: 'prt-supplier', contactName: 'prt-contact',
    contactNumber: 'prt-contact-number', currency: 'prt-currency', discountAmount: 'prt-discount', supplierDeduction: 'prt-deduction',
    remarks: 'prt-remarks-editor' },
  header: () => ({
    returnDate: byId('prt-date').value,
    purchaseOrderId: !prtFromSalesReturn() && prtRef().kind === 'po' ? prtRef().id : null,
    grnId: !prtFromSalesReturn() && prtRef().kind === 'grn' ? prtRef().id : null,
    salesReturnId: prtFromSalesReturn() ? byId('prt-sr-id').value || null : null,
    createdBy: byId('prt-created-by').value.trim(), createdByContact: phoneOf(byId('prt-created-by-contact')),
    supplierInvoiceNo: byId('prt-supplier-invoice').value.trim(), returnReason: byId('prt-reason').value,
    warehouseId: byId('prt-warehouse').value || null, settlementMode: byId('prt-settlement').value,
    supplierId: byId('prt-supplier-id').value || null, contactName: byId('prt-contact').value.trim(),
    contactNumber: phoneOf(byId('prt-contact-number')), currency: prtCurrency(),
    supplierDeduction: byId('prt-deduction').value.trim() || '0',
  }),
  check(form, errors) {
    if (!byId('prt-date').value) errors.push({ node: byId('prt-date'), message: 'Enter the return date.' });
    if (!byId('prt-created-by').value.trim()) errors.push({ node: byId('prt-created-by'), message: 'Enter who created the return.' });
    if (!byId('prt-reason').value) errors.push({ node: byId('prt-reason'), message: 'Select the return reason.' });
    if (prtFromSalesReturn() && !byId('prt-sr-id').value) errors.push({ node: byId('prt-sr'), message: 'Select the sales return.' });
    if (!byId('prt-supplier-id').value) errors.push({ node: byId('prt-supplier'), message: 'Select the supplier.' });
    const deduction = byId('prt-deduction').value.trim();
    if (deduction !== '' && !/^\d{1,11}(\.\d{1,3})?$/.test(deduction)) errors.push({ node: byId('prt-deduction'), message: 'Enter an amount with up to 3 decimals.' });
    form.page.rowsOf('items').forEach((row, index) => {
      const received = pbNum(pbCell(row, 'receivedQty').value);
      if (received > 0 && pbNum(pbCell(row, 'quantity').value) > received + 0.0005) {
        errors.push({ node: pbCell(row, 'quantity'), message: `Row ${index + 1}: the return quantity cannot be more than the quantity received (${pbQty(received)}).` });
      }
    });
  },
  // Every line shows its total (0.000 on a blank one) and its brand; Total Return Amount less the Supplier Deduction.
  afterRefresh(totals) {
    prtForm.page.rowsOf('items').forEach((row, i) => {
      row.querySelector('[data-total]').textContent = pbShow(totals.lineTotals[i]);
      row.querySelector('[data-brand-show]').value = pbCell(row, 'brandName').value;
    });
    const deduction = Math.min(pbNum(byId('prt-deduction').value), Math.max(0, totals.grand));
    byId('prt-grand').textContent = pbShow(totals.grand - deduction);
    for (const label of byId('prt-form').querySelectorAll('[data-prt-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
  },
  fill(form, prt) {
    byId('prt-date').value = prt.returnDate;
    fillLookup(byId('prt-ref'), prt.grnId ? { id: `grn:${prt.grnId}`, code: prt.grnCode }
      : prt.purchaseOrderId ? { id: `po:${prt.purchaseOrderId}`, code: prt.purchaseOrderCode } : null);
    byId('prt-created-by').value = prt.createdBy || signedInName.toUpperCase();   // read-only: kept as saved
    putPhone(byId('prt-created-by-contact'), prt.createdByContact);
    byId('prt-supplier-invoice').value = prt.supplierInvoiceNo || '';
    byId('prt-reason').value = prt.returnReason || '';
    fillLookup(byId('prt-sr'), prt.salesReturnId ? { id: prt.salesReturnId, code: prt.salesReturnCode } : null);
    byId('prt-sr-field').hidden = !prtFromSalesReturn();
    byId('prt-ref-field').hidden = prtFromSalesReturn();
    setSelectValue(byId('prt-warehouse'), prt.warehouseId ? String(prt.warehouseId) : '', prtWarehouseLabel(prt));
    byId('prt-settlement').value = prt.settlementMode || 'Debit Note';
    fillLookup(byId('prt-supplier'), prt.supplierId ? { id: prt.supplierId, name: prt.supplierName } : null);
    fillLookup(byId('prt-contact'), prt.contactName ? { id: prt.contactName, name: prt.contactName } : null);
    putPhone(byId('prt-contact-number'), prt.contactNumber);
    prtSetCurrency(prt.currency);
    byId('prt-deduction').value = pbMoney(pbNum(prt.supplierDeduction));
  },
  onReset() {
    byId('prt-date').value = todayInputValue();
    prtSetCurrency('OMR');                          // hidden ids were cleared by the reset
    byId('prt-deduction').value = '0.000';
    forgetLookups('prtref', 'prtsr');
    byId('prt-sr-field').hidden = true;             // the reason starts blank: the Ref ID (PO / GRN) shows
    byId('prt-ref-field').hidden = false;
    // Return From: the stock points (the list is loaded before a saved return is filled in).
    return purchaseOptions(byId('prt-warehouse'), 'api/warehouses.php', row => [row.code, row.name].filter(Boolean).join(' – '));
  },
  init(form) {
    // A supplier picked by hand: its contact and currency; another supplier's PO / GRN goes.
    byId('prt-supplier').addEventListener('input', async () => {
      if (byId('prt-ref-id').value) fillLookup(byId('prt-ref'), null);
      fillLookup(byId('prt-contact'), null);
      byId('prt-contact-number').value = '';
      await prtShowSupplier();
      form.page.absorb();
      form.refresh();
    });
    byId('prt-contact').addEventListener('input', () => prtShowContact(form));
    // Return Reason: "Sales Return" shows the Sales Return ID in place of the Ref ID, and opens its list.
    byId('prt-reason').addEventListener('change', () => {
      prtShowReason(form);
      if (prtFromSalesReturn() && !byId('prt-sr-id').value) openLookup(byId('prt-sr'));
    });
    // Sales Return ID picked: its items become the lines (not a PO's or GRN's), with its stock point and VAT.
    byId('prt-sr').addEventListener('input', async () => {
      const value = byId('prt-sr-id').value;
      if (!value) return;
      try {
        const doc = await apiRequest(`api/sales-returns.php?id=${value}`);
        if (byId('prt-sr-id').value !== value) return;          // another sales return was picked meanwhile
        if (doc.warehouseId) setSelectValue(byId('prt-warehouse'), String(doc.warehouseId), prtWarehouseLabel(doc));
        byId('prt-vat-mode').value = doc.vatMode === 'exclude' ? 'exclude' : 'include';
        const rows = await prtSalesReturnRows(form, doc);
        if (byId('prt-sr-id').value !== value) return;
        await loadPurchaseLines(form, rows, row => row);
        form.page.absorb();
        form.syncVatToggle();
        form.refresh();
        showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
      } catch (error) { showToast('The sales return could not be loaded', error.message, true); }
    });
    byId('prt-form').addEventListener('input', event => {
      if (['prt-currency', 'prt-discount', 'prt-deduction'].includes(event.target.id)) form.refresh();
    });
    // Another item picked on a line: the quantity received was for the item before, so there is none now.
    byId('prt-items').addEventListener('input', event => {
      if (!['itemName', 'itemCode'].includes(event.target.dataset.field)) return;
      const received = pbCell(event.target.closest('tr'), 'receivedQty');
      if (received) received.value = '0';
    });
    // Ref ID picked: the PO's or GRN's supplier, contact, currency, stock point, VAT and lines. Each line is returned at
    // its net unit price (after its line discount), all of the quantity received to begin with.
    byId('prt-ref').addEventListener('input', async () => {
      if (!byId('prt-ref-id').value) return;
      const grn = prtRef().kind === 'grn';
      try {
        const loaded = await prtLoadRef();
        if (!loaded) return;                                    // another document was picked meanwhile
        const { doc } = loaded;
        await loadPurchaseLines(form, doc.items, line => {
          const { received, unit } = prtRefLine(line, grn);
          return { ...purchaseLineRow(line), receivedQty: received, quantity: received, condition: 'Damaged',
            price: unit, vatRate: pbNum(line.vatRate).toFixed(2), discountPct: '0.00', discountAmount: '0.000', foc: 'No' };
        });
        form.syncVatToggle();
        form.refresh();
        showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
      } catch (error) { showToast(`The ${grn ? 'GRN' : 'purchase order'} could not be loaded`, error.message, true); }
    });
  },
});

/* ---------- Purchase Replacement (Return & Replacement) ----------
   Goods a supplier sends in place of goods sent back to it. Ref ID picks the purchase order or GRN they came in on:
   its supplier, contact, currency, stock point, VAT and lines are copied in, each line's quantity (a GRN's received
   quantity) as Received Qty (Replace Qty starts at all of it and can be at most that) and its net unit price as Old
   Price and New Price. A Replacement Item (none: the same item comes back) takes its buying rate as the New Price.
   Each line's Difference = Replace Qty × (New − Old), its VAT % added on top (VAT Enabled; Disabled sets every line's
   VAT % to 0). Price Difference = Replacement − Returned value (+ VAT on the difference when excluded) − Discount +
   Handling / Delivery Charge, as backend/src/purchase_replacement.php works it out: above 0 it is paid to the
   supplier, below 0 the supplier owes it. */
const prpForm = createPurchaseForm({
  key: 'prp', route: 'returns/purchase-replacement/new', noun: 'Purchase Replacement', api: 'api/purchase-replacements.php',
  listRoute: 'returns/purchase-replacement',
  kind: 'po', template: 'pb-line-prp', lineExtras: ['receivedQty', 'condition', 'oldPrice', 'replacementItemId'], lookups: ['prtref'], vatDefault: 'exclude',
  firstField: () => byId('prp-date'),
  onShow: () => openLookup(byId('prp-ref')),          // a new replacement starts by picking the PO / GRN
  fieldNodes: { replacementDate: 'prp-date', purchaseOrderId: 'prp-ref', grnId: 'prp-ref', createdBy: 'prp-created-by',
    createdByContact: 'prp-created-by-contact', supplierInvoiceNo: 'prp-supplier-invoice', replacementReason: 'prp-reason',
    warehouseId: 'prp-warehouse', returnedGoods: 'prp-returned', supplierId: 'prp-supplier', contactName: 'prp-contact',
    contactNumber: 'prp-contact-number', currency: 'prp-currency', discountAmount: 'prp-discount', handlingCharge: 'prp-shipping',
    shipping: 'prp-shipping', remarks: 'prp-remarks-editor' },
  header: () => ({
    replacementDate: byId('prp-date').value,
    purchaseOrderId: prtRef('prp').kind === 'po' ? prtRef('prp').id : null, grnId: prtRef('prp').kind === 'grn' ? prtRef('prp').id : null,
    createdBy: byId('prp-created-by').value.trim(), createdByContact: phoneOf(byId('prp-created-by-contact')),
    supplierInvoiceNo: byId('prp-supplier-invoice').value.trim(), replacementReason: byId('prp-reason').value,
    warehouseId: byId('prp-warehouse').value || null, returnedGoods: byId('prp-returned').value,
    supplierId: byId('prp-supplier-id').value || null, contactName: byId('prp-contact').value.trim(),
    contactNumber: phoneOf(byId('prp-contact-number')), currency: prtCurrency('prp'),
    handlingCharge: byId('prp-shipping').value.trim() || '0',
  }),
  check(form, errors) {
    if (!byId('prp-date').value) errors.push({ node: byId('prp-date'), message: 'Enter the replacement date.' });
    if (!byId('prp-created-by').value.trim()) errors.push({ node: byId('prp-created-by'), message: 'Enter who created the replacement.' });
    if (!byId('prp-reason').value) errors.push({ node: byId('prp-reason'), message: 'Select the replacement reason.' });
    if (!byId('prp-supplier-id').value) errors.push({ node: byId('prp-supplier'), message: 'Select the supplier.' });
    const money = /^\d{1,11}(\.\d{1,3})?$/;
    form.page.rowsOf('items').forEach((row, index) => {
      if (!pbCell(row, 'itemName').value.trim() && !pbCell(row, 'itemId').value) return;
      const old = pbCell(row, 'oldPrice').value.trim();
      if (old !== '' && !money.test(old)) errors.push({ node: pbCell(row, 'oldPrice'), message: `Row ${index + 1}: enter the old price with up to 3 decimals.` });
      const received = pbNum(pbCell(row, 'receivedQty').value);
      if (received > 0 && pbNum(pbCell(row, 'quantity').value) > received + 0.0005) {
        errors.push({ node: pbCell(row, 'quantity'), message: `Row ${index + 1}: the replace quantity cannot be more than the quantity received (${pbQty(received)}).` });
      }
    });
  },
  // The replacement's own totals (the shared ones cannot go below 0): each line's Difference, the values and the
  // Price Difference, with what it means.
  afterRefresh() {
    const rows = prpForm.page.rowsOf('items');
    const totals = rpTotals(rows, prpForm.vatMode(), 'prp');
    rows.forEach((row, i) => { row.querySelector('[data-total]').textContent = pbShow(totals.lineTotals[i]); });
    byId('prp-returned-value').textContent = pbShow(totals.returned);
    byId('prp-replacement-value').textContent = pbShow(totals.replacement);
    byId('prp-vat').textContent = pbShow(totals.vat);
    byId('prp-grand').textContent = pbShow(totals.grand);
    const grand = Math.round(totals.grand * 1000);
    byId('prp-grand-note').textContent = grand > 0 ? 'Payable to the supplier'
      : grand < 0 ? 'Owed by the supplier (debit note / refund)' : 'No difference – like-for-like replacement';
    for (const label of byId('prp-form').querySelectorAll('[data-prp-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
  },
  fill(form, prp) {
    byId('prp-date').value = prp.replacementDate;
    fillLookup(byId('prp-ref'), prp.grnId ? { id: `grn:${prp.grnId}`, code: prp.grnCode }
      : prp.purchaseOrderId ? { id: `po:${prp.purchaseOrderId}`, code: prp.purchaseOrderCode } : null);
    byId('prp-created-by').value = prp.createdBy || signedInName.toUpperCase();   // read-only: kept as saved
    putPhone(byId('prp-created-by-contact'), prp.createdByContact);
    byId('prp-supplier-invoice').value = prp.supplierInvoiceNo || '';
    setSelectValue(byId('prp-reason'), prp.replacementReason || '');
    setSelectValue(byId('prp-warehouse'), prp.warehouseId ? String(prp.warehouseId) : '', prtWarehouseLabel(prp));
    setSelectValue(byId('prp-returned'), prp.returnedGoods || 'Sent to Supplier');
    fillLookup(byId('prp-supplier'), prp.supplierId ? { id: prp.supplierId, name: prp.supplierName } : null);
    fillLookup(byId('prp-contact'), prp.contactName ? { id: prp.contactName, name: prp.contactName } : null);
    putPhone(byId('prp-contact-number'), prp.contactNumber);
    prtSetCurrency(prp.currency, 'prp');
  },
  onReset() {
    byId('prp-date').value = todayInputValue();
    byId('prp-returned').value = 'Sent to Supplier';
    prtSetCurrency('OMR', 'prp');                   // hidden ids were cleared by the reset
    forgetLookups('prtref');
    // Receive To: the stock points (the list is loaded before a saved replacement is filled in).
    return purchaseOptions(byId('prp-warehouse'), 'api/warehouses.php', row => [row.code, row.name].filter(Boolean).join(' – '));
  },
  init(form) {
    // A supplier picked by hand: its contact and currency; another supplier's PO / GRN goes.
    byId('prp-supplier').addEventListener('input', async () => {
      if (byId('prp-ref-id').value) fillLookup(byId('prp-ref'), null);
      fillLookup(byId('prp-contact'), null);
      byId('prp-contact-number').value = '';
      await prtShowSupplier('prp');
      form.page.absorb();
      form.refresh();
    });
    byId('prp-contact').addEventListener('input', () => prtShowContact(form, 'prp'));
    byId('prp-form').addEventListener('input', event => {
      if (['prp-currency', 'prp-discount', 'prp-shipping'].includes(event.target.id)) form.refresh();
    });
    byId('prp-items').addEventListener('input', async event => {
      const row = event.target.closest('tr');
      const field = event.target.dataset.field;
      // Another returned item: the quantity received was for the item before, so there is none now.
      if (['itemName', 'itemCode'].includes(field)) { pbCell(row, 'receivedQty').value = '0'; return; }
      if (field !== 'replacementItemName') return;
      // A replacement item picked: its buying rate is the New Price; cleared, the same item comes back at the old price.
      const id = pbCell(row, 'replacementItemId').value;
      if (!id) {
        pbCell(row, 'replacementItemName').value = '';
        pbCell(row, 'price').value = pbMoney(pbNum(pbCell(row, 'oldPrice').value));
      } else {
        const item = await pbItem(id).catch(() => null);
        if (!item || pbCell(row, 'replacementItemId').value !== id) return;
        if (pbNum(item.buyingRate) > 0) pbCell(row, 'price').value = pbMoney(pbNum(item.buyingRate));
      }
      form.page.absorb();
      form.refresh();
    });
    // Ref ID (a PO or GRN) picked: its supplier, contact, currency, stock point, VAT and lines. Each line comes back at
    // its net unit price (Old and New Price), all of the quantity received to begin with.
    byId('prp-ref').addEventListener('input', async () => {
      if (!byId('prp-ref-id').value) return;
      const grn = prtRef('prp').kind === 'grn';
      try {
        const loaded = await prtLoadRef('prp');
        if (!loaded) return;                                    // another document was picked meanwhile
        const { doc } = loaded;
        await loadPurchaseLines(form, doc.items, line => {
          const { received, unit } = prtRefLine(line, grn);
          return { ...purchaseLineRow(line), receivedQty: received, quantity: received, condition: 'Damaged',
            replacementItemId: '', replacementItemName: '', oldPrice: unit, price: unit, vatRate: pbNum(line.vatRate).toFixed(2),
            discountPct: '0.00', discountAmount: '0.000', foc: 'No' };
        });
        form.syncVatToggle();
        form.refresh();
        showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
      } catch (error) { showToast(`The ${grn ? 'GRN' : 'purchase order'} could not be loaded`, error.message, true); }
    });
  },
});

/* ---------- Sales Replacement (Return & Replacement) ----------
   Goods sent to a customer in place of goods they return. Ref ID picks the delivery note they went out on: its buyer,
   PO number, contact, currency, stock point and lines are copied in, with the Sales Entry made against it, each line's quantity as Sold Qty (Replace Qty
   starts at all of it and can be at most that) and its net unit price as Old Price and New Price. A Replacement Item
   (none: the same item goes back) takes its selling price as the New Price. Each line's Difference = Replace Qty ×
   (New − Old), its VAT % added on top (VAT Enabled; Disabled sets every line's VAT % to 0). Price Difference = Replacement − Returned
   value (+ VAT on the difference when excluded) − Discount + Handling / Delivery Charge, as
   backend/src/sales_replacement.php works it out: above 0 the buyer pays, below 0 it is owed to the buyer. */
const rpCurrency = () => byId('rp-currency-id').value || 'OMR';
function rpSetCurrency(code) {
  const text = String(code || 'OMR').toUpperCase();
  fillLookup(byId('rp-currency'), PO_CURRENCIES.find(row => row.code === text) || { id: text, code: text, name: text });
}
// The buyer's contact persons as suggestions for Buyer Contact Person; a new pick also sets the currency and, when the
// buyer has one contact, fills it in.
async function rpShowCustomer({ fresh = false } = {}) {
  const id = byId('rp-customer-id').value;
  const list = byId('rp-contact-list');
  if (!id) { list.replaceChildren(); return; }
  const customer = await pbCustomer(id).catch(() => null);
  if (!customer || byId('rp-customer-id').value !== id) return;
  const contacts = (customer.contacts || []).filter(contact => contact.name);
  list.replaceChildren(...contacts.map(contact => new Option(contact.name)));
  if (!fresh) return;
  const code = String(customer.currency || '').toUpperCase();
  if (PO_CURRENCIES.some(row => row.code === code)) rpSetCurrency(code);
  if (contacts.length === 1) {
    byId('rp-contact').value = contacts[0].name;
    putPhone(byId('rp-contact-number'), salesCustomerPhone(contacts[0].number, customer));
  }
}
// The Sales Entry made against the picked delivery note: shown, never picked.
function rpSetSalesEntry(entry) {
  byId('rp-se').value = entry ? entry.code : '';
  byId('rp-se-id').value = entry ? String(entry.id) : '';
}
// The totals as the server works them out (srp_totals()): the lines' differences, the returned and replacement
// values, the VAT on the difference and the Price Difference.
function rpTotals(rows, vatMode, key = 'rp') {
  let returned = 0;
  let replacement = 0;
  let vat = 0;
  const lineTotals = rows.map(row => {
    const qty = pbNum(pbCell(row, 'quantity').value);
    const old = qty * pbNum(pbCell(row, 'oldPrice').value);
    const now = qty * pbNum(pbCell(row, 'price').value);
    const diff = now - old;
    const rate = pbNum(pbCell(row, 'vatRate').value);
    returned += old;
    replacement += now;
    vat += vatMode === 'include' ? diff * rate / (100 + rate) : diff * rate / 100;
    return vatMode === 'include' ? diff : diff * (1 + rate / 100);
  });
  const difference = replacement - returned + (vatMode === 'exclude' ? vat : 0);
  const handling = pbNum(byId(`${key}-shipping`).value);
  const discount = Math.min(pbNum(byId(`${key}-discount`).value), Math.max(0, difference + handling));
  return { lineTotals, returned, replacement, vat, grand: difference - discount + handling };
}

const rpForm = createPurchaseForm({
  key: 'rp', route: 'returns/sales-replacement/new', noun: 'Sales Replacement', api: 'api/sales-replacements.php', listRoute: 'returns/sales-replacement',
  kind: 'po', template: 'pb-line-rp', lineExtras: ['soldQty', 'condition', 'oldPrice', 'replacementItemId'], lookups: ['returndn', 'salesentry'], vatDefault: 'exclude',
  firstField: () => byId('rp-date'),
  onShow: () => openLookup(byId('rp-customer')),          // a new replacement starts by picking the Buyer
  fieldNodes: { replacementDate: 'rp-date', deliveryNoteId: 'rp-ref', salesEntryId: 'rp-se', customerId: 'rp-customer',
    customerPo: 'rp-customer-po', currency: 'rp-currency', replacementReason: 'rp-reason', warehouseId: 'rp-warehouse', returnedGoods: 'rp-returned',
    contactName: 'rp-contact', contactNumber: 'rp-contact-number', discountAmount: 'rp-discount', handlingCharge: 'rp-shipping',
    shipping: 'rp-shipping', remarks: 'rp-remarks-editor' },
  header: () => ({
    replacementDate: byId('rp-date').value, deliveryNoteId: byId('rp-ref-id').value || null, salesEntryId: byId('rp-se-id').value || null,
    customerId: byId('rp-customer-id').value || null, customerPo: byId('rp-customer-po').value.trim(), currency: rpCurrency(),
    replacementReason: byId('rp-reason').value, warehouseId: byId('rp-warehouse').value || null, returnedGoods: byId('rp-returned').value,
    contactName: byId('rp-contact').value.trim(), contactNumber: phoneOf(byId('rp-contact-number')),
    handlingCharge: byId('rp-shipping').value.trim() || '0',
  }),
  check(form, errors) {
    if (!byId('rp-date').value) errors.push({ node: byId('rp-date'), message: 'Enter the replacement date.' });
    if (!byId('rp-customer-id').value) errors.push({ node: byId('rp-customer'), message: 'Select the buyer.' });
    if (!byId('rp-reason').value) errors.push({ node: byId('rp-reason'), message: 'Select the replacement reason.' });
    const money = /^\d{1,11}(\.\d{1,3})?$/;
    const handling = byId('rp-shipping').value.trim();
    if (handling !== '' && !money.test(handling)) errors.push({ node: byId('rp-shipping'), message: 'Enter an amount with up to 3 decimals.' });
    form.page.rowsOf('items').forEach((row, index) => {
      if (!pbCell(row, 'itemName').value.trim() && !pbCell(row, 'itemId').value) return;
      const old = pbCell(row, 'oldPrice').value.trim();
      if (old !== '' && !money.test(old)) errors.push({ node: pbCell(row, 'oldPrice'), message: `Row ${index + 1}: enter the old price with up to 3 decimals.` });
      const sold = pbNum(pbCell(row, 'soldQty').value);
      if (sold > 0 && pbNum(pbCell(row, 'quantity').value) > sold + 0.0005) {
        errors.push({ node: pbCell(row, 'quantity'), message: `Row ${index + 1}: the replace quantity cannot be more than the quantity sold (${pbQty(sold)}).` });
      }
    });
  },
  // The replacement's own totals (the shared ones cannot go below 0): each line's Difference, the values and the
  // Price Difference, with what it means for the buyer.
  afterRefresh() {
    const rows = rpForm.page.rowsOf('items');
    const totals = rpTotals(rows, rpForm.vatMode());
    rows.forEach((row, i) => { row.querySelector('[data-total]').textContent = pbShow(totals.lineTotals[i]); });
    byId('rp-returned-value').textContent = pbShow(totals.returned);
    byId('rp-replacement-value').textContent = pbShow(totals.replacement);
    byId('rp-vat').textContent = pbShow(totals.vat);
    byId('rp-grand').textContent = pbShow(totals.grand);
    const grand = Math.round(totals.grand * 1000);
    byId('rp-grand-note').textContent = grand > 0 ? 'The buyer pays the difference'
      : grand < 0 ? 'Owed to the buyer (credit / refund)' : 'No difference – like-for-like replacement';
    for (const label of byId('rp-form').querySelectorAll('[data-rp-base]')) label.textContent = 'OMR';   // PRICES_IN_OMR
  },
  fill(form, rp) {
    byId('rp-date').value = rp.replacementDate;
    fillLookup(byId('rp-ref'), rp.deliveryNoteId ? { id: rp.deliveryNoteId, code: rp.deliveryNoteCode } : null);
    rpSetSalesEntry(rp.salesEntryId ? { id: rp.salesEntryId, code: rp.salesEntryCode } : null);
    fillLookup(byId('rp-customer'), rp.customerId ? { id: rp.customerId, name: rp.customerName } : null);
    byId('rp-customer-po').value = rp.customerPo || '';
    rpSetCurrency(rp.currency);
    setSelectValue(byId('rp-reason'), rp.replacementReason || '');
    setSelectValue(byId('rp-warehouse'), rp.warehouseId ? String(rp.warehouseId) : '', [rp.warehouseCode, rp.warehouseName].filter(Boolean).join(' – '));
    setSelectValue(byId('rp-returned'), rp.returnedGoods || 'Collected from Buyer');
    byId('rp-contact').value = rp.contactName || '';
    putPhone(byId('rp-contact-number'), rp.contactNumber);
  },
  afterFill: () => rpShowCustomer(),
  // Undo / Clear All put the Sales Entry id back; its number is shown again from the cached list.
  async afterRestore() {
    const id = byId('rp-se-id').value;
    if (!id) { byId('rp-se').value = ''; return; }
    const entry = (await loadLookup('salesentry').catch(() => [])).find(row => String(row.id) === id);
    if (byId('rp-se-id').value === id && entry) byId('rp-se').value = entry.code;
  },
  onReset() {
    byId('rp-date').value = todayInputValue();
    byId('rp-returned').value = 'Collected from Buyer';
    rpSetCurrency('OMR');                          // hidden ids were cleared by the reset
    byId('rp-contact-list').replaceChildren();
    forgetLookups('returndn', 'salesentry');
    // Issue From: the stock points (the list is loaded before a saved replacement is filled in).
    return purchaseOptions(byId('rp-warehouse'), 'api/warehouses.php', row => [row.code, row.name].filter(Boolean).join(' – '));
  },
  init(form) {
    // A buyer picked: their contact persons, currency and (when they have one) contact; the other buyer's document goes.
    byId('rp-customer').addEventListener('input', async () => {
      if (byId('rp-ref-id').value) { fillLookup(byId('rp-ref'), null); rpSetSalesEntry(null); }   // the other buyer's delivery note
      byId('rp-contact').value = '';
      byId('rp-contact-number').value = '';
      await rpShowCustomer({ fresh: true });
      form.page.absorb();
      form.refresh();
    });
    byId('rp-form').addEventListener('input', event => {
      if (['rp-currency', 'rp-discount', 'rp-shipping'].includes(event.target.id)) form.refresh();
    });
    byId('rp-items').addEventListener('input', async event => {
      const row = event.target.closest('tr');
      const field = event.target.dataset.field;
      // Another returned item: the quantity sold was for the item before, so there is none now.
      if (['itemName', 'itemCode'].includes(field)) { pbCell(row, 'soldQty').value = '0'; return; }
      if (field !== 'replacementItemName') return;
      // A replacement item picked: its selling price is the New Price; cleared, the same item goes back at the old price.
      const id = pbCell(row, 'replacementItemId').value;
      if (!id) {
        pbCell(row, 'replacementItemName').value = '';
        pbCell(row, 'price').value = pbMoney(pbNum(pbCell(row, 'oldPrice').value));
      } else {
        const item = await pbItem(id).catch(() => null);
        if (!item || pbCell(row, 'replacementItemId').value !== id) return;
        if (pbNum(item.sellingPrice) > 0) pbCell(row, 'price').value = pbMoney(pbNum(item.sellingPrice));
      }
      form.page.absorb();
      form.refresh();
    });
    // Ref ID (a delivery note) picked: its buyer, PO number, contact, currency, stock point, VAT and lines, and the
    // Sales Entry made against it (only its number). Each line goes back at its net unit price (after its line
    // discount), all of its quantity to begin with.
    byId('rp-ref').addEventListener('input', async () => {
      const value = byId('rp-ref-id').value;
      if (!value) return;
      try {
        const doc = await apiRequest(`api/delivery-notes.php?id=${value}`);
        if (byId('rp-ref-id').value !== value) return;          // another delivery note was picked meanwhile
        const entry = (await loadLookup('salesentry').catch(() => [])).find(row => String(row.deliveryNoteId) === String(doc.id));   // newest first
        if (byId('rp-ref-id').value !== value) return;
        rpSetSalesEntry(entry ? { id: entry.id, code: entry.code } : null);
        if (doc.customerId) {
          fillLookup(byId('rp-customer'), { id: doc.customerId, name: doc.customerName });
          await rpShowCustomer();
        }
        rpSetCurrency(doc.currency);
        byId('rp-customer-po').value = doc.customerPo || byId('rp-customer-po').value;
        if (doc.contactName !== undefined) {
          byId('rp-contact').value = doc.contactName || '';
          putPhone(byId('rp-contact-number'), doc.contactNumber);
        }
        if (doc.warehouseId) setSelectValue(byId('rp-warehouse'), String(doc.warehouseId), [doc.warehouseCode, doc.warehouseName].filter(Boolean).join(' – '));   // issued from where they went out
        byId('rp-vat-mode').value = doc.vatMode === 'exclude' ? 'exclude' : 'include';
        await loadPurchaseLines(form, doc.items, line => {
          const quantity = pbNum(line.quantity);
          const net = line.foc ? 0 : Math.max(0, quantity * pbNum(line.price) - pbNum(line.discountAmount));
          const unit = pbMoney(quantity > 0 ? net / quantity : 0);
          return { ...purchaseLineRow(line), soldQty: pbQty(quantity), quantity: pbQty(quantity), condition: 'Damaged',
            replacementItemId: '', replacementItemName: '', oldPrice: unit, price: unit, vatRate: pbNum(line.vatRate).toFixed(2),
            discountPct: '0.00', discountAmount: '0.000', foc: 'No' };
        });
        form.syncVatToggle();
        form.refresh();
        showToast('Items fetched', `${doc.items.length} item${doc.items.length === 1 ? '' : 's'} from ${doc.code}.`);
      } catch (error) { showToast('The delivery note could not be loaded', error.message, true); }
    });
  },
});

const PURCHASE_FORMS = [prForm, rfqForm, poForm, grnForm, qtForm, soForm, dnForm, tiForm, peForm, seForm, srForm, rpForm, prtForm, prpForm, saForm, stForm, rsvForm];

/* ---------- GRN line: rejection reason and Stock Transfer ----------
   Rejected is Received - Accepted; while it is more than 0 the line shows a Rejection Reason box under the item name.
   Transfer (the line's button) opens the Stock Transfer popup: rows of destination stock point and quantity, sent on
   from the accepted stock; never the stock point the goods are received into, each stock point once, at most the
   accepted quantity in all. The rows are kept as JSON in the line's hidden transfers cell, so undo and save see them. */
let grnTransferKeys = null;            // the open Stock Transfer popup's keys (handleWindowKeys calls it first)
const grnTransfers = row => {
  try { return JSON.parse(pbCell(row, 'transfers')?.value || '[]') || []; } catch { return []; }
};

// The Rejection Reason box runs from the Item Name to the end of the Rej. Qty box.
function sizeGrnReason(row) {
  const reason = pbCell(row, 'rejectReason');
  if (!reason || reason.hidden) return;
  // Laid over the row (it never widens the Item Name column), lined up with the item name box.
  const wrap = reason.parentElement.querySelector('.fp-input-wrap');
  reason.style.left = `${wrap.offsetLeft}px`;
  const left = wrap.getBoundingClientRect().left;
  const right = pbCell(row, 'rejectedQty').getBoundingClientRect().right;
  reason.style.width = right > left ? `${Math.round(right - left)}px` : '';
}

function syncGrnRow(row) {
  const reason = pbCell(row, 'rejectReason');
  if (reason) {
    reason.hidden = !(pbNum(pbCell(row, 'rejectedQty').value) > 0);
    row.classList.toggle('has-reason', !reason.hidden);
    sizeGrnReason(row);
  }
  const badge = row.querySelector('[data-transfer-badge]');
  if (!badge) return;
  const sent = grnTransfers(row).reduce((sum, t) => sum + pbNum(t.quantity), 0);
  badge.hidden = !(sent > 0);
  badge.textContent = pbQty(sent);
  const button = badge.closest('button');
  button.classList.toggle('is-set', sent > 0);
  button.classList.toggle('is-over', sent > pbNum(pbCell(row, 'acceptedQty').value) + 0.0005);
  button.title = sent > 0 ? `Stock Transfer: ${pbQty(sent)} sent to other stock points` : 'Stock Transfer: send accepted stock to other stock points';
}

function initGrnTransfer(form) {
  const dialog = byId('grn-transfer');
  const list = byId('grn-transfer-rows');
  let row = null;                       // the GRN line being allocated
  let points = [];                      // the stock points it may go to

  const accepted = () => pbNum(pbCell(row, 'acceptedQty').value);
  const unit = () => pbCell(row, 'unit')?.value.trim() || '';
  const withUnit = quantity => `${pbQty(quantity)}${unit() ? ` ${unit()}` : ''}`;
  const lines = () => [...list.querySelectorAll('li')];
  const showError = message => { byId('grn-transfer-error').textContent = message; byId('grn-transfer-error').hidden = !message; };

  // A stock point is used once per transfer: each row's list leaves out the stock points the other rows have chosen
  // (its own choice stays). A row removed or changed gives its stock point back to the others. + Add Stock Point
  // is off once every stock point is in use.
  function syncPoints() {
    const selects = lines().map(li => li.querySelector('[data-gt-point]'));
    const chosen = selects.map(select => select.value).filter(Boolean);
    for (const select of selects) {
      for (const option of select.options) {
        if (!option.value) continue;
        const taken = option.value !== select.value && chosen.includes(option.value);
        option.hidden = taken;
        option.disabled = taken;
      }
    }
    const free = points.filter(point => !chosen.includes(String(point.id))).length;
    const blank = selects.some(select => !select.value);
    const add = dialog.querySelector('[data-gt="add"]');
    add.disabled = free === 0 || (free === 1 && blank);
    add.title = add.disabled ? 'Every stock point is already on a transfer row' : 'Add another destination stock point (Shift+X)';
  }

  function totals() {
    syncPoints();
    const sent = lines().reduce((sum, li) => sum + pbNum(li.querySelector('[data-gt-qty]').value), 0);
    byId('grn-transfer-allocated').textContent = withUnit(sent);
    byId('grn-transfer-allocated').classList.toggle('is-over', sent > accepted() + 0.0005);
    byId('grn-transfer-empty').hidden = lines().length > 0;
    showError(sent > accepted() + 0.0005 ? `Total transfer quantity (${pbQty(sent)}) exceeds the accepted quantity (${pbQty(accepted())}).` : '');
  }

  function addLine(transfer = {}, focus = true) {
    if (!transfer.warehouseId && focus) {
      const chosen = lines().map(li => li.querySelector('[data-gt-point]').value).filter(Boolean);
      const free = points.filter(point => !chosen.includes(String(point.id)));
      if (!free.length || (free.length === 1 && lines().some(li => !li.querySelector('[data-gt-point]').value))) {
        showError('Every stock point is already on a transfer row.');
        return;
      }
    }
    const li = el('li', 'gt-row');
    const place = el('label', 'gt-field gt-field-point');
    const select = el('select', 'fp-input fp-select fp-select-list gt-select');   // the green list, not the browser's blue
    select.dataset.gtPoint = '';
    select.append(Object.assign(document.createElement('option'), { value: '', textContent: 'Select destination stock point...' }));
    for (const point of points) {
      select.append(Object.assign(document.createElement('option'), { value: String(point.id), textContent: point.type ? `${point.code} · ${point.name} (${point.type})` : `${point.code} · ${point.name}` }));
    }
    select.value = transfer.warehouseId ? String(transfer.warehouseId) : '';
    if (transfer.warehouseId && select.value !== String(transfer.warehouseId)) {     // a stock point no longer listed
      select.append(Object.assign(document.createElement('option'), { value: String(transfer.warehouseId), textContent: transfer.warehouseCode || `Stock point ${transfer.warehouseId}` }));
      select.value = String(transfer.warehouseId);
    }
    place.append(el('span', 'gt-label', 'Destination Stock Point *'), select);
    const amount = el('label', 'gt-field gt-field-qty');
    const qty = el('input', 'fp-input gt-qty');
    Object.assign(qty, { type: 'text', inputMode: 'decimal', autocomplete: 'off', placeholder: 'Qty', value: transfer.quantity ? pbQty(pbNum(transfer.quantity)) : '' });
    qty.dataset.gtQty = '';
    amount.append(el('span', 'gt-label', 'Transfer Qty *'), qty);
    const remove = el('button', 'pb-icon-btn pb-icon-danger gt-remove');
    Object.assign(remove, { type: 'button', title: 'Remove this stock transfer' });
    remove.dataset.gt = 'remove';
    remove.setAttribute('aria-label', 'Remove this stock transfer');
    remove.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6M10 11v6M14 11v6"></path></svg>';
    li.append(place, amount, remove);
    list.append(li);
    totals();                                // first: the other rows' stock points come off this row's list …
    if (focus) enterField(select);           // … then its list opens (the stock points still free only)
  }

  async function open(line) {
    if (pbNum(pbCell(line, 'acceptedQty').value) <= 0) {
      showToast('Nothing accepted on this line', 'Enter the accepted quantity first; only accepted stock can be transferred.', true);
      return;
    }
    row = line;
    const receiving = byId('grn-warehouse-id').value;
    points = (await loadLookup('warehouse')).filter(point => String(point.id) !== String(receiving));
    const code = pbCell(row, 'itemCode').value.trim();
    byId('grn-transfer-item').textContent = `${pbCell(row, 'itemName').value.trim() || 'Selected item'}${code ? ` (${code})` : ''}`;
    byId('grn-transfer-accepted').textContent = withUnit(accepted());
    list.replaceChildren();
    showError('');
    const saved = grnTransfers(row);
    if (saved.length) saved.forEach(transfer => addLine(transfer, false)); else addLine({}, false);
    totals();
    dialog.showModal();
    const first = list.querySelector('select');
    if (first && !first.value) enterField(first);   // nothing chosen yet: its list opens straight away
    else (first || dialog.querySelector('[data-gt="add"]')).focus();
  }

  function close() {
    dialog.close();
    row?.querySelector('[data-action="transfer"]')?.focus();
  }

  function save() {
    const receiving = byId('grn-warehouse-id').value;
    const seen = new Set();
    const transfers = [];
    let sent = 0;
    for (const li of lines()) {
      const select = li.querySelector('[data-gt-point]');
      const qty = li.querySelector('[data-gt-qty]');
      const point = select.value;
      const amount = qty.value.trim();
      if (!point && !amount) continue;                       // a blank row is left out
      const fail = (node, message) => { showError(message); node.focus(); return false; };
      if (!point) return fail(select, 'Select the destination stock point for every transfer row.');
      if (point === String(receiving)) return fail(select, 'The destination cannot be the stock point the goods are received into.');
      if (seen.has(point)) return fail(select, 'This stock point is chosen more than once. Put its quantity on one row.');
      if (!/^\d{1,11}(\.\d{1,3})?$/.test(amount) || !(pbNum(amount) > 0)) return fail(qty, 'Enter a transfer quantity more than 0 (up to 3 decimals).');
      seen.add(point);
      sent += pbNum(amount);
      transfers.push({ warehouseId: Number(point), quantity: pbQty(pbNum(amount)) });
    }
    if (sent > accepted() + 0.0005) {
      showError(`Total transfer quantity (${pbQty(sent)}) exceeds the accepted quantity (${pbQty(accepted())}).`);
      return false;
    }
    pbCell(row, 'transfers').value = transfers.length ? JSON.stringify(transfers) : '';
    syncGrnRow(row);
    form.page.record();
    close();
    return true;
  }

  // The reason boxes follow the column widths (window size, the page being shown).
  const sizeReasons = () => form.page.rowsOf('items').forEach(sizeGrnReason);
  window.addEventListener('resize', sizeReasons);
  new ResizeObserver(sizeReasons).observe(byId('grn-items'));
  byId('grn-items').addEventListener('click', event => {
    const button = event.target.closest('[data-action="transfer"]');
    if (button) open(button.closest('tr'));
  });
  dialog.addEventListener('click', event => {
    const action = event.target.closest('[data-gt]')?.dataset.gt;
    if (action === 'add') addLine();
    else if (action === 'save') save();
    else if (action === 'cancel') close();
    else if (action === 'remove') {
      const li = event.target.closest('li');
      const next = li.nextElementSibling || li.previousElementSibling;
      li.remove();
      totals();
      (next?.querySelector('select') || dialog.querySelector('[data-gt="add"]')).focus();
    }
  });
  dialog.addEventListener('input', totals);
  dialog.addEventListener('change', event => { if (event.target.matches('[data-gt-point]')) totals(); });
  // A stock point picked from its list with Enter: on to that row's quantity.
  dialog.addEventListener('menu-advance', event => {
    const qty = event.target.closest('li.gt-row')?.querySelector('[data-gt-qty]');
    if (qty) { qty.focus(); qty.select(); }
  });
  dialog.addEventListener('cancel', event => { event.preventDefault(); close(); });   // Esc
  // Keys: Shift+X adds a row; Enter goes stock point → quantity → the next row (Save after the last);
  // ↑ / ↓ move between the rows' same field; Ctrl+Enter saves.
  grnTransferKeys = event => {
    const target = event.target;
    if (!dialog.contains(target)) return;
    const li = target.closest('li.gt-row');
    if (event.shiftKey && !event.ctrlKey && !event.altKey && event.key.toLowerCase() === 'x') {
      event.preventDefault();
      event.stopPropagation();
      addLine();
      return;
    }
    if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
      event.preventDefault();
      event.stopPropagation();
      save();
      return;
    }
    if (event.key === 'Enter' && li && !target.closest('button')) {
      event.preventDefault();
      event.stopPropagation();
      if (target.matches('[data-gt-point]')) { li.querySelector('[data-gt-qty]').focus(); li.querySelector('[data-gt-qty]').select(); return; }
      const next = li.nextElementSibling;
      if (next) enterField(next.querySelector('[data-gt-point]'));   // the next row's stock point list opens, as on the forms
      else dialog.querySelector('[data-gt="save"]').focus();
      return;
    }
    // Arrows, as a table: ← / → along the line (Stock Point → Qty → Delete; in the Qty box only from its edge, so the
    // caret still moves in the number), ↑ / ↓ to the same field of the line above / below; past the last line ↓ goes
    // to + Add Stock Point, then the footer (Cancel, Save), where ← / → move along and ↑ goes back to the last line.
    const ARROWS = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'];
    if (!ARROWS.includes(event.key) || event.ctrlKey || event.altKey || event.metaKey || event.shiftKey) return;
    const go = node => { if (!node) return; event.preventDefault(); event.stopPropagation(); node.focus(); if (node.matches?.('[data-gt-qty]')) node.select(); };
    const add = dialog.querySelector('[data-gt="add"]');
    const footer = [...dialog.querySelectorAll('.gt-foot button')];
    const lastLine = () => lines().at(-1);
    if (li) {
      const cells = [li.querySelector('[data-gt-point]'), li.querySelector('[data-gt-qty]'), li.querySelector('[data-gt="remove"]')];
      const col = cells.findIndex(cell => cell === target || cell?.contains(target));
      if (col < 0) return;
      const qtyBox = cells[1];
      const caretAtEdge = edge => target !== qtyBox || qtyBox.selectionStart !== qtyBox.selectionEnd
        || (edge === 'start' ? qtyBox.selectionStart === 0 : qtyBox.selectionEnd === qtyBox.value.length);
      if (event.key === 'ArrowLeft') { if (col > 0 && caretAtEdge('start')) go(cells[col - 1]); else if (col > 0) return; else event.preventDefault(); return; }
      if (event.key === 'ArrowRight') { if (col < cells.length - 1 && caretAtEdge('end')) go(cells[col + 1]); else if (col < cells.length - 1) return; else event.preventDefault(); return; }
      const other = event.key === 'ArrowDown' ? li.nextElementSibling : li.previousElementSibling;
      if (other) { go([other.querySelector('[data-gt-point]'), other.querySelector('[data-gt-qty]'), other.querySelector('[data-gt="remove"]')][col]); return; }
      if (event.key === 'ArrowDown') { go(add.disabled ? footer.at(-1) : add); return; }
      event.preventDefault();                                   // the first line: ↑ stays
      return;
    }
    if (target === add) {
      if (event.key === 'ArrowUp') go(lastLine()?.querySelector('[data-gt-point]'));
      else if (event.key === 'ArrowDown' || event.key === 'ArrowRight') go(footer.at(-1));
      else event.preventDefault();
      return;
    }
    const at = footer.indexOf(target);
    if (at >= 0) {
      if (event.key === 'ArrowLeft') go(at > 0 ? footer[at - 1] : (add.disabled ? footer[0] : add));
      else if (event.key === 'ArrowRight') go(footer[Math.min(footer.length - 1, at + 1)]);
      else if (event.key === 'ArrowUp') go(add.disabled ? lastLine()?.querySelector('[data-gt-point]') : add);
      else event.preventDefault();
    }
  };
}

/* ---------- Purchase Book list pages  (#/purchase-book/purchase-request, quotation-request, purchase-order, grn) ----------
   The master list page (createMasterList) for each document: search, Filter (by document and date), View with the
   item lines, Edit (the form with the document filled in), PDF, Delete, Import and CSV export. Quick Menu ›
   Purchase Book opens these; Purchase Book › Create still opens the empty forms. */

const pbDate = value => (value ? shortDate(String(value).slice(0, 10)) : '');
// A Purchase Order's PDF dates: 18/11/2026.
const poSlashDate = value => { const [y, m, d] = String(value || '').slice(0, 10).split('-'); return y && m && d ? `${d}/${m}/${y}` : ''; };
// Formatted remarks as text (list rows and table cells), one line per paragraph or list item.
const remarksPlainText = html => {
  const box = document.createElement('div');
  box.append(remarksFragment(html));
  box.querySelectorAll('br').forEach(br => br.replaceWith('\n'));
  box.querySelectorAll('div, p, li').forEach(block => block.append('\n'));
  return box.textContent.replace(/\n{3,}/g, '\n\n').trim();
};
const pbAmount = value => (value === null || value === undefined || value === '' ? '' : pbMoney(pbNum(value)));

// The View popup for one document kind: an Items tab with the lines; Summary (PO, GRN) and Remarks & Print on General Information.
function purchaseItemsSection(kind) {
  return (record, note) => {
    if (!record) return { general: [], tabs: [{ label: 'Items', sections: [viewCard({ title: 'Items', wide: true }, viewNote(note))] }] };
    const item = line => [line.itemCode, lineItemNameCell(line), line.brandName];
    const mono = value => viewMono(value);
    const table = kind === 'grn'
      ? viewTable(['Code', 'Item', 'Brand', 'Rec. Qty', 'Acc. Qty', 'Rej. Qty', 'Rejection Reason', 'Unit', 'Expiry', 'Unit Cost', 'VAT %', 'Disc %', 'Transfers', 'Total'],
        record.items.map(l => [...item(l), mono(pbQty(pbNum(l.receivedQty))), mono(pbQty(pbNum(l.acceptedQty))), mono(pbQty(pbNum(l.rejectedQty))), l.rejectReason || '',
          l.unit, pbDate(l.expiryDate), mono(pbAmount(l.unitCost)), mono(pbQty(pbNum(l.vatRate))), mono(pbQty(pbNum(l.discountPct))),
          (l.transfers || []).map(t => `${t.warehouseCode || t.warehouseName}: ${pbQty(pbNum(t.quantity))}`).join(', '), mono(pbAmount(l.lineTotal))]), 'No items.')
      : kind === 'po'
        ? viewTable(['Code', 'Item', 'Qty', 'Unit', 'Price', 'VAT %', 'Disc %', 'Disc. Amt', 'Line Total'],
          record.items.map(l => [l.itemCode, lineItemNameCell(l), mono(pbQty(pbNum(l.quantity))), l.unit, l.foc ? 'FOC' : mono(pbAmount(l.price)),
            mono(pbQty(pbNum(l.vatRate))), mono(pbQty(pbNum(l.discountPct))), mono(pbAmount(l.discountAmount)), mono(pbAmount(l.lineTotal))]), 'No items.')
        : viewTable(['Code', 'Item', 'Brand', 'Quantity', 'Unit'],
          record.items.map(l => [...item(l), mono(pbQty(pbNum(l.quantity))), l.unit]), 'No items.');
    const general = [];
    if (kind === 'po' || kind === 'grn') {
      const money = { type: 'mono' };
      general.push(viewCard({ title: 'Summary' }, viewFields([
        { label: 'Prices', value: record.vatMode === 'exclude' ? 'VAT Enabled (added on top)' : 'VAT Included' },
        { label: 'Subtotal', value: pbAmount(record.subtotal), column: money }, { label: 'VAT', value: pbAmount(record.vatAmount), column: money },
        { label: 'Discount Amount', value: pbAmount(record.discountAmount), column: money }, { label: 'Shipping Price', value: pbAmount(record.shipping), column: money },
        { label: 'Grand Total', value: pbAmount(record.grandTotal), column: { type: 'code' } },
      ])));
    }
    general.push(viewCard({ title: 'Remarks & Print' }, viewFields([
      { label: 'Remarks', value: isRemarksHtml(record.remarks) ? remarksPlainText(record.remarks) : record.remarks, column: { type: 'wrap' } },
      { label: 'Signatory Slots', value: !record.includeSignatory ? 'Not included'
        : (record.signatories || []).length ? record.signatories.map(entry => [entry.name, entry.title].filter(Boolean).join(', ')).join(' · ') : 'Included' },
      { label: 'Seal', value: record.attachSeal ? 'Attached' : 'Not attached' },
    ])));
    return { general, tabs: [{ label: 'Items', count: record.items.length,
      sections: [viewCard({ title: 'Items', count: viewCount(record.items.length, 'item'), wide: true }, table)] }] };
  };
}

/* Import: one item line per sheet row. Rows with the same Document No become one document (a blank
   Document No makes the row a document of its own); the first row of a group gives the header fields. */
// Dates in any common layout (see sheetDate): 13/11/2026, 2026-11-13, 13 Nov 2026, Nov 13 2026, Excel numbers.
const readSheetDate = label => {
  const read = value => {
    if (!value) return '';
    const date = sheetDate(value);
    if (!date) throw new Error(`${label} "${value}" is not a date (use DD/MM/YYYY or YYYY-MM-DD)`);
    return date;
  };
  read.isDate = true;
  return read;
};
const readSheetNumber = (label, decimals = 3) => readNumberAs(label, n => n >= 0 && n < 1e11, 'must be a number of 0 or more', decimals);
const readVatMode = value => {
  if (!value) return '';
  if (/^(incl|inc\b|yes|y$|with)/i.test(value)) return 'include';
  if (/^(excl|exc\b|no|n$|without|plus)/i.test(value)) return 'exclude';
  throw new Error(`VAT "${value}" must be Include or Exclude`);
};

const PB_IMPORT_GROUP = { key: 'docNo', label: 'Document No', headers: ['document', 'document number', 'doc no', 'group', 'sl no'] };
const PB_IMPORT_ITEM = [
  { key: 'itemCode', label: 'Item Code', headers: ['code', 'sku', 'part no'] },
  { key: 'itemName', label: 'Item Name', headers: ['item', 'description', 'item description', 'product'] },
  { key: 'brand', label: 'Brand', headers: ['make', 'brand name'] },
];
const pbImportQty = { key: 'quantity', label: 'Quantity', headers: ['qty'], read: readSheetNumber('Quantity') };
const pbImportUnit = { key: 'unit', label: 'Unit', headers: ['uom', 'unit of measure'] };
const pbImportRemarks = { key: 'remarks', label: 'Remarks', headers: ['notes', 'comments'] };

function groupSheetDocuments(rows) {
  const groups = new Map();
  for (const row of rows) {
    const key = row.docNo ? `doc:${row.docNo.toLowerCase()}` : `line:${row.sheetLine}`;
    if (!groups.has(key)) groups.set(key, { ...row, code: '', name: row.docNo || row.itemName, lines: [] });
    groups.get(key).lines.push(row);
  }
  return [...groups.values()];
}

// Looks a master record up by name or code; a typed item that is not in the master stays free text.
async function optionalLookupId(kind, text) {
  if (!text) return null;
  try { return await importLookupId(kind, text); } catch { return null; }
}
async function importItemLine(row) {
  const itemId = await optionalLookupId('item', row.itemName) ?? await optionalLookupId('itemcode', row.itemCode);
  return {
    itemId, itemCode: row.itemCode, itemName: row.itemName, brandId: await optionalLookupId('brand', row.brand), brandName: row.brand,
    uomId: await optionalLookupId('uom', row.unit), unit: row.unit,
  };
}

/* The Purchase Book Filter (#pb-filter) of each list: its filters (rail), the No. column's prefix, what the search
   finds besides the number, the two lines of a document's Details and who raised it (Employee). */
const pbfItems = row => `${row.itemCount || 0} item${Number(row.itemCount) === 1 ? '' : 's'}`;
// The Supplier filter (RFQ, PO, GRN): the document's supplier(s) as { key, code, name }.
const pbfSupplierOf = row => (row.supplierId || row.supplierName
  ? [{ key: row.supplierId ? `sup:${row.supplierId}` : `name:${String(row.supplierName).trim().toLowerCase()}`, code: row.supplierCode || '', name: row.supplierName || '', kind: 'sup' }] : []);
// Party (Trade Management, Transaction Entry): the document's customer as { key, code, name }.
const pbfCustomerOf = row => (row.customerId || row.customerName
  ? [{ key: row.customerId ? `cus:${row.customerId}` : `name:${String(row.customerName).trim().toLowerCase()}`, code: row.customerCode || '', name: row.customerName || '', kind: 'cus' }] : []);
// Purchase Book (RFQ, PO, GRN), Trade Management and Transaction Entry: the All countries dropdown by the search
// (countryPick): the country of the document's supplier / customer. Trade Management and Transaction Entry also have
// Party on the rail, with Debtors (customers) and Creditors (suppliers) (partyKinds; partyNoun: the kind it opens on).
const PB_DOC_FILTERS = {
  pr: {
    tabs: ['all', 'date', 'qty', 'emp'], short: 'PR', searchHint: 'type or requester',
    details: row => [`${row.purchaseType} · ${pbfItems(row)}`, `Requested by ${row.requestedBy || '—'}${row.referenceNo ? ` · Ref ${row.referenceNo}` : ''}`],
    employee: { key: 'requestedBy', label: 'Requested By' },
  },
  rfq: {
    // As the Purchase Request's filter: Employee is the Requested By (of the PR this request came from).
    tabs: ['all', 'date', 'party', 'qty', 'emp'], short: 'RFQ', searchHint: 'PR, supplier or requester', countryPick: true,
    parties: row => (row.suppliers || []).map(s => ({ key: `sup:${s.id}`, code: s.code, name: s.name })),   // every supplier it went to
    details: row => [`${pbfItems(row)} · ${row.supplierCount} supplier${row.supplierCount === 1 ? '' : 's'}${row.purchaseRequestCode ? ` · ${row.purchaseRequestCode}` : ''}`,
      `Requested by ${row.requestedBy || '—'} · ${row.name}`],
    employee: { key: 'requestedBy', label: 'Requested By' },
  },
  po: {
    tabs: ['all', 'date', 'party', 'vat', 'value', 'disc', 'qty', 'emp'], short: 'PO', searchHint: 'supplier or reference', countryPick: true,
    parties: pbfSupplierOf,
    details: row => [row.supplierName || 'No supplier', [pbfItems(row), row.reference, row.salesman && `Created by ${row.salesman}`].filter(Boolean).join(' · ')],
    employee: { key: 'salesman', label: 'Created By' },
  },
  grn: {
    tabs: ['all', 'date', 'party', 'vat', 'value', 'disc', 'qty'], short: 'GRN', searchHint: 'supplier or PO', countryPick: true,
    parties: pbfSupplierOf,
    details: row => [row.supplierName || 'No supplier', [pbfItems(row), row.poNumber ? `PO ${row.poNumber}` : 'No PO', row.warehouseName].filter(Boolean).join(' · ')],
  },
  // Trade Management › Quotation (sales): the Quotation Request's filter, VAT, Value and Disc %; Employee is its Created By.
  qt: {
    // VAT: In when a line has a VAT % above 0 (the quotation has no VAT switch, only each line's VAT %).
    tabs: ['all', 'date', 'party', 'vat', 'value', 'disc', 'qty', 'emp'], short: 'Quotation', searchHint: 'customer, reference or creator',
    parties: pbfCustomerOf, partyTab: 'Party', partyNoun: 'Customer', partyKinds: true, countryPick: true,
    details: row => [row.customerName || 'No customer', [pbfItems(row), row.referenceNo && `Ref ${row.referenceNo}`, row.salesman && `Created by ${row.salesman}`].filter(Boolean).join(' · ')],
    employee: { key: 'salesman', label: 'Created By' },
  },
  // Trade Management › Sales Order: the Quotation's filter without VAT. Employee: the Created By of its quotation.
  so: {
    tabs: ['all', 'date', 'party', 'value', 'disc', 'qty', 'emp'], short: 'SO', searchHint: 'customer, quotation or creator',
    parties: pbfCustomerOf, partyTab: 'Party', partyNoun: 'Customer', partyKinds: true, countryPick: true,
    details: row => [row.customerName || 'No customer', [pbfItems(row), row.quotationCode && `Quotation ${row.quotationCode}`, row.createdBy && `Created by ${row.createdBy}`].filter(Boolean).join(' · ')],
    employee: { key: 'createdBy', label: 'Created By' },
  },
  // Trade Management › Delivery Note: the Quotation's filter. Employee is the note's Created By (salesman).
  dn: {
    tabs: ['all', 'date', 'party', 'vat', 'value', 'disc', 'qty', 'emp'], short: 'DN', searchHint: 'customer, reference or creator',
    parties: pbfCustomerOf, partyTab: 'Party', partyNoun: 'Customer', partyKinds: true, countryPick: true,
    details: row => [row.customerName || 'No customer', [pbfItems(row), row.referenceNo && `Ref ${row.referenceNo}`, row.salesman && `Created by ${row.salesman}`].filter(Boolean).join(' · ')],
    employee: { key: 'salesman', label: 'Created By' },
  },
  // Transaction Entry › Tax Invoice: the Delivery Note's filter. Employee: the Created By of the document it came from.
  ti: {
    tabs: ['all', 'date', 'party', 'vat', 'value', 'disc', 'qty', 'emp'], short: 'Invoice', searchHint: 'customer, reference or creator',
    parties: pbfCustomerOf, partyTab: 'Party', partyNoun: 'Customer', partyKinds: true, countryPick: true,
    details: row => [row.customerName || 'No customer', [pbfItems(row), row.referenceNo && `Ref ${row.referenceNo}`, row.createdBy && `Created by ${row.createdBy}`].filter(Boolean).join(' · ')],
    employee: { key: 'createdBy', label: 'Created By' },
  },
  // Transaction Entry › Purchase Entry: the Tax Invoice's filter without VAT and Disc %. Employee: the Created By of its
  // purchase order (or its GRN's).
  pe: {
    tabs: ['all', 'date', 'party', 'value', 'qty', 'emp'], short: 'Purchase', searchHint: 'supplier, invoice, PO / GRN or creator',
    parties: pbfSupplierOf, partyTab: 'Party', partyNoun: 'Supplier', partyKinds: true, countryPick: true,
    details: row => [row.supplierName || 'No supplier', [pbfItems(row), row.supplierInvoiceNo && `Inv ${row.supplierInvoiceNo}`, row.reference,
      row.createdBy && `Created by ${row.createdBy}`].filter(Boolean).join(' · ')],
    employee: { key: 'createdBy', label: 'Created By' },
  },
  // Transaction Entry › Sales Entry: the Purchase Entry's filter. Employee: the Created By of its tax invoice (or delivery note).
  se: {
    tabs: ['all', 'date', 'party', 'value', 'qty', 'emp'], short: 'Sales', searchHint: 'customer, ref no, invoice / DN or creator',
    parties: pbfCustomerOf, partyTab: 'Party', partyNoun: 'Customer', partyKinds: true, countryPick: true,
    details: row => [row.customerName || 'No customer', [pbfItems(row), row.customerRefNo && `Ref ${row.customerRefNo}`, row.reference,
      row.createdBy && `Created by ${row.createdBy}`].filter(Boolean).join(' · ')],
    employee: { key: 'createdBy', label: 'Created By' },
  },
};

function purchaseList(spec) {
  return createMasterList({
    key: spec.key, route: spec.route, newRoute: `#/${spec.route}/new`, noun: spec.noun, nouns: spec.nouns,
    api: spec.api, lookups: spec.lookups || [], formPage: spec.key, edit: id => spec.form.page.edit(id),
    dateOf: spec.dateOf, pdf: row => printPurchaseDocument(spec, row.id), related: purchaseItemsSection(spec.kind), viewTitle: () => spec.noun,
    noView: true,      // only the Masters lists have View; documents: Edit, PDF, Delete (Enter on a row edits it)
    ...spec.listHooks,  // the Return & Replacement and Supply lists: their own Filter and the Export under the list
    docFilter: PB_DOC_FILTERS[spec.key],
    columns: spec.columns, fromApi: spec.fromApi, sample: {},
    importColumns: [PB_IMPORT_GROUP, ...spec.importColumns], importKey: 'itemName', importSamples: spec.importSamples,
    importHint: 'One item per row. Rows with the same Document No become one document; a blank Document No makes a document of one item.',
    // A Document No that is already a document's number (PR000018) is a duplicate; other rows add new documents.
    matchRow: (rows, group) => (group.docNo ? rows.find(existing => sameText(existing.code, group.docNo)) : undefined),
    groupRows: groupSheetDocuments,
    async toPayload(group) {
      const items = [];
      for (const line of group.lines) items.push({ ...await importItemLine(line), ...spec.importLine(line) });
      return { ...await spec.importHeader(group), remarks: group.remarks, items };
    },
  });
}

