/* ---------- The company letterhead behind every printed page ----------
   The letterhead given on Create a Company (uploaded as a PNG / JPG / PDF, or generated) is printed as the whole
   A4 page, on every page, and the document is laid out between its header and its footer, inside its side
   margins. Where those are is read from the letterhead itself: the rows of ink at the top (logo, contact details,
   rules) up to the first wide blank band, the same at the bottom, and how far in from the edges the ink starts.
   A PDF letterhead's first page is drawn to an image with pdf.js (vendor/pdfjs, loaded only then).
   Resolves to { src, top, bottom, side } (fractions of the page height / width), or null without a letterhead. */
let letterheadPromise = null;
function companyLetterhead() {
  letterheadPromise ||= loadLetterhead().catch(error => { console.warn('Letterhead not used:', error); return null; });
  return letterheadPromise;
}

async function loadLetterhead() {
  const profile = await companyProfile();
  const name = profile?.files?.letterhead;
  if (!name) return null;
  const url = 'api/company-profile.php?file=letterhead';
  // An image is downloaded once and kept in memory: the server sends it uncached, so pointing every preview at
  // the API address would download it again (a blank page until it arrives).
  let source;
  if (/\.pdf$/i.test(name)) source = await pdfFirstPage(url);
  else {
    const response = await fetch(url, { credentials: 'same-origin' });
    if (!response.ok) throw new Error('the letterhead image could not be loaded');
    source = await loadPrintImage(URL.createObjectURL(await response.blob()));
  }
  const width = source.naturalWidth || source.width, height = source.naturalHeight || source.height;
  const bands = letterheadBands(source, width, height);
  const src = source instanceof HTMLCanvasElement
    ? URL.createObjectURL(await new Promise(resolve => source.toBlob(resolve, 'image/png')))
    : source.src;
  return { src, ...bands };
}

/* A Purchase Order of a company without an uploaded letterhead: the "Blue bars" design (letterheads.js, the one the
   Create a Company page generates) drawn from the company's details: logo or name on the left, e-mail and phone,
   CR / address / VAT on the right, the bars under the header and the footer with the website. Blank details are
   left out (a company without a profile shows its name only). */
let drawnLetterheadPromise = null;
function drawnLetterhead(fallbackName) {
  drawnLetterheadPromise ||= (async () => {
    if (typeof LETTERHEADS === 'undefined' || !LETTERHEADS.length) return null;
    const p = (await companyProfile()) || {};
    const logo = p.files?.logo ? await loadPrintImage('api/company-profile.php?file=logo').catch(() => null) : null;
    try { await document.fonts?.ready; } catch { /* the default font then */ }
    const s = value => String(value ?? '').trim();
    const data = {
      name: s(p.companyName) || s(fallbackName), businessType: s(p.businessType) === 'Others' ? '' : s(p.businessType), logo,
      email: s(p.email), phone: s(p.phone), website: s(p.website), cr: s(p.crNumber), vat: s(p.vatRegNumber),
      building: s(p.building), street: s(p.street), area: s(p.area), city: s(p.city), country: s(p.country),
      poBox: s(p.poBox), postalCode: s(p.postalCode), colors: lhPalette(logo),
    };
    const canvas = Object.assign(document.createElement('canvas'), { width: LETTERHEAD_WIDTH, height: LETTERHEAD_HEIGHT });
    const ctx = canvas.getContext('2d');
    try { LETTERHEADS[0].draw(ctx, data); } catch { ctx.clearRect(0, 0, canvas.width, canvas.height); LETTERHEADS[0].draw(ctx, { ...data, logo: null }); }
    const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
    return blob ? { src: URL.createObjectURL(blob), ...letterheadBands(canvas, canvas.width, canvas.height) } : null;
  })().catch(error => { console.warn('Drawn letterhead not used:', error); return null; });
  return drawnLetterheadPromise;
}

function loadPrintImage(url) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('the letterhead image could not be loaded'));
    img.src = url;
  });
}

// The first page of a PDF as a canvas, A4 width at 200 dpi.
async function pdfFirstPage(url) {
  const pdfjs = await import('./vendor/pdfjs/pdf.min.js');
  pdfjs.GlobalWorkerOptions.workerSrc = new URL('vendor/pdfjs/pdf.worker.min.js', location.href).href;
  const response = await fetch(url, { credentials: 'same-origin' });
  if (!response.ok) throw new Error('the letterhead PDF could not be loaded');
  const pdf = await pdfjs.getDocument({ data: await response.arrayBuffer(), isEvalSupported: false }).promise;
  try {
    const page = await pdf.getPage(1);
    const scale = 1654 / page.getViewport({ scale: 1 }).width;
    const viewport = page.getViewport({ scale });
    const canvas = Object.assign(document.createElement('canvas'), { width: Math.round(viewport.width), height: Math.round(viewport.height) });
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    await page.render({ canvasContext: ctx, viewport }).promise;
    return canvas;
  } finally {
    pdf.destroy();
  }
}

/* Where the letterhead's header ends and its footer starts, and its side margin, as fractions of the page.
   Ink: a pixel clearly darker than the paper (a faint watermark behind the text area does not count). The header
   is the ink in the top 45 % up to the first blank band of 4 % of the page; the footer the same from the bottom
   in the lowest 35 %. A gap is kept after the header and before the footer. */
function letterheadBands(source, width, height) {
  const W = 240, H = Math.max(1, Math.round(W * height / width));
  const canvas = Object.assign(document.createElement('canvas'), { width: W, height: H });
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.fillStyle = '#fff';
  ctx.fillRect(0, 0, W, H);
  ctx.drawImage(source, 0, 0, W, H);
  const data = ctx.getImageData(0, 0, W, H).data;
  const inkAt = (x, y) => { const i = (y * W + x) * 4; return Math.min(data[i], data[i + 1], data[i + 2]) < 200; };
  const rowInk = y => { let n = 0; for (let x = 0; x < W; x++) if (inkAt(x, y)) n++; return n > 1; };
  const gap = Math.round(H * 0.04);
  let headerEnd = 0;
  for (let y = 0, last = -1; y < H * 0.45; y++) {
    if (rowInk(y)) last = y;
    else if (last >= 0 && y - last > gap) break;
    headerEnd = last + 1;
  }
  let footerStart = H;
  for (let y = H - 1, last = -1; y > H * 0.65; y--) {
    if (rowInk(y)) last = y;
    else if (last >= 0 && last - y > gap) break;
    footerStart = last >= 0 ? last : H;
  }
  // Side margin: where the header's and footer's ink starts from the left and right edges.
  let left = W, right = W;
  for (const [from, to] of [[0, headerEnd], [footerStart, H]]) {
    for (let y = from; y < to; y++) {
      for (let x = 0; x < W; x++) if (inkAt(x, y)) { left = Math.min(left, x); right = Math.min(right, W - 1 - x); }
    }
  }
  const side = Math.min(0.1, Math.max(0.04, Math.min(left, right) / W));
  return {
    top: headerEnd ? Math.min(0.45, headerEnd / H + 0.025) : 0.05,
    bottom: footerStart < H ? Math.min(0.35, (H - footerStart) / H + 0.02) : 0.05,
    side,
  };
}

/* ---------- The document preview page and its PDF ----------
   A Purchase Book document opens on a preview page (#pb-preview): a dark bar with Print / Export PDF and Back
   (Esc / B), and the A4 page under it, on the company letterhead when there is one. A new Purchase Request opens
   here as soon as it is saved; the lists' PDF buttons open it too. Print / Export PDF (or Ctrl+P) lays the same
   page out in #pb-print-sheet and hands it to the browser's print dialog ("Save as PDF").
   Laid out as the procurement document design: the title, the Buyer (this company) beside the other party, the
   details in a grid, the item table, Remarks & Notes beside the totals, then the signatory slots and the seal.
   Ticked "Include Signatory Slots" prints the signatory slots (name and title each); "Attach Seal" prints the company seal. */
const PB_TITLES = { pr: 'Purchase Request', rfq: 'Request for Quotation', po: 'Purchase Order', grn: 'Goods Received Note',
  qt: 'Quotation', so: 'Sales Order', dn: 'Delivery Note', ti: 'Tax Invoice', pe: 'Purchase Invoice', se: 'Sales Invoice', sr: 'Sales Return',
  rp: 'Sales Replacement', prt: 'Purchase Return', prp: 'Purchase Replacement',
  sa: 'Stock Adjustment', st: 'Stock Transfer', rsv: 'Stock Reservation' };
const SALES_KEYS = ['qt', 'so', 'dn', 'ti', 'se', 'sr', 'rp'];       // documents to a customer (Trade Management, Sales Entry)
const SUPPLY_KEYS = ['sa', 'st', 'rsv'];                  // Supply Management documents (company and stock points, no supplier)
let companyProfilePromise = null;
function companyProfile() {
  companyProfilePromise ||= apiRequest('api/company-profile.php').catch(() => null);
  return companyProfilePromise;
}

// Lays the document out in `sheet` (the preview page or the print sheet); resolves once its images have loaded.
// supplier may be a promise; stillWanted() false (another supplier or document was picked meanwhile) leaves the sheet alone.
/* A Purchase Order's PDF is in the supplier's currency, a Quotation's, Delivery Note's and Tax Invoice's in the customer's: the document is priced in
   OMR (PRICES_IN_OMR) and its prices, line totals and totals are converted at the fixed SO_RATES_TO_OMR, with no OMR
   figures printed. The form's summary keeps the OMR Grand Total. A document in OMR, or in a currency without a rate,
   prints as it is (in OMR). */
const PARTY_CURRENCY_PDF = ['po', 'qt', 'dn', 'ti'];
function inPartyCurrency(spec, doc) {
  const currency = String(doc.currency || 'OMR').toUpperCase();
  const rate = SO_RATES_TO_OMR[currency];
  if (!PARTY_CURRENCY_PDF.includes(spec.key) || currency === 'OMR' || !rate) return doc;
  const to = value => pbNum(value) / rate;
  return {
    ...doc, inPartyCurrency: true,
    subtotal: to(doc.subtotal), vatAmount: to(doc.vatAmount), discountAmount: to(doc.discountAmount), shipping: to(doc.shipping),
    roundOff: to(doc.roundOff), advancePayment: to(doc.advancePayment), grandTotal: to(doc.grandTotal),
    items: (doc.items || []).map(l => ({ ...l, price: to(l.price), discountAmount: to(l.discountAmount), lineTotal: to(l.lineTotal) })),
  };
}

/* The Sales Order PDF (not a Proforma Invoice): the order's costing sheet. REF NO and DATE under the title; Supplier
   Details (the order's supplier, "Multiple Suppliers", or the supplier this copy is for) beside Buyer / Customer
   Details (contact and phone when given); Ref Quotation / PO · Payment Terms · Currency / Supplier Currency; one line
   per item with its selling price and total (OMR), buying unit and total in the supplier's currency (AED: 10% transport
   included) and profit %; Remarks & Notes beside the Total Selling Price, Item Landing Cost, any other costs and the
   Total Profit. Buying costs are kept in OMR (soRefreshCosts): the supplier currency figures are converted at the
   fixed SO_RATES_TO_OMR. copy: a single supplier's copy of a multi-supplier order (the order-wide costs left off). */
function soCostingParts(doc, { picked = null, customer = null } = {}) {
  const multi = doc.supplierMode === 'multi';
  const allSuppliers = multi && !picked;
  const lineCurrency = line => String((multi ? line.supplierCurrency : doc.supplierCurrency) || 'OMR').toUpperCase();
  const landingOf = currency => (currency === 'AED' ? 1.1 : 1);
  const toCurrency = (omr, currency) => omr / (SO_RATES_TO_OMR[currency] || 1);
  // 1,108.800 · 173.2632: thousands separated, three decimals at least and a fourth when it is not 0.
  const money = value => (Number.isFinite(value) ? value : 0).toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 4 });
  const money3 = value => (Number.isFinite(value) ? value : 0).toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });   // 6,600.000
  const text = value => String(value ?? '').trim();
  const items = doc.items || [];
  const currencies = [...new Set(items.map(lineCurrency))];
  const oneCurrency = !allSuppliers || currencies.length === 1 ? (currencies[0] || lineCurrency({})) : '';
  // The Quotation Request's layout (ps-docbox, ps-table, ps-bottom) with the Sales Order's own details.
  const parts = [el('h1', 'ps-title', 'Sales Order')];

  // Supplier | Buyer.
  const party = (label, name, lines = []) => {
    const box = el('div', 'ps-party');
    box.append(el('div', 'ps-label', label));
    if (name) box.append(el('div', 'ps-party-name', name));
    const list = el('div', 'ps-party-lines');
    for (const line of lines) {
      if (Array.isArray(line)) {
        const row = el('div', 'ps-party-line');
        row.append(el('span', 'ps-party-key', line[0]), el('span', '', `: ${line[1]}`));
        list.append(row);
      } else {
        list.append(el('div', 'ps-party-text', line));
      }
    }
    box.append(list);
    return box;
  };
  const supplierName = picked?.name || doc.supplierName;
  const supplierBox = allSuppliers
    ? party('Supplier Details', 'Multiple Suppliers', ['Supplier details specified per line item in the table below'])
    : party('Supplier Details', text(supplierName) ? `M/s. ${text(supplierName)}` : '—');
  const buyerLines = [text(doc.contactName) && ['Contact', text(doc.contactName)], text(doc.contactNumber) && ['Phone', text(doc.contactNumber)]].filter(Boolean);
  const buyerName = text(customer?.name || doc.customerName);
  const parties = el('div', 'ps-parties');
  parties.append(supplierBox, party('Buyer / Customer Details', buyerName ? `M/s. ${buyerName}` : '—', buyerLines));

  // Ref No · Date · Ref Quotation / PO · Payment Terms · Currency (/ Supplier Currency).
  const refs = [text(doc.quotationCode), text(doc.customerPo)].filter(Boolean).join(' / ') || 'N/A';
  const payment = [text(doc.paymentMode), doc.paymentMode === 'Credit' && text(doc.creditPeriod)].filter(Boolean).join(' · ') || 'As agreed';
  const base = 'OMR';
  const showSupplierCurrency = oneCurrency && oneCurrency !== base;
  const meta = [['Ref No', text(doc.code) || '—'], ['Date', String(doc.orderDate || doc.date || '').slice(0, 10) || '—'], ['Ref Quotation / PO', refs, 'ref'],
    ['Payment Terms', payment], [showSupplierCurrency ? 'Currency / Supplier Currency' : 'Currency', showSupplierCurrency ? `${base} / ${oneCurrency}` : base]];
  const metaGrid = el('dl', 'ps-meta');
  metaGrid.style.setProperty('--ps-cols', String(meta.length));
  meta.forEach(([label, value, kind], i) => {
    const item = el('div', `ps-meta-item${i === meta.length - 1 ? ' is-row-end' : ''}${kind === 'ref' ? ' is-ref' : ''}`);
    item.append(el('dt', '', label), el('dd', '', value));
    metaGrid.append(item);
  });
  const box = el('div', 'ps-docbox');
  box.append(parties, metaGrid);
  parts.push(box);
  parts.push(el('div', 'ps-section-title', 'Ordered Items'));   // the table apart from the box, as the Quotation Request's

  // The lines.
  const unitTag = currency => el('div', 'pso-unit', `(${currency})`);
  const heads = [['SL', 'sno'], ['Description', 'name pso-c-desc'], ...(allSuppliers ? [['Supplier', 'supplier pso-c-supplier']] : []), ['Qty', 'num pso-c-fit'], ['Unit', 'center pso-c-fit'],
    ['Selling Price', 'num pso-c-fit', base], ['Selling Total', 'num pso-c-fit', base], ['Buying Unit', 'num pso-c-fit', oneCurrency], ['Buying Total', 'num pso-c-fit', oneCurrency], ['Profit %', 'num pso-c-fit']];
  const cls = kind => kind.split(' ').map(part => (part.startsWith('pso-') ? part : `ps-c-${part}`)).join(' ');
  const table = el('table', `ps-table pso-table${allSuppliers ? ' pso-has-supplier' : ''}`);
  const thead = el('thead');
  const headRow = el('tr');
  for (const [label, kind, currency] of heads) {
    const th = el('th', cls(kind), label);
    if (currency) th.append(unitTag(currency));
    headRow.append(th);
  }
  thead.append(headRow);
  const tbody = el('tbody');
  let landing = 0;
  items.forEach((line, i) => {
    const currency = lineCurrency(line);
    const factor = landingOf(currency);
    const qty = pbNum(line.quantity);
    const price = pbNum(line.price);
    const buyingOmr = pbNum(line.buyingCost);
    landing += qty * buyingOmr * factor;
    // Kept in OMR to 3 decimals: 7 AED is saved as 0.739, so the unit is shown to 3 decimals again (7.000, not 7.0047).
    const buyingUnit = Math.round(toCurrency(buyingOmr, currency) * 1000) / 1000;
    const profit = price > 0 ? (price - buyingOmr * factor) / price * 100 : 0;
    const tr = el('tr');
    const desc = el('td', cls('name pso-c-desc'));
    if (line.itemNameHtml) desc.append(remarksFragment(line.itemNameHtml)); else desc.textContent = text(line.itemName);
    if (text(line.brandName)) desc.append(el('div', 'ps-make', `Make: ${text(line.brandName)}`));
    if (text(line.deliveryTerm)) desc.append(el('div', 'ps-make', `Delivery: ${text(line.deliveryTerm)}`));
    const numCell = (value, extra = [], strong = false) => { const td = el('td', cls(strong ? 'num total' : 'num')); td.append(el('div', '', value), ...extra); return td; };
    tr.append(el('td', cls('sno'), String(i + 1)), desc,
      ...(allSuppliers ? [el('td', cls('supplier pso-c-supplier'), text(line.supplierName) || '—')] : []),
      el('td', cls('num'), pbQty(qty)), el('td', cls('center'), text(line.unit)),
      numCell(money3(price)), numCell(money3(pbNum(line.lineTotal)), [], true),
      numCell(money(buyingUnit), [unitTag(currency)]),
      numCell(money(qty * buyingUnit * factor), [unitTag(currency), ...(factor > 1 ? [el('div', 'pso-trans', '(Trans Incl.)')] : [])]),
      el('td', `${cls('num')} pso-profit${profit < 0 ? ' is-loss' : ''}`, `${profit.toFixed(2)}%`));
    tbody.append(tr);
  });
  table.append(thead, tbody);
  parts.push(table);

  // Remarks & Notes | the totals and the profit.
  const bottom = el('div', 'ps-bottom');
  const side = el('div', 'ps-side');
  const remarks = el('div', 'ps-remarks');
  remarks.append(el('div', 'ps-label', 'Remarks & Notes'));
  if (text(doc.remarks)) {
    if (isRemarksHtml(doc.remarks)) { const body = el('div', 'ps-remarks-body'); body.append(remarksFragment(doc.remarks)); remarks.append(body); }
    else remarks.append(el('div', 'ps-remarks-text', doc.remarks));
  } else {
    remarks.append(el('div', 'ps-remarks-text pso-empty', 'No additional remarks provided.'));
  }
  side.append(remarks);
  const subtotal = pbNum(doc.subtotal);
  // The order-wide costs (left off a single supplier's copy, as its discount and charges are).
  const costs = picked ? [] : [['Discount', pbNum(doc.discountAmount)], ['Custom Duty', pbNum(doc.customDuty)],
    ['Transportation Charge', pbNum(doc.shipping)], ['Business Promotion', pbNum(doc.businessPromotion)]].filter(([, value]) => value);
  const profit = subtotal - landing - costs.reduce((sum, [, value]) => sum + value, 0);
  const totals = el('dl', 'ps-totals');
  const totalRow = (label, value, className = '') => { const row = el('div', className); row.append(el('dt', '', label), el('dd', '', value)); return row; };
  totals.append(totalRow('Total Selling Price (Subtotal)', `${base} ${money3(subtotal)}`), totalRow('Item Landing Cost', `${base} ${money(landing)}`),
    ...costs.map(([label, value]) => totalRow(label, `${base} ${money(value)}`)),
    totalRow(`Total ${profit < 0 ? 'Loss' : 'Profit'} (${base})`, `${money(profit)} (${(subtotal > 0 ? profit / subtotal * 100 : 0).toFixed(2)}%)`,
      `ps-total-grand pso-profit-row${profit < 0 ? ' is-loss' : ''}`));
  bottom.append(side, totals);
  parts.push(bottom);
  return parts;
}

async function fillPurchaseSheet(sheet, spec, doc, { screen = false, supplier: chosenSupplier = null, hidePrices = false, stillWanted = () => true } = {}) {
  doc = inPartyCurrency(spec, doc);
  // The GRN: the procurement document design (letterhead, supplier details, totals box). The Purchase Order keeps
  // Nathaneal's design.
  const procurement = spec.key === 'grn';
  const isSales = SALES_KEYS.includes(spec.key);
  // Everything the page needs is asked for at once (not one after another), so it shows without a wait.
  const [profile, uploadedLetterhead, ownSupplier, picked, customer] = await Promise.all([companyProfile(), companyLetterhead(),
    (procurement || ['po', 'pe', 'prt', 'prp'].includes(spec.key)) && doc.supplierId ? pbSupplier(String(doc.supplierId)).catch(() => null) : null,
    chosenSupplier,
    isSales && doc.customerId ? pbCustomer(String(doc.customerId)).catch(() => null) : null]);
  if (!stillWanted()) return;
  // The supplier this copy is addressed to: the one chosen on a Quotation Request, a Purchase Order's / GRN's own.
  const supplier = picked || ownSupplier;
  // A GRN always prints on a letterhead: the uploaded one, else the drawn "Blue bars" design.
  const letterhead = uploadedLetterhead
    || (procurement || spec.key === 'po' ? await drawnLetterhead(byId('app')?.querySelector('.brand-name')?.textContent) : null);   // GRN and PO
  if (!stillWanted()) return;
  // GRN Inspection Mode: no Rate / VAT / Amount and no money totals, only the number of items.
  const noPrices = spec.key === 'grn' && hidePrices;
  const proforma = spec.key === 'so' && doc.documentTitle === 'Proforma Invoice';
  const title = proforma ? 'Proforma Invoice' : PB_TITLES[spec.key];
  const text = value => String(value ?? '').trim() || '—';
  const cell = (tag, className, value) => el(tag, className, text(value));
  // Only what is filled is printed: a detail, party line or box left blank on the document is left off the page.
  const filled = value => String(value ?? '').trim() !== '';
  const filledPair = ([, value]) => filled(value);
  // Trade Management documents go to a customer: `customer` has its details from the Customer master (the name
  // kept on the document otherwise).
  const buyer = () => ({
    label: 'Buyer', name: customer?.name || doc.customerName,
    lines: [customer?.address, ['Country', customer?.country], ['VATIN', customer?.taxRegNo], ['E-mail', customer?.email],
      ['Contact Person', doc.contactName], ['Contact Number', doc.contactNumber]],
  });
  // The supplier's details from the Supplier master, as the Buyer's: address, country, VATIN, e-mail, contact
  // (the document's own contact first). Blank ones are left out (party() skips them).
  const supplierLines = (s, contactName = '', contactNumber = '') => {
    const contact = (s?.contacts || []).find(c => filled(c.name) || filled(c.email) || filled(c.number)) || {};
    return [[s?.address, s?.city, filled(s?.zipCode) ? `PC: ${s.zipCode}` : ''].filter(filled).join(', '),   // no postal code: nothing (not "false")
      ['Country', s?.country], ['VATIN', s?.taxRegNo], ['E-mail', s?.email || contact.email],
      ['Contact Person', contactName || s?.contactPerson || contact.name],
      ['Contact Number', contactNumber || s?.phone || s?.telephone || contact.number]];
  };
  const terms = [['Currency', doc.currency], ['Delivery Location', doc.deliveryLocation], ['Payment Terms', doc.paymentMode],
    ...(doc.creditPeriod ? [['Credit Period', doc.creditPeriod]] : [])];
  // The other party (right of this company) and the details grid, for each kind.
  const layout = {
    pr: () => ({
      party: { label: 'Requested By', name: doc.requestedBy, lines: [['Purchase Type', doc.purchaseType]] },
      meta: [['PR No', doc.code], ['Requested Date', pbDate(doc.requestedDate)], ['Required By', pbDate(doc.requiredDate)], ['Reference ID', doc.referenceNo]],
    }),
    rfq: () => ({
      // One copy per supplier (the preview's Supplier switch): addressed to that supplier, with its details.
      party: supplier
        ? { label: 'Supplier', name: supplier.name, lines: supplierLines(supplier) }
        : (doc.suppliers || []).length === 1 ? { label: 'Supplier', name: doc.suppliers[0].name, lines: [] }
        // All Suppliers: one copy naming every supplier the request goes to.
        : { label: 'Suppliers', name: `${(doc.suppliers || []).length} Suppliers`, lines: (doc.suppliers || []).map((s, i) => `${i + 1}. ${s.name}`) },
      meta: [['RFQ No', doc.code], ['Request Date', pbDate(doc.requestDate)], ['Submission Deadline', pbDate(doc.submissionDeadline)]],   // the PR stays internal
    }),
    // Purchase Order: Buyer | Supplier (no e-mail), then PO ID · PO Date · RFQ Ref · Payment Mode over Delivery Terms |
    // Delivery To, always in the same places (a blank one shows "—").
    po: () => ({
      party: { label: 'Supplier', name: doc.supplierName,
        lines: supplierLines(supplier, doc.contactName, doc.contactNumber).filter(line => !Array.isArray(line) || line[0] !== 'E-mail') },
      poGrid: [['PO ID', doc.code, 'id'], ['PO Date', poSlashDate(doc.poDate)], ['RFQ Ref', doc.quotationNumber || doc.quotationRequestCode, 'id'],
        ['Payment Mode', [doc.paymentMode, doc.paymentMode === 'Credit' && doc.creditPeriod].filter(Boolean).join(' · ')],
        ['Delivery Terms', doc.deliveryTerms, 'wide'], ['Delivery To', doc.deliveryLocation, 'wide']],
      meta: [],
    }),
    // Goods Received Note (view_grn_pdf design): Buyer / Receiver beside Supplier / Vendor, then GRN ID · GRN Date · PO Ref · Stock Point.
    // Goods Received Note: Buyer / Receiver over Supplier / Vendor on the left; GRN ID, GRN Date and the supplier's
    // PO over the Stock Point on the right.
    grn: () => ({
      buyerLabel: 'Buyer / Receiver',
      party: { label: 'Supplier / Vendor', name: doc.supplierName, lines: [] },   // the name only (the final GRN design)
      grnBox: {
        ids: [['GRN ID', doc.code], ['GRN Date', poSlashDate(doc.grnDate)], ['Supplier PO / Other Reference', doc.poNumber || doc.purchaseOrderCode, 'ref']],
        point: ['Stock Point', [doc.warehouseCode, doc.warehouseName].filter(Boolean).join(' · ')],
      },
      meta: [],
    }),
    // Sales documents: this company is the Supplier, the customer the Buyer (as the quotation layout).
    qt: () => ({
      party: buyer(),
      meta: [['Quote Ref', doc.code], ['Date', pbDate(doc.quotationDate)], ['Ref Num', doc.referenceNo], ['Offer Validity', doc.offerValidity],
        ...terms, ['Salesman', doc.salesman], ['Salesman Contact', doc.salesmanContact]],
    }),
    so: () => ({
      party: buyer(),
      meta: [[proforma ? 'Invoice No' : 'SO No', doc.code], ['Date', pbDate(doc.orderDate)], ['Customer PO No', doc.customerPo],
        ['Quotation Ref', doc.quotationCode], ['Purchase Category', doc.purchaseCategory], ...terms],
    }),
    dn: () => ({
      party: buyer(),
      meta: [['DN No', doc.code], ['Date', pbDate(doc.deliveryNoteDate)], ['Customer PO No', doc.customerPo], ['Ref Num', doc.referenceNo],
        ['Delivery Location', doc.deliveryLocation], ['Carrier', doc.carrier], ['Vehicle #', doc.vehicleNo], ['Salesman', doc.salesman]],
    }),
    ti: () => ({
      party: buyer(),
      meta: [['Invoice No', doc.code], ['Date', pbDate(doc.invoiceDate)], ['Customer PO No', doc.customerPo], ['Ref ID', doc.referenceNo],
        ['Purchase Category', doc.purchaseCategory], ...terms],
    }),
    // The old Purchase Invoice: Buyer (this company) beside the Supplier (address, country, e-mail, contact person,
    // contact number), then Purchase No · Purchase Date · Supplier Inv No over PO Ref · GRN Ref · Currency.
    pe: () => ({
      party: { label: 'Supplier', name: doc.supplierName, lines: supplierLines(supplier).filter(line => !Array.isArray(line) || line[0] !== 'VATIN') },
      cols: 3,
      meta: [['Purchase No', doc.code], ['Purchase Date', poSlashDate(doc.purchaseDate)], ['Supplier Inv No', doc.supplierInvoiceNo],
        ['PO Ref', doc.purchaseOrderCode], ['GRN Ref', doc.grnCode], ['Currency', doc.currency]],
    }),
    // Supply Management: the company beside the stock point (adjustment), both stock points (transfer) or the
    // customer (reservation).
    sa: () => ({
      buyerLabel: 'Company',
      party: { label: 'Stock Point', name: doc.warehouseName, lines: [['Code', doc.warehouseCode]] },
      meta: [['Adjustment ID', doc.code], ['Date', poSlashDate(doc.adjustmentDate)], ['Status', doc.status],
        ['Reason', doc.reason], ['Requested By', doc.requestedBy], ['Approved By', doc.approvedBy]],
    }),
    st: () => ({
      buyerLabel: 'Company',
      party: { label: 'Stock Points', name: '', lines: [['From', [doc.fromWarehouseCode, doc.fromWarehouseName].filter(Boolean).join(' · ')],
        ['To', [doc.toWarehouseCode, doc.toWarehouseName].filter(Boolean).join(' · ')]] },
      meta: [['Transfer ID', doc.code], ['Transfer Date', poSlashDate(doc.transferDate)], ['Expected Date', poSlashDate(doc.expectedDate)],
        ['Transfer Reason', doc.transferReason]],
    }),
    rsv: () => ({
      buyerLabel: 'Company',
      party: { label: 'Customer', name: doc.customerName, lines: [] },
      meta: [['Reservation ID', doc.code], ['Reservation Date', poSlashDate(doc.reservationDate)], ['Reservation Type', doc.reservationType],
        ['Reference Number', doc.referenceNo], ['Stock Point', doc.warehouseName || 'All stock points'], ['Required Date', poSlashDate(doc.requiredDate)],
        ['Created By', doc.createdBy]],
    }),
    // The same for a sale: the customer as Buyer; Sales No · Sales Date · Customer PO / Ref No over Tax Invoice Ref ·
    // Delivery Note Ref · Currency.
    se: () => ({
      party: buyer(),
      cols: 3,
      meta: [['Sales No', doc.code], ['Sales Date', poSlashDate(doc.salesDate)], ['Customer PO / Ref No', doc.customerRefNo],
        ['Tax Invoice Ref', doc.taxInvoiceCode], ['Delivery Note Ref', doc.deliveryNoteCode], ['Currency', doc.currency]],
    }),
    // A sales return: the customer as Buyer; SR No · Return Date · Delivery Note Ref · Customer PO, then why, where to and how refunded.
    sr: () => ({
      party: buyer(),
      meta: [['SR No', doc.code], ['Return Date', pbDate(doc.returnDate)], ['Delivery Note Ref', doc.deliveryNoteCode], ['Sales Entry Ref', doc.salesEntryCode], ['Customer PO No', doc.customerPo],
        ['Return Reason', doc.returnReason], ['Return To', doc.warehouseName], ['Refund Mode', doc.refundMode], ['Currency', doc.currency]],
    }),
    // A purchase return: the supplier with its details; PRT No · Return Date · PO / GRN Ref · Supplier Inv No, then why,
    // where from and how it is settled.
    prt: () => ({
      party: { label: 'Supplier', name: doc.supplierName, lines: supplierLines(supplier, doc.contactName, doc.contactNumber) },
      meta: [['PRT No', doc.code], ['Return Date', pbDate(doc.returnDate)],
        ...(doc.salesReturnCode ? [['Sales Return Ref', doc.salesReturnCode]] : [['PO Ref', doc.purchaseOrderCode], ['GRN Ref', doc.grnCode]]),
        ['Supplier Inv No', doc.supplierInvoiceNo], ['Return Reason', doc.returnReason], ['Return From', doc.warehouseName],
        ['Settlement Mode', doc.settlementMode], ['Currency', doc.currency], ['Created By', doc.createdBy], ['Created By Contact', doc.createdByContact]],
    }),
    // A purchase replacement: the supplier with its details; PRP No · Replacement Date · PO / GRN Ref · Supplier Inv No,
    // then why, where it is received to and what happens to the returned goods.
    prp: () => ({
      party: { label: 'Supplier', name: doc.supplierName, lines: supplierLines(supplier, doc.contactName, doc.contactNumber) },
      meta: [['PRP No', doc.code], ['Replacement Date', pbDate(doc.replacementDate)], ['PO Ref', doc.purchaseOrderCode], ['GRN Ref', doc.grnCode],
        ['Supplier Inv No', doc.supplierInvoiceNo], ['Replacement Reason', doc.replacementReason], ['Receive To', doc.warehouseName],
        ['Returned Goods', doc.returnedGoods], ['Currency', doc.currency], ['Created By', doc.createdBy], ['Created By Contact', doc.createdByContact]],
    }),
    rp: () => ({
      party: buyer(),
      meta: [['SRP No', doc.code], ['Replacement Date', pbDate(doc.replacementDate)], ['Delivery Note Ref', doc.deliveryNoteCode], ['Sales Entry Ref', doc.salesEntryCode],
        ['Customer PO No', doc.customerPo], ['Replacement Reason', doc.replacementReason], ['Issue From', doc.warehouseName],
        ['Returned Goods', doc.returnedGoods], ['Currency', doc.currency]],
    }),
  }[spec.key]();
  // The item table's columns: [heading, kind of cell, value], the same structure on every document. Item Code is
  // printed on the Purchase Request only; the brand is not a column but "MAKE: …" under the item name.
  const qty = value => pbQty(pbNum(value));
  // The line's discount as a percent (the saved one, else worked out from the amount).
  const poDiscPct = l => (l.discountPct != null && l.discountPct !== '' ? pbNum(l.discountPct)
    : pbNum(l.quantity) * pbNum(l.price) > 0 ? pbNum(l.discountAmount) / (pbNum(l.quantity) * pbNum(l.price)) * 100 : 0);
  const grnMoney = value => pbNum(value).toLocaleString('en-US', { minimumFractionDigits: 3, maximumFractionDigits: 3 });   // 12,946.500
  const columns = [
    [['grn', 'pe', 'se', 'sr', 'prt'].includes(spec.key) ? '#' : 'SL.NO', 'sno', (l, i) => i + 1],
    ...(spec.key === 'pr' ? [['Item Code', 'code', l => l.itemCode]] : []),
    ['Item Name', 'name', l => l.itemName],
    // A multi-supplier sales order's All Suppliers copy: each line's supplier, after the item.
    ...(doc.showLineSupplier ? [['Supplier', 'supplier', l => l.supplierName]] : []),
    ...{
      simple: [['Qty', 'center', l => qty(l.quantity)], ['Unit', 'center', l => l.unit]],
      po: [['Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit],
        [`Price${doc.inPartyCurrency ? ` (${doc.currency})` : PRICES_IN_OMR.includes(spec.key) ? ' (OMR)' : doc.currency ? ` (${doc.currency})` : ''}`, 'num', l => (l.foc ? 'FOC' : pbAmount(l.price))],
        ['VAT %', 'num', l => `${pbNum(l.vatRate).toFixed(2)}%`], ['Disc %', 'num', l => `${poDiscPct(l).toFixed(2)}%`], ['Line Total', 'num total', l => pbAmount(l.lineTotal)]],
      grn: [['Qty', 'qty', l => qty(l.acceptedQty)], ['Unit', 'center', l => l.unit],
        ...(noPrices ? [] : [['Rate', 'num', l => grnMoney(l.unitCost)], ['VAT %', 'num', l => `${pbNum(l.vatRate).toFixed(2)}%`],
          ['Amount', 'num total', l => grnMoney(l.lineTotal)]])],
    // A sales order: no discount column, and VAT only on a proforma invoice (the buying side is never printed).
    so: [['Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit],
      [`Unit Price (${doc.inPartyCurrency ? doc.currency : 'OMR'})`, 'num', l => pbAmount(l.price)],
      ...(proforma || spec.key === 'ti' ? [['VAT (%)', 'num', l => pbNum(l.vatRate).toFixed(2)]] : []), ['Total Price', 'num total', l => pbAmount(l.lineTotal)]],
    // A purchase entry: quantity × rate, no VAT or line discount.
    pe: [['Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit],
      ['Price (OMR)', 'num', l => pbAmount(l.price)], ['Line Total', 'num total', l => pbAmount(l.lineTotal)]],
    // A sales return: the quantity returned and the condition it came back in.
    sr: [['Return Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit], ['Condition', 'center', l => l.condition],
      ['Unit Price (OMR)', 'num', l => pbAmount(l.price)],
      ['VAT (%)', 'num', l => pbNum(l.vatRate).toFixed(2)], ['Total Price', 'num total', l => pbAmount(l.lineTotal)]],
    // A purchase return: the quantity received and returned, and the condition of the goods.
    prt: [['Received Qty', 'num', l => qty(l.receivedQty)], ['Return Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit],
      ['Condition', 'center', l => l.condition], ['Unit Price (OMR)', 'num', l => pbAmount(l.price)],
      ['VAT (%)', 'num', l => pbNum(l.vatRate).toFixed(2)], ['Total Price', 'num total', l => pbAmount(l.lineTotal)]],
    // A purchase replacement: what the supplier sends in place of each returned item, at the old and the new price.
    prp: [['Received Qty', 'num', l => qty(l.receivedQty)], ['Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit],
      ['Condition', 'center', l => l.condition], ['Replacement Item', 'supplier', l => l.replacementItemName || 'Same item'],
      ['Old Price', 'num', l => pbAmount(l.oldPrice)], ['New Price', 'num', l => pbAmount(l.price)],
      ['VAT (%)', 'num', l => pbNum(l.vatRate).toFixed(2)], ['Difference (OMR)', 'num total', l => pbAmount(l.lineTotal)]],
    // A sales replacement: what goes back in place of each returned item, at the old and the new price.
    rp: [['Qty', 'num', l => qty(l.quantity)], ['Unit', 'num', l => l.unit], ['Condition', 'center', l => l.condition],
      ['Replacement Item', 'supplier', l => l.replacementItemName || 'Same item'],
      ['Old Price', 'num', l => pbAmount(l.oldPrice)], ['New Price', 'num', l => pbAmount(l.price)],
      ['VAT (%)', 'num', l => pbNum(l.vatRate).toFixed(2)], ['Difference (OMR)', 'num total', l => pbAmount(l.lineTotal)]],
    // Supply Management.
    sa: [['System Qty', 'num', l => qty(l.systemQty)], ['Physical Qty', 'num', l => qty(l.quantity)],
      ['Difference', 'num', l => { const d = pbNum(l.quantity) - pbNum(l.systemQty); return d > 0.0005 ? `+${pbQty(d)}` : pbQty(d); }],
      ['Unit Cost', 'num', l => pbAmount(l.unitCost)], ['Adj. Value', 'num total', l => pbAmount((pbNum(l.quantity) - pbNum(l.systemQty)) * pbNum(l.unitCost))]],
    st: [['Qty', 'num', l => qty(l.quantity)], ['Unit', 'center', l => l.unit], ['Unit Cost', 'num', l => pbAmount(l.unitCost)],
      ['Total', 'num total', l => pbAmount(pbNum(l.quantity) * pbNum(l.unitCost))]],
    rsv: [['Reserved Qty', 'num', l => qty(l.quantity)], ['Unit', 'center', l => l.unit]],
    }[SUPPLY_KEYS.includes(spec.key) ? spec.key : spec.key === 'so' || spec.key === 'ti' ? 'so' : spec.key === 'pe' || spec.key === 'se' ? 'pe' : ['sr', 'rp', 'prt', 'prp'].includes(spec.key) ? spec.key : spec.kind],
  ];
  const cellClass = kind => kind.split(' ').map(part => `ps-c-${part}`).join(' ');

  const companyName = profile?.companyName || byId('app')?.querySelector('.brand-name')?.textContent || 'Growth Engine';
  const parts = [];
  if (!letterhead) {                                   // no letterhead: the company name heads the page
    const brand = el('div', 'ps-brand');
    brand.append(el('div', 'ps-company', companyName));
    parts.push(brand);
  }
  // The Sales Order: its own costing layout (soCostingParts); every other document the layout below.
  const soDesign = spec.key === 'so' && !proforma;
  if (soDesign) parts.push(...soCostingParts(doc, { picked, customer }));
  if (!soDesign) {
  parts.push(el('h1', 'ps-title', title));

  // Buyer (this company, from Create a Company) | the other party.
  const party = (label, name, lines) => {
    const box = el('div', 'ps-party');
    box.append(el('div', 'ps-label', label));
    if (filled(name)) box.append(el('div', 'ps-party-name', String(name).trim()));
    const list = el('div', 'ps-party-lines');
    for (const line of lines) {
      if (Array.isArray(line)) {
        if (!filled(line[1])) continue;
        const row = el('div', 'ps-party-line');
        row.append(el('span', 'ps-party-key', line[0]), el('span', '', `: ${String(line[1]).trim()}`));   // label | value columns
        list.append(row);
      } else if (String(line ?? '').trim()) {
        list.append(el('div', 'ps-party-text', line));
      }
    }
    box.append(list);
    return box;
  };
  const p = profile || {};
  const address = [p.building, p.street, p.area, p.city, p.poBox && `PO Box: ${p.poBox}`, p.postalCode && `PC: ${p.postalCode}`]
    .map(value => String(value ?? '').trim()).filter(Boolean).join(', ');
  const parties = el('div', 'ps-parties');
  parties.append(
    // A multi-supplier sales order's copy for one supplier: that supplier, not this company, is the Supplier.
    spec.key === 'so' && picked ? party('Supplier', picked.name, supplierLines(picked)) :
    party(isSales ? 'Supplier' : (layout.buyerLabel || 'Buyer'), companyName, layout.buyerLines
      ? [address, ['Country', p.country], ['VATIN', p.vatRegNumber], ['E-mail', p.email], ...layout.buyerLines]
      : [address, ['Country', p.country], ['VATIN', p.vatRegNumber], ['E-mail', p.email], ['Contact Number', p.phone]]),
    party(layout.party.label, layout.party.name, layout.party.lines),
  );
  const box = el('div', 'ps-docbox');
  const stackItem = ([label, value, kind]) => {
    const item = el('div', kind === 'ref' ? 'ps-idbox-item is-ref' : 'ps-idbox-item');
    item.append(el('dt', '', label), cell('dd', '', value));
    return item;
  };
  if (layout.grnBox) {
    const grid = el('div', 'ps-grnbox');
    const ids = el('dl', 'ps-idbox ps-grnbox-ids');
    ids.append(...layout.grnBox.ids.filter(filledPair).map(stackItem));
    const point = el('dl', 'ps-idbox ps-grnbox-point');
    if (filledPair(layout.grnBox.point)) point.append(stackItem(layout.grnBox.point));
    const [buyerBox, supplierBox] = [...parties.children];
    grid.append(buyerBox, ids, supplierBox, point);
    box.append(grid);
  } else if (layout.idBox) {
    // Supplier / Vendor on the left, the document number and date stacked on the right.
    const top = el('div', 'ps-docbox-top');
    const ids = el('dl', 'ps-idbox');
    for (const [label, value] of layout.idBox.filter(filledPair)) {
      const item = el('div', 'ps-idbox-item');
      item.append(el('dt', '', label), cell('dd', '', value));
      ids.append(item);
    }
    top.append(layout.noBuyer ? parties.lastElementChild : parties, ids);
    box.append(top);
  } else {
    box.append(parties);
  }
  if (layout.poGrid) {
    const grid = el('dl', 'ps-pogrid');
    for (const [label, value, kind] of layout.poGrid) {
      const item = el('div', `ps-pogrid-item${kind ? ` is-${kind}` : ''}`);
      item.append(el('dt', '', label), cell('dd', '', value));
      grid.append(item);
    }
    box.append(grid);
  }
  const metaGrid = el('dl', 'ps-meta');
  layout.meta = layout.meta.filter(filledPair);
  const count = layout.meta.length;
  const cols = layout.cols || (count <= 4 ? count : count % 3 === 0 ? 3 : 4);
  metaGrid.style.setProperty('--ps-cols', String(cols));
  let column = 0;
  layout.meta.forEach(([label, value, span], i) => {
    const next = layout.meta[i + 1];
    const full = span === 'full';
    if (full) column = 0;
    column += full ? cols : 1;
    // The last item before a full-width one stretches to the row's end, so no row is left open.
    const fill = !full && next?.[2] === 'full' && column % cols ? cols - (column % cols) + 1 : 1;
    if (fill > 1) column += fill - 1;
    const rowEnd = column % cols === 0;
    const item = el('div', rowEnd ? 'ps-meta-item is-row-end' : 'ps-meta-item');
    if (full) item.style.gridColumn = '1 / -1';
    else if (fill > 1) item.style.gridColumn = `span ${fill}`;
    if (/\bRef\b|Reference|PO Number/.test(label)) item.classList.add('is-ref');   // the source document, in blue
    item.append(el('dt', '', label), cell('dd', '', value));
    metaGrid.append(item);
  });
  if (layout.meta.length) box.append(metaGrid);
  parts.push(box);

  parts.push(el('div', 'ps-section-title', { pr: 'Requested Items', rfq: 'Requested Items', po: 'Ordered Items', grn: 'Received & Accepted Items',
    qt: 'Quoted Items', so: 'Ordered Items', dn: 'Delivered Items', ti: 'Invoiced Items', pe: 'Ordered Items', se: 'Sold Items', sr: 'Returned Items', prt: 'Returned Items', prp: 'Replacement Items',
    sa: 'Adjusted Items', st: 'Transferred Items', rsv: 'Reserved Items' }[spec.key]));
  const table = el('table', `ps-table ps-table-${spec.kind}${noPrices ? ' ps-table-noprices' : ''}${spec.key === 'po' ? ' ps-table-pdoc' : ''}`);
  const thead = el('thead');
  const headRow = el('tr');
  headRow.append(...columns.map(([label, kind]) => el('th', cellClass(kind), label)));
  thead.append(headRow);
  const tbody = el('tbody');
  doc.items.forEach((line, i) => {
    const tr = el('tr');
    tr.append(...columns.map(([, kind, value]) => el('td', cellClass(kind), String(value(line, i) ?? '').trim())));   // a blank cell stays blank
    // The item name (with the line's bold / colour), then "MAKE: brand" under it on a quotation or sales order with a brand.
    const nameCell = tr.querySelector('.ps-c-name');
    if (line.itemNameHtml) nameCell.replaceChildren(remarksFragment(line.itemNameHtml));
    const brand = String(line.brandName ?? '').trim();
    if (brand && ['qt', 'so'].includes(spec.key)) nameCell.append(el('div', 'ps-make', `Make: ${brand}`));   // the quotation and sales order only
    const term = String(line.deliveryTerm ?? '').trim();           // sales lines
    if (term) nameCell.append(el('div', 'ps-make', `Delivery: ${term}`));
    const transfers = (line.transfers || []).filter(t => pbNum(t.quantity) > 0);
    if (spec.key === 'grn' && transfers.length) {
      // Under the item name: "↳ Stock Transfer: 2 BOX to [SOHAR STORE (WH-2026-0002)]", one line per stock point.
      for (const t of transfers) {
        const note = el('div', 'ps-transfer-note');
        const point = t.warehouseName && t.warehouseCode ? `${t.warehouseName} (${t.warehouseCode})` : t.warehouseName || t.warehouseCode;
        note.append(el('span', 'ps-transfer-label', '↳ Stock Transfer:'), el('b', '', ` ${qty(t.quantity)}`),
          el('span', 'ps-transfer-label', ` ${String(line.unit || '').trim()} to`.replace(/\s+to$/, ' to')), el('span', 'ps-transfer-pill', point));
        nameCell.append(note);
      }
      // Under the accepted quantity: a small "WH-2026-0002 : 2" tag per stock point.
      const list = el('div', 'ps-transfers');
      for (const t of transfers) list.append(el('div', 'ps-transfer', `${t.warehouseCode || t.warehouseName} : ${qty(t.quantity)}`));
      const qtyCell = tr.querySelector('.ps-c-qty');
      qtyCell.replaceChildren(el('div', 'ps-qty-main', qtyCell.textContent), list);
      table.classList.add('has-transfers');            // the Qty column widens to fit the tags
    }
    tbody.append(tr);
  });
  table.append(thead, tbody);
  parts.push(table);

  // Remarks & Notes and the PO's Certification Required on the left, the totals on the right.
  const bottom = el('div', noPrices ? 'ps-bottom ps-bottom-count' : 'ps-bottom');   // Inspection Mode: the count box runs the full width
  const side = el('div', 'ps-side');
  if (doc.remarks) {
    const remarks = el('div', 'ps-remarks');
    remarks.append(el('div', 'ps-label', 'Remarks & Notes'));
    if (isRemarksHtml(doc.remarks)) {
      const body = el('div', 'ps-remarks-body');
      body.append(remarksFragment(doc.remarks));
      remarks.append(body);
    } else {
      remarks.append(el('div', 'ps-remarks-text', doc.remarks));
    }
    side.append(remarks);
  }
  if (spec.key === 'po' || (spec.key === 'qt' && (doc.certifications || []).length)) {   // the PO always has the box: N/A when none
    const certification = el('div', 'ps-remarks ps-certification');
    certification.append(el('div', 'ps-label', 'Certification Required'),
      el('div', 'ps-remarks-text', (doc.certifications || []).join(', ') || 'N/A'));
    side.append(certification);
  }
  if (side.childElementCount) bottom.append(side);
  if (noPrices) {
    const totals = el('dl', 'ps-totals ps-totals-count');
    const row = el('div', 'ps-total-grand');
    row.append(el('dt', '', 'Total Number of Items:'), el('dd', '', String(doc.items.length)));
    totals.append(row);
    bottom.append(totals);
  } else if (SUPPLY_KEYS.includes(spec.key)) {
    const totals = el('dl', 'ps-totals');
    const lines = doc.items || [];
    const rowsOut = {
      sa: [['Total Items', String(lines.length)], ['Net Quantity Change', (() => { const n = pbNum(doc.netQuantity); return n > 0.0005 ? `+${pbQty(n)}` : pbQty(n); })()],
        ['Grand Total', pbAmount(doc.totalValue), true]],
      st: [['Total Items', String(lines.length)], ['Total Quantity', pbQty(pbNum(doc.totalQty))], ['Grand Total', pbAmount(doc.grandTotal), true]],
      rsv: [['Total Items', String(lines.length)], ['Total Reserved Quantity', pbQty(pbNum(doc.totalQty)), true]],
    }[spec.key];
    for (const [label, value, strong] of rowsOut) {
      const row = el('div', strong ? 'ps-total-grand' : '');
      row.append(el('dt', '', `${label}:`), el('dd', '', value));
      totals.append(row);
    }
    bottom.append(totals);
  } else if (spec.key === 'grn') {
    const totals = el('dl', 'ps-totals ps-grn-totals');
    const currency = doc.currency || profile?.baseCurrency || 'OMR';     // a GRN has no currency of its own: the company's
    const money = (value, sign = '') => `${currency ? `${currency} ` : ''}${sign}${grnMoney(value)}`;   // OMR -1.000
    for (const [label, value, sign] of [['Subtotal', doc.subtotal], [doc.vatMode === 'exclude' ? 'VAT (Tax)' : 'VAT (included)', doc.vatAmount],
      ['Discount', doc.discountAmount, '-'], ['Shipping / Freight', doc.shipping]]) {
      if ((label === 'Discount' || label.startsWith('Shipping')) && !pbNum(value)) continue;   // shown only when there is one
      const row = el('div', label === 'Discount' ? 'ps-total-discount' : '');
      row.append(el('dt', '', label), el('dd', '', money(value, sign)));
      totals.append(row);
    }
    const grand = el('div', 'ps-grn-grand');
    grand.append(el('dt', '', `Grand Total${currency ? ` (${currency})` : ''}`), el('dd', '', grnMoney(doc.grandTotal)));
    totals.append(grand);
    bottom.append(totals);
  } else if (spec.key === 'rp' || spec.key === 'prp') {
    // A sales / purchase replacement: the returned and replacement values, the VAT on the difference, then the Price
    // Difference (below 0: owed to the buyer, or owed by the supplier). A zero discount or charge is left out.
    const totals = el('dl', 'ps-totals');
    const currency = ' OMR';                              // PRICES_IN_OMR: only the OMR difference is printed
    for (const [label, value, kind] of [['Returned Items Value', doc.returnedValue], ['Replacement Items Value', doc.replacementValue],
      [doc.vatMode === 'exclude' ? 'VAT on Difference' : 'VAT on Difference (included)', doc.vatAmount],
      ['Discount', doc.discountAmount, 'discount'], ['Handling / Delivery Charge', doc.handlingCharge], ['Price Difference', doc.grandTotal, 'grand']]) {
      if (!kind?.startsWith('grand') && (label === 'Discount' || label.startsWith('Handling')) && !pbNum(value)) continue;
      const row = el('div', kind === 'grand' ? 'ps-total-grand' : kind === 'discount' ? 'ps-total-discount' : '');
      row.append(el('dt', '', `${label}:`), el('dd', '', `${kind === 'discount' ? '-' : ''}${pbAmount(value)}${currency}`));
      totals.append(row);
    }
    bottom.append(totals);
  } else if (spec.kind !== 'simple') {
    const totals = el('dl', spec.key === 'po' ? 'ps-totals ps-po-totals' : 'ps-totals');   // the PO: Grand Total in a green box
    // PRICES_IN_OMR: the prices and totals are in OMR; the Grand Total is also given in the party's currency (fixed rates).
    const inOmr = PRICES_IN_OMR.includes(spec.key) && !doc.inPartyCurrency;   // a PO / quotation / delivery note / tax invoice in another currency: already converted
    // A sales order, purchase / sales entry and purchase / sales return print only the OMR totals (no Grand Total in
    // the party's currency).
    const poRate = inOmr && !['so', 'pe', 'se', 'sr', 'prt'].includes(spec.key) && doc.currency && doc.currency !== 'OMR' ? SO_RATES_TO_OMR[doc.currency] : 0;
    const currency = inOmr ? ' OMR' : doc.currency ? ` ${doc.currency}` : '';
    const grn = spec.key === 'grn';
    for (const [label, value, strong] of [[grn ? 'Subtotal (Accepted Net)' : 'Subtotal (Net)', doc.subtotal],
      [doc.vatMode === 'exclude' ? 'Total VAT / Tax' : 'VAT (included)', doc.vatAmount],
      ['Discount', doc.discountAmount],
      [grn ? 'Shipping / Freight' : ({ qt: 'Delivery Charge', so: 'Transportation Charge', dn: 'Delivery Charge', ti: 'Transportation Charge' }[spec.key] || 'Shipping'), doc.shipping],
      ...(spec.key === 'qt' ? [['Round Off', doc.roundOff]] : []),          // left out when 0
      ...(spec.key === 'sr' ? [['Restocking Fee', doc.restockingFee]] : []),  // left out when 0
      ...(spec.key === 'prt' ? [['Supplier Deduction', doc.supplierDeduction]] : []),
      [{ sr: 'Total Refund', prt: 'Total Return Amount' }[spec.key] || 'Grand Total', doc.grandTotal, true],
      // A sales order's advance (left out when none) and what is still due.
      ...((spec.key === 'so' || spec.key === 'ti') && pbNum(doc.advancePayment) ? [['Advance Payment', doc.advancePayment], ['Balance Due', pbNum(doc.grandTotal) - pbNum(doc.advancePayment)]] : [])]) {
      if (!strong && !pbNum(value) && !label.startsWith('Subtotal') && !label.includes('VAT')) continue;   // a zero discount / shipping is left out
      if ((spec.key === 'pe' || spec.key === 'se' || (spec.key === 'so' && !proforma)) && label.includes('VAT')) continue;   // no VAT on a sales order / purchase or sales entry
      const discount = label === 'Discount' || label === 'Restocking Fee' || label === 'Supplier Deduction';
      const entry = ['pe', 'se', 'sr', 'prt'].includes(spec.key);   // the old Purchase Invoice: "Special Discount: -1.000"
      const row = el('div', strong ? 'ps-total-grand' : discount && (grn || entry) ? 'ps-total-discount' : '');
      row.append(el('dt', '', `${label === 'Discount' && entry && !['sr', 'prt'].includes(spec.key) ? 'Special Discount' : label}:`), el('dd', '', `${discount && (grn || entry) ? '-' : ''}${pbAmount(value)}${currency}`));
      totals.append(row);
    }
    if (poRate) {
      const row = el('div', 'ps-total-grand');
      const grandLabel = { sr: 'Total Refund', prt: 'Total Return Amount' }[spec.key] || 'Grand Total';
      row.append(el('dt', '', `${grandLabel} (${doc.currency}):`), el('dd', '', `${pbAmount(pbNum(doc.grandTotal) / poRate)} ${doc.currency}`));
      totals.append(row);
    }
    bottom.append(totals);
  }
  if (bottom.childElementCount) parts.push(bottom);
  }                                                    // !soDesign

  const foot = el('footer', 'ps-foot');
  if (doc.includeSignatory) {
    const signs = el('div', 'ps-signs');
    for (const slot of doc.signatories || []) {
      const sign = el('div', 'ps-sign');
      sign.append(el('div', 'ps-sign-name', slot.name || ''));
      if (slot.title) sign.append(el('div', 'ps-sign-title', slot.title));
      signs.append(sign);
    }
    foot.append(signs);
  }
  const loading = [];
  const imageLoaded = img => new Promise(resolve => { img.onload = resolve; img.onerror = () => { img.remove(); resolve(); }; });
  // A quotation: the General Terms & Conditions on a page of their own (the company's, from Create a Company, else
  // the standard ones in terms.js), with the quotation's own Offer Validity and currency in them.
  const termsText = spec.key === 'qt' && typeof renderQuotationTerms === 'function'
    ? String(profile?.termsConditions ?? '').trim() || (typeof QUOTATION_TERMS_DEFAULT === 'string' ? QUOTATION_TERMS_DEFAULT : '')
    : '';
  const sealSrc = doc.attachSeal ? await companySealImage() : null;
  if (!stillWanted()) return;
  // Attach Seal: the seal on every page, at its foot on the right above the letterhead's footer (added with the
  // letterhead below; printed it is fixed, so the browser repeats it; on screen fitPreviewPages repeats it).
  let pageSeal = null;
  if (sealSrc) {
    pageSeal = el('img', 'ps-seal ps-page-seal');
    pageSeal.alt = 'Company seal';
    loading.push(imageLoaded(pageSeal));
    pageSeal.src = sealSrc;
  }
  if (foot.childElementCount) parts.push(foot);

  // The page frame: a table whose header and footer rows repeat on every printed page, keeping the letterhead's
  // header and footer clear (or a plain margin without a letterhead). Printed, the letterhead image is fixed
  // behind the frame, so the browser prints it on every page; on screen it is repeated down the page.
  const frame = el('table', 'ps-frame');
  const spacer = className => { const row = el('tr'); const td = el('td'); td.append(el('div', className)); row.append(td); return row; };
  const frameHead = el('thead'); frameHead.append(spacer('ps-space-top'));
  const frameFoot = el('tfoot'); frameFoot.append(spacer('ps-space-bottom'));
  const frameBody = el('tbody'); const bodyRow = el('tr'); const bodyCell = el('td', 'ps-body');
  // Every amount on the page with thousands separators (1,061,720.000).
  for (const part of parts) {
    const walker = document.createTreeWalker(part, NodeFilter.SHOW_TEXT);
    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
      const grouped = groupDigits(node.nodeValue);
      if (grouped !== node.nodeValue) node.nodeValue = grouped;
    }
  }
  bodyCell.append(...parts); bodyRow.append(bodyCell); frameBody.append(bodyRow);   // no faint logo behind the items
  if (termsText) {
    const currencyCode = PRICES_IN_OMR.includes(spec.key) && !doc.inPartyCurrency ? 'OMR' : String(doc.currency || profile?.baseCurrency || 'OMR').toUpperCase();
    const currencyName = PO_CURRENCIES.find(row => row.code === currencyCode)?.name;
    const validity = String(doc.offerValidity ?? '').trim().toLowerCase() || '30 days';   // "30 Days" → "30 days"
    const termsRow = el('tr', 'ps-terms-row');
    const termsCell = el('td', 'ps-body ps-terms');
    termsCell.append(el('div', 'ps-terms-title', 'General Terms & Conditions'),
      renderQuotationTerms(termsText, { validity, currency: currencyName ? `${currencyName} (${currencyCode})` : currencyCode }));
    termsRow.append(termsCell);
    frameBody.append(termsRow);
  }
  frame.append(frameHead, frameBody, frameFoot);
  const sheetParts = [frame];
  sheet.classList.toggle('has-letterhead', Boolean(letterhead));
  sheet.classList.toggle('ps-po', procurement);   // the procurement look (bold capital values, totals box): PO and GRN
  sheet.classList.toggle('ps-grn', spec.key === 'grn');
  sheet.classList.toggle('has-seal', Boolean(pageSeal));   // each page keeps room for the seal at its foot
  sheet.classList.toggle('ps-pdoc', spec.key === 'po');   // the Purchase Order design
  sheet.style.setProperty('--ps-top', `${((letterhead?.top ?? 0.05) * 297).toFixed(1)}mm`);
  sheet.style.setProperty('--ps-bottom', `${((letterhead?.bottom ?? 0.05) * 297).toFixed(1)}mm`);
  sheet.style.setProperty('--ps-side', `${((letterhead?.side ?? 0.06) * 210).toFixed(1)}mm`);
  if (letterhead) {
    const back = el('img', 'ps-letterhead');
    back.alt = '';
    loading.push(imageLoaded(back));
    back.src = letterhead.src;
    sheetParts.unshift(back);
  }
  if (pageSeal) sheetParts.push(pageSeal);
  sheet.replaceChildren(...sheetParts);
  await Promise.all(loading);
  if (screen) fitPreviewPages(sheet, letterhead);
}

// On screen: the page is as tall as the whole A4 pages it takes, with the letterhead on each of them.
// On screen the A4 pages are one tall sheet, so it is laid out as printing would: anything that would run past a page's
// writing area (the letterhead's footer) moves down to the next page's writing area (under its header): an item row
// (the table's header row repeats over it), the totals, the signatures, a term. The quotation's terms always start a
// new page. Then the sheet is as tall as its whole pages, with the letterhead and a gap on each.
function fitPreviewPages(sheet, letterhead) {
  sheet.style.minHeight = '';
  for (const node of sheet.querySelectorAll('.pv-break, .pv-repeat-head, .pv-page-gap, .ps-letterhead[data-page], .ps-page-seal[data-page]')) node.remove();
  const sheetTop = () => sheet.getBoundingClientRect().top;
  const pageHeight = sheet.getBoundingClientRect().width * 297 / 210;
  const topSpace = sheet.querySelector('.ps-space-top')?.offsetHeight || 0;
  const bottomSpace = sheet.querySelector('.ps-space-bottom')?.offsetHeight || 0;
  const usable = pageHeight - topSpace - bottomSpace;
  const pageStart = page => page * pageHeight + topSpace;          // where a page's writing area starts
  // How far `node` must move down to sit wholly inside one page's writing area (0: it already does, or it is too
  // tall for any page and is left to run on).
  const shiftFor = (node, forceNewPage = false) => {
    const box = node.getBoundingClientRect();
    if (!box.height && !forceNewPage) return 0;
    const top = box.top - sheetTop();
    const page = Math.floor(top / pageHeight);
    if (forceNewPage) return top > pageStart(page) + 1 || page === 0 ? pageStart(page + 1) - top : 0;
    if (page > 0 && top < pageStart(page)) return pageStart(page) - top;           // in the next page's header
    const end = page * pageHeight + pageHeight - bottomSpace;
    if (top + box.height <= end + 0.5 || box.height > usable) return 0;
    return pageStart(page + 1) - top;
  };
  const spacer = (height, tag = 'div') => {
    const node = el(tag, 'pv-break');
    node.style.height = `${height}px`;
    return node;
  };
  const pushBlock = (node, force = false) => {
    const shift = shiftFor(node, force);
    if (shift > 0.5) node.before(spacer(shift));
  };
  const pushRow = (row, table) => {
    const shift = shiftFor(row);
    if (shift <= 0.5) return;
    const columns = row.children.length;
    const gapRow = el('tr', 'pv-break');
    const gapCell = el('td');
    gapCell.colSpan = columns;
    gapRow.append(gapCell);
    row.before(gapRow);
    const head = table.tHead?.rows[0]?.cloneNode(true);       // the column headings again, at the top of the new page
    if (head) { head.classList.add('pv-repeat-head'); row.before(head); }
    // The gap takes what is left of this page, so the headings and the row start the next one.
    gapCell.style.height = `${Math.max(0, shift)}px`;
  };
  for (const body of sheet.querySelectorAll('.ps-frame > tbody > tr > td.ps-body')) {
    if (body.classList.contains('ps-terms')) pushBlock(body.firstElementChild, true);   // the terms: a page of their own
    for (const part of [...body.children]) {
      if (part.classList.contains('pv-break')) continue;
      if (part.matches('table.ps-table')) {
        // The headings with the first row: never alone at the foot of a page (the spacer goes before the table).
        const firstRow = part.tBodies[0]?.rows[0];
        const lead = el('div');
        const headTop = (part.tHead || part).getBoundingClientRect().top;
        const leadBottom = (firstRow || part.tHead || part).getBoundingClientRect().bottom;
        Object.assign(lead.style, { position: 'absolute', left: '0', width: '1px', top: `${headTop - sheetTop()}px`, height: `${leadBottom - headTop}px` });
        sheet.append(lead);
        const shift = shiftFor(lead);
        lead.remove();
        if (shift > 0.5) part.before(spacer(shift));
        for (const row of [...part.tBodies[0]?.rows || []]) pushRow(row, part);
      } else if (part.matches('.ps-terms-list')) {
        for (const item of [...part.children]) pushBlock(item);
      } else if (!part.matches('.ps-terms-title') || !body.classList.contains('ps-terms')) {
        pushBlock(part);
      }
    }
  }
  const pages = Math.max(1, Math.ceil((sheet.scrollHeight - 2) / pageHeight));
  sheet.style.minHeight = `${pages * 297}mm`;
  // Between two pages a gap, so the preview shows separate A4 sheets (as they print), not one long page.
  for (let page = 1; page < pages; page++) {
    const gap = el('div', 'pv-page-gap');
    gap.style.top = `${page * 297}mm`;
    gap.setAttribute('aria-hidden', 'true');
    sheet.append(gap);
  }
  // The seal (Attach Seal) at the foot of every page.
  const seal = sheet.querySelector('.ps-page-seal:not([data-page])');
  for (let page = 1; seal && page < pages; page++) {
    const copy = seal.cloneNode();
    copy.dataset.page = String(page);
    copy.style.setProperty('--ps-page', String(page));
    seal.after(copy);
  }
  const first = sheet.querySelector('.ps-letterhead');
  if (!letterhead || !first) return;
  for (let page = 1; page < pages; page++) {
    const copy = first.cloneNode();
    copy.dataset.page = String(page);
    copy.style.top = `${page * 297}mm`;
    first.after(copy);
  }
}

let previewDoc = null;           // { spec, doc } on the preview page
async function printPurchaseDocument(spec, id) {
  let doc;
  try { doc = await apiRequest(`${spec.api}?id=${id}`); } catch (error) { showToast('The document could not be opened', error.message, true); return; }
  const dialog = byId('pb-preview');
  // A Quotation Request: the Supplier switch shows All Suppliers (one copy naming them all, the first choice) or
  // the copy for one supplier, with that supplier's details. With a single supplier it is addressed to it.
  // A multi-supplier Sales Order: All Suppliers (every line, with a Supplier column) or one supplier's lines.
  const suppliers = spec.key === 'rfq' ? doc.suppliers || [] : soLineSuppliers(spec, doc);
  previewDoc = { spec, doc, supplierId: suppliers.length === 1 ? String(suppliers[0].id) : '' };
  const switcher = byId('pv-supplier');
  switcher.replaceChildren(new Option('All Suppliers', ''), ...suppliers.map(s => new Option(s.name, String(s.id))));
  switcher.value = previewDoc.supplierId;
  switcher.closest('.pv-supplier').hidden = suppliers.length < 2;
  dialog.classList.toggle('pv-po', spec.key === 'grn');   // a GRN: the dark bar scrolls away with the page
  previewDoc.hidePrices = false;
  syncPriceToggle();
  byId('pv-title').textContent = `${PB_TITLES[spec.key]} • ${doc.code}`;
  if (!dialog.open) dialog.showModal();
  dialog.querySelector('[data-pv="print"]').focus();
  await showPreviewSheet();
}

// A multi-supplier sales order's suppliers, once each, in the order their lines come.
function soLineSuppliers(spec, doc) {
  if (spec.key !== 'so' || doc.supplierMode !== 'multi') return [];
  const seen = new Map();
  for (const line of doc.items || []) {
    if (line.supplierId && !seen.has(String(line.supplierId))) seen.set(String(line.supplierId), { id: line.supplierId, name: line.supplierName || '' });
  }
  return [...seen.values()];
}

// The document as the preview shows it. A multi-supplier sales order: All Suppliers adds the Supplier column; one
// supplier keeps only that supplier's lines, totalled on their own (the order-wide discount, charges and advance
// are left off that copy).
function previewDocument(current) {
  const { spec, doc, supplierId } = current;
  if (spec.key !== 'so' || doc.supplierMode !== 'multi') return doc;
  if (!supplierId) return { ...doc, showLineSupplier: true };
  const items = doc.items.filter(line => String(line.supplierId) === supplierId);
  let subtotal = 0;
  let vat = 0;
  for (const line of items) {
    const net = line.foc ? 0 : Math.max(0, pbNum(line.quantity) * pbNum(line.price) - pbNum(line.discountAmount));
    const rate = pbNum(line.vatRate);
    subtotal += net;
    vat += doc.vatMode === 'include' ? net * rate / (100 + rate) : net * rate / 100;
  }
  const grand = subtotal + (doc.vatMode === 'include' ? 0 : vat);
  return { ...doc, items, subtotal: pbMoney(subtotal), vatAmount: pbMoney(vat), discountAmount: '0', shipping: '0', advancePayment: '0',
    grandTotal: pbMoney(grand) };
}

// The previewed document's supplier (Quotation Request): its details from the Supplier master, else the name kept on the request.
async function previewSupplier() {
  const { spec, doc, supplierId } = previewDoc;
  if (!supplierId) return null;
  // A sales order: one supplier's copy, with that supplier's details from the Supplier master.
  const kept = (spec.key === 'so' ? soLineSuppliers(spec, doc) : doc.suppliers || []).find(s => String(s.id) === supplierId) || {};
  try { return { ...kept, ...(await pbSupplier(supplierId)) }; } catch { return kept; }
}

// Draws the preview page for the current document (and supplier).
async function showPreviewSheet() {
  const current = previewDoc;
  if (!current) return;
  const dialog = byId('pb-preview');
  const sheet = dialog.querySelector('.pv-sheet');
  sheet.replaceChildren();
  sheet.style.minHeight = '';
  dialog.scrollTop = 0;
  const { supplierId, hidePrices } = current;
  try {
    // The chosen supplier's details load alongside the rest of the page (fillPurchaseSheet waits for them all at once).
    await fillPurchaseSheet(sheet, current.spec, previewDocument(current), { screen: true, supplier: previewSupplier(), hidePrices: current.hidePrices,
      stillWanted: () => previewDoc === current && current.supplierId === supplierId && current.hidePrices === hidePrices });
  } catch (error) {
    showToast('The document could not be shown', error.message, true);
  }
}

async function printPreviewDocument() {
  if (!previewDoc) return;
  const { spec, doc, hidePrices } = previewDoc;
  const sheet = byId('pb-print-sheet');
  const supplier = await previewSupplier();
  await fillPurchaseSheet(sheet, spec, previewDocument(previewDoc), { supplier, hidePrices });
  const pageTitle = document.title;
  // The browser's suggested PDF file name (a Quotation Request's names the supplier too).
  document.title = `${doc.code} ${PB_TITLES[spec.key]}${supplier?.name ? ` - ${supplier.name}` : ''}`;
  document.body.classList.add('is-printing');
  const done = () => {
    document.body.classList.remove('is-printing');
    document.title = pageTitle;
    sheet.replaceChildren();
    window.removeEventListener('afterprint', done);
  };
  window.addEventListener('afterprint', done);
  window.print();
}

// The preview page's keys: Esc (the usual popup Esc) or B goes back, P or Ctrl+P prints; nothing reaches the page.
function handlePreviewKeys(event) {
  const plain = !event.ctrlKey && !event.metaKey && !event.altKey;
  const key = event.key.toLowerCase();
  if (plain && key === 'b') {
    event.preventDefault();
    if (!event.repeat) byId('pb-preview').close();
  } else if ((plain && key === 'p') || ((event.ctrlKey || event.metaKey) && !event.altKey && key === 'p')) {
    event.preventDefault();
    if (!event.repeat) printPreviewDocument();
  }
}

// GRN: Hide Prices (Inspection Mode) / Show Prices (Commercial Mode).
function syncPriceToggle() {
  const button = byId('pv-prices');
  const grn = previewDoc?.spec.key === 'grn';
  button.hidden = !grn;
  if (!grn) return;
  const hidden = Boolean(previewDoc.hidePrices);
  button.classList.toggle('is-on', hidden);
  button.setAttribute('aria-pressed', String(hidden));
  button.querySelector('span').textContent = hidden ? 'Show Prices (Commercial Mode)' : 'Hide Prices (Inspection Mode)';
}

function initPurchasePreview() {
  const dialog = byId('pb-preview');
  dialog.addEventListener('click', event => {
    const action = event.target.closest('[data-pv]')?.dataset.pv;
    if (action === 'prices' && previewDoc) {
      previewDoc.hidePrices = !previewDoc.hidePrices;
      syncPriceToggle();
      showPreviewSheet();
    }
    if (action === 'print') printPreviewDocument();
    if (action === 'back') dialog.close();
  });
  byId('pv-supplier').addEventListener('change', event => {
    if (!previewDoc) return;
    previewDoc.supplierId = event.target.value;
    showPreviewSheet();
  });
  dialog.addEventListener('close', () => {
    previewDoc = null;
    dialog.querySelector('.pv-sheet').replaceChildren();
    // Back on the page it was opened from; after a save that form is gone, so the list (or page) takes the keys.
    setTimeout(() => { if (!document.activeElement || document.activeElement === document.body) focusPageAnchor(); }, 0);
  });
}

// The PDF preview's letterhead (read from the image), company details and seal are made ready once the dashboard has
// shown, so the first preview opens at once instead of after a blank pause.
function warmUpPreview() {
  const warm = async () => {
    const letterhead = await companyLetterhead();
    if (!letterhead) await drawnLetterhead(byId('app')?.querySelector('.brand-name')?.textContent);   // the GRN's drawn one
  };
  const later = window.requestIdleCallback || (callback => setTimeout(callback, 1500));
  later(() => { warm().catch(() => {}); }, { timeout: 3000 });
}

function initPurchaseBook() {
  composePurchaseTemplates();
  for (const form of PURCHASE_FORMS) form.page.init();
  for (const list of PURCHASE_LISTS) list.init();
  stkInit();                                  // Supply Management › Stock Ledger
  initSealButtons();
  initPurchasePreview();
  loadPurchaseMasters();
  warmUpPreview();
  // Items made in another tab (Create Item) show up in the searches once this tab is back in front.
  window.addEventListener('focus', () => {
    if (!PURCHASE_FORMS.some(form => form.spec.key === currentPage)) return;
    forgetLookups('item', 'itemcode');
    pbData.items.clear();
  });
}

/* =====================================================================
   Load + boot
   ===================================================================== */

let loadSeq = 0;
// pending: the figures already on their way (asked for together with the sign-in check, at start-up).
async function loadDashboard(pending) {
  const seq = ++loadSeq;
  renderChartMonths();
  const data = await (pending || fetchDashboard(currentPeriod, state.range));
  if (seq !== loadSeq) return;            // a newer load is already under way
  state.data = data;
  renderKpis(data.kpis);
  renderProfitLoss(data.profitLoss);
  renderReturns(data.returns);
  renderQuotations(data.quotations);
  renderInsights(data.insights);
  renderActivities(data.activities, data.activityTotal);
  const chartIsCurrent = state.chartYear === currentPeriod.year && state.chartMonth === currentPeriod.month;
  if (chartIsCurrent) { chartSeq++; renderChart(data.chart); }   // a month still loading must not overwrite it
  else loadChart();
}

// A month button: only the chart card changes; the other cards keep the current month's figures.
let chartSeq = 0;
async function loadChart() {
  const seq = ++chartSeq;
  renderChartMonths();
  const data = await fetchDashboard({ year: state.chartYear, month: state.chartMonth });
  if (seq !== chartSeq) return;           // a newer month is already loading
  renderChart(data.chart);
}

document.addEventListener('DOMContentLoaded', async () => {
  // The figures are asked for at once, beside the sign-in check, so they arrive with the page instead of after
  // every screen below has been set up (a lag right after signing in).
  const firstFigures = fetchDashboard(currentPeriod, state.range);
  const user = await checkSignedIn();
  if (!user) return;
  document.documentElement.classList.remove('auth-pending');
  loadDashboard(firstFigures);
  initDashRange();
  byId('header-user').textContent = user.fullName || user.username;
  useSignedInName(user);
  // The signed-in company's name in the header (also printed on Purchase Book PDFs, which read it from there).
  if (user.company?.name) {
    document.querySelector('#app .brand-name, .brand-name').textContent = user.company.name;
    document.title = `${user.company.name} · Growth Engine`;
  }
  byId('sign-out').addEventListener('click', signOut);
  initCompanyIcon();
  loadCompanyIcon();
  byId('footer-year').textContent = String(today.getFullYear());
  for (const select of [...document.querySelectorAll('select[data-phone-code]'),
    ...[...document.querySelectorAll('template')].flatMap(template => [...template.content.querySelectorAll('select[data-phone-code]')])]) fillPhoneCodes(select);
  initKeyboardNavigation();
  initDateFields();
  initInputFilters();
  initUppercaseFields();
  initFieldChecks();
  initFocusScrolling();
  initQuickMenu();
  initLookups();
  initSuggestFields();
  initItemPage();
  for (const form of MASTER_FORMS) form.init();
  initPurchaseBook();
  initMasterFilter();
  initRrFilter();
  initPbFilter();
  initMasterImport();
  initMasterView();
  initMasterConfirm();
  if (typeof initLiveUpdates === 'function') initLiveUpdates();   // sync.js
  initQuickItem();
  initQuickSupplier();
  initQuickContact();
  initItemDescription();
  initAuditPage();
  employeeForm.init();
  initEmployeesPage();
  userForm.init();
  initUserSettingPage();
  initNoAccessPage();
  applyUserAccess();
  for (const list of MASTER_LISTS) list.init();
  window.addEventListener('hashchange', renderRoute);
  renderRoute();
});
